const e=[{id:1,code:"GOV-101",icon:"DoorOpen",accent:"#2563eb",title:"خطة الإخلاء في حالات الطوارئ",subtitle:"Emergency Evacuation Plans",summary:"إعداد خطة الإخلاء للدوائر والمباني الحكومية",blocks:[{body:"تُعدّ خطة الإخلاء في حالات الطوارئ من أهم الوثائق في أي دائرة حكومية، إذ تحمي حياة الموظفين والمراجعين عند وقوع حوادث مثل الحرائق أو الزلازل أو المخاطر الكيميائية."},{heading:"1. خطوات إعداد الخطة",body:"تتطلب الخطة الناجحة الخطوات الآتية:",points:["المخطط: أعِدّ مخططًا كاملًا للمبنى يبيّن مسارات الإخلاء ومواقع مطفآت الحريق.","مسارات الإخلاء: يجب أن يكون لكل طابق مساران متباعدان للإخلاء على الأقل (NFPA 101)، ويجب أن تُفتح أبواب الخروج من الداخل دون مفتاح.","نقطة التجمع: مكان آمن خارج المبنى، على مسافة موصى بها لا تقل عن 50 مترًا.","المسؤولية: حدِّد مسؤولًا عن الإخلاء لكل طابق.","نظام الإنذار: جرس أو صفارة إنذار حريق تُسمع في جميع الطوابق.","التدريب: تمرين عملي على الإخلاء مرة واحدة كل 3 أشهر."]},{heading:"2. قواعد الإخلاء الآمن",body:"عند انطلاق جرس الإنذار:",points:["تحرّك بهدوء وانتظام — لا تركض.","لا تستخدم المصعد — اخرج عبر السلالم فقط.","إذا وُجد دخان، فاخفض جسمك وازحف على ركبتيك تحت الدخان.","قبل فتح الباب، افحصه بظهر يدك — فإن كان ساخنًا فلا تفتحه وابحث عن مسار آخر.","ساعد الأشخاص الذين يحتاجون إلى المساعدة، وأغلق الأبواب خلفك.","توجّه مباشرةً إلى نقطة التجمع وابقَ هناك."]},{heading:"3. دور المسؤولين",body:"يحتاج كل طابق إلى مسؤول عن الحريق:",points:["مسؤول الحريق (Fire Warden): المسؤول الرئيسي عن الطابق.","تفتيش جميع الغرف (بما فيها دورات المياه والمخازن) للتأكد من عدم بقاء أحد.","إرشاد الأشخاص إلى مسارات الإخلاء.","عدّ الأشخاص في نقطة التجمع وإبلاغ فريق الدفاع المدني 115."]},{heading:"4. المراجعون ومن يحتاج إلى مساعدة",body:"يجب أن تشمل الخطة جميع الأشخاص، لا الموظفين فقط:",points:["المراجعون لا يعرفون الطرق: يصطحبهم موظفو الاستقبال إلى نقطة التجمع.","لكل شخص يستخدم كرسيًا متحركًا أو لديه إعاقة حركية، يكون هناك زميل محدد وطريق مخطط له.","يُنبَّه من لا يستطيع سماع الجرس (الصم وضعاف السمع) بالإشارة أو بالضوء.","تخرج قائمة الموظفين وسجل المراجعين مع المسؤول إلى نقطة التجمع."]},{heading:"5. بعد التمرين",body:"كل تمرين فرصة لتحسين الخطة:",points:["هل سُمع الجرس في كل الغرف، بما فيها دورات المياه والمخازن؟","هل كانت طرق وأبواب الخروج مفتوحة وخالية؟","هل كان العدّ في نقطة التجمع سريعًا ودقيقًا؟","دوّن النواقص، وحدد مسؤولًا عن إصلاح كل منها، وتحقق منها في التمرين التالي."]}],media:[{kind:"image",src:"media/images/gov_evacuation.png",title:"مخطط الإخلاء",description:"نموذج لمخطط إخلاء"}],quiz:[{question:"على أي مسافة يُوصى بأن تبعد نقطة التجمع عن المبنى؟",options:[{text:"10 أمتار",correct:!1},{text:"25 مترًا",correct:!1},{text:"50 مترًا",correct:!0},{text:"100 متر",correct:!1}],explanation:"50 مترًا على الأقل، لتكون بعيدة عن الزجاج والقطع المتساقطة وعن الدخان، ولكي لا تسدّ طريق مركبات الطوارئ."},{question:"في أثناء الإخلاء وصلت إلى باب مغلق. ماذا تفعل قبل فتحه؟",options:[{text:"أفتحه بسرعة لأرى إن كان هناك دخان",correct:!1},{text:"أفحصه بظهر يدي",correct:!0},{text:"أدفعه بكتفي بقوة لأفتحه",correct:!1},{text:"أفحص مقبضه براحة يدي",correct:!1}],explanation:"قبل فتح الباب، افحصه بظهر يدك — فإن كان ساخنًا فلا تفتحه وابحث عن مسار آخر."},{question:"ماذا يفعل مسؤول الحريق (Fire Warden) في الطابق في أثناء الإخلاء؟",options:[{text:"يبقى في مكتبه لحماية ملفات الدائرة",correct:!1},{text:"يعود إلى الداخل لجمع الأغراض المنسية",correct:!1},{text:"يفتّش جميع الغرف للتأكد من عدم بقاء أحد",correct:!0},{text:"يطفئ كل حريق في الطابق قبل أن يخرج",correct:!1}],explanation:"يفتّش مسؤول الحريق جميع الغرف (بما فيها دورات المياه والمخازن) للتأكد من عدم بقاء أحد، ويرشد الأشخاص إلى مسارات الإخلاء، ثم يعدّهم في نقطة التجمع ويُبلغ فريق الدفاع المدني 115."},{question:"أثناء الإخلاء، ملأ دخان كثيف الدرج الرئيسي. ما أفضل تصرف؟",options:[{text:"استخدم طريق الخروج الثاني وأغلق الأبواب خلفك",correct:!0},{text:"احبس أنفاسك وانزل بسرعة عبر الدرج الرئيسي",correct:!1},{text:"استخدم المصعد لأن الدرج مليء بالدخان",correct:!1},{text:"انتظر داخل الدرج حتى ينقشع الدخان",correct:!1}],explanation:"لكل طابق طريقان متباعدان ليكون أحدهما بديلًا عن الآخر؛ والمصعد والدخان كلاهما قد يقتل."},{question:"في نقطة التجمع يقول زميل: «حاسوبي المحمول على المكتب، سأعود بسرعة.» والحريق لم يُطفأ بعد. ماذا تفعل؟",options:[{text:"أمنعه وأقول إن أحدًا لا يدخل حتى يأذن فريق 115",correct:!0},{text:"أسمح له إن لم يظهر دخان عند المدخل الرئيسي",correct:!1},{text:"أذهب معه حتى لا يكون وحده ونعود بسرعة",correct:!1},{text:"أسمح له إن كان طابقه بعيدًا عن الحريق",correct:!1}],explanation:"ينتشر الدخان بسرعة في كل المبنى، حتى في الطوابق البعيدة. لا شيء يساوي حياة إنسان؛ والعودة لا تكون إلا بإذن الدفاع المدني."},{question:"يريد مدير أن يقفل باب الخروج الخلفي بالمفتاح أثناء الدوام حتى لا يغادر أحد مبكرًا. ما الجواب الآمن؟",options:[{text:"يجب أن يُفتح الباب من الداخل دون مفتاح؛ ويُضبط بطريقة أخرى",correct:!0},{text:"القفل مقبول إذا بقي المفتاح طوال اليوم مع الحارس القريب من الباب",correct:!1},{text:"القفل مقبول ما دام الباب الرئيسي مفتوحًا طوال الدوام",correct:!1},{text:"القفل مقبول إذا عُلّقت عليه لافتة «الباب مغلق» ومخطط الإخلاء",correct:!1}],explanation:"يجب أن تُفتح أبواب الخروج من الداخل دون مفتاح؛ ففي الحريق لا وقت للبحث عن مفتاح، وقد يكون الطريق الرئيسي مسدودًا."}],steps:[{title:"إطلاق الإنذار",detail:"إذا رأيت نارًا أو دخانًا، فاستخدم زر الإنذار اليدوي ونبّه من حولك بصوتك. اتصل بالرقم 115 من مكان آمن، أو تأكد من أن شخصًا آخر قد اتصل.",critical:!0},{title:"أوقف العمل واخرج",detail:"عند سماع الإنذار، اترك العمل واخرج من أقرب مخرج آمن. استخدم الدرج لا المصعد، وأغلق الأبواب خلفك حتى لا ينتشر الدخان.",critical:!0},{title:"تفقّد الطابق من قبل المسؤول",detail:"يتفقد مسؤول الطابق بسرعة الغرف ودورات المياه والمخازن وقاعات الاجتماعات الواقعة على طريق خروجه، ويساعد المراجعين ومن يحتاج إلى مساعدة، ثم يخرج. ولا يدخل في دخان كثيف.",critical:!0},{title:"إذا سدّ الدخان الطريق",detail:"استخدم طريق الخروج الثاني. وإذا اضطررت إلى المرور عبر الدخان فانخفض، وافحص كل باب بظهر يدك قبل فتحه. وإذا كان الطريقان مسدودين، فادخل غرفة فيها نافذة وأغلق الباب وسدّ الفتحة أسفله بقطع قماش واتصل بالرقم 115 وأخبرهم بمكانك.",critical:!0},{title:"ابقَ في نقطة التجمع",detail:"توجّه إلى نقطة التجمع وعرّف نفسك لمسؤول الطابق حتى يتم عدّك. ويُبلغ المسؤول فريق 115 باسم كل شخص مفقود وآخر مكان شوهد فيه."},{title:"العودة بإذن فقط",detail:"لا يعود أحد إلى المبنى حتى يعلن الدفاع المدني أو الجهة المختصة أنه آمن. وبعد كل حادث أو تمرين، راجع الخطة وأصلح ما لم ينجح."}],warnings:["لا تستخدم المصعد أثناء الحريق: قد يتوقف فتُحتجز داخله، أو ينقلك إلى طابق الحريق.","لا تعد إلى المبنى لأخذ أغراضك أو للبحث عن أحد: أبلغ فريق 115 عن الشخص المفقود، لأنهم يدخلون بملابس ومعدات وقاية.","لا تقفل أبواب الخروج بالمفتاح، ولا تضع الصناديق والأثاث في الدرج والممرات: الطريق المسدود يتحول إلى فخ في حالة الطوارئ."],tips:["ضع خطة خاصة وزميلًا محددًا لكل موظف يحتاج إلى مساعدة (كرسي متحرك، مرض، حمل).","احتفظ بسجل للمراجعين عند المدخل الرئيسي، حتى يعرف المسؤول في نقطة التجمع عدد المراجعين الذين كانوا داخل المبنى.","علّق مخطط الإخلاء مع علامة «أنت هنا» قرب الدرج والمصاعد.","في التمارين، اعتبر الطريق الرئيسي مسدودًا من حين لآخر حتى يستخدم الموظفون الطريق الثاني ويتعلموه."],activity:{prompt:"أنت عند مكتب الاستقبال وعدد من المواطنين يقفون في الطابور. انطلق جرس الحريق وتصل رائحة دخان من الممر. ماذا تفعل؟",options:[{text:"أنهي معاملة المواطن الأول ثم أخرج",correct:!1,feedback:"غير صحيح: كل دقيقة تأخير تسمح للدخان بأن يسد الطريق؛ ويمكن إنجاز المعاملة لاحقًا."},{text:"أطلب من المواطنين بهدوء أن يرافقوني، وأقودهم عبر الدرج إلى نقطة التجمع",correct:!0,feedback:"صحيح: المراجعون لا يعرفون الطرق؛ يقودهم الموظف بهدوء عبر الطريق الآمن ويُعَدّون في نقطة التجمع."},{text:"أذهب إلى مكتبي لآخذ الملفات المهمة معي",correct:!1,feedback:"غير صحيح: الأرواح قبل الوثائق؛ يجب أن تكون الوثائق المهمة محفوظة في خزنة أو منسوخة قبل وقوع الحادث."},{text:"أرسل المواطن المسن بالمصعد حتى لا يسقط على الدرج",correct:!1,feedback:"غير صحيح: قد يتوقف المصعد ويُحتجز داخله؛ بدلًا من ذلك انزل معه ببطء عبر الدرج أو اطلب المساعدة."}]},caseStudy:[{prompt:"أنت مسؤول الطابق الثاني. اندلع حريق في مخزن في الطابق الأول والإنذار يرن. يدخل الدخان إلى الدرج الرئيسي، أما الدرج الثاني في نهاية الممر فخالٍ. ما أول ما تفعله؟",options:[{text:"أوجّه الناس إلى الدرج الثاني وأغلق أبواب الدرج الرئيسي",correct:!0,feedback:"صحيح: هذا هو سبب وجود طريقين متباعدين؛ وإغلاق الأبواب يُبعد الدخان عن الطابق."},{text:"أُنزل الناس بسرعة عبر الدرج الرئيسي لأنه الأقرب",correct:!1,feedback:"غير صحيح: الدخان في الدرج الرئيسي، واستنشاقه قد يُفقد الإنسان وعيه خلال أنفاس قليلة."},{text:"أطلب من الجميع البقاء في مكاتبهم حتى يصل فريق 115",correct:!1,feedback:"غير صحيح: البقاء في الغرفة يكون فقط عندما يكون الطريقان مسدودين؛ وهنا يوجد طريق خالٍ."},{text:"أنزل إلى الطابق الأول لأطفئ حريق المخزن بالمطفأة",correct:!1,feedback:"غير صحيح: حريق وصل دخانه إلى الدرج لم يعد صغيرًا؛ ومهمة المسؤول إخلاء طابقه."}]},{prompt:"الجميع في نقطة التجمع. عند العدّ تبيّن غياب موظفة من الأرشيف. يقول زميل إنها ربما في دورة المياه القريبة من الأرشيف في الطابق الثاني. ماذا تفعل؟",options:[{text:"أعود إلى المبنى لأبحث عنها بنفسي في دورة المياه",correct:!1,feedback:"غير صحيح: من دون ملابس وقاية تصبح ضحية أخرى؛ فريق 115 يدخل بالمعدات."},{text:"أُبلغ فريق 115 فورًا باسمها وآخر مكان معروف لها",correct:!0,feedback:"صحيح: المعلومة الواضحة (من، أي طابق، أي غرفة) تختصر وقت البحث وتنقذ الحياة."},{text:"أنتظر، فربما خرجت من باب آخر وستأتي",correct:!1,feedback:"غير صحيح: الانتظار يضيّع وقتًا ثمينًا؛ يتم الإبلاغ فورًا، وإذا ظهرت يُبلَّغ الفريق."},{text:"أرسل زميلين شابين ليتفقدا دورة المياه بسرعة",correct:!1,feedback:"غير صحيح: الشباب لا يحمي من الدخان؛ وبهذا تعرّض شخصين آخرين للخطر."}]}],realCase:"في دائرة حكومية، اندلع حريق صغير في مخزن بالطابق الأول ووصل الدخان إلى الدرج الرئيسي. كان الموظفون قد استخدموا الدرج الثاني عدة مرات في التمارين، فقاد مسؤولو الطوابق الناس إليه بهدوء وأغلقوا أبواب الدخان. وخرج المراجعون من مكتب الاستقبال برفقة موظف. وفي نقطة التجمع استُخدم سجل المراجعين وقائمة الموظفين، فتبيّن أنه لم يبقَ أحد في الداخل. وبعد ذلك أفرغ المدير المخزن من الأوراق والصناديق القديمة. الدرس: الطريق الثاني الذي تم التدرب عليه ينقذ الأرواح عندما يُسد الطريق الرئيسي."},{id:2,code:"GOV-102",icon:"FileLock",accent:"#059669",title:"حماية الوثائق",subtitle:"Document Protection",summary:"إجراءات حماية الوثائق المهمة من الحريق والمياه",blocks:[{body:"الوثائق الحكومية ثروة ثمينة، وقد يؤدي فقدانها بسبب الحريق أو المياه إلى توقف عمل الدائرة وضياع حقوق المواطنين. لذلك فإن حمايتها ونسخها أمر ضروري."},{heading:"1. تصنيف الوثائق",body:"تحديد درجة أهمية الوثائق:",points:["المستوى A — بالغة الأهمية: العقود والوثائق المالية والقانونية.","المستوى B — مهمة: التقارير والمراسلات الرسمية.","المستوى C — عادية: المراسلات غير الرسمية."]},{heading:"2. الحماية المادية",body:"إجراءات الحماية المادية:",points:["خزائن مقاومة للحريق: لوثائق المستوى A.","خزائن معدنية مقفلة، مرفوعة عن الأرض.","أكياس وصناديق بلاستيكية مقاومة للماء.","التحكم في البيئة: مكان بارد وجاف بدرجة حرارة ورطوبة ثابتتين."]},{heading:"3. قاعدة 3-2-1 للنسخ الاحتياطية (Backup)",body:"قاعدة 3-2-1:",points:["3 نسخ من كل بيانات مهمة.","نوعان (2) مختلفان من وسائط التخزين.","نسخة واحدة (1) في مكان آخر خارج المبنى."]},{heading:"4. خطة استمرارية العمل",body:"يجب أن يعرف كل قسم كيف يستعيد عمله بعد حريق أو فيضان:",points:["قائمة السجلات الحيوية (Vital Records): الوثائق التي يتوقف العمل من دونها.","أماكن نسخها ومن يستطيع استرجاعها بسرعة.","أين وكيف تستمر الخدمة إذا تعذّر استخدام المبنى.","تُختبر الخطة عمليًا مع استرجاع النسخ، لا على الورق فقط."]},{heading:"5. بعد الحريق أو الفيضان",body:"إنقاذ الوثائق بأمان:",points:["قبل أي شيء، لا تدخل إلا بإذن الدفاع المدني.","انقل الوثائق المبللة بلطف إلى مكان بارد وجاف جيد التهوية؛ ولا تستخدم المدافئ.","أنقذ المستوى A أولًا، واطلب مساعدة مختصي حفظ الوثائق.","سجّل كل ما فُقد أو تضرر قبل التخلص منه."]}],media:[{kind:"image",src:"media/images/gov_backup.png",title:"النسخ الاحتياطية (Backup)",description:"قاعدة 3-2-1"}],quiz:[{question:"ماذا تعني قاعدة 3-2-1؟",options:[{text:"3 حواسيب، وخادمان (2)، وغرفة خوادم (1) مقفلة",correct:!1},{text:"3 نسخ، ونوعان (2) من الوسائط، ونسخة (1) خارج المبنى",correct:!0},{text:"3 أيام",correct:!1},{text:"3 نسخ يوميًا، ونسختان (2) لأسبوع، ونسخة (1) لشهر كامل",correct:!1}],explanation:"3 نسخ على نوعين (2) من الوسائط، ونسخة واحدة (1) في مكان آخر خارج المبنى."},{question:"أين يجب حفظ وثائق المستوى A، مثل العقود؟",options:[{text:"على رفوف مفتوحة قرب نافذة المكتب",correct:!1},{text:"في خزنة مقاومة للحريق",correct:!0},{text:"في صندوق كرتوني تحت المكتب",correct:!1},{text:"في القبو على الأرض مباشرةً",correct:!1}],explanation:"وثائق المستوى A (العقود والوثائق المالية والقانونية) بالغة الأهمية، وتُحفظ في خزائن مقاومة للحريق؛ أما غيرها ففي خزائن معدنية مقفلة مرفوعة عن الأرض."},{question:"أي مكان يناسب حفظ الوثائق المهمة؟",options:[{text:"غرفة دافئة قرب المدافئ ليبقى الورق جافًا",correct:!1},{text:"القبو، قرب أنابيب المياه",correct:!1},{text:"غرفة مشمسة قرب النوافذ ليبقى الهواء متجددًا",correct:!1},{text:"مكان بارد وجاف بدرجة حرارة ورطوبة ثابتتين",correct:!0}],explanation:"احفظ الوثائق في مكان بارد وجاف بدرجة حرارة ورطوبة ثابتتين وبعيدًا عن الماء: ففقدانها بسبب الحريق أو المياه قد يؤدي إلى توقف عمل الدائرة وضياع حقوق المواطنين."},{question:"قاعدة بيانات العقود ونسختها كلتاهما على خادم واحد في مبنى الأرشيف نفسه. ما نقطة الضعف الرئيسية؟",options:[{text:"لا توجد نسخة في مكان آخر خارج المبنى",correct:!0},{text:"الخادم قديم جدًا ويجب استبداله",correct:!1},{text:"تُعمل النسخة يوميًا لا كل ساعة",correct:!1},{text:"العقود الورقية في غرفة أخرى من الأرشيف",correct:!1}],explanation:"وفق قاعدة 3-2-1 يجب أن تكون نسخة واحدة خارج المبنى؛ فحريق أو فيضان واحد قد يقضي على الأصل والنسخة معًا."},{question:"تأخذ دائرتك نسخًا احتياطية كل أسبوع، لكنها لم تختبر قط استرجاعها. ما الذي يجب فعله؟",options:[{text:"استرجع نسخة فعليًا من حين لآخر وسجّل النتيجة",correct:!0},{text:"زد عدد النسخ إلى مرتين أسبوعيًا فقط",correct:!1},{text:"لا حاجة لذلك؛ إذا أُخذت النسخة فهي تعمل",correct:!1},{text:"اطبع النسخ أيضًا وضعها في الأرشيف",correct:!1}],explanation:"النسخة التي لم تُسترجع قط قد تكون تالفة أو ناقصة؛ والاختبار وحده يُظهر أنها ستعمل وقت الطوارئ."},{question:"يدخل الماء من أنبوب منفجر إلى الأرشيف ويقترب من المقابس الكهربائية. ما أول تصرف؟",options:[{text:"ابتعد عن الماء وأخرج الناس وأبلغ المسؤول عن الكهرباء والمياه",correct:!0},{text:"ادخل في الماء وارفع صناديق المستوى A عن الأرض أولًا",correct:!1},{text:"انزع كل الأسلاك من المقابس بيديك المبللتين لقطع الكهرباء",correct:!1},{text:"التقط بسرعة صورًا للأضرار من داخل الغرفة لتقرير المدير",correct:!1}],explanation:"الماء والكهرباء معًا خطر صعق؛ والأرواح قبل الوثائق. يقطع المسؤول الكهرباء والماء، ثم تُنقذ الملفات."}],steps:[{title:"احصر الوثائق وصنّفها",detail:"أعدّ قائمة بوثائق كل قسم وبياناته، وحدّد مستوى كل منها (A أو B أو C). واكتب مكان كل منها ومن المسؤول عنها."},{title:"احفظها في المكان المناسب",detail:"وثائق المستوى A في خزائن مقاومة للحريق؛ والبقية في خزائن معدنية مقفلة مرفوعة عن الأرض، بعيدًا عن أنابيب المياه والمدافئ والمقابس الكهربائية."},{title:"انسخ واختبر النسخة",detail:"امسح الوثائق المهمة ضوئيًا وطبّق قاعدة 3-2-1. واسترجع نسخة فعليًا من حين لآخر للتأكد من أنها تعمل؛ فالنسخة غير المختبرة قد لا تعمل وقت الطوارئ."},{title:"احمِ الأرشيف من الحريق",detail:"أبقِ غرفة الأرشيف مرتبة ومغلقة: لا سجائر ولا مدافئ ولا أسلاك تمديد فيها، ولا توضع الأوراق على الأرض أو أمام الأبواب وطرق الخروج."},{title:"في الطوارئ: الأرواح أولًا",detail:"عند انطلاق إنذار الحريق أو وصول المياه، اترك الوثائق واخرج. إذا كانت الخزنة في متناول يدك ولا يضيّع إغلاقها أي وقت فأغلقها؛ وإلا فاخرج مباشرة.",critical:!0},{title:"بعد الحادث: استعادة العمل",detail:"لا تدخل إلا بعد إذن الدفاع المدني. استعد تقديم الخدمات من النسخ المحفوظة خارج المبنى، وانقل الوثائق المبللة إلى مكان بارد وجاف واطلب مساعدة مختص، وسجّل ما فُقد."}],warnings:["لا تعد إلى مبنى فيه حريق أو مياه من أجل الوثائق: لا ورقة تساوي حياة إنسان، والنسخ الاحتياطية وُجدت لهذا الغرض.","لا تضع الوثائق على أرضية القبو أو تحت أنابيب المياه: ماء أنبوب منفجر أو ماء الإطفاء سيتلفها.","لا تُبقِ النسخة الوحيدة من البيانات المهمة على حاسوب واحد أو في المبنى نفسه: حريق واحد يقضي على الأصل والنسخة معًا."],tips:["ضع على الصناديق والملفات علامة مستواها (A، B، C) حتى تُعرف بسرعة في الطوارئ.","عيّن في كل قسم مسؤولًا عن السجلات يعرف قائمة المستوى A وأماكن نسخها.","ضع النسخة الخارجية في مكان لا يتأثر بالحادث نفسه (حريق، فيضان).","افحص السقف والأنابيب فوق الأرشيف بعد المطر والثلج، وأبلغ فورًا عن أي تسرّب."],activity:{prompt:"في الصباح تلاحظ أن الماء، بعد مطر الليل، يقطر من سقف الأرشيف على عدة صناديق ملفات موضوعة على الأرض. ماذا تفعل؟",options:[{text:"أنقل الصناديق إلى مكان جاف ومرتفع وأبلغ المدير والصيانة بالتسرّب",correct:!0,feedback:"صحيح: توقف الضرر مبكرًا ويُصلَح سببه حتى لا يتكرر."},{text:"أضع مدفأة قرب الصناديق لتجف بسرعة",correct:!1,feedback:"غير صحيح: المدفأة قرب الورق خطر حريق، والحرارة تزيد تلف الورق المبلل."},{text:"أغطيها بالبلاستيك وأتركها في مكانها على الأرض",correct:!1,feedback:"ليس كافيًا: البلاستيك يساعد لوقت قصير، لكن الصناديق تبقى على الأرض والتسرّب لم يُبلَّغ عنه."},{text:"لا أفعل شيئًا، فهذا عمل قسم الصيانة",correct:!1,feedback:"غير صحيح: حماية الوثائق مسؤولية كل الموظفين؛ وكل ساعة تأخير تزيد الضرر."}]},caseStudy:[{prompt:"أنت في غرفة الأرشيف، وعلى مكتبك عدة عقود من المستوى A والخزنة في الغرفة المجاورة. انطلق جرس الحريق وبدأ الدخان يظهر في الممر. ماذا تفعل؟",options:[{text:"أترك العقود وأغلق الباب وأخرج",correct:!0,feedback:"صحيح: الأرواح أولًا؛ إغلاق الباب يبطئ النار والدخان، ونسخ العقود يجب أن تكون في مكان آخر."},{text:"آخذ العقود إلى الغرفة المجاورة وأقفل عليها الخزنة",correct:!1,feedback:"غير صحيح: الذهاب إلى غرفة أخرى مع وجود الدخان يضيّع وقت الخروج؛ الخزنة فقط إن كانت في متناول يدك."},{text:"أحمل كل صناديق المستوى A معي إلى الخارج",correct:!1,feedback:"غير صحيح: الصناديق الثقيلة تبطئك وتشغل يديك، وقد تسد الطريق على الآخرين."},{text:"أتصل بالمدير لأسأله ماذا أفعل بالملفات",correct:!1,feedback:"غير صحيح: يجب أن تكون الخطة قد أجابت عن هذا السؤال قبل الحادث؛ والآن وقت الخروج."}]},{prompt:"أُطفئ الحريق، لكن الأرشيف تبلل بماء الإطفاء. يريد المدير استئناف خدمة المواطنين غدًا. ما أفضل طريقة؟",options:[{text:"نبدأ من النسخ الخارجية ونطلب مساعدة مختص للملفات المبللة",correct:!0,feedback:"صحيح: هذا هو هدف قاعدة 3-2-1؛ يستمر العمل وتُعالَج الملفات المبللة بشكل صحيح."},{text:"نجفف الملفات المبللة بالمدافئ داخل الغرفة لتكون جاهزة غدًا",correct:!1,feedback:"غير صحيح: المدافئ قرب الورق خطر حريق جديد، وتزيد تلف الورق المبلل."},{text:"نرمي كل الأوراق المبللة فورًا ونبدأ من جديد",correct:!1,feedback:"غير صحيح: يمكن إنقاذ كثير من الملفات، ورمي الوثائق الرسمية قد يضيّع حقوق الناس."},{text:"ندخل الأرشيف اليوم قبل أن يعلن الدفاع المدني سلامة المبنى",correct:!1,feedback:"غير صحيح: بعد الحريق قد يكون السقف والكهرباء خطرين؛ والدخول بإذن فقط."}]}],realCase:"في إحدى الليالي انفجر أنبوب ماء في قبو دائرة حكومية فامتلأ الأرشيف بالماء. تبللت كل الصناديق الموضوعة على الأرض، أما الملفات في الخزائن المعدنية المرفوعة والعقود في الخزنة فبقيت جافة. وكانت الدائرة قد مسحت العقود المهمة ضوئيًا واحتفظت بنسخة في مبنى آخر، فاستؤنفت الخدمة بسرعة وساعد مختص في معالجة الملفات المبللة. وبعد ذلك نُقل الأرشيف إلى طابق أعلى. الدرس: الرفع والفصل والنسخ."},{id:3,code:"GOV-103",icon:"Zap",accent:"#ca8a04",title:"السلامة الكهربائية",subtitle:"Electrical Safety",summary:"المخاطر الكهربائية في الدوائر وفحص الأجهزة",blocks:[{body:"تُعدّ الكهرباء من الأسباب الرئيسية لاندلاع الحرائق في الدوائر. ويجب فحص الأسلاك القديمة، وتحميل المقابس فوق طاقتها، وأجهزة التدفئة بصورة منتظمة."},{heading:"1. المخاطر الكهربائية",body:"المخاطر الشائعة في الدوائر:",points:["التحميل الزائد: توصيل أجهزة كثيرة بمقبس واحد.","الأسلاك القديمة ذات العوازل المتشققة أو المكسورة.","وجود الماء بالقرب من الأجهزة والمقابس الكهربائية.","أسلاك التمديد (Extension): استخدامها بكثرة وبصورة دائمة."]},{heading:"2. قواعد السلامة",body:"القواعد اليومية:",points:["لا توصل سلك تمديد بسلك تمديد آخر.","يجب أن تكون يداك جافتين قبل لمس المقبس.","صِل المدفأة مباشرةً بمقبس الجدار، لا بسلك تمديد."]},{heading:"3. الحريق الكهربائي",body:"إذا اندلع حريق في جهاز كهربائي:",points:["إن استطعت ذلك بأمان، فافصل الكهرباء من اللوحة الكهربائية واتصل بالرقم 115.","إذا كان الحريق صغيرًا وكنت مدرَّبًا، فاستخدم مطفأة ثاني أكسيد الكربون (CO₂) أو مطفأة المسحوق الجاف (ABC) وطريق الخروج خلفك؛ وإلا فاخرج.","لا تستخدم الماء ولا الرغوة إلا إذا أظهر الملصق تصنيف الفئة C أو علامة اختبار كهربائي — فهناك خطر الصعق الكهربائي."]},{heading:"4. علامات الإنذار والإبلاغ",body:"أبلغ عن هذه العلامات بالطريقة المعتمدة قبل أن تتحول إلى حريق:",points:["مقبس أو قابس ساخن، أو لون بني حول المقبس.","مصابيح تومض أو يخفت ضوؤها ويشتد.","قواطع في اللوحة تفصل بشكل متكرر.","صوت طقطقة أو رائحة بلاستيك محترق."]},{heading:"5. إذا تعرّض شخص لصعق كهربائي",body:"ساعد دون أن تصبح الضحية الثانية:",points:["لا تلمسه؛ اقطع الكهرباء أولًا من المفتاح أو القابس أو اللوحة.","اتصل بالرقم 122 حتى لو بدا المصاب بخير، لأن الصعق قد يؤثر في القلب.","إذا لم يستجب ولم يتنفس طبيعيًا فابدأ CPR واستخدم جهاز AED.","برّد الحروق في مكان الصعق بالماء البارد الجاري، ولا تضع عليها أي شيء."]}],media:[{kind:"video",src:"media/videos/gov_electrical.mp4",title:"السلامة الكهربائية",description:"إرشادات"}],quiz:[{question:"أي مطفأة حريق هي الأفضل للحريق الكهربائي؟",options:[{text:"الماء",correct:!1},{text:"الرغوة أو دلو من الماء",correct:!1},{text:"CO₂ أو المسحوق الجاف",correct:!0},{text:"بطانية أو قطعة قماش مبللة",correct:!1}],explanation:"لا يوصل CO₂ والمسحوق الجاف الكهرباء؛ أما الماء والرغوة العاديان فيوصلانها وقد يسببان الصعق الكهربائي."},{question:"كيف يجب توصيل المدفأة الكهربائية؟",options:[{text:"بسلك تمديد",correct:!1},{text:"بمقبس واحد مع أجهزة كثيرة أخرى",correct:!1},{text:"مباشرةً بمقبس الجدار",correct:!0},{text:"بسلكي تمديد موصولين معًا",correct:!1}],explanation:"صِل المدفأة مباشرةً بمقبس الجدار، لا بسلك تمديد، ولا توصل سلك تمديد بسلك تمديد آخر؛ فالتحميل الزائد من المخاطر الشائعة في الدوائر."},{question:"اندلع حريق في جهاز كهربائي في دائرتك. ما أول ما تفعله إن استطعت ذلك بأمان؟",options:[{text:"أفصل الكهرباء من اللوحة الكهربائية وأتصل بالرقم 115",correct:!0},{text:"أسكب دلوًا من الماء عليه ليبرد",correct:!1},{text:"أفتح غطاءه لأرى أي جزء يحترق",correct:!1},{text:"أرشّه بأقرب مطفأة رغوة",correct:!1}],explanation:"إن استطعت ذلك بأمان، فافصل الكهرباء من اللوحة الكهربائية واتصل بالرقم 115؛ ولا تستخدم مطفأة CO₂ أو المسحوق الجاف (ABC) إلا إذا كان الحريق صغيرًا وكنت مدرَّبًا وطريق الخروج خلفك؛ وإلا فاخرج."},{question:"أصيب زميل بصعق كهربائي ويده ما زالت على سلك الجهاز ولا يستطيع تركه. ما أول تصرف؟",options:[{text:"اقطع الكهرباء من المفتاح أو اللوحة قبل لمسه",correct:!0},{text:"اسحب يده بقوة لتفصلها عن السلك",correct:!1},{text:"اسكب الماء عليه ليبرد جسمه",correct:!1},{text:"اتصل بالرقم 122 وانتظر دون قطع الكهرباء",correct:!1}],explanation:"ما دامت الكهرباء غير مقطوعة فكل من يلمسه يُصعق أيضًا. بعد القطع اتصل بالرقم 122 وابدأ CPR إذا لزم الأمر."},{question:"تلاحظ أن المقبس خلف مكتبك ساخن وتغيّر لونه إلى البني. ماذا تفعل؟",options:[{text:"أوقف استخدامه وأبلغ الصيانة",correct:!0},{text:"أنقل أجهزتي إلى مقبس آخر ولا أخبر أحدًا",correct:!1},{text:"أفك غطاء المقبس بالمفك وأفحصه بنفسي",correct:!1},{text:"ألف حوله شريطًا لاصقًا وأستمر في استخدامه",correct:!1}],explanation:"السخونة واللون البني علامتان على توصيل سيئ أو حمل زائد وقد تسببان حريقًا؛ ولا يصلحه إلا كهربائي مؤهل."},{question:"أيّ من هذه الممارسات في المكتب غير آمنة؟",options:[{text:"تمديد سلك تمديد تحت السجاد حتى طاولة الاجتماعات",correct:!0},{text:"وصل المدفأة مباشرة بمقبس الجدار",correct:!1},{text:"إبقاء الطريق إلى اللوحة خاليًا ووضع أسماء على مفاتيحها",correct:!1},{text:"إطفاء الأجهزة غير الضرورية في نهاية الدوام",correct:!1}],explanation:"السلك تحت السجاد يُداس فيتلف عازله، والسجاد يحبس الحرارة؛ وهذا سبب شائع للحريق. أما الممارسات الثلاث الأخرى فآمنة."}],steps:[{title:"افحص قبل الاستخدام",detail:"افحص السلك والقابس والمقبس: عازل متشقق، آثار احتراق، سخونة أو رائحة احتراق. لا تستخدم جهازًا تالفًا؛ ضع عليه علامة وأبلغ الصيانة."},{title:"خفّف الحمل عن المقبس",detail:"صِل المدافئ والأجهزة ذات القدرة العالية بمقبس الجدار مباشرة، ولا تصل سلك تمديد بآخر، واستخدم سلك التمديد لفترة قصيرة فقط."},{title:"أبعد الماء عن الكهرباء",detail:"لا تضع الشاي والماء والمزهريات على الأجهزة أو قرب المقابس، والمس المفاتيح والقوابس بيدين جافتين."},{title:"أبلغ عن علامات الخطر",detail:"إذا شممت رائحة احتراق أو رأيت شررًا أو سخن المقبس: أوقف الاستخدام، وأطفئ الجهاز وافصله إن أمكن ذلك بأمان، وأبلغ الصيانة. لا تصلحه بنفسك؛ فقط كهربائي مؤهل."},{title:"حريق كهربائي",detail:"أطلق الإنذار واتصل بالرقم 115. وإذا أمكنك ذلك بأمان فاقطع الكهرباء من اللوحة. استخدم مطفأة CO₂ أو البودرة الجافة (ABC) فقط إذا كانت كل إجابات فحص ما قبل الاستخدام «نعم»؛ وإلا فاخرج وأغلق الباب.",critical:!0},{title:"الصعق الكهربائي",detail:"لا تلمس شخصًا ما زال متصلًا بالكهرباء. اقطع الكهرباء أولًا من المفتاح أو اللوحة، ثم اتصل بالرقم 122. وإذا لم يستجب ولم يتنفس طبيعيًا فابدأ الإنعاش القلبي الرئوي (CPR) واطلب جهاز AED.",critical:!0}],warnings:["لا تلمس المصاب بالصعق قبل قطع الكهرباء: سيمر التيار في جسمك أيضًا وتصبح ضحية ثانية.","لا تسكب الماء أو الرغوة على جهاز كهربائي مشتعل: الماء يوصل الكهرباء وهناك خطر صعق.","لا تفتح لوحة الكهرباء ولا تُصلح الأسلاك إن لم تكن كهربائيًا مؤهلًا: العمل الكهربائي الخاطئ سبب للحريق والصعق."],tips:["أبقِ الطريق إلى لوحة الكهرباء خاليًا، وضع على مفاتيحها أسماء الغرف والطوابق.","في نهاية الدوام أطفئ المدافئ والغلايات والأجهزة غير الضرورية وافصلها عن المقابس.","لا تمدّ الأسلاك تحت السجاد أو بين الباب وإطاره أو في ممرات المشي.","إذا كانت المقابس قليلة فاطلب من كهربائي مؤهل تركيب مقابس جديدة، لا أسلاك تمديد دائمة."],activity:{prompt:"في الشتاء، تصل زميلتك مدفأة بسلك تمديد موصول به أيضًا طابعة وغلاية، والسلك تحت المكتب فوق السجادة. ماذا تفعل؟",options:[{text:"أطلب منها بلطف وصل المدفأة بمقبس الجدار مباشرة وأبلغ الصيانة",correct:!0,feedback:"صحيح: المدفأة حمل كبير؛ وتحميل سلك التمديد فوق طاقته يسخّنه، والسجاد يحبس الحرارة فيبدأ الحريق."},{text:"لا أقول شيئًا، فالسلك لم يسخن بعد",correct:!1,feedback:"غير صحيح: يبدأ الحريق بعد ساعات من التشغيل، وغالبًا حين لا يكون أحد في الغرفة."},{text:"أصل سلك تمديد آخر به لتوزيع الحمل",correct:!1,feedback:"غير صحيح: وصل سلك تمديد بآخر لا يخفف الحمل؛ فكل الحمل ما زال على مقبس جدار واحد."},{text:"أغطي السلك بالورق حتى لا يتعثر به أحد",correct:!1,feedback:"غير صحيح: الورق يحبس الحرارة ويشتعل بسهولة؛ وهذا يزيد الخطر."}]},caseStudy:[{prompt:"تصدر رائحة احتراق ودخان خفيف من سلك تمديد خلف آلة النسخ، ويظهر لهب صغير. ما أول ما تفعله؟",options:[{text:"أطلق الإنذار وأتصل بالرقم 115 وأقطع الكهرباء من اللوحة إن كان ذلك آمنًا",correct:!0,feedback:"صحيح: الإنذار يحمي الجميع، وقطع الكهرباء يوقف سبب الحريق ويقلل خطر الصعق."},{text:"أسكب ماء الغلاية على السلك",correct:!1,feedback:"غير صحيح: الماء على حريق كهربائي ما زال موصولًا بالتيار يسبب صعقًا كهربائيًا."},{text:"أسحب السلك من المقبس بيدي رغم أنهما مبللتان",correct:!1,feedback:"غير صحيح: اليدان المبللتان والسلك المحترق يزيدان خطر الصعق؛ اقطع الكهرباء من اللوحة."},{text:"أفتح النافذة وأواصل عملي",correct:!1,feedback:"غير صحيح: الحريق الصغير يكبر بسرعة؛ والهواء يغذي النار."}]},{prompt:"قُطعت الكهرباء والحريق ما زال صغيرًا. أنت مدرّب ومطفأة CO₂ قرب الباب خلفك. تستخدم المطفأة لكن النار لا تنطفئ وتبدأ الأوراق القريبة بالاشتعال. ماذا تفعل الآن؟",options:[{text:"أتوقف وأخرج وأغلق الباب وأتأكد من إبلاغ 115",correct:!0,feedback:"صحيح: إذا لم تنطفئ النار فورًا فقد حان وقت الخروج؛ والباب المغلق يبطئ النار والدخان."},{text:"أحضر مطفأة أخرى وأعود وحدي إلى الغرفة",correct:!1,feedback:"غير صحيح: الحريق المنتشر لم يعد مناسبًا للمطافئ اليدوية؛ وقد يقطع الدخان طريقك."},{text:"أستخدم مطفأة ماء على الأوراق لأن الكهرباء مقطوعة",correct:!1,feedback:"غير صحيح: الحريق انتشر؛ والهدف الآن الخروج الآمن لا تجربة مطفأة أخرى."},{text:"أترك الباب مفتوحًا ليخرج الدخان إلى الممر",correct:!1,feedback:"غير صحيح: الباب المفتوح ينشر الدخان في طرق الخروج ويغذي النار بالهواء."}]}],realCase:"في دائرة حكومية، وصل الموظفون في الشتاء مدفأة وغلاية وطابعة معًا بسلك تمديد واحد. شمّ أحد الموظفين رائحة بلاستيك محترق، فأطفأ المدفأة وفصلها عن المقبس لأن ذلك كان آمنًا، وأبلغ الصيانة. ووجد كهربائي مؤهل أن عازل السلك قد ذاب. فركّب المدير مقابس جديدة بواسطة كهربائي ومنع وصل أسلاك التمديد ببعضها. ولم يندلع حريق. الدرس: رائحة الاحتراق إنذار، لا أمر بسيط."},{id:4,code:"GOV-104",icon:"HeartPulse",accent:"#dc2626",title:"برنامج الإسعافات الأولية",subtitle:"First Aid Program",summary:"تشكيل فريق الإسعافات الأولية وتجهيز المستلزمات",blocks:[{body:"تحتاج كل دائرة إلى برنامج للإسعافات الأولية. ويُوصى بوجود شخص مدرَّب واحد على الأقل في كل طابق وفي كل نوبة دوام، وعدد أكبر في الدوائر الكبيرة."},{heading:"1. فريق الإسعافات الأولية",body:"تشكيلة الفريق:",points:["شخص مدرَّب واحد على الأقل في كل طابق وفي كل نوبة دوام.","دورة معتمدة في الإسعافات الأولية والإنعاش القلبي الرئوي (CPR) وجهاز إزالة الرجفان الخارجي الآلي (AED).","تجديد التدريب والشهادة كل سنتين."]},{heading:"2. حقيبة الإسعافات الأولية",body:"المستلزمات الضرورية:",points:["ضمادات (Bandage) وشاش نظيف (Gauze).","مواد تطهير الجروح (Antiseptic).","مقص وملقط.","قفازات طبية تُستخدم لمرة واحدة.","قناع CPR لإعطاء أنفاس الإنقاذ بأمان."]},{heading:"3. الإنعاش القلبي الرئوي (CPR)",body:"خطوات CPR للبالغين:",points:["1. إذا كان الشخص لا يستجيب ولا يتنفس بصورة طبيعية: اتصل بالإسعاف على الرقم 122 واطلب جهاز AED؛ ثم ضعه على ظهره فوق سطح صلب.","2. أجرِ 30 ضغطة صدرية في منتصف الصدر: بعمق 5-6 سم، وبمعدل 100-120 ضغطة في الدقيقة.","3. أعطِ نَفَسين (مدة كل منهما نحو ثانية واحدة) إذا كنت مدرَّبًا؛ وإلا فاكتفِ بالضغطات الصدرية.","4. استمر بنسبة 30:2 حتى وصول جهاز AED أو سيارة الإسعاف؛ واستخدم AED فور وصوله."]},{heading:"4. خطة الإسعافات الأولية في الدائرة",body:"يجب أن تجيب الخطة عن هذه الأسئلة:",points:["من المدرَّب في كل طابق وفي كل دوام؟","أين حقيبة الإسعافات الأولية وجهاز AED ومن يفحصهما؟","من يتصل بالرقم 122 ومن ينتظر الإسعاف عند الباب؟","أين تُسجَّل الحوادث ومن يعيد تجهيز الحقيبة بعد كل حادث؟"]},{heading:"5. حوادث شائعة في المكاتب",body:"الإسعاف الأولي الصحيح:",points:["النزيف الشديد: اضغط مباشرة على الجرح وأنت ترتدي القفازين واتصل بالرقم 122؛ وإذا تشبّعت الضمادة فضع أخرى فوقها.","الحروق (من الغلاية أو الماء الساخن): برّدها تحت الماء البارد الجاري 20 دقيقة؛ لا ثلج ولا زبدة ولا معجون أسنان.","الاختناق (لدى البالغين): 5 ضربات بين لوحي الكتف ثم 5 ضغطات على البطن، وكرّر حتى يخرج الجسم العالق أو يصل الإسعاف.","فاقد الوعي الذي يتنفس طبيعيًا: إن لم يُشتبه بإصابة في الرقبة أو الظهر فوضعية الإفاقة واتصل بالرقم 122."]}],media:[{kind:"video",src:"media/videos/gov_cpr.mp4",title:"الإنعاش القلبي الرئوي (CPR)",description:"كيفية إجراء CPR"}],quiz:[{question:"في CPR، كم ضغطة صدرية تُجرى قبل النَّفَسين؟",options:[{text:"10",correct:!1},{text:"15",correct:!1},{text:"30",correct:!0},{text:"50",correct:!1}],explanation:"النسبة الصحيحة للبالغين هي 30:2 (AHA 2025)."},{question:"انهار زميل لك، وهو لا يستجيب ولا يتنفس بصورة طبيعية. ما أول ما تفعله؟",options:[{text:"أعطيه ماءً ليشرب",correct:!1},{text:"أضعه في وضعية الإفاقة وأنتظر",correct:!1},{text:"أنتظر بضع دقائق لأرى إن كان سيستفيق",correct:!1},{text:"أتصل بالإسعاف على الرقم 122 وأطلب جهاز AED",correct:!0}],explanation:"إذا كان الشخص لا يستجيب ولا يتنفس بصورة طبيعية، فاتصل بالإسعاف على الرقم 122 واطلب جهاز AED، ثم ضعه على ظهره فوق سطح صلب وابدأ الضغطات الصدرية."},{question:"لست مدرَّبًا على إعطاء أنفاس الإنقاذ. ماذا تفعل في أثناء CPR؟",options:[{text:"أعطي الأنفاس فقط دون ضغطات",correct:!1},{text:"أكتفي بالضغطات الصدرية",correct:!0},{text:"أوقف CPR حتى يصل شخص مدرَّب",correct:!1},{text:"أجري 15 ضغطة ثم أستريح",correct:!1}],explanation:"إذا لم تكن مدرَّبًا على إعطاء الأنفاس، فاكتفِ بالضغطات الصدرية في منتصف الصدر بمعدل 100-120 ضغطة في الدقيقة، واستمر حتى وصول جهاز AED أو سيارة الإسعاف."},{question:"تتصل بالرقم 122 من أجل زميل فاقد الوعي. ما أول معلومة تقولها؟",options:[{text:"المكان بدقة: المبنى والطابق والمدخل القريب",correct:!0},{text:"اسمك ورقم هاتفك واسم قسمك",correct:!1},{text:"عمر الزميل واسمه الكامل ووظيفته",correct:!1},{text:"أمراضه السابقة والأدوية التي يتناولها",correct:!1}],explanation:"إذا انقطع الاتصال فالمكان يكفي لوصول الإسعاف. ثم قل ما حدث وكم مصابًا وما الأخطار، ولا تُنهِ المكالمة حتى يُطلب منك ذلك."},{question:"أحرق زميل يده بماء الغلاية. ما الإسعاف الأولي الصحيح؟",options:[{text:"تبريدها تحت الماء البارد الجاري 20 دقيقة",correct:!0},{text:"وضع الثلج مباشرة على الحرق حتى يخف الألم",correct:!1},{text:"دهن الحرق بمعجون الأسنان أو الزبدة",correct:!1},{text:"فقء الفقاعات ولفّها بقطعة قماش جافة بإحكام",correct:!1}],explanation:"الماء البارد الجاري يسحب الحرارة من الجلد ويقلل الضرر. أما الثلج فيؤذي الجلد، والزبدة والمعجون يحبسان الحرارة، وفقء الفقاعات يفتح الباب للجراثيم."},{question:"زميلة لديها حساسية شديدة لا تستطيع التنفس بسهولة بعد الطعام. وحاقن الأدرينالين الخاص بها (الذي وصفه الطبيب) في حقيبتها. ماذا تفعل؟",options:[{text:"أساعدها على استخدام حاقنها وأتصل بالرقم 122",correct:!0},{text:"أعطيها حبة للحساسية من حقيبة الإسعافات الأولية",correct:!1},{text:"أعطيها ماء وأنتظر لأرى إن كانت ستتحسن",correct:!1},{text:"آخذها بسيارتي إلى بيتها لترتاح هناك",correct:!1}],explanation:"الحساسية الشديدة قد تقتل بسرعة. ويقتصر الإسعاف الأولي على مساعدة الشخص على استخدام جهازه الخاص الموصوف من الطبيب؛ ولا يعطي أدوية أخرى، ويُتصل بالرقم 122 دائمًا."}],steps:[{title:"هل المكان آمن؟",detail:"انظر قبل الاقتراب: كهرباء، نار، دخان، غاز أو أشياء قد تسقط. وإذا لم يكن المكان آمنًا فلا تدخل واتصل بالرقم 115.",critical:!0},{title:"الاستجابة والتنفس",detail:"نادِه بصوت عالٍ وهزّ كتفيه برفق. وانظر هل يتنفس بشكل طبيعي أم لا.",critical:!0},{title:"اتصل بالرقم 122 واطلب جهاز AED",detail:"اتصل بالرقم 122 أو اطلب من شخص محدد أن يتصل؛ واذكر المكان أولًا (المبنى، الطابق، المدخل). وأرسل شخصًا آخر لإحضار حقيبة الإسعافات الأولية وجهاز AED، وشخصًا ثالثًا لانتظار الإسعاف عند المدخل الرئيسي.",critical:!0},{title:"إذا لم يتنفس طبيعيًا: CPR",detail:"ضعه على ظهره على سطح صلب وابدأ الضغطات الصدرية. وعند وصول جهاز AED شغّله فورًا واتبع تعليماته الصوتية.",critical:!0},{title:"إذا كان يتنفس طبيعيًا",detail:"إذا لم يكن هناك اشتباه بإصابة في الرقبة أو الظهر أو الورك أو الحوض، فضعه على جنبه (وضعية الإفاقة). لا تعطه شيئًا بالفم، وابقَ معه وراقب تنفسه حتى وصول الإسعاف.",critical:!0},{title:"بعد الحادث",detail:"سجّل الحادث (الوقت، ما حدث، ما تم فعله)، وأعد تجهيز حقيبة الإسعافات الأولية واجعل جهاز AED جاهزًا للعمل. وناقش مع الفريق باختصار ما نجح وما يحتاج إلى تحسين."}],warnings:["لا تعطِ أي شيء (ماء، طعام، دواء) لشخص فاقد الوعي أو غير واعٍ تمامًا: قد يختنق.","لا تحرّك من أصيب بعد سقوط أو ضربة على الرأس أو الظهر، إلا إذا كان المكان خطرًا أو احتاج إلى CPR: التحريك قد يزيد إصابة العمود الفقري سوءًا.","لا تعطِ أدوية من الحقيبة؛ ساعد الشخص فقط على استخدام جهازه الخاص الذي وصفه له الطبيب (مثل حاقن الأدرينالين الذاتي أو جهاز الاستنشاق)."],tips:["علّق في كل طابق أسماء المدربين وأرقامهم ومكان حقيبة الإسعافات الأولية وجهاز AED.","ضع جهاز AED في مكان ظاهر غير مقفل يعرفه كل الموظفين ويصلون إليه بسرعة.","افحص حقيبة الإسعافات الأولية بانتظام وبعد كل استخدام، واستبدل المواد المنتهية الصلاحية.","تدرّب على مكالمة 122 كأنها حقيقية: المكان أولًا، ثم ما حدث وعدد المصابين."],activity:{prompt:"في قاعة الاجتماعات يسقط موظف فجأة ولا يستجيب ولا يتنفس طبيعيًا. أنت مدرّب وجهاز AED في الممر. ماذا تفعل؟",options:[{text:"أطلب من شخص محدد الاتصال بالرقم 122 وإحضار جهاز AED، وأبدأ CPR فورًا",correct:!0,feedback:"صحيح: الطلب المباشر من شخص محدد يضمن التنفيذ، والإنعاش المبكر مع AED يزيدان فرصة النجاة."},{text:"أذهب لإحضار جهاز AED ثم أتصل بالرقم 122",correct:!1,feedback:"ليس الأفضل: يوجد آخرون في القاعة؛ وزّع المهام حتى لا يتأخر الإنعاش والاتصال."},{text:"أضعه في وضعية الإفاقة وأنتظر الإسعاف",correct:!1,feedback:"غير صحيح: وضعية الإفاقة لمن يتنفس طبيعيًا فقط؛ هذا الشخص يحتاج إلى CPR."},{text:"أرش الماء على وجهه ليستفيق",correct:!1,feedback:"غير صحيح: الماء لا يوقظ من توقف قلبه، ويضيّع وقتًا ثمينًا."}]},caseStudy:[{prompt:"في الأرشيف سقط زميل عن سلّم. هو واعٍ ويتنفس طبيعيًا، لكنه يقول إن ظهره يؤلمه كثيرًا وهو ممدد على الأرض. ماذا تفعل؟",options:[{text:"لا أحرّكه، وأتصل بالرقم 122 وأبقى معه وأطمئنه",correct:!0,feedback:"صحيح: بعد السقوط وألم الظهر قد يزيد التحريك إصابة العمود الفقري؛ والمكان آمن فلا داعي لتحريكه."},{text:"أساعده على الوقوف والجلوس على كرسي",correct:!1,feedback:"غير صحيح: الوقوف قد يزيد إصابة الظهر سوءًا؛ انتظر فريق الإسعاف."},{text:"أضعه على جنبه (وضعية الإفاقة)",correct:!1,feedback:"غير صحيح: لا تُستخدم وضعية الإفاقة مع الاشتباه بإصابة الظهر، وهو واعٍ ويتنفس."},{text:"أعطيه حبة مسكّن من الحقيبة",correct:!1,feedback:"غير صحيح: لا تُعطى الأدوية في الإسعاف الأولي هنا؛ قد يحتاج إلى جراحة والأطباء يقررون."}]},{prompt:"قبل وصول الإسعاف، يتوقف الزميل فجأة عن الاستجابة ولا يتنفس طبيعيًا. ماذا تفعل الآن؟",options:[{text:"أضعه على ظهره وأبدأ CPR وأطلب جهاز AED",correct:!0,feedback:"صحيح: الإنعاش هو الحالة التي يُسمح فيها بالتحريك؛ فمن دونه لن ينجو حتى مع إصابة الظهر."},{text:"أتركه في مكانه لأن ظهره مصاب وأنتظر",correct:!1,feedback:"غير صحيح: إن لم يتنفس طبيعيًا فالانتظار ينتهي بالوفاة؛ الإنعاش أهم من حماية الظهر."},{text:"أضعه على جنبه ليبقى مجرى التنفس مفتوحًا",correct:!1,feedback:"غير صحيح: من لا يتنفس طبيعيًا يحتاج إلى CPR على ظهره، لا إلى وضعية الإفاقة."},{text:"أرش الماء البارد على وجهه ليستفيق",correct:!1,feedback:"غير صحيح: الماء لا يعيد تشغيل القلب؛ وكل دقيقة بلا إنعاش تقلل فرصة النجاة."}]}],realCase:"في دائرة حكومية سقط موظف في الممر ولم يكن يتنفس طبيعيًا. طلبت زميلة مدرّبة المساعدة بصوت عالٍ. اتصل أحدهم بالرقم 122 وذكر المكان أولًا: المبنى والطابق والمدخل القريب. وأحضر الثاني جهاز AED من مكانه الظاهر الذي يعرفه الجميع. وانتظر زميل ثالث الإسعاف عند المدخل الرئيسي ودلّهم على الطريق. واستمر الإنعاش واستخدام AED حتى تسلّم فريق الإسعاف. الدرس: معرفة مكان AED وتوزيع المهام يوفّران وقتًا ثمينًا."},{id:5,code:"GOV-105",icon:"Flame",accent:"#ea580c",title:"الحريق ومطفآت الحريق في الدوائر",subtitle:"Fire Prevention & Extinguisher Use",summary:"الوقاية من الحرائق واستخدام مطفآت الحريق في المباني الحكومية",blocks:[{body:"يشكّل اندلاع الحرائق في الدوائر خطرًا جديًا. فالورق والحواسيب والأسلاك القديمة والتحميل الكهربائي الزائد هي الأسباب الرئيسية للحرائق. ويحمي برنامج الوقاية والاستعداد حياة الموظفين والمال العام."},{heading:"1. أسباب الحرائق في الدوائر",body:"الأسباب الرئيسية:",points:["التحميل الكهربائي الزائد: توصيل أجهزة كثيرة بمقبس واحد.","الورق والوثائق: مواد سريعة الاشتعال.","السجائر وأعواد الثقاب: سبب رئيسي لاشتعال الحرائق.","المدافئ وأجهزة التدفئة المتنقلة: خطر فصل الشتاء.","المطابخ الصغيرة: أثناء إعداد الشاي والقهوة.","البطاريات والشواحن: الارتفاع المفرط في درجة الحرارة."]},{heading:"2. أنواع مطفآت الحريق",body:"تحتاج الدوائر إلى الأنواع الآتية:",points:["مطفأة المسحوق الجاف (ABC): لحرائق الفئات A وB وC — وليست للمعادن (D) ولا لزيوت الطبخ (K).","مطفأة CO₂: لحرائق الأجهزة الكهربائية — لا تُلحق ضررًا بالحواسيب.","مطفأة الماء: للفئة A فقط (الورق والخشب والملابس) — وليست للكهرباء ولا للزيوت.","يوصي الكود البريطاني BS 5306-8 بمطفأتين (2) على الأقل في كل طابق (باستثناء الطوابق الصغيرة جدًا)؛ أما القاعدة الخاصة بدوائر دهوك فتضعها مديرية الدفاع المدني، ولم تُؤكَّد بعدُ.","ضع مطفآت الحريق قرب الأبواب وعلى مسارات الإخلاء.","فحص بصري شهري (مسمار الأمان والختم سليمان، والملصق مقروء، ومؤشر الضغط في المنطقة الخضراء إن وُجد؛ ومطفأة CO₂ لا مقياس لها، لذا ارفعها لتتأكد من أنها ممتلئة) وفحص وصيانة كل سنة من قِبل شخص مختص (NFPA 10)."]},{heading:"3. طريقة PASS",body:`قبل استخدام المطفأة (يجب أن تكون كل الإجابات «نعم»):
• الحريق صغير وفي بدايته، مثل حريق في سلة مهملات أو مقلاة.
• المطفأة مناسبة لهذا النوع من الحريق.
• طريق الخروج خلفك، والنار ليست بينك وبين المخرج.
• تمّ إطلاق الإنذار: نُبِّه الآخرون واتُّصل بالرقم 115.
• أنت مدرَّب على استخدام المطفأة.
• لا يوجد دخان أو حرارة يمنعان خروجك.
• إذا لم تنطفئ النار فورًا، فتوقّف واخرج وأغلق الباب خلفك.

طريقة PASS هي الطريقة العامة لمعظم مطفآت الحريق اليدوية. أما مطفآت الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والعوامل النظيفة (Clean Agent) والمطفآت ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة. كيفية استخدام مطفأة الحريق:`,points:["P = Pull (اسحب): اسحب مسمار الأمان وانزعه.","A = Aim (وجِّه): وجِّه فوهة الخرطوم (Nozzle) نحو قاعدة النار.","S = Squeeze (اضغط): اضغط مقبض المطفأة بقوة.","S = Sweep (حرِّك): حرِّك الفوهة عند قاعدة النار من جانب إلى آخر.","المسافة: ابدأ من المسافة المحددة على ملصق المطفأة أو في تعليمات الشركة المصنّعة، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار.","اترك طريق الخروج خلفك؛ وإذا لم تنطفئ النار فورًا أو بدأت تنتشر، فاخرج وأغلق الباب خلفك وتأكد من الاتصال بالرقم 115."]},{heading:"4. أنظمة الإنذار",body:"الأنظمة الضرورية في الدوائر:",points:["صفارة إنذار الحريق: يجب أن تُسمع في كل طابق.","زر الإنذار اليدوي (Pull Station): قرب المخارج.","كشف الدخان (Smoke Detection): وفق ما يتطلبه كود الحريق الخاص بالمبنى (Fire Code) (ولم يُؤكَّد بعدُ المتطلب الخاص بدوائر دهوك).","إضاءة الطوارئ: تعمل تلقائيًا عند انقطاع الكهرباء.","اكتب الرقم 115 على جدار كل غرفة."]}],media:[{kind:"video",src:"media/videos/gov_fire_prevention.mp4",title:"الوقاية من الحرائق",description:"إرشادات كاملة للدوائر"},{kind:"image",src:"media/images/gov_pass_method.png",title:"طريقة PASS",description:"خطوة بخطوة"},{kind:"image",src:"media/images/gov_extinguisher_types.png",title:"أنواع مطفآت الحريق",description:"ABC، CO₂، الماء"}],quiz:[{question:"أي مطفأة حريق هي الأفضل لحرائق الحواسيب؟",options:[{text:"مطفأة الماء",correct:!1},{text:"مطفأة CO₂",correct:!0},{text:"مطفأة الرغوة",correct:!1},{text:"بطانية",correct:!1}],explanation:"لا تُلحق CO₂ ضررًا بالحواسيب ولا توصل الكهرباء."},{question:"في طريقة PASS، ماذا يعني الحرف A؟",options:[{text:"Alert (التنبيه)",correct:!1},{text:"Aim (وجِّه)",correct:!0},{text:"Action (التنفيذ)",correct:!1},{text:"Away (بعيدًا)",correct:!1}],explanation:"A = Aim: وجِّه فوهة الخرطوم نحو قاعدة النار."},{question:"كم مطفأة حريق على الأقل يوصي بها الكود البريطاني BS 5306-8 في كل طابق؟",options:[{text:"مطفأة واحدة (1)",correct:!1},{text:"مطفأتان (2)",correct:!0},{text:"3 مطفآت",correct:!1},{text:"5 مطفآت",correct:!1}],explanation:"يوصي الكود البريطاني BS 5306-8 بمطفأتين (2) على الأقل في كل طابق (باستثناء الطوابق الصغيرة جدًا)، ويجب ألّا تتجاوز مسافة الوصول إليها الحد المسموح به. أما القاعدة الخاصة بدوائر دهوك فتضعها مديرية الدفاع المدني، ولم تُؤكَّد بعدُ."},{question:"أنت مدرّب والمطفأة المناسبة في يدك، لكن الدخان بدأ يملأ الممر الذي هو طريق خروجك. ماذا تفعل؟",options:[{text:"أخرج فورًا لأن طريق خروجي في خطر",correct:!0},{text:"أستخدم المطفأة بسرعة قبل أن يزداد الدخان",correct:!1},{text:"أنخفض وأبقى في الغرفة حتى أطفئ النار",correct:!1},{text:"أطلب من زميل فتح النافذة ليخرج الدخان",correct:!1}],explanation:"في فحص «نعم أو لا»، الدخان أو الحرارة التي تسد طريق الخروج تعني «لا»؛ عندها لا تُستخدم المطفأة وتخرج."},{question:"أطفأت حريقًا صغيرًا بالمطفأة وبقي نصفها. ماذا تفعل بالمطفأة بعد ذلك؟",options:[{text:"أبلغ المسؤول لإعادة تعبئتها أو استبدالها",correct:!0},{text:"أعيدها إلى مكانها لأن نصفها ما زال ممتلئًا",correct:!1},{text:"أتركها قرب مكتبي لحريق آخر",correct:!1},{text:"أعيد مسمار الأمان وأستخدمها كما هي",correct:!1}],explanation:"المطفأة المستعملة قد ينخفض ضغطها فتفرغ بسرعة في الحريق القادم؛ لذلك تُعاد تعبئتها بعد كل استخدام."},{question:"ترى حريقًا في الدائرة. أيّ تصرف يسبق أي محاولة إطفاء؟",options:[{text:"إطلاق الإنذار والتأكد من الاتصال بالرقم 115",correct:!0},{text:"فتح النوافذ ليخرج الدخان من الغرفة",correct:!1},{text:"جمع الوثائق المهمة من المكاتب القريبة",correct:!1},{text:"الاتصال بالمدير لأخذ الإذن",correct:!1}],explanation:"إذا فشل الإطفاء يجب أن يكون الآخرون قد أُنذروا وأن يكون فريق 115 في الطريق؛ لذلك يأتي الإنذار أولًا دائمًا."}],steps:[{title:"الإنذار أولًا",detail:"اصرخ «حريق!» واستخدم زر الإنذار اليدوي واتصل بالرقم 115، أو تأكد من أن شخصًا محددًا قد اتصل. وهذا يسبق أي محاولة إطفاء.",critical:!0},{title:"فحص «نعم أو لا»",detail:"هل الحريق صغير وفي بدايته؟ هل المطفأة مناسبة؟ هل طريق الخروج خلفك؟ هل أُطلق الإنذار؟ هل أنت مدرّب؟ هل الطريق خالٍ من الدخان والحرارة؟ إذا كانت إجابة واحدة «لا» فاخرج.",critical:!0},{title:"PASS بأمان",detail:"ابدأ من المسافة المذكورة على الملصق وطريق الخروج خلفك. اسحب مسمار الأمان، ووجّه الفوهة إلى قاعدة النار، واضغط المقبض، وحرّكها من جانب إلى آخر. ولا تقترب إلا عندما تصغر النار."},{title:"إذا لم تنطفئ فورًا فاخرج",detail:"إذا لم تنطفئ النار فورًا أو انتشرت أو ازداد الدخان: توقف واخرج وأغلق الباب خلفك. وفي نقطة التجمع أخبر فريق 115 بمكان الحريق.",critical:!0},{title:"بعد الاستخدام",detail:"أبلغ المسؤول عن كل مطفأة استُخدمت ولو قليلًا لإعادة تعبئتها أو استبدالها. ولا تُعِدها إلى مكانها كما هي."}],warnings:["لا تستخدم الماء أو مطفأة الماء على حريق كهربائي أو حريق زيت الطهي: الماء يوصل الكهرباء ويجعل الزيت المشتعل ينفجر وينتشر.","لا تسمح للنار بأن تصبح بينك وبين طريق الخروج: إذا فرغت المطفأة أو كبرت النار ستُحاصر.","لا تسدّ الطريق إلى المطافئ وأزرار الإنذار بالمكاتب أو الصناديق أو الأثاث: كل ثانية مهمة في الطوارئ."],tips:["اعرف مكان أقرب مطفأتين وأقرب زر إنذار في طابقك.","في المطبخ الصغير لا تبتعد عمّا هو على النار، وأطفئ الغلايات والمدافئ في نهاية الدوام.","ضع المدافئ بعيدًا عن الستائر والأوراق والمكاتب، ولا تجفف عليها الملابس أبدًا.","إذا وجدت في الفحص الشهري أن المسمار أو الختم مفقود أو أن مؤشر مقياس الضغط خارج اللون الأخضر، فأبلغ المسؤول فورًا."],activity:{prompt:"في مطبخ الدائرة الصغير اشتعل الزيت في مقلاة بينما كان زميلك يطهو. أقرب مطفأة هي مطفأة ماء، وغطاء المقلاة على الطاولة. ماذا تفعل؟",options:[{text:"أطفئ مصدر الحرارة إن كان ذلك آمنًا وأضع الغطاء على المقلاة؛ وإن لم تنطفئ أخرج وأتصل بالرقم 115",correct:!0,feedback:"صحيح: الغطاء يقطع الهواء عن النار، وإطفاء الحرارة يمنع تغذيتها؛ ولا تحرّك المقلاة."},{text:"أستخدم مطفأة الماء على المقلاة",correct:!1,feedback:"غير صحيح: الماء على الزيت المشتعل يجعله ينفجر وينثر الزيت المشتعل في المطبخ كله."},{text:"أحمل المقلاة وأخرج بها بسرعة",correct:!1,feedback:"غير صحيح: قد ينسكب الزيت الساخن فيحرقك ويحرق غيرك وينشر النار في الطريق."},{text:"أرمي قطعة قماش مبللة بالماء على المقلاة",correct:!1,feedback:"غير صحيح: القماش المبلل يضيف ماء إلى الزيت وقد ينشر النار؛ استخدم غطاء معدنيًا أو بطانية حريق."}]},caseStudy:[{prompt:"اندلع حريق صغير في سلة الأوراق في قاعة الاجتماعات. أنت مدرّب ومطفأة البودرة الجافة (ABC) قرب الباب. ولم يُطلق أحد الإنذار بعد. ماذا تفعل؟",options:[{text:"أنبّه بصوت عالٍ وأطلب من أحدهم الاتصال بالرقم 115، ثم أستخدم المطفأة بعد فحص «نعم أو لا»",correct:!0,feedback:"صحيح: الإنذار يسبق الإطفاء، حتى يكون الجميع مستعدين إن فشلت المحاولة."},{text:"أرش المطفأة بسرعة على أعلى اللهب دون تنبيه أحد",correct:!1,feedback:"غير صحيح: الهدف قاعدة النار لا أعلاها؛ ومن دون إنذار لن يكون أحد مستعدًا إن لم تنطفئ."},{text:"أغلق الباب وأعود إلى مكتبي",correct:!1,feedback:"غير صحيح: إغلاق الباب جيد، لكن من دون إنذار واتصال بالرقم 115 تكبر النار ولا يعلم أحد."},{text:"أسكب الشاي على سلة الأوراق",correct:!1,feedback:"غير صحيح: كوب شاي لا يطفئ حريق أوراق ويضيع الوقت."}]},{prompt:"بدأت باستخدام PASS. صغرت النار، لكنها امتدت فجأة إلى الستارة والدخان يزداد. والمطفأة توشك أن تفرغ. ماذا تفعل الآن؟",options:[{text:"أتوقف وأخرج وأغلق الباب وأبلغ فريق 115 في نقطة التجمع",correct:!0,feedback:"صحيح: الحريق الذي ينتشر لم يعد صغيرًا؛ والباب المغلق يبطئ النار والدخان ويمنح الناس وقتًا للخروج."},{text:"أحضر مطفأة أخرى من طابق آخر وأعود وحدي",correct:!1,feedback:"غير صحيح: خلال ذلك تكبر النار والدخان وقد يقطعان طريقك."},{text:"أفتح النافذة ليخرج الدخان وأواصل",correct:!1,feedback:"غير صحيح: الهواء الجديد يغذي النار ويسرّع انتشارها."},{text:"أبقى في الغرفة وأنتظر فريق 115",correct:!1,feedback:"غير صحيح: البقاء في غرفة تنتشر فيها النار قد ينتهي بفقدان الوعي من الدخان."}]}],realCase:"في دائرة حكومية بقيت مدفأة مشتعلة قرب ستارة فاشتعلت الستارة. صاح موظف «حريق!»، وضغط زميل زر الإنذار واتصل بالرقم 115. وأجرى موظف مدرّب فحص «نعم أو لا»: كانت النار صغيرة، ومطفأة ABC في متناول اليد، والباب خلفه. فأطفأ النار، وتفقّد فريق 115 الغرفة. واستُبدلت المطفأة المستعملة في اليوم نفسه. الدرس: الإنذار قبل الإطفاء، والمطفأة المستعملة تُستبدل فورًا."},{id:6,code:"GOV-106",icon:"Activity",accent:"#d97706",title:"الزلازل في المباني الحكومية",subtitle:"Earthquake Safety in Gov Buildings",summary:"كيفية حماية النفس والإخلاء الآمن أثناء الزلزال",blocks:[{body:"يقع إقليم كوردستان في منطقة نشطة زلزاليًا. والمباني الحكومية، ولا سيما القديمة منها، معرّضة للخطر. ويُسهم الاستعداد ومعرفة الإجراءات في إنقاذ الأرواح."},{heading:"1. أثناء الزلزال",body:"إذا كنت داخل الدائرة:",points:["انخفض (Drop): انزل فورًا على ركبتيك ويديك.","احتمِ (Cover): ادخل تحت طاولة متينة، بعيدًا عن النوافذ والخزائن الثقيلة (وليس عند المدخل)، واحمِ رأسك ورقبتك.","تمسّك (Hold On): أمسك بساق الطاولة حتى يتوقف الاهتزاز.","لا تركض نحو الخارج — فكثير من الإصابات تحدث أثناء الركض وبسبب سقوط القطع.","لا تستخدم المصعد — فقد يتوقف وتبقى عالقًا فيه.","إذا كنت في مكان مفتوح: ابتعد عن المباني وأسلاك الكهرباء والأعمدة."]},{heading:"2. بعد الزلزال",body:"الخطوات بعد الزلزال:",points:["افحص نفسك وزملاءك بحثًا عن إصابات.","اخرج عبر السلالم (لا المصعد!)","إذا شممت رائحة غاز أو سمعت صوت تسرّبه: اخرج واتصل بالرقم 115 من الخارج؛ ولا يُغلق الغازَ من الصمام الرئيسي إلا الموظفون المدرَّبون والمكلَّفون، إذا أمكن الوصول إليه بأمان، دون دخول المكان الذي تجمّع فيه الغاز ودون تشغيل أيّ مفتاح.","توجّه إلى نقطة التجمع وعُدّ الأشخاص.","إذا وُجد مصابون أو أشخاص عالقون تحت الأنقاض، فاتصل بالرقمين 115 و122.","انتبه إلى الهزات الارتدادية (Aftershocks).","لا تعد إلى داخل المبنى حتى يتأكد المختصون من سلامته."]},{heading:"3. الاستعداد المسبق",body:"التحضيرات الضرورية:",points:["أعِدّ خطة للزلازل وعلّقها على الجدار.","ثبّت الخزائن والرفوف والأجهزة الثقيلة بالجدار.","جهّز حقيبة طوارئ في كل طابق.","فحص المبنى سنويًا من قِبل مهندس مختص.","تمرين «انخفض، احتمِ، تمسّك» (Drop, Cover, Hold On) كل 3 أشهر.","حدِّد نقطتَي تجمع (واحدة قريبة وأخرى بعيدة)."]},{heading:"4. مسؤولية المديرين",body:"يجب على المديرين:",points:["تعيين مسؤول عن الزلازل لكل طابق.","إبقاء قائمة الموظفين جاهزة لعدّ الأشخاص.","وضع خطة خاصة للأشخاص ذوي الاحتياجات الخاصة.","فحص نظام الإنذار بصورة منتظمة.","كتابة أرقام الطوارئ (115، 122، 104) في كل غرفة."]},{heading:"5. إذا حوصرت تحت الأنقاض",body:"حافظ على طاقتك وأرشد المنقذين بهذه الطرق:",points:["غطِّ فمك وأنفك بقطعة قماش أو بملابسك حتى لا تستنشق الغبار.","اطرق على أنبوب أو جدار أو استخدم صفّارة حتى يعثر عليك فريق الإنقاذ.","الصراخ كملاذ أخير فقط: فهو يُدخل الغبار إلى الصدر ويستنزف الطاقة.","لا تشعل عود ثقاب أو نارًا فقد يكون هناك غاز قريب؛ استخدم ضوء الهاتف."]}],media:[{kind:"video",src:"media/videos/gov_earthquake.mp4",title:"الزلزال في الدائرة",description:"تمرين عملي"},{kind:"image",src:"media/images/gov_drop_cover_hold.png",title:"انخفض، احتمِ، تمسّك (Drop, Cover, Hold On)",description:"خطوة بخطوة"}],quiz:[{question:"أثناء الزلزال، ما أول ما يجب فعله؟",options:[{text:"الركض نحو الخارج",correct:!1},{text:"الدخول إلى المصعد",correct:!1},{text:"انخفض، احتمِ، تمسّك (Drop, Cover, Hold On)",correct:!0},{text:"فتح النوافذ",correct:!1}],explanation:"انخفض تحت طاولة متينة، واحتمِ، وتمسّك حتى يتوقف الاهتزاز."},{question:"بعد الزلزال، ماذا نستخدم للخروج من المبنى؟",options:[{text:"المصعد",correct:!1},{text:"سلالم المبنى",correct:!0},{text:"النوافذ",correct:!1},{text:"لا فرق",correct:!1}],explanation:"اخرج دائمًا عبر السلالم — فقد يتوقف المصعد."},{question:"وفقًا لهذا البرنامج، كم مرة يلزم إجراء تمرين الزلزال في الدائرة؟",options:[{text:"كل سنة",correct:!1},{text:"كل 6 أشهر",correct:!1},{text:"كل 3 أشهر",correct:!0},{text:"مرة واحدة فقط",correct:!1}],explanation:"يوصي هذا البرنامج بإجراء تمرين عملي مرة واحدة كل 3 أشهر."},{question:"يبدأ الزلزال وأنت في ممر لا طاولات فيه ولا كراسي. ماذا تفعل؟",options:[{text:"أنخفض بجانب جدار داخلي وأحمي رأسي ورقبتي بذراعيّ",correct:!0},{text:"أركض بسرعة نحو أقرب باب خروج",correct:!1},{text:"أقف عند النافذة لأرى ما يحدث في الخارج",correct:!1},{text:"أدخل المصعد لأصل إلى الطابق الأرضي بسرعة",correct:!1}],explanation:"إن لم توجد طاولة فانخفض بجانب جدار داخلي بعيدًا عن النوافذ واحمِ رأسك ورقبتك؛ فالركض والنوافذ والمصاعد خطرة."},{question:"بعد الزلزال تشم رائحة غاز في الممر، والصمام الرئيسي في نهاية الممر حيث الرائحة أقوى. ماذا تفعل؟",options:[{text:"لا أقترب من الصمام، وأخرج وأنبّه الآخرين وأتصل بالرقم 115 من الخارج",correct:!0},{text:"أسرع إلى نهاية الممر وأغلق الصمام قبل أي شيء آخر",correct:!1},{text:"أتصل بالرقم 115 بهاتفي من داخل الممر حتى لا يضيع أي وقت",correct:!1},{text:"أشعل أضواء الممر لأرى بوضوح مكان تسرب الغاز",correct:!1}],explanation:"لا يُغلق الصمام إلا إذا كان قريبًا ويمكن بلوغه دون دخول المكان الذي تجمّع فيه الغاز ودون أي مفتاح. والصمام هنا في مكان الغاز، لذا اخرج واتصل من الخارج."},{question:"زميلك يستخدم كرسيًا متحركًا ويبدأ الزلزال. ماذا يفعل؟",options:[{text:"تقفل العجلات وتنحني وتحمي رأسها ورقبتها",correct:!0},{text:"تتحرك بالكرسي بسرعة نحو المصعد",correct:!1},{text:"تنزل من الكرسي إلى الأرض تحت الطاولة",correct:!1},{text:"تتجه إلى باب الغرفة وتبقى عنده",correct:!1}],explanation:"من يستخدم كرسيًا متحركًا يقفل العجلات حتى لا يتحرك الكرسي، وينحني ويحمي رأسه ورقبته؛ فالحركة أثناء الاهتزاز والأبواب والمصاعد خطرة."}],steps:[{title:"انخفض، احتمِ، تمسّك",detail:"عند بدء الاهتزاز انخفض في مكانك على يديك وركبتيك، وادخل تحت طاولة متينة بعيدًا عن النوافذ والخزائن الثقيلة، وتمسّك بساق الطاولة حتى يتوقف الاهتزاز. وإن لم توجد طاولة فاجلس بجانب جدار داخلي واحمِ رأسك ورقبتك بذراعيك.",critical:!0},{title:"ابقَ مكانك حتى يتوقف الاهتزاز",detail:"لا تركض إلى الخارج أثناء الاهتزاز ولا تستخدم المصعد. وإذا كنت على كرسي متحرك فاقفل العجلات وانحنِ واحمِ رأسك ورقبتك.",critical:!0},{title:"بعد الاهتزاز: انظر وافحص",detail:"افحص نفسك وزملاءك بحثًا عن إصابات. وإذا شممت رائحة غاز أو سمعت صوت تسربه: لا تستخدم أي مفتاح أو مصباح أو هاتف في الداخل، واخرج واتصل بالرقم 115 من الخارج.",critical:!0},{title:"اخرج عبر الدرج بحذر",detail:"اخرج عبر الدرج منتبهًا للأنقاض والزجاج المكسور والأسلاك الساقطة، وابقَ في الخارج بعيدًا عن الجدران والنوافذ وأسلاك الكهرباء. وتوقّع الهزات الارتدادية."},{title:"العدّ والإبلاغ",detail:"عُدّ الأشخاص في نقطة التجمع. وأبلغ فريق 115 باسم كل مفقود أو محاصر وآخر مكان معروف له، واتصل بالرقم 122 إذا وُجد مصابون. ولا يدخل أحد للبحث.",critical:!0},{title:"العودة بعد الفحص",detail:"يبقى المبنى خاليًا حتى يؤكد الخبراء المعنيون سلامته، حتى لو لم تظهر أضرار من الخارج."}],warnings:["لا تقف عند الباب ولا تعتمد على «مثلث الحياة»: الباب لا يحميك من الأشياء المتساقطة؛ انخفض، احتمِ، تمسّك.","إذا وُجدت رائحة غاز بعد الزلزال فلا تشعل عود ثقاب أو مصباحًا أو مفتاحًا، ولا تدخل المكان الذي تجمّع فيه الغاز لإغلاق الصمام: شرارة واحدة قد تسبب انفجارًا.","لا تعد إلى المبنى بعد الزلزال من أجل الوثائق أو الأغراض: قد تُسقط الهزات الارتدادية مبنى أضعفه الزلزال."],tips:["ضع الملفات والأشياء الثقيلة على الرفوف السفلى، ولا تعلّق شيئًا ثقيلًا فوق المكاتب.","احتفظ بمصباح يدوي وصفّارة وحذاء متين تحت مكتبك.","في التمرين اعتبر إحدى نقطتي التجمع مغلقة حتى يعرف الموظفون الطريق إلى الأخرى.","ضع الخطة مسبقًا مع الموظفين ذوي الاحتياجات الخاصة: من يساعدهم وعبر أي طريق."],activity:{prompt:"أنت عند مكتب الاستقبال وعدد من المواطنين يقفون قرب نوافذ زجاجية كبيرة. يبدأ الزلزال. ماذا تفعل؟",options:[{text:"أنادي بصوت عالٍ «انخفضوا، احتموا، تمسّكوا» بعيدًا عن النوافذ، وأحتمي أنا تحت المكتب",correct:!0,feedback:"صحيح: يحتاج المراجعون إلى تعليمات قصيرة وواضحة؛ والزجاج يتكسر ويسبب جروحًا خطيرة."},{text:"أقود المواطنين بسرعة نحو الباب الرئيسي والخارج",correct:!1,feedback:"غير صحيح: تحدث إصابات كثيرة أثناء الركض ومن سقوط الزجاج والقطع قرب المداخل."},{text:"أقف عند باب الغرفة لأنه أمتن مكان",correct:!1,feedback:"غير صحيح: الباب في المباني الحديثة ليس أمتن من غيره ولا يحمي من الأشياء المتساقطة."},{text:"أقود المواطنين إلى المصعد لينزلوا بسرعة",correct:!1,feedback:"غير صحيح: قد يتوقف المصعد أثناء الزلزال ويُحتجز الناس داخله."}]},caseStudy:[{prompt:"توقف الاهتزاز. سقطت قطع من السقف والغبار في كل مكان. وفي يد أحد الزملاء جرح صغير، ورائحة غاز تأتي من مطبخ الطابق. ماذا تفعل؟",options:[{text:"أُخرج الجميع عبر الدرج دون استخدام المفاتيح أو الهواتف في الداخل، وأتصل بالرقم 115 من الخارج",correct:!0,feedback:"صحيح: رائحة الغاز بعد الزلزال خطر انفجار؛ ويمكن معالجة الجرح الصغير في الخارج."},{text:"أذهب إلى المطبخ لأغلق صمام الغاز",correct:!1,feedback:"غير صحيح: لا يُغلق الصمام إلا إذا كان قريبًا ويمكن بلوغه دون دخول المكان الذي تجمّع فيه الغاز؛ والغاز هنا في المطبخ."},{text:"أشعل الأضواء لأرى الأضرار بشكل أفضل",correct:!1,feedback:"غير صحيح: المفتاح قد يُحدث شرارة تُشعل الغاز."},{text:"نبقى عند مكاتبنا لأن هزات ارتدادية قد تأتي",correct:!1,feedback:"غير صحيح: بعد توقف الاهتزاز يجب الخروج بحذر، خاصة مع وجود رائحة غاز."}]},{prompt:"الجميع في نقطة التجمع القريبة. ظهر شق كبير في جدار المبنى المطل على النقطة، ويريد المدير أن يعود الموظفون لإحضار الملفات المهمة. ماذا تقترح؟",options:[{text:"ننتقل إلى نقطة التجمع البعيدة ونعدّ الأشخاص، ولا يدخل أحد حتى يؤكد الخبراء سلامة المبنى",correct:!0,feedback:"صحيح: هذا سبب وجود النقطة البعيدة؛ فالجدار المتشقق قد يسقط مع هزة ارتدادية."},{text:"يذهب متطوعان فقط بسرعة ويحضران الملفات",correct:!1,feedback:"غير صحيح: التطوع لا يحمي الحياة؛ الملفات تُستعاد من النسخ، أما الأرواح فلا."},{text:"ندخل الطابق الأول فقط بين الهزات الارتدادية",correct:!1,feedback:"غير صحيح: لا أحد يعرف متى تأتي الهزة التالية، والطابق الأول قد ينهار أيضًا."},{text:"نبقى في النقطة القريبة وننتظر لأنها المخطط لها",correct:!1,feedback:"غير صحيح: يجب أن تكون نقطة التجمع آمنة؛ وعندما يتشقق جدار فوقها ينتقل الجميع إلى النقطة البعيدة."}]}],realCase:"أثناء الدوام هزّ زلزال متوسط مبنى حكوميًا قديمًا. كان الموظفون قد تدربوا عدة مرات على «انخفض، احتمِ، تمسّك» فاحتموا فورًا تحت المكاتب. وبقيت الخزائن المثبتة بالجدران في مكانها، أما خزانة غير مثبتة فسقطت على كرسي فارغ. وبعد الاهتزاز أخرج مسؤولو الطوابق الناس عبر الدرج. وشمّ أحد الموظفين رائحة غاز، فلم يستخدم أحد المفاتيح واتُّصل بالرقم 115 من الخارج. وأُغلق المبنى حتى فحصه المهندسون. الدرس: تثبيت الخزائن والتدريب يحميان الأرواح."},{id:7,code:"GOV-107",icon:"Wind",accent:"#475569",title:"السلامة من الغاز والتهوية",subtitle:"Gas Safety & Ventilation",summary:"مخاطر الغاز في الدوائر وأهمية التهوية السليمة",blocks:[{body:"تُستخدم المدافئ وأجهزة التدفئة العاملة بالغاز والنفط الأبيض (الكيروسين) بكثرة في الدوائر خلال فصل الشتاء. وقد يؤدي تسرّب الغاز إلى الانفجار والحريق، كما أن الاحتراق غير الكامل يُنتج غاز أول أكسيد الكربون (CO) السام، وهو غاز عديم اللون والرائحة وقد يكون قاتلًا. والتهوية السليمة ومعرفة المخاطر تُنقذان الأرواح."},{heading:"1. خطر غاز أول أكسيد الكربون (CO)",body:"غاز CO قاتل صامت:",points:["غاز CO عديم اللون والرائحة والطعم — ولا يمكن اكتشافه بالحواس.","الأعراض: الصداع، والدوخة، والغثيان والتقيؤ، واضطراب الوعي؛ ثم فقدان الوعي والوفاة.","المصدر: مدافئ الغاز والنفط الأبيض (الكيروسين) في الغرف غير المهوّاة.","الشتاء هو الفصل الأخطر، لأن الأبواب والنوافذ تكون مغلقة.","حدّ OSHA للعاملين هو 50 ppm (متوسط 8 ساعات)، لكن يجب أن يكون تركيز CO في غرف العمل قريبًا من الصفر؛ فأي تركيز لغاز CO دليل على نقص التهوية."]},{heading:"2. قواعد التهوية السليمة",body:"التهوية اللازمة في الدوائر:",points:["عند تشغيل مدفأة بلا مدخنة، اترك نافذة مفتوحة قليلًا لدخول الهواء النقي.","الغرف التي فيها مدفأة موصولة بمدخنة (Chimney): لا تشغّل مروحة شفط (Extractor Fan) في الوقت نفسه إلا إذا تحقّق فنّي مختص من أن دخان المدفأة ما زال يخرج بأمان؛ فالمروحة قد تسحب الدخان وغاز CO إلى داخل الغرفة، حتى لو كانت في غرفة أخرى.","أنبوب المدخنة (Chimney): يجب أن يكون سليمًا ومفتوحًا، غير مسدود.","لا تسدّ الممرات ومسارات الإخلاء بالمدافئ.","أطفئ المدافئ التي بلا مدخنة قبل النوم وعند مغادرة الغرفة، وجدّد هواء الغرفة من وقت لآخر.","يجب أن تكون للمطابخ ودورات المياه تهوية خاصة."]},{heading:"3. تسرّب الغاز — ماذا أفعل؟",body:"إذا شممت رائحة غاز:",points:["افتح النوافذ والأبواب في طريقك إلى الخارج إن استطعت.","لا تُشعل أي عود ثقاب ولا تلمس مفاتيح الكهرباء (لا تشغّلها ولا تطفئها)!","لا تستخدم الهاتف المحمول داخل المبنى — فقد تُحدث شرارة واحدة انفجارًا.","اخرج وأخرِج جميع الأشخاص.","اتصل بالرقم 115 من خارج المبنى.","لا يُغلق الغازَ من الصمام الرئيسي إلا الموظفون المدرَّبون والمكلَّفون، إذا أمكن الوصول إليه بأمان ودون دخول المكان الذي تجمّع فيه الغاز؛ ولا تعُد إلى الداخل أبدًا للوصول إليه."]},{heading:"4. الفحص الشهري",body:"الفحص:",points:["افحص مدخنة المدفأة — يجب ألّا تكون مسدودة.","افحص وصلات أنابيب الغاز بالماء والصابون (اختبار الفقاعات)؛ ولا تفحصها بالنار أبدًا.","ركّب كاشف CO (Carbon Monoxide Detector).","يفحص فني مختص المدافئ سنويًا.","احتفظ بسجل الفحوصات."]},{heading:"5. إذا انطلق إنذار CO أو ظهرت الأعراض",body:"غاز CO بلا رائحة، لذلك يكفي الإنذار أو الأعراض للتصرف:",points:["أخرج الجميع فورًا إلى الهواء النقي في الخارج؛ ولا تنتظر أن تشم رائحة.","اتصل بالرقم 115 من الخارج، واتصل بالرقم 122 أيضًا إذا عانى أحد من صداع أو دوار أو قيء أو تشوّش.","لا يُعطى فاقد الوعي أو المشوّش شيئًا بالفم؛ وإذا لم يتنفس طبيعيًا فابدأ CPR.","لا يعود أحد حتى يُعلن المكان آمنًا ويفحص فني مؤهل المدافئ."]},{heading:"6. من يفعل ماذا؟",body:"يجب أن تكون المسؤوليات واضحة قبل الحادث:",points:["كل الموظفين: لا مفاتيح ولا نار، الخروج، التنبيه، و115 من الخارج.","الموظفون المكلّفون: الصمام الرئيسي فقط إذا بلغوه بأمان من خارج منطقة الغاز.","مسؤول الطابق: عدّ الأشخاص في نقطة التجمع وإبلاغ فريق 115.","المدير: فحص المدافئ والخراطيم من قبل فني مؤهل والاحتفاظ بسجلات الفحص."]}],media:[{kind:"video",src:"media/videos/gov_gas_safety.mp4",title:"خطر الغاز",description:"كيفية الاكتشاف والإجراءات"},{kind:"image",src:"media/images/gov_co_detector.png",title:"كاشف CO",description:"موضع التركيب"}],quiz:[{question:"ما خصائص غاز CO (أول أكسيد الكربون)؟",options:[{text:"له رائحة قوية مثل البيض الفاسد",correct:!1},{text:"يظهر كدخان رمادي مائل إلى الزرقة",correct:!1},{text:"عديم اللون والرائحة",correct:!0},{text:"ليست له أي خصائص",correct:!1}],explanation:"غاز CO عديم اللون والرائحة والطعم — ولذلك فهو خطير ويلزم جهاز كاشف له."},{question:"إذا شممت رائحة غاز، ما أول ما يجب فعله؟",options:[{text:"تشغيل المصباح الكهربائي لمعرفة مصدر الغاز",correct:!1},{text:"الخروج مع فتح النوافذ في الطريق",correct:!0},{text:"الاتصال بالرقم 115 بالهاتف وأنت ما زلت في الداخل",correct:!1},{text:"تشغيل المدفأة",correct:!1}],explanation:"لا تقترب من النار ولا تلمس المفاتيح، وافتح النوافذ في طريقك إلى الخارج إن استطعت، واخرج واتصل بالرقم 115 من الخارج."},{question:"متى يجب إطفاء مدفأة الغاز التي بلا مدخنة؟",options:[{text:"فقط عندما تفرغ أسطوانة الغاز تمامًا",correct:!1},{text:"قبل النوم وعند مغادرة الغرفة",correct:!0},{text:"في الصيف فقط",correct:!1},{text:"فقط عندما تصبح الغرفة دافئة أكثر من اللازم",correct:!1}],explanation:"لا تترك المدافئ التي بلا مدخنة مشتعلة أبدًا أثناء النوم أو عند خلو الغرفة من الأشخاص؛ وجدّد هواء الغرفة من وقت لآخر."},{question:"تشم رائحة غاز، والصمام الرئيسي في نهاية الممر حيث الرائحة أقوى. ماذا تفعل؟",options:[{text:"لا أقترب؛ أخرج وأنبّه الآخرين وأتصل بالرقم 115 من الخارج",correct:!0},{text:"أحبس أنفاسي وأسرع إلى نهاية الممر لأغلق الصمام الرئيسي بنفسي",correct:!1},{text:"أذهب مستعينًا بضوء الهاتف لأرى الصمام جيدًا في العتمة ثم أغلقه",correct:!1},{text:"أضغط جرس الحريق الكهربائي ثم أذهب لإغلاق الصمام الرئيسي",correct:!1}],explanation:"لا يُغلق الصمام إلا إذا كان قريبًا ويمكن بلوغه دون دخول منطقة الغاز ودون مفاتيح. والصمام هنا داخل منطقة الغاز؛ والهاتف والجرس الكهربائي قد يُحدثان شررًا أيضًا."},{question:"يرنّ كاشف CO في غرفتك، لكن لا أحد يشم شيئًا والجميع يشعرون بأنهم بخير. ماذا تفعل؟",options:[{text:"يخرج الجميع إلى الهواء النقي ونتصل بالرقم 115 من الخارج",correct:!0},{text:"أنزع بطارية الكاشف لأنه يعطي إنذارًا خاطئًا بوضوح",correct:!1},{text:"أفتح النافذة ويبقى الجميع في أماكنهم ويواصلون العمل",correct:!1},{text:"ننتظر في الغرفة حتى يصاب أحدنا بالصداع أو الدوار",correct:!1}],explanation:"غاز CO بلا لون ولا رائحة ولا طعم؛ وإنذار الكاشف هو الطريقة الوحيدة لمعرفته. يخرج الجميع ولا يعود أحد حتى يُعلن المكان آمنًا."},{question:"في الفحص الشهري يريد زميل اختبار وصلة خرطوم الأسطوانة بالقدّاحة ليرى إن كان الغاز يتسرب. ماذا تقول له؟",options:[{text:"توقّف؛ ضع ماء وصابونًا على الوصلة وراقب الفقاعات",correct:!0},{text:"لا بأس، لكن افعل ذلك ببطء وابقَ بعيدًا عن النافذة والستائر",correct:!1},{text:"لا بأس، بشرط ألا تكون الأسطوانة ممتلئة وأن يكون الصمام نصف مغلق",correct:!1},{text:"استخدم عود ثقاب بدل القدّاحة لأن لهبه أصغر",correct:!1}],explanation:"تُختبر وصلات الغاز بالماء والصابون (اختبار الفقاعات) لا باللهب أبدًا؛ فاللهب قد يُفجّر الغاز المتسرب. وإذا ظهرت فقاعات فأغلق الأسطوانة إن كان ذلك آمنًا واستدعِ فنيًا."}],steps:[{title:"لا شرر",detail:"إذا شممت رائحة غاز: لا تُشعل عود ثقاب أو نارًا، ولا تلمس المفاتيح والمصابيح وجرس الباب (لا تشغيلًا ولا إطفاءً)، ولا تستخدم الهاتف أو الأجهزة الكهربائية داخل المبنى.",critical:!0},{title:"الصمام فقط إن كان ذلك آمنًا",detail:"أغلق صمام الغاز فقط إذا كان قريبًا ويمكنك بلوغه دون دخول المكان الذي تجمّع فيه الغاز ودون لمس أي مفتاح أو مصدر شرر. وإلا فلا تقترب منه. أما الصمام الرئيسي للمبنى فلا يغلقه إلا الموظفون المدرّبون المكلّفون.",critical:!0},{title:"اخرج ونبّه الآخرين",detail:"اخرج ونبّه من حولك بصوتك ليخرجوا، لا بجرس كهربائي. وإن كان ذلك سهلًا فافتح النوافذ والأبواب في طريقك، لكن لا تتأخر من أجل ذلك.",critical:!0},{title:"اتصل بالرقم 115 من الخارج",detail:"اتصل بالرقم 115 بعيدًا عن المبنى: المكان، وأين الرائحة، وهل بقي أحد في الداخل، وهل أُغلق الصمام أم لا.",critical:!0},{title:"ابقَ في الخارج",detail:"لا يدخل أحد، لا من أجل الصمام ولا من أجل الأغراض، حتى يعلن فريق 115 أن المبنى آمن. وبعد ذلك لا يعيد تشغيل نظام الغاز إلا فني مؤهل."}],warnings:["لا تبحث أبدًا عن مكان تسرب الغاز بعود ثقاب أو قدّاحة: اللهب قد يُفجّر الغاز فورًا.","لا تعد إلى المبنى لإغلاق الصمام: الغاز يتجمع مع الوقت وأي شرارة قد تسبب انفجارًا.","لا تشغّل مدفأة غاز بلا مدخنة في غرفة مغلقة أو أثناء النوم: غاز CO بلا رائحة وقد يقتل دون إنذار."],tips:["ضع علامة على مكان صمام الغاز الرئيسي، وأبقِ الطريق إليه خاليًا، وعلّق قربه أسماء الموظفين المكلّفين.","ركّب كاشف CO في كل غرفة فيها مدفأة تعمل بالوقود واختبره بانتظام.","افحص خراطيم الغاز: إذا كانت متشققة أو متصلبة أو قديمة فاستبدلها بواسطة فني مؤهل.","في التمرين، تحقق من أن الموظفين يعرفون ما لا يجوز فعله عند شم رائحة الغاز: لا مفاتيح ولا هواتف ولا أجراس."],activity:{prompt:"عند وصولك إلى الدائرة صباحًا تشم رائحة غاز قوية في الممر القريب من المطبخ. الموقد في المطبخ موصول بأسطوانة عبر خرطوم، ومفتاح الإنارة قرب الباب. ماذا تفعل؟",options:[{text:"لا أشغّل المفتاح، وأخرج وأنبّه الزملاء القادمين وأتصل بالرقم 115 من الخارج",correct:!0,feedback:"صحيح: الرائحة قوية، أي أن الغاز تجمّع في المطبخ والممر؛ والأسطوانة داخل منطقة الغاز فلا يجوز الاقتراب منها."},{text:"أدخل المطبخ وأغلق صمام الأسطوانة",correct:!1,feedback:"غير صحيح: الصمام في المكان الذي تجمّع فيه الغاز؛ وحسب القاعدة لا تقترب منه بل تخرج."},{text:"أشعل أضواء الممر لأرى مكان التسرب",correct:!1,feedback:"غير صحيح: المفتاح يُحدث شرارة صغيرة قد تُفجّر الغاز."},{text:"أتصل بالرقم 115 بالهاتف من الممر ليعرفوا المكان بدقة",correct:!1,feedback:"غير صحيح: الهاتف داخل منطقة الغاز قد يُحدث شرارة؛ ويمكنك وصف المكان بدقة من الخارج أيضًا."}]},caseStudy:[{prompt:"في مساء شتوي يشكو موظفان في غرفة مغلقة تعمل فيها مدفأة غاز بلا مدخنة من صداع ودوار؛ وأحدهما مشوّش ولا يجيب بشكل سليم. ماذا تفعل؟",options:[{text:"أُخرج الجميع فورًا إلى الهواء النقي وأتصل بالرقمين 122 و115 من الخارج",correct:!0,feedback:"صحيح: الصداع والدوار والتشوّش في غرفة مغلقة فيها مدفأة علامات تسمم بغاز CO؛ والهواء النقي والمساعدة الطبية أولًا."},{text:"أفتح نافذة وأطلب منهما مواصلة العمل",correct:!1,feedback:"غير صحيح: الشخص المشوّش يحتاج إلى مساعدة طبية، وغاز CO لا يخرج من الجسم بسرعة."},{text:"أعطيهما حبوب صداع وماء",correct:!1,feedback:"غير صحيح: هذا تسمم لا صداع عادي؛ الدواء لا يزيل الخطر، والشخص المشوّش لا يُعطى شيئًا بالفم."},{text:"أطلب منهما الاستراحة على الكراسي في الغرفة نفسها",correct:!1,feedback:"غير صحيح: البقاء في الغرفة مع CO يزيد التسمم وقد يقتل."}]},{prompt:"في الخارج يتحسن الموظف المشوّش قليلًا. يقول المدير: «بعد تهوية الغرفة يمكننا العودة وإشعال المدفأة من جديد.» ما القرار الأفضل؟",options:[{text:"لا تُشعل المدفأة حتى يفحصها فني مؤهل مع التهوية، ويُفحص من ظهرت عليهم الأعراض من قبل الفريق الطبي",correct:!0,feedback:"صحيح: سبب CO لم يُعالَج بعد؛ والتحسن في الخارج ليس دليلًا على السلامة."},{text:"نعود بعد فتح النوافذ لفترة قصيرة",correct:!1,feedback:"غير صحيح: التهوية القصيرة لا تصلح سبب CO؛ فعند تشغيل المدفأة مجددًا يعود الغاز."},{text:"نشعل المدفأة مع ترك الباب مفتوحًا ونواصل العمل",correct:!1,feedback:"غير صحيح: الباب المفتوح لا يضمن السلامة؛ فالمدفأة المعطوبة قد تنتج CO خطرًا رغم ذلك."},{text:"ننقل المدفأة إلى غرفة أخرى أصغر",correct:!1,feedback:"غير صحيح: في غرفة أصغر يتجمع CO أسرع؛ فيزداد الخطر."}]}],realCase:"في الشتاء كانت مدفأة غاز بلا مدخنة تعمل في غرفة مغلقة النوافذ في دائرة حكومية. وبعد ساعات شعر عدد من الموظفين بصداع ودوار. فاشتبه موظف تلقى تدريبًا عن CO بوجود الغاز. خرج الجميع إلى الهواء النقي واتُّصل بالرقمين 122 و115 من الخارج. وفحص فريق الإسعاف الموظفين. ووجد فني مؤهل أن التهوية لم تكن كافية. فركّبت الدائرة كواشف CO وطبّقت قاعدة التهوية. الدرس: أعراض CO تبدو كصداع عادي."},{id:8,code:"GOV-108",icon:"Lock",accent:"#0891b2",title:"الأمن السيبراني وحماية البيانات",subtitle:"Cybersecurity & Data Protection",summary:"حماية الأنظمة الحاسوبية والبيانات الحكومية من الهجمات الإلكترونية والفيروسات",blocks:[{body:"في العصر الرقمي، تشكّل الهجمات السيبرانية خطرًا كبيرًا على الدوائر الحكومية. فالبيانات الشخصية للمواطنين والوثائق الرسمية والأنظمة المالية كلها أهداف محتملة. ولذلك فإن استعداد الموظفين وتدريبهم أمر ضروري."},{heading:"1. أنواع المخاطر السيبرانية",body:"المخاطر الرئيسية:",points:["التصيّد الاحتيالي (Phishing): رسائل بريد إلكتروني ورسائل مزيّفة تهدف إلى سرقة المعلومات.","الفيروسات والبرامج الضارة (Malware).","برامج الفدية (Ransomware): تشفير البيانات وقفلها والمطالبة بالمال.","الهندسة الاجتماعية (Social Engineering): خداع الموظفين للحصول على المعلومات.","شبكات WiFi غير المحمية: سرقة المعلومات عبر الشبكة.","ذواكر USB المجهولة: قد تنقل الفيروسات."]},{heading:"2. قواعد كلمة المرور (Password)",body:"كلمة المرور القوية:",points:["الطول: 15 حرفًا ورمزًا على الأقل (NIST SP 800-63B-4).","عبارة مرور طويلة مكوّنة من عدة كلمات (Passphrase) يسهل تذكّرها وتكون قوية.","لا تغيّر كلمة المرور وفق فترة زمنية محددة؛ بل غيّرها فقط عند الاشتباه في انكشافها.","لا تستخدم الاسم أو رقم الهاتف أو 123456.","فعِّل التحقق بخطوتين (2FA).","استخدم كلمة مرور مختلفة لكل نظام."]},{heading:"3. البريد الإلكتروني الآمن",body:"كيف تحمي نفسك في البريد الإلكتروني:",points:["لا تفتح الروابط المجهولة — وتحقّق من عنوان المرسِل.","لا تفتح المرفقات الواردة من عناوين مجهولة.","إذا وصلتك رسالة بريد إلكتروني مشبوهة، فأبلغ قسم تقنية المعلومات (IT).","لا ترسل كلمة المرور أو رقم الحساب المصرفي عبر البريد الإلكتروني.","استخدم البريد الإلكتروني الرسمي فقط لأعمال الدائرة."]},{heading:"4. الحماية المادية",body:"حماية الأجهزة:",points:["اقفل حاسوبك عند ابتعادك عن المكتب (Win+L).","لا تسمح للآخرين برؤية المعلومات على شاشتك.","لا تُدخل ذواكر USB المجهولة في الحاسوب.","أتلِف الأوراق السرية بآلة تمزيق الورق (Shredder).","احمِ هاتف العمل برمز PIN أو ببصمة الإصبع."]},{heading:"5. علامات التصيّد",body:"تكون الرسالة مشبوهة إذا:",points:["تحمل استعجالًا أو تهديدًا: «اليوم»، «فورًا»، «سيُغلق حسابك».","عنوان المرسل يشبه العنوان الصحيح لكن فيه حرف مختلف أو نطاق آخر.","تطلب كلمة المرور أو رمز التحقق أو بيانات مصرفية.","تحتوي رابطًا أو مرفقًا غير متوقع، أو تطلب بطاقات هدايا أو تحويل أموال."]},{heading:"6. الإبلاغ عن حادث سيبراني",body:"الإبلاغ المبكر والواضح يختصر الوقت الذي يحتاجه القسم:",points:["ماذا حدث ومتى: رسالة، رابط، ملف، أو كلمة مرور أُدخلت.","أي حاسوب أو حساب تأثر.","لا تحذف الدليل: اترك الرسالة مكانها حتى يقول لك القسم ماذا تفعل.","اتبع تعليمات القسم، مثل فصل الجهاز عن الشبكة إذا طلبوا ذلك."]}],media:[{kind:"video",src:"media/videos/gov_cybersecurity.mp4",title:"الأمن السيبراني",description:"أسس الحماية"},{kind:"image",src:"media/images/gov_phishing.png",title:"التعرّف على التصيّد الاحتيالي",description:"نماذج لرسائل بريد إلكتروني مزيّفة"}],quiz:[{question:"ما التصيّد الاحتيالي (Phishing)؟",options:[{text:"برنامج يحمي الحاسوب من الفيروسات",correct:!1},{text:"رسائل بريد إلكتروني مزيّفة لسرقة المعلومات",correct:!0},{text:"نوع من الحرائق",correct:!1},{text:"برنامج يصنع نسخًا احتياطية تلقائيًا",correct:!1}],explanation:"التصيّد الاحتيالي رسائل بريد إلكتروني مزيّفة تبدو كأنها رسمية بهدف سرقة المعلومات."},{question:"كم حرفًا ورمزًا على الأقل يجب أن تتضمن كلمة المرور القوية؟",options:[{text:"10",correct:!1},{text:"12",correct:!1},{text:"8",correct:!1},{text:"15",correct:!0}],explanation:"يشترط المعيار NIST (SP 800-63B-4) لكلمة المرور غير المقترنة بالتحقق بخطوتين (2FA) ما لا يقل عن 15 رمزًا؛ والطول أهم من تنويع الرموز."},{question:"إذا وجدت ذاكرة USB مجهولة على الأرض، فماذا تفعل؟",options:[{text:"أُدخلها في الحاسوب",correct:!1},{text:"أسلّمها إلى مسؤول تقنية المعلومات (IT)",correct:!0},{text:"آخذها إلى المنزل",correct:!1},{text:"لا فرق",correct:!1}],explanation:"قد تحتوي الذواكر المجهولة على فيروسات — فسلّمها إلى قسم تقنية المعلومات (IT)."},{question:"يتصل بك شخص يقول إنه من قسم تقنية المعلومات ويطلب رمز التحقق الذي وصل الآن إلى هاتفك. ماذا تفعل؟",options:[{text:"لا أعطي الرمز، وأنهي المكالمة وأبلغ عبر القناة الرسمية",correct:!0},{text:"أعطيه الرمز إن كان يعرف اسمي الكامل وقسمي",correct:!1},{text:"أعطيه نصف الرمز فقط لأتأكد أنه صادق",correct:!1},{text:"أرسل له الرمز بالبريد الإلكتروني بدلًا من الهاتف",correct:!1}],explanation:"رمز التحقق لك وحدك؛ ومن يعرفه يستطيع دخول حسابك. قسم تقنية المعلومات لا يطلبه أبدًا، ومعرفة اسمك ليست دليلًا على الصدق."},{question:"تصلك رسالة عاجلة باسم المدير: «أنا في اجتماع؛ اشترِ اليوم بطاقات هدايا وأرسل لي رموزها.» ماذا تفعل؟",options:[{text:"أتحقق من المدير بطريقة أخرى: اتصال على رقمه المعروف أو وجهًا لوجه",correct:!0},{text:"أشتري بسرعة لأن المدير في اجتماع ولا يستطيع الرد",correct:!1},{text:"أرد على الرسالة نفسها وأسأل كم بطاقة يحتاج وبأي قيمة بالضبط",correct:!1},{text:"أشتري بطاقة واحدة فقط حتى تكون خسارة الدائرة صغيرة إن كانت خدعة",correct:!1}],explanation:"الاستعجال والسرية وطلب بطاقات الهدايا علامات احتيال. تحقق دائمًا بطريقة أخرى تعرفها أنت، وأبلغ قسم تقنية المعلومات."},{question:"نقرت على رابط ثم أدركت أنه قد يكون مزيفًا. ولم يظهر أي ضرر بعد. ما أفضل تصرف؟",options:[{text:"أخبر قسم تقنية المعلومات فورًا بما حدث",correct:!0},{text:"أنتظر حتى تظهر مشكلة ثم أبلغ",correct:!1},{text:"أنزّل برنامج تنظيف من الإنترنت وأعالج الأمر بنفسي",correct:!1},{text:"أحذف سجل التصفح حتى لا يبقى أثر",correct:!1}],explanation:"كثير من البرامج الضارة تعمل بصمت؛ والإبلاغ المبكر يتيح للقسم إيقافها قبل انتشارها. أما تنزيل البرامج من الإنترنت ومحو الآثار فيزيدان المشكلة."}],steps:[{title:"توقّف وافحص",detail:"قبل النقر على أي رسالة غير متوقعة: افحص عنوان المرسل، والرابط (مرّر الفأرة فوقه قبل النقر)، وأي طلب للاستعجال أو تهديد."},{title:"لا تفتح ولا تردّ",detail:"إذا ساورك شك فلا تفتح الروابط والمرفقات ولا تردّ على الرسالة. وإذا بدت من شخص تعرفه فتحقق منه برقم تعرفه أنت أو وجهًا لوجه، لا بالرقم المذكور في الرسالة."},{title:"أبلغ قسم تقنية المعلومات",detail:"أبلغ عن الرسالة المشبوهة بالطريقة التي حددها قسم تقنية المعلومات، ثم احذفها وفق تعليماتهم. ولا تعِد توجيهها إلى زملائك لأن ذلك ينشر الرابط."},{title:"إذا نقرت: أبلغ فورًا",detail:"إذا نقرت على رابط أو فتحت ملفًا أو أدخلت كلمة المرور، فأبلغ قسم تقنية المعلومات فورًا وغيّر كلمة المرور وفق تعليماتهم. لا تحاول إصلاح الأمر بنفسك ولا تخفِه؛ فكل ساعة تزيد الضرر."},{title:"احمِ الأجهزة والبيانات",detail:"اقفل الحاسوب عندما تبتعد عن مكتبك، ولا تُدخل ذاكرات USB مجهولة، واسمح بالتحديثات التي يرسلها قسم تقنية المعلومات، واستخدم البريد الرسمي فقط لأعمال الدائرة."}],warnings:["لا تعطِ كلمة المرور أو رمز التحقق (2FA) لأي شخص، حتى لو قال إنه من قسم تقنية المعلومات: هذا القسم لا يطلب كلمة مرورك أبدًا.","لا تُدخل في الحاسوب ذاكرة USB وُجدت على الأرض أو في الطريق: ربما تُركت عمدًا لنشر البرامج الضارة.","لا تُخفِ خطأً (مثل النقر على رابط مزيف): الإبلاغ المبكر قد يوقف الهجوم قبل أن يصل إلى الشبكة كلها."],tips:["تحقق من أي طلب لتغيير حساب مصرفي أو تحويل أموال باتصال على رقم معروف.","قبل النقر مرّر الفأرة فوق الرابط وانظر إلى أين يذهب العنوان الحقيقي.","استخدم عبارة طويلة كلمةً للمرور وكلمة مختلفة لكل نظام؛ وإذا وفّر قسم تقنية المعلومات أداة لإدارة كلمات المرور فاستخدمها.","في الأماكن العامة لا تتصل بأنظمة الدائرة عبر شبكات WiFi غير محمية."],activity:{prompt:"تصلك رسالة باسم «قسم تقنية المعلومات»: «سيُغلق صندوق بريدك اليوم ما لم تسجّل الدخول عبر هذا الرابط.» وعنوان المرسل من خارج نطاق الدائرة. ماذا تفعل؟",options:[{text:"لا أنقر على الرابط وأبلغ قسم تقنية المعلومات عبر القناة الرسمية",correct:!0,feedback:"صحيح: الاستعجال والتهديد والعنوان الخارجي علامات تصيّد؛ والإبلاغ يتيح لقسم تقنية المعلومات حماية جميع الموظفين."},{text:"أسجّل الدخول بسرعة حتى لا يُغلق بريدي",correct:!1,feedback:"غير صحيح: الصفحة المزيفة تسرق كلمة مرورك، ثم يستطيع المهاجم إرسال رسائل باسمك."},{text:"أردّ على الرسالة وأسأل هل هي حقيقية",correct:!1,feedback:"غير صحيح: الرد يصل إلى المهاجم الذي سيقول «نعم، إنها حقيقية»؛ تحقق مع القسم بطريقة أخرى."},{text:"أعيد توجيهها إلى زملائي لتنبيههم",correct:!1,feedback:"غير صحيح: إعادة التوجيه تنشر الرابط وقد ينقر عليه أحدهم؛ والتنبيه من مهام قسم تقنية المعلومات."}]},caseStudy:[{prompt:"نقرت على رابط في رسالة بدت صادرة عن مكتب المدير، وأدخلت كلمة المرور. ثم أدركت أن الصفحة مزيفة. ماذا تفعل؟",options:[{text:"أبلغ قسم تقنية المعلومات فورًا وأغيّر كلمة المرور وفق تعليماتهم",correct:!0,feedback:"صحيح: كلمة المرور انكشفت؛ والتغيير السريع وإبلاغ القسم يقطعان الطريق على المهاجم."},{text:"لا أقول شيئًا وأنتظر لأرى هل سيحدث شيء",correct:!1,feedback:"غير صحيح: قد يستخدم المهاجم حسابك فورًا؛ والتأخير يكبّر الضرر."},{text:"أحذف الرسالة حتى لا يراها أحد",correct:!1,feedback:"غير صحيح: الحذف لا يحمي كلمة المرور ويُتلف الدليل الذي يحتاجه القسم."},{text:"أطفئ الحاسوب وأعمل على حاسوب آخر",correct:!1,feedback:"غير صحيح: كلمة المرور ما زالت بيد المهاجم؛ وتغيير الحاسوب لا يحمي الحساب."}]},{prompt:"في الصباح التالي تظهر الملفات على القرص المشترك بأسماء غريبة، وتظهر على شاشة زميل رسالة: «بياناتك مقفلة؛ ادفع المال.» ماذا تفعل؟",options:[{text:"نوقف العمل على ذلك الحاسوب ولا ندفع، ونبلغ القسم فورًا ونتبع تعليماته",correct:!0,feedback:"صحيح: هذا فيروس فدية؛ يستطيع القسم عزل الأجهزة عن الشبكة واستعادة البيانات من النسخ المحفوظة."},{text:"ندفع المال لتعود البيانات بسرعة",correct:!1,feedback:"غير صحيح: لا ضمان لعودة البيانات، والدفع يشجع هجمات أخرى؛ والقرار للجهة المسؤولة لا للموظف."},{text:"نعيد تشغيل الحواسيب مرارًا حتى تختفي الرسالة",correct:!1,feedback:"غير صحيح: إعادة التشغيل لا تقضي على الفيروس وقد تُتلف معلومات يحتاجها القسم."},{text:"ننسخ الملفات المتبقية إلى ذاكرة USB لحمايتها",correct:!1,feedback:"غير صحيح: الذاكرة قد تنقل الفيروس إلى حواسيب أخرى؛ وحماية البيانات مهمة القسم عبر النسخ المحمية."}]}],realCase:"في دائرة حكومية تلقت موظفة في القسم المالي رسالة بدت صادرة عن مورّد معروف، تطلب تغيير رقم الحساب المصرفي لدفع فاتورة وتقول إن الأمر عاجل. فاتصلت بالمورّد على رقمه المسجل في سجلات الدائرة، فقال إنه لم يرسل أي طلب كهذا. فأبلغت قسم تقنية المعلومات الذي نبّه جميع موظفي القسم المالي. الدرس: طلبات تغيير المدفوعات يُتحقق منها دائمًا بطريقة أخرى."},{id:9,code:"GOV-109",icon:"ShieldAlert",accent:"#7c3aed",title:"الأمن الشخصي والوقاية من العنف",subtitle:"Personal Safety & Workplace Security",summary:"حماية الموظفين من المخاطر الأمنية والعنف في مكان العمل",blocks:[{body:"لا تقتصر سلامة الموظفين على الحريق والكهرباء. فالعنف في مكان العمل والتهديدات والحوادث الأمنية تتطلب الاستعداد أيضًا. ويجب على كل موظف أن يعرف كيف يحمي نفسه في هذه الحالات."},{heading:"1. المخاطر الأمنية في الدوائر",body:"الحالات الأمنية:",points:["المراجعون الغاضبون وغير الراضين.","التهديد الجسدي.","الطرود والأشياء المشبوهة.","الهجوم المسلح أو السرقة أو النهب.","احتجاز الرهائن.","التهديد عبر الهاتف أو الإنترنت."]},{heading:"2. اهرب، اختبئ، أبلِغ (Run, Hide, Tell)",body:"إذا وقع حادث أمني:",points:["Run (اهرب): إذا كان هناك طريق آمن، فاخرج من المبنى بسرعة.","اعرف دائمًا أقرب مسار للخروج.","Hide (اختبئ): إذا لم تستطع الهرب، فاختبئ في غرفة واقفل الباب.","اجعل هاتفك المحمول صامتًا وأوقف الاهتزاز أيضًا.","Tell (أبلِغ): عندما تصبح في مكان آمن، اتصل بالرقم 104 (الشرطة).","أدلِ بجميع المعلومات بدقة: المكان، وعدد الأشخاص، وأوصافهم."]},{heading:"3. التعامل مع المراجعين الغاضبين",body:"أساليب تهدئة الموقف:",points:["تحدّث بصوت هادئ ومنخفض.","أصغِ إليه وأظهِر أنك تتفهّم موقفه.","حافظ على مسافة آمنة (1.5-2 متر).","أبقِ طريق خروجك مفتوحًا دائمًا.","نبِّه أحد زملائك ليأتي لمساعدتك.","إذا ساء الموقف، فاضغط زر الطوارئ أو اتصل بالرقم 104."]},{heading:"4. استعداد الدائرة",body:"التحضيرات الأمنية:",points:["تركيب كاميرات المراقبة (CCTV).","نظام التحكم في الدخول (Access Control).","زر الطوارئ (Panic Button) أسفل مكاتب الاستقبال.","تدريب الموظفين كل 6 أشهر.","تحديث الخطة الأمنية واختبارها.","إنشاء اتصال مباشر مع أقرب مركز للشرطة."]},{heading:"5. الطرود المشبوهة ومكالمات التهديد",body:"حالتان قد يواجههما أي موظف:",points:["الطرد المشبوه: لا تلمسه ولا تفتحه ولا تحرّكه.","أبعِد الناس عن المكان وامنعهم من الاقتراب.","أبلِغ مسؤول الأمن واتصل بالرقم 104 من مكان آمن.","مكالمة التهديد: حافظ على هدوئك، وأصغِ، ودع المتصل يتكلم.","دوّن كلماته بنصّها، والوقت، والصوت، والأصوات المحيطة به.","بعد المكالمة، أبلِغ مديرك والرقم 104 فورًا."]},{heading:"6. بعد الحادث",body:"ما تفعله الدائرة بعد أي تهديد أو عمل عنيف:",points:["تأكد من سلامة الجميع وقدّم الإسعافات الأولية عند الحاجة (اتصل بالرقم 122).","اكتب تقريرًا: ماذا حدث، ومتى، ومن كان حاضرًا، وما الذي قيل.","احتفظ بالرسائل والتسجيلات والأشياء للشرطة؛ ولا تنظّف مكان الحادث إذا كانت الشرطة قادمة.","ادعم الموظفين المتأثرين؛ فالحديث مع شخص موثوق يساعد.","راجع الخطة الأمنية وأصلِح ما لم ينجح."]}],media:[{kind:"video",src:"media/videos/gov_security.mp4",title:"الأمن الشخصي",description:"اهرب، اختبئ، أبلِغ (Run, Hide, Tell)"},{kind:"image",src:"media/images/gov_deescalation.png",title:"أساليب التهدئة",description:"التعامل مع المراجعين الغاضبين"}],quiz:[{question:"في طريقة Run, Hide, Tell، ما الخطوة الأولى؟",options:[{text:"الاختباء",correct:!1},{text:"الهرب",correct:!0},{text:"المقاومة",correct:!1},{text:"الاتصال بالشرطة",correct:!1}],explanation:"الإجراء الأول: Run (اهرب) إذا كان هناك طريق آمن."},{question:"عند التعامل مع مراجع غاضب، ماذا تفعل؟",options:[{text:"أرفع صوتي حتى يتوقف عن الصراخ",correct:!1},{text:"أتحدث بهدوء وأصغي إليه",correct:!0},{text:"أتجاهله",correct:!1},{text:"أطلب منه أن يعود في يوم آخر",correct:!1}],explanation:"تحدّث بهدوء وأصغِ إليه — فهذا يهدّئ الموقف."},{question:"ما رقم الشرطة في إقليم كوردستان؟",options:[{text:"115",correct:!1},{text:"122",correct:!1},{text:"104",correct:!0},{text:"911",correct:!1}],explanation:"الرقم 104 هو رقم الشرطة في إقليم كوردستان."},{question:"يغضب مراجع ويتقدم نحوك من فوق الكاونتر. ما الذي يجب أن تحميه أولًا؟",options:[{text:"مسافتك وطريقًا مفتوحًا للخروج",correct:!0},{text:"الملفات والأوراق على المكتب أمامك",correct:!1},{text:"فرصتك لشرح تعليمات الدائرة له",correct:!1},{text:"مكان المراجع في طابور الانتظار",correct:!1}],explanation:"المسافة والطريق المفتوح يحميانك إذا أصبح المراجع عنيفًا؛ أما الأوراق والشرح فيمكن أن ينتظرا."},{question:"تجد حقيبة متروكة تظهر منها أسلاك قرب مدخل الدائرة. ما التصرف الصحيح؟",options:[{text:"احملها إلى الخارج كي لا يُصاب أحد في المبنى",correct:!1},{text:"افتحها بحذر لترى ما بداخلها",correct:!1},{text:"أبعِد الناس واتصل بالرقم 104 من مكان آمن",correct:!0},{text:"غطّها بصندوق وتابع عملك",correct:!1}],explanation:"لا تلمس الشيء المشبوه ولا تحرّكه أبدًا: فتحريكه قد يفجّره. أخلِ المكان ودع الشرطة تتولى الأمر."},{question:"أثناء هجوم أنت مختبئ في غرفة مقفلة. أيّ تصرف خاطئ؟",options:[{text:"جعل الهاتف صامتًا وإيقاف الاهتزاز",correct:!1},{text:"الابتعاد عن الباب والتزام الصمت",correct:!1},{text:"الاتصال بالرقم 104 بهدوء عندما يكون الكلام آمنًا",correct:!1},{text:"فتح الباب لمعرفة ما إذا كان المهاجم قد غادر",correct:!0}],explanation:"فتح الباب قد يكشف مكان اختبائك. ابقَ مختبئًا حتى تقول الشرطة إن المكان آمن."}],steps:[{title:"تعرّف إلى علامات الخطر مبكرًا",detail:"الصوت المرتفع والقبضتان المشدودتان والحركة المضطربة والتهديد أو رفض الإصغاء علامات على أن الموقف قد يتحول إلى عنف. تصرّف مبكرًا: حافظ على هدوئك ولا تجادله."},{title:"حافظ على المسافة وعلى طريق خروجك",detail:"حافظ على مسافة آمنة (1.5-2 متر)، واجعل المكتب أو الكاونتر بينك وبينه، ولا تسمح أبدًا بأن يقف الشخص بينك وبين الباب.",critical:!0},{title:"هدّئ الموقف",detail:"تحدّث بصوت هادئ ومنخفض، وأصغِ إليه، وأعد صياغة مشكلته بكلماتك، واقترح خطوة تالية واقعية. لا تقطع وعودًا لا تستطيع الوفاء بها."},{title:"اطلب المساعدة مبكرًا",detail:"نبّه زميلًا بالعبارة أو الإشارة المتفق عليها، واضغط زر الطوارئ إن وُجد. وإذا صار الشخص مهدِّدًا، فاخرج من الغرفة واتصل بالرقم 104 من مكان آمن.",critical:!0},{title:"عند وقوع هجوم: اهرب، اختبئ، أبلِغ",detail:"اهرب إذا كان هناك طريق آمن؛ وإلا فاختبئ خلف باب مقفل بعد جعل هاتفك صامتًا؛ واتصل بالرقم 104 عندما يصبح الكلام آمنًا. لا تحاول أبدًا إيقاف المهاجم أو نزع سلاحه.",critical:!0},{title:"أبلِغ ووثّق",detail:"بعد كل حادث، حتى إن لم يُصب أحد، أبلِغ مديرك ومسؤول الأمن، ودوّن ما حدث ومتى ومن كان حاضرًا وما قيل."}],warnings:["لا تجادل الشخص الغاضب ولا تصرخ في وجهه ولا تلمسه ولا تسدّ طريقه: فذلك يزيد احتمال العنف. وإذا أراد المغادرة فدعه يغادر.","لا تحاول أبدًا إيقاف مهاجم أو شخص مسلّح أو تفتيشه أو نزع سلاحه. مهمتك أن تبتعد وتختبئ وتتصل بالرقم 104.","لا تلمس طردًا أو شيئًا مشبوهًا ولا تفتحه ولا تحرّكه. أبعِد الناس عنه واتصل بالرقم 104 من مكان آمن."],tips:["اتفق مع زملائك على عبارة سرية تعني: تعالَ إلى مكتبي الآن وأبلِغ الأمن.","رتّب مكتبك بحيث تصل إلى الباب دون أن تمر بجانب المراجع.","احفظ الرقم 104 ورقم مسؤول الأمن في هاتفك.","أبلِغ مديرك بأي تهديد يصلك بالهاتف أو برسالة، حتى إن بدا مزاحًا."],activity:{prompt:"يبدأ مراجع عند مكتب الاستقبال بالصراخ لأن معاملته تأخرت. يضرب المكتب بيده ويقترب منك. زميلك في الغرفة المجاورة. ماذا تفعل؟",options:[{text:"أصرخ عليه أنا أيضًا ليفهم أنه لا يستطيع التصرف هكذا",correct:!1,feedback:"الصراخ المقابل يزيد التوتر ويقرّب احتمال الهجوم؛ أما الصوت الهادئ المنخفض فيخفّفه."},{text:"أتراجع للحفاظ على المسافة وطريق خروجي، وأتحدث بهدوء، وأشير إلى زميلي ليأتي",correct:!0,feedback:"صحيح: المسافة والطريق المفتوح يحميانك، والصوت الهادئ يخفف التوتر، والزميل يوفّر الدعم ويكون شاهدًا."},{text:"أمسك ذراعه وأقوده إلى الباب",correct:!1,feedback:"لمس الشخص الغاضب قد يحوّل الصراخ إلى شجار. حافظ على مسافتك واطلب المساعدة."},{text:"أتجاهله وأواصل عملي حتى يهدأ",correct:!1,feedback:"التجاهل يُشعره بأن أحدًا لا يسمعه، وكثيرًا ما يزيد غضبه. أصغِ إليه وأظهر أنك تفهمه واطلب الدعم."}]},caseStudy:[{prompt:"تعمل في الطابق الثاني من دائرة عامة. تسمع صراخًا ودويًّا عاليًا من مدخل الطابق الأرضي، والناس يركضون. لا تعرف ما الذي يحدث. ما أول ما تفعله؟",options:[{text:"أنزل إلى المدخل لأرى ما حدث",correct:!1,feedback:"التوجه نحو خطر مجهول يعرّضك للخطر. ابتعد عنه."},{text:"إذا كان الدرج البعيد عن المدخل آمنًا أُخرج من حولي؛ وإلا نختبئ في غرفة ونقفل الباب",correct:!0,feedback:"صحيح: اهرب إذا كان هناك طريق آمن؛ وإن لم يكن، فاختبئ."},{text:"أتصل بعائلتي لأسألهم ماذا أفعل",correct:!1,feedback:"الاتصال بالعائلة يضيّع الوقت. اذهب أولًا إلى مكان آمن ثم اتصل بالرقم 104."}]},{prompt:"أنت وثلاثة زملاء مختبئون في مكتب مقفل. الصراخ مستمر في الممر. يريد أحد الزملاء فتح الباب ليرى. ماذا الآن؟",options:[{text:"نُبقي الباب مقفلًا، ونجعل الهواتف صامتة، ونبتعد عن الباب، ويتصل أحدنا بهدوء بالرقم 104 ويذكر مكاننا",correct:!0,feedback:"صحيح: ابقوا مختبئين وصامتين، وأبلِغوا 104 بمكانكم وبما سمعتم عندما يصبح الكلام آمنًا."},{text:"نفتح الباب قليلًا لنعرف إن كان الخطر قد زال",correct:!1,feedback:"فتح الباب قد يكشف مكان اختبائكم. انتظروا حتى تقول الشرطة إن المكان آمن."},{text:"نخرج معًا ونحاول إيقاف ذلك الشخص",correct:!1,feedback:"لا تواجهوا المهاجم أبدًا. مهمتكم أن تبقوا آمنين وأن تقدّموا المعلومات إلى 104."}]}],realCase:"جاءت امرأة إلى دائرة عامة لتسأل عن راتبها التقاعدي الذي تأخر شهورًا. وعند الكاونتر بدأت تصرخ وهدّدت الموظفة. أبقت الموظفة الكاونتر بينها وبين المراجِعة، وخفضت صوتها، وأصغت إليها وأعادت عليها مشكلتها. وفي الوقت نفسه قالت العبارة السرية المتفق عليها عبر الهاتف الداخلي، فجاء زميل وحارس الأمن. هدأت المراجِعة وحُدّد لها موعد مع مدير القسم. وبعد ذلك كتبت الموظفة تقريرًا قصيرًا، ونقلت الدائرة كراسي الانتظار حتى يتمكن الموظفون دائمًا من الوصول إلى الباب الخلفي."},{id:10,code:"GOV-110",icon:"Armchair",accent:"#16a34a",title:"الصحة والسلامة في مكان العمل",subtitle:"Occupational Health & Ergonomics",summary:"حماية صحة الموظفين في مكان العمل والتنظيم السليم للمكتب والكرسي",blocks:[{body:"كثيرًا ما يجلس الموظفون الحكوميون أمام الحاسوب 8 ساعات أو أكثر، مما يسبب آلام الظهر والعينين والكتفين. ويُسهم التنظيم السليم لمكان العمل (Ergonomics) والنشاط البدني في الحفاظ على صحة العاملين."},{heading:"1. تنظيم المكتب والكرسي (Ergonomics)",body:"مكان العمل السليم:",points:["الكرسي: يجب أن يدعم الظهر؛ واضبط ارتفاعه بحيث تستقر القدمان بالكامل على الأرض.","الشاشة: يكون أعلاها بمستوى العينين أو أدنى قليلًا، وعلى مسافة 50-70 سم.","لوحة المفاتيح: يكون المرفقان بزاوية تقارب 90°.","الفأرة: قريبة من لوحة المفاتيح وبالمستوى نفسه.","ارتفاع المكتب: يجب أن يتناسب مع طول قامتك.","الإضاءة: يجب ألّا يسقط الضوء مباشرةً على الشاشة."]},{heading:"2. حماية العينين",body:"إجهاد العين الناتج عن الشاشات (Computer Vision Syndrome):",points:["قاعدة 20-20-20: كل 20 دقيقة، انظر لمدة 20 ثانية إلى شيء يبعد 20 قدمًا (نحو 6 أمتار).","ارمش كثيرًا — فأمام الشاشة يقلّ رمش العينين فتجفّان.","خفّف سطوع الشاشة في المساء.","فعِّل الوضع الليلي (Night Mode).","النظارات المضادة للضوء الأزرق (Blue Light) ليس لها أي فائدة مثبتة (AAO)؛ وإذا أصيبت عيناك بالجفاف أو الإجهاد، فراجع طبيب العيون.","افحص عينيك سنويًا."]},{heading:"3. آلام الظهر والكتفين",body:"الوقاية والعلاج:",points:["انهض كل 45 دقيقة وتحرّك قليلًا.","تمديد الرقبة: أمِل رأسك ببطء نحو كل كتف.","تمديد الظهر: أدِر جسمك ببطء وأنت جالس على الكرسي.","استخدم السلالم بدلًا من المصعد متى كان ذلك مناسبًا.","اشرب الماء بانتظام طوال اليوم.","الجلوس الصحيح: ظهر مستقيم، وكتفان مسترخيتان، وقدمان على الأرض."]},{heading:"4. الصحة النفسية",body:"السلامة النفسية للموظفين:",points:["ضغط العمل (Stress): تعرّف على أسبابه الرئيسية.","تنظيم الوقت: افصل بين وقت العمل ووقت الراحة.","الحديث: تحدّث مع زملائك عن المشكلات.","خذ استراحة لمدة 15 دقيقة في الهواء الطلق كل يوم.","لا تستخدم هاتفك لأعمال الوظيفة أثناء الاستراحة.","إذا استمرت الأعراض: تواصل مع مختص في الصحة النفسية."]},{heading:"5. الانزلاق والتعثر والسقوط في المكتب",body:"عادات بسيطة تمنع كثيرًا من الإصابات:",points:["أبقِ الممرات والدرج والمخارج خالية من الصناديق والحقائب والأسلاك.","أغلق الأدراج وأبواب الخزائن بعد الاستعمال.","امسح الماء أو الشاي المسكوب فورًا، أو ضع لافتة تحذير.","استخدم سلّمًا صغيرًا للوصول إلى الرفوف العالية، ولا تستخدم الكرسي أبدًا.","أبلِغ مسؤول المبنى عن السجاد المرتخي والبلاط المكسور والزوايا المظلمة."]},{heading:"6. الرفع والحمل",body:"صناديق الورق والأجهزة أثقل غالبًا مما تبدو:",points:["افحص الوزن قبل الرفع واطلب المساعدة إذا شككت.","اثنِ ركبتيك وأبقِ ظهرك مستقيمًا.","أمسك الحمل قريبًا من جسمك.","استدِر بقدميك؛ ولا تلوِ ظهرك.","استخدم عربة للأحمال الثقيلة أو الكثيرة."]}],media:[{kind:"video",src:"media/videos/gov_ergonomics.mp4",title:"بيئة العمل المريحة (Ergonomics)",description:"تنظيم المكتب والكرسي"},{kind:"image",src:"media/images/gov_posture.png",title:"الجلوس الصحيح",description:"صورة إرشادية"},{kind:"image",src:"media/images/gov_eye_care.png",title:"قاعدة 20-20-20",description:"حماية العينين"}],quiz:[{question:"ما الغرض من قاعدة 20-20-20؟",options:[{text:"حماية الأذنين",correct:!1},{text:"حماية العينين",correct:!0},{text:"حماية الظهر",correct:!1},{text:"حماية اليدين",correct:!1}],explanation:"كل 20 دقيقة، انظر لمدة 20 ثانية إلى شيء يبعد 20 قدمًا (نحو 6 أمتار) — لحماية العينين (AAO)."},{question:"على أي مسافة من العينين يجب أن تكون شاشة الحاسوب؟",options:[{text:"20-30 سم",correct:!1},{text:"30-40 سم",correct:!1},{text:"50-70 سم",correct:!0},{text:"1 متر",correct:!1}],explanation:"المسافة الأنسب هي 50-70 سم (نحو طول الذراع)."},{question:"كل كم دقيقة ينبغي للموظف أن ينهض عن مكتبه ويتحرك؟",options:[{text:"20 دقيقة",correct:!1},{text:"45 دقيقة",correct:!0},{text:"ساعتان (2)",correct:!1},{text:"ساعة واحدة (1)",correct:!1}],explanation:"يُوصى بأن تنهض كل 45 دقيقة وتتحرك قليلًا."},{question:"بعد انتقالك إلى مكتب جديد تشعر بألم في الرقبة. شاشتك منخفضة وتنظر إليها إلى الأسفل طوال اليوم. ما أول ما تغيّره؟",options:[{text:"ارفع الشاشة ليكون أعلاها بمستوى العينين أو أدنى قليلًا",correct:!0},{text:"قرّب الشاشة لتصبح على بُعد نحو 20-30 سم من عينيك",correct:!1},{text:"ارفع سطوع الشاشة إلى أقصى درجة ممكنة",correct:!1},{text:"اخفض مقعد كرسيك قليلًا لتبدو الشاشة أعلى",correct:!1}],explanation:"النظر إلى الأسفل يحني الرقبة. يجب أن يكون أعلى الشاشة بمستوى العينين أو أدنى قليلًا، على بُعد 50-70 سم."},{question:"ما الطريقة الأكثر أمانًا للوصول إلى ملفات على رف مرتفع؟",options:[{text:"الوقوف على كرسي المكتب ذي العجلات",correct:!1},{text:"التسلق على الرفوف السفلى للخزانة",correct:!1},{text:"استخدام سلّم صغير مناسب أو طلب المساعدة",correct:!0},{text:"الوقوف على أطراف الأصابع وسحب الصندوق",correct:!1}],explanation:"الكراسي ذات العجلات والرفوف ليست مصممة للوقوف عليها وقد تتحرك أو تنقلب؛ أما السلّم الصغير فثابت."},{question:"يتعثر زميل بسلك ممدود عبر الممر. بعد الإسعافات الأولية، ما أهم خطوة تالية؟",options:[{text:"تذكير الجميع بالانتباه إلى مواضع أقدامهم",correct:!1},{text:"إبعاد السلك عن الممر وتسجيل الحادث",correct:!0},{text:"وضع سجادة فوق السلك لإخفائه",correct:!1},{text:"الانتظار لمعرفة ما إذا كان أحد آخر سيتعثر به",correct:!1}],explanation:"يجب إزالة السبب وتسجيل الحادث؛ فالتذكير والسجادة يُبقيان الخطر في مكانه."}],steps:[{title:"رتّب مكان عملك",detail:"اضبط الكرسي بحيث تستقر قدماك بالكامل على الأرض ويكون لظهرك سند؛ واجعل أعلى الشاشة بمستوى العينين أو أدنى قليلًا، على بُعد 50-70 سم، والفأرة بجانب لوحة المفاتيح."},{title:"أرِح عينيك",detail:"طبّق قاعدة 20-20-20: كل 20 دقيقة انظر إلى شيء على بُعد نحو 6 أمتار مدة 20 ثانية، وارمش كثيرًا."},{title:"تحرّك بانتظام",detail:"قف وتحرك قليلًا كل 45 دقيقة. أدِّ تمارين تمديد الرقبة والظهر ببطء، وتوقف إذا شعرت بألم."},{title:"أبقِ الممرات والمخارج خالية",detail:"أبعِد الأسلاك والصناديق والحقائب عن الممرات وعن المخارج، وأغلق الأدراج بعد الاستعمال، وامسح السوائل المسكوبة فورًا؛ وأبلِغ عن السجاد المرتخي والبلاط المكسور والإضاءة الضعيفة.",critical:!0},{title:"ارفع الأحمال وانقلها بأمان",detail:"أبقِ الحمل قريبًا من جسمك، واثنِ ركبتيك، ولا تلوِ ظهرك، واستخدم عربة أو اطلب المساعدة للأحمال الثقيلة أو الكبيرة مثل صناديق الورق."},{title:"اعتنِ بصحتك النفسية",detail:"خذ فترات راحتك، وتحدث مع زملائك أو مديرك عن ضغط العمل، وراجع مختصًا في الصحة النفسية إذا استمرت الأعراض."}],warnings:["لا تمدّ الأسلاك عبر الممرات ولا تكدّس الصناديق في الممرات وأمام المخارج: يتعثر بها الناس، وتسدّ طريق الخروج في الطوارئ.","لا تقف أبدًا على كرسي ذي عجلات للوصول إلى رف مرتفع، ولا ترفع حملًا لست متأكدًا من قدرتك عليه: استخدم سلّمًا صغيرًا أو عربة أو استعن بزميل."],tips:["افحص ارتفاع الكرسي والشاشة كلما انتقلت إلى مكتب جديد.","ضع الطابعة وسلة المهملات على بُعد خطوات لتقف أكثر.","احتفظ بزجاجة ماء على مكتبك لتذكّرك بالشرب.","أبلِغ مديرك مبكرًا إذا لم يزل ألم ظهرك أو رقبتك أو معصمك."],activity:{prompt:"تشكو زميلة جديدة من ألم في الرقبة وتعب في العينين. حاسوبها المحمول موضوع مباشرة على سطح المكتب، والنافذة خلف الشاشة، وتعمل ساعات دون راحة. بماذا تنصحها أولًا؟",options:[{text:"أن ترفع الشاشة إلى مستوى العينين، وتدير المكتب كي لا يسقط ضوء النافذة على الشاشة، وتأخذ فترات راحة قصيرة",correct:!0,feedback:"صحيح: ارتفاع الشاشة والوهج وطول العمل دون راحة هي الأسباب الرئيسة لألمها وتعب عينيها."},{text:"أن تشتري نظارة تحجب الضوء الأزرق",correct:!1,feedback:"لا فائدة مثبتة لنظارات الضوء الأزرق (AAO). أصلِح وضع الشاشة والإضاءة، وراجِع طبيب العيون إذا استمرت المشكلة."},{text:"أن تعمل أسرع لتنهي مبكرًا وترتاح في البيت",correct:!1,feedback:"العمل ساعات دون راحة جزء من المشكلة؛ فالاستراحات القصيرة والحركة خلال اليوم هي التي تساعد."},{text:"أن تضع الحاسوب على حجرها لتقترب الشاشة",correct:!1,feedback:"هذا يزيد انحناء الرقبة. يجب أن يكون أعلى الشاشة بمستوى العينين أو أدنى قليلًا، على بُعد 50-70 سم."}]},caseStudy:[{prompt:"أنت مسؤول السلامة في دائرتك. في جولة تفقدية تجد سلك تمديد ممدودًا عبر الممر إلى مدفأة، وصناديق ملفات مكدّسة أمام باب مخرج الطوارئ. ما أول ما تفعله؟",options:[{text:"أُبعد الصناديق عن المخرج فورًا وأُخرج السلك من الممر، ثم أبلّغ المدير بالأمرين",correct:!0,feedback:"صحيح: المخرج المسدود مشكلة تمس سلامة الأرواح ويجب إصلاحها الآن؛ ثم يأتي خطر التعثر مباشرة."},{text:"أدوّن الأمرين في تقريري الشهري وأعالجهما لاحقًا",correct:!1,feedback:"المخرج المسدود لا ينتظر التقرير: ففي الحريق قد يُحاصَر الناس."},{text:"أغطي السلك بسجادة كي لا يتعثر به أحد",correct:!1,feedback:"يتعثر الناس بالسجادة أيضًا، والسلك تحت السجادة قد يسخن دون أن يُرى. أخرِج السلك من الممر."}]},{prompt:"نُقلت الصناديق، لكن الموظفين يقولون إنه لا مكان آخر للمدفأة والملفات. وقد تعثرت زميلة من قبل وأُصيب معصمها. ماذا بعد؟",options:[{text:"أطلب من الموظفين أن يكونوا أكثر حذرًا أثناء المشي",correct:!1,feedback:"التنبيه وحده لا يزيل الخطر؛ يجب معالجة السبب."},{text:"أتأكد من تلقي الزميلة الإسعافات الأولية، وأسجّل الحادث، وأطلب من المدير مقبسًا قرب المكتب ومكانًا لحفظ الملفات",correct:!0,feedback:"صحيح: اعتنِ بالمصابة، وسجّل ما حدث، وأزِل السبب بحل دائم."},{text:"أترك لكل موظف أن يقرر بنفسه أين يضع الأشياء",correct:!1,feedback:"من دون قرار يعود الخطر؛ يجب أن يوفّر المدير حلًا آمنًا."}]}],realCase:"في قسم حكومي مزدحم، اشتكى عدد من الموظفين من آلام الظهر والرقبة. كان معظمهم يعملون على حواسيب محمولة موضوعة مباشرة على سطح المكتب، ونادرًا ما يقفون خلال اليوم. طلب مسؤول السلامة من كل شخص فحص ارتفاع كرسيه، ورفع الشاشات إلى مستوى العينين بقواعد بسيطة، ونقل الطابعة إلى آخر الغرفة. ووافق المدير على استراحات حركة قصيرة. وفي الجولة نفسها نُقل سلكان كانا يعبران الممر، وأُزيل صندوق كان يسد مخرج الحريق. وطُلب من الموظفين أن يبلّغوا عمّا إذا كانت التغييرات قد ساعدتهم."},{id:11,code:"GOV-111",icon:"Waves",accent:"#2563eb",title:"الفيضانات والأضرار الناجمة عن المياه",subtitle:"Flood Response & Water Damage",summary:"الاستعداد للفيضانات وأضرار المياه في الدوائر والاستجابة لها",blocks:[{body:"قد تصل المياه إلى الدوائر من عدة مصادر: الأمطار والسيول الطبيعية، أو انفجار أنابيب المياه، أو أعطال منظومة التكييف، أو تسرّب المياه من الطابق العلوي. ويُسهم الاستعداد والوعي في تقليل الأضرار."},{heading:"1. مصادر المياه في الدوائر",body:"من أين تأتي المياه:",points:["الأمطار والسيول الطبيعية: ولا سيما في المناطق المنخفضة.","انفجار أنابيب المياه: الأنابيب القديمة والصدئة.","ذوبان الثلوج: يتحول الثلج إلى ماء ويتسرب إلى داخل المبنى.","تسرّب المياه من الطابق العلوي: من دورات المياه والمطبخ.","منظومة التكييف: تجمّع المياه وتسرّبها.","خزانات المياه: انفجار الخزان أو تسرّبه."]},{heading:"2. قبل الفيضان — الاستعداد",body:"التحضيرات الضرورية:",points:["احفظ الوثائق المهمة في الطوابق العليا وفي الخزائن المرتفعة.","لا تضع الحواسيب على الأرض — بل ارفعها 30 سم على الأقل عن الأرض.","يجب ألّا تكون أسلاك الكهرباء ممددة على الأرض.","اعرف مخطط الأنابيب وموقع صمام المياه الرئيسي.","جهّز مضخة لسحب المياه (Sump Pump).","أبقِ قائمة أرقام الفنيين والطوارئ جاهزة."]},{heading:"3. أثناء الفيضان",body:"إذا دخلت المياه إلى الدائرة:",points:["إذا لم تكن واقفًا في الماء واستطعت الوصول إلى المفتاح بأمان، فافصل التيار الكهربائي الرئيسي — فاجتماع الكهرباء والماء قاتل.","اتصل بالرقم 115 وأبلغ مسؤول المبنى.","يتوجه جميع الموظفين بأمان إلى مكان مرتفع.","إذا كان منسوب المياه منخفضًا: انقل الوثائق والحواسيب إلى مكان مرتفع.","لا تخُض في مياه الفيضان: فـ15 سم من المياه الجارية بسرعة قد تُسقط الإنسان، و30 سم قد تجرف السيارة؛ وهناك أيضًا خطر الكهرباء والأمراض.","أغلق صمام المياه الرئيسي."]},{heading:"4. بعد الفيضان",body:"بعد انحسار المياه:",points:["فحص المبنى: يجب أن يفحص المختصون المبنى قبل العودة إليه.","لا تُعِد تشغيل الكهرباء حتى يتأكد الفني من أنها آمنة.","التطهير (Disinfection): مياه الفيضان ملوثة وتنقل البكتيريا والأمراض.","التهوية: افتح جميع النوافذ والأبواب.","التقط صورًا للتوثيق ولأغراض التأمين.","أزِل الأشياء المتضررة بأمان."]},{heading:"5. انفجار الأنابيب وتسرب المياه داخل المبنى",body:"ليس كل فيضان يأتي من الخارج:",points:["اعرف مكان صمام المياه الرئيسي ومن يستطيع إغلاقه.","أغلق الصمام فقط إذا كنت تصل إليه من مكان جاف.","أبعِد الناس عن الأرض المبللة قرب المقابس والأجهزة.","لا تنزع أي قابس ولا تشغّل أي جهاز وأنت واقف في الماء.","أبلِغ مسؤول المبنى وسجّل من أين بدأ التسرب."]},{heading:"6. تحذيرات الفيضان وسلامة الموظفين",body:"عند الإعلان عن أمطار غزيرة أو تحذير من فيضان:",points:["اتبع تعليمات الدفاع المدني والإعلانات الرسمية.","لا يعبر الموظفون الطرق المغمورة سيرًا أو بالسيارة؛ فلينتظروا أو يسلكوا طريقًا آمنًا آخر.","انقل السيارات والسجلات والأجهزة مبكرًا إلى مكان أعلى.","تحقق من وجود جميع الموظفين والمراجعين في نقطة التجمع.","ساعِد الزملاء الذين يحتاجون إلى مساعدة للوصول إلى الطوابق العليا."]}],media:[{kind:"video",src:"media/videos/gov_flood_response.mp4",title:"الاستجابة للفيضان",description:"ماذا نفعل عند دخول المياه"},{kind:"image",src:"media/images/gov_flood_prep.png",title:"الاستعداد للفيضان",description:"خطوة بخطوة"}],quiz:[{question:"عند حدوث فيضان في الدائرة، ما أول ما يجب فعله؟",options:[{text:"جمع الوثائق المهمة وحملها إلى خارج المبنى",correct:!1},{text:"فصل التيار الكهربائي الرئيسي (إن كان ذلك آمنًا)",correct:!0},{text:"التقاط الصور",correct:!1},{text:"نقل الحواسيب إلى الطابق السفلي",correct:!1}],explanation:"اجتماع الكهرباء والماء يشكّل خطرًا على الحياة. فإذا لم تكن واقفًا في الماء واستطعت الوصول إلى المفتاح بأمان، فافصل التيار الكهربائي الرئيسي فورًا؛ وإلا فاخرج واتصل بالرقم 115."},{question:"أين نحفظ الوثائق المهمة في دائرة معرّضة لخطر الفيضان؟",options:[{text:"على الأرض داخل صناديق من الكرتون",correct:!1},{text:"في الطابق السفلي داخل خزائن معدنية مغلقة",correct:!1},{text:"في الطوابق العليا وفي الخزائن المرتفعة",correct:!0},{text:"لا فرق",correct:!1}],explanation:"احفظ الوثائق المهمة دائمًا في مكان مرتفع وآمن."},{question:"لماذا يلزم التطهير بعد الفيضان؟",options:[{text:"لإزالة الرائحة الكريهة التي يتركها الطين",correct:!1},{text:"لأن مياه الفيضان تنقل البكتيريا والأمراض",correct:!0},{text:"لكي تبدو الجدران والأرضيات نظيفة من جديد",correct:!1},{text:"لا يلزم",correct:!1}],explanation:"مياه الفيضان شديدة التلوث وتنقل البكتيريا والأمراض."},{question:"الماء يرتفع في مكتبك والمفتاح الرئيسي في زاوية مبللة. ما التصرف الصحيح؟",options:[{text:"اخُض في الماء بسرعة إلى المفتاح وافصل التيار",correct:!1},{text:"اترك المفتاح، وانقل الجميع إلى طابق أعلى، واتصل بالرقم 115",correct:!0},{text:"انزع قابس كل حاسوب قبل مغادرة الغرفة",correct:!1},{text:"ابقَ وارفع الملفات على المكاتب أولًا",correct:!1}],explanation:"لا تفصل التيار إلا من مكان جاف. فإذا كان المفتاح في مكان مبلل فاتركه، وانقل الناس إلى مكان مرتفع، واتصل بالرقم 115."},{question:"الطريق أمام الدائرة مغطى بماء سريع يبدو أنه لا يتجاوز الكاحل. يريد زميل العبور فيه بسيارته إلى البيت. بماذا تنصحه؟",options:[{text:"أن يقود بسرعة ثابتة كي لا يتوقف محرك السيارة",correct:!1},{text:"ألّا يعبر؛ وأن ينتظر أو يسلك طريقًا آمنًا آخر",correct:!0},{text:"أن يعبره سيرًا على قدميه لأن الماء ضحل",correct:!1},{text:"أن يتبع سيارة أكبر من سيارته عبر الماء",correct:!1}],explanation:"15 سم من الماء السريع قد تُسقط الإنسان، و30 سم قد تجرف السيارة. لا تعبر مياه الفيضان سيرًا أو بالسيارة أبدًا."},{question:"انحسر الماء. متى يمكن للموظفين إعادة تشغيل الكهرباء في الدائرة؟",options:[{text:"بمجرد أن تبدو الأرض جافة",correct:!1},{text:"بعد أن يؤكد فنّي أن ذلك آمن",correct:!0},{text:"عندما يصل مسؤول المبنى صباحًا",correct:!1},{text:"بعد نزع قوابس جميع الحواسيب",correct:!1}],explanation:"قد يُلحق الماء بالأسلاك والأجهزة ضررًا لا يُرى. والفنّي وحده يقرر متى تكون الكهرباء آمنة."}],steps:[{title:"اجعل الكهرباء آمنة، ومن مكان جاف فقط",detail:"إذا لم تكن واقفًا في الماء وكان بإمكانك الوصول إلى المفتاح بأمان، فافصل التيار الرئيسي. وإذا كانت الأرض مبللة أو كان المفتاح قريبًا من الماء، فلا تلمسه: غادر المكان.",critical:!0},{title:"أطلِق التنبيه واتصل بالرقم 115",detail:"نبّه الجميع في الطابق، وأبلِغ مسؤول المبنى، واتصل بالرقم 115: اذكر المكان وعمق الماء وما إذا كان هناك محاصَرون.",critical:!0},{title:"انقل الناس إلى مكان مرتفع",detail:"ينتقل الموظفون والمراجعون عبر الدرج إلى طابق أعلى أو إلى مكان مرتفع آمن، وفق تعليمات الدفاع المدني. ساعِد الزملاء والمراجعين الذين يحتاجون إلى مساعدة.",critical:!0},{title:"احمِ الوثائق فقط إذا كان ذلك آمنًا",detail:"إذا كان الماء قليلًا ولم تكن في خطر، فارفع الملفات والحواسيب إلى أعلى. لا تبقَ في الخلف أبدًا ولا تخض في الماء لإنقاذ الأجهزة."},{title:"ابتعد عن مياه الفيضان",detail:"15 سم من الماء السريع قد تُسقط الإنسان، و30 سم قد تجرف السيارة؛ وقد يكون الماء مكهربًا أو ملوثًا. لا تعبره سيرًا أو بالسيارة أبدًا.",critical:!0},{title:"لا تعد إلا بعد إعلان أن المكان آمن",detail:"عُد بعد أن يفحص خبير المبنى. ولا يعيد تشغيل الكهرباء إلا فنّي. البس قفازات وأحذية مطاطية للتنظيف، وطهّر كل ما لامسه الماء."}],warnings:["لا تلمس أبدًا مفتاحًا أو مقبسًا أو جهازًا كهربائيًا وأنت واقف في الماء أو الأرض مبللة: الكهرباء والماء معًا يقتلان.","لا تعبر مياه الفيضان سيرًا أو بالسيارة أبدًا، حتى إن بدت ضحلة: 15 سم من الماء السريع قد تُسقط الإنسان.","لا تعد إلى المبنى لإنقاذ ملفات أو أجهزة عندما يكون الماء في ارتفاع."],tips:["حدِّد مكان المفتاح الرئيسي للكهرباء وصمام المياه الرئيسي على خطة الطوارئ في الدائرة.","احفظ السجلات المهمة في خزائن مرتفعة واحتفظ بنسخ منها خارج المبنى.","جهّز حقيبة مقاومة للماء للوثائق الأساسية.","بعد الأمطار الغزيرة، افحص القبو والطابق الأرضي قبل أن يبدأ الموظفون العمل."],activity:{prompt:"تهطل أمطار غزيرة ويبدأ الماء بالدخول من تحت باب مكتبك في الطابق الأرضي. يصل الماء إلى الكاحل ويرتفع. لوحة الكهرباء في الجهة المقابلة من الغرفة والأرض بقربها مبللة. ماذا تفعل؟",options:[{text:"أخوض في الماء إلى اللوحة وأفصل التيار",correct:!1,feedback:"ستكون واقفًا في الماء وأنت تلمس اللوحة؛ والكهرباء والماء معًا قد يقتلان. اتركها."},{text:"لا أقترب من اللوحة؛ أصعد بالجميع عبر الدرج إلى طابق أعلى، وأبلغ مسؤول المبنى، وأتصل بالرقم 115",correct:!0,feedback:"صحيح: لا يمكن الوصول إلى المفتاح من مكان جاف، لذلك ينتقل الناس إلى مكان مرتفع ويتولى مسؤول المبنى و115 أمر الكهرباء بأمان."},{text:"أنقل الحواسيب إلى مخزن القبو",correct:!1,feedback:"القبو أول ما يغمره الماء، والبقاء لنقل الأجهزة يضيّع الوقت ويعرّضك للخطر."},{text:"أبقى على مكتبي وأنتظر توقف المطر",correct:!1,feedback:"مياه الفيضان قد ترتفع بسرعة. اصعد الآن إلى طابق أعلى."}]},caseStudy:[{prompt:"أنت مسؤول الطابق الأرضي. انفجر أنبوب ماء في المخزن، والماء ينتشر على طول الممر نحو غرفة الخوادم والمقابس القريبة من الأرض. لم يُصب أحد. ما أول ما تفعله؟",options:[{text:"أُبعد الناس عن المكان المبلل والمقابس، وأطلب إغلاق صمام المياه الرئيسي إذا أمكن الوصول إليه من مكان جاف، وأبلغ مسؤول المبنى",correct:!0,feedback:"صحيح: احمِ الناس من الكهرباء أولًا، ثم أوقف الماء من مصدره إذا كان ذلك آمنًا."},{text:"أنزع قوابس الحواسيب في الممر المبلل واحدًا تلو الآخر",correct:!1,feedback:"لمس القوابس في مكان مبلل فيه خطر الصعق الكهربائي. ابتعد ودع التيار يُفصل بأمان."},{text:"أدفع الماء بنفسي بالممسحة نحو البالوعة",correct:!1,feedback:"الممسحة لا توقف الماء وتُبقيك في مكان مبلل قرب المقابس. أوقف المصدر وأبعِد الناس."}]},{prompt:"أُغلق صمام المياه، لكن الماء وصل إلى أحد المقابس وتنبعث رائحة احتراق من الجدار. ماذا بعد؟",options:[{text:"أسكب دلوًا من الماء على المقبس",correct:!1,feedback:"الماء على عطل كهربائي قد يسبب صعقًا كهربائيًا وينشر الخطر؛ لا تستخدم الماء أبدًا على أجهزة يسري فيها التيار."},{text:"أنتظر لأرى إن كانت الرائحة ستزول",correct:!1,feedback:"رائحة الاحتراق من مقبس مبلل قد تكون بداية حريق كهربائي. تصرّف الآن."},{text:"أشغّل إنذار الحريق، وأُخرج الجميع من الطابق، وأتصل بالرقم 115؛ ولا يُفصل التيار من المفتاح الرئيسي إلا إذا أمكن الوصول إليه من مكان جاف",correct:!0,feedback:"صحيح: الحريق الكهربائي المحتمل حالة طوارئ حريق. أخلِ المكان، واتصل بالرقم 115، وافصل التيار فقط إذا كان ذلك آمنًا."}]}],realCase:"بعد ليلة من الأمطار الغزيرة، وصل الموظفون إلى دائرة عامة فوجدوا الماء في أرشيف القبو وفي الطابق الأرضي. أراد أحد الموظفين النزول على درج القبو لإنقاذ الملفات. فأوقفه مسؤول المبنى: كانت مصابيح القبو لا تزال مضاءة والماء قد وصل إلى المقابس. أبقى الجميع في الطوابق العليا واتصل بالرقم 115. وبعد فصل التيار وفحص المبنى، لبس الموظفون قفازات وأحذية مطاطية لإخراج الملفات المبللة. ثم نقلت الدائرة أرشيفها إلى طابق علوي."},{id:12,code:"GOV-112",icon:"FlaskConical",accent:"#65a30d",title:"المواد الكيميائية ومواد التنظيف",subtitle:"Chemical Safety & Cleaning Agents",summary:"الاستخدام الآمن لمواد التنظيف والمواد الكيميائية في الدوائر",blocks:[{body:"تستخدم الدوائر الحكومية أنواعًا كثيرة من مواد التنظيف. وقد يؤدي خلط بعض هذه المواد إلى تكوّن غازات سامة وخطرة. ومعرفة هذه المواد واستخدامها بصورة صحيحة يُنقذان الأرواح."},{heading:"1. المواد الخطرة في الدوائر",body:"توجد هذه المواد في كثير من الدوائر:",points:["مبيّض الكلور (Bleach): لتنظيف دورات المياه — وإذا خُلط بحمض أو بالأمونيا كوّن غازات سامة.","الأمونيا: لتنظيف النوافذ — تضر بالجهاز التنفسي.","الأحماض: لإزالة الترسبات الكلسية — تحرق الجلد.","حبر الطابعات (Toner): مسحوق ناعم — يشكّل خطرًا على الرئتين.","سائل تصحيح الكتابة (Correction Fluid): قابل للاشتعال وأبخرته ضارة.","حمض البطاريات: يسبب حروقًا كيميائية."]},{heading:"2. قاعدة عدم الخلط!",body:"لا تخلط هذه المواد أبدًا:",points:["الكلور + الأمونيا = غاز الكلورامين (سام وقاتل).","الكلور + الحمض = غاز الكلور (سام وقاتل).","الكلور + الخل (وهو حمض) = غاز الكلور.","استخدم كل مادة على حدة.","خفِّفها بالماء فقط وفق التعليمات المدوّنة على العبوة — لا بمادة أخرى.","اقرأ دائمًا التعليمات المدوّنة على ملصق العبوة (Label)."]},{heading:"3. معدات الوقاية الشخصية (PPE)",body:"معدات الحماية عند استخدام المواد:",points:["القفازات: ضرورية مع جميع المواد الكيميائية.","الكمامة: عند استخدام الكلور والمواد ذات الروائح النفّاذة.","النظارات الواقية: للأحماض والبخاخات.","ملابس الحماية: للمواد القوية.","إذا لامست المادة الجلد أو العينين: اغسلها بالماء الجاري مدة 20 دقيقة على الأقل؛ وإذا حدث حرق أو تسمم، فاتصل بالرقم 122.","التهوية: افتح النافذة أثناء التنظيف."]},{heading:"4. تخزين المواد والتخلص منها",body:"قواعد تخزين المواد:",points:["احفظها في مكان مقفل.","بعيدًا عن أشعة الشمس والحرارة.","اكتب اسم المادة على جميع القوارير والعبوات.","أبقِ صحائف بيانات السلامة (SDS) جاهزة.","تخلّص من المواد منتهية الصلاحية بالطريقة الصحيحة — ولا تسكبها في مجاري الصرف الصحي.","احفظها بعيدًا عن الطعام ومياه الشرب."]},{heading:"5. الانسكابات والتسربات الصغيرة",body:"إذا انسكب منتج تنظيف في الدائرة:",points:["أبعِد الناس وافتح النوافذ إذا كان ذلك آمنًا.","البس القفازات قبل أن تلمس أي شيء.","امتصّ الانسكاب الصغير بالورق أو القماش وضعه في كيس مغلق.","لا تصبّه في البالوعة إلا إذا سمح الملصق بذلك.","عند انسكاب كبير أو رائحة قوية أو شعور أشخاص بتوعك: غادر الغرفة وأغلق الباب واتصل بالرقمين 115 و122."]}],media:[{kind:"video",src:"media/videos/gov_chemical_safety.mp4",title:"السلامة الكيميائية",description:"الاستخدام الصحيح"},{kind:"image",src:"media/images/gov_mixing_danger.png",title:"خطر الخلط",description:"المواد التي يجب ألّا تُخلط"},{kind:"image",src:"media/images/gov_ppe_cleaning.png",title:"PPE للتنظيف",description:"معدات الحماية"}],quiz:[{question:"ماذا يحدث إذا خلطنا الكلور بالأمونيا؟",options:[{text:"يتكوّن منظّف أقوى للبقع الصعبة",correct:!1},{text:"يتكوّن غاز الكلورامين (السام)",correct:!0},{text:"لا يحدث شيء",correct:!1},{text:"تتكوّن رغوة بيضاء غير ضارة",correct:!1}],explanation:"خلط الكلور بالأمونيا يُكوّن غاز الكلورامين — وفي ذلك خطر على الحياة."},{question:"إذا لامست مادة كيميائية الجلد، فماذا نفعل؟",options:[{text:"نمسحها بمنديل جاف ثم نغطيها بضمادة",correct:!1},{text:"نغسلها بالماء مدة 20 دقيقة على الأقل",correct:!0},{text:"نضع عليها طبقة سميكة من الكريم",correct:!1},{text:"لا نفعل شيئًا",correct:!1}],explanation:"اغسلها فورًا بالماء الجاري مدة 20 دقيقة على الأقل وانزع الملابس الملوثة؛ وإذا حدث حرق، فاتصل بالرقم 122."},{question:"أين نحفظ مواد التنظيف في الدائرة؟",options:[{text:"على رف مفتوح قرب المدفأة لتبقى جافة",correct:!1},{text:"في المطبخ بجانب الطعام والمشروبات",correct:!1},{text:"في مكان مقفل وبعيد عن الحرارة",correct:!0},{text:"لا فرق",correct:!1}],explanation:"احفظها في مكان مقفل، بعيدًا عن الحرارة والطعام."},{question:"تناثر مزيل الترسبات الكلسية في عين عاملة تنظيف. ما أول ما تفعله؟",options:[{text:"اشطف العين بالماء الجاري 20 دقيقة على الأقل",correct:!0},{text:"ضع قطرات للعين ودعها ترتاح قليلًا",correct:!1},{text:"افرك العين برفق بمنديل نظيف وجاف",correct:!1},{text:"غطِّ العين وانتظر حتى يزول الألم",correct:!1}],explanation:"اشطف فورًا بالماء الجاري مدة 20 دقيقة على الأقل؛ واتصل بالرقم 122 لأن العين قد تكون محترقة."},{question:"شرب زميل سائل تنظيف من قنينة ماء بلا ملصق. ما التصرف الصحيح؟",options:[{text:"حثّه على التقيؤ في أسرع وقت ثم أعطه ماءً",correct:!1},{text:"أعطه حليبًا لتخفيف السائل في معدته",correct:!1},{text:"لا تحثّه على التقيؤ؛ احتفظ بالقنينة واتصل بالرقم 122",correct:!0},{text:"أعطه ماءً مالحًا ودعه يرتاح في غرفة هادئة",correct:!1}],explanation:"التقيؤ قد يحرق الحلق مرة أخرى ويؤذي الرئتين. لا تعطِ شيئًا عن طريق الفم إلا إذا قال الطبيب ذلك، واحتفظ بالعبوة واتصل بالرقم 122."},{question:"أيّ ترتيب للتخزين خاطئ؟",options:[{text:"الكلور ومنظفات الأحماض على رفوف منفصلة في مخزن مقفل",correct:!1},{text:"اسم المنتج مكتوب على كل عبوة",correct:!1},{text:"منظّف مخفّف محفوظ في قنينة ماء قديمة في المطبخ",correct:!0},{text:"صحائف SDS محفوظة حيث يجدها عمال التنظيف",correct:!1}],explanation:"المادة الكيميائية في قنينة شراب أو قرب الطعام قد تُشرب بالخطأ. أبقِ المواد موسومة ومقفلًا عليها وبعيدة عن الطعام."}],steps:[{title:"اقرأ الملصق وصحيفة SDS أولًا",detail:"قبل استخدام أي منتج، اقرأ ملصقه: لأي غرض هو، وكيف يُخفَّف، وما الحماية اللازمة. وتعطي صحيفة بيانات السلامة (SDS) كل التفاصيل."},{title:"هوِّ المكان والبس معدات الحماية",detail:"افتح النوافذ والبس القفازات؛ وأضِف نظارات واقية أو كمامة عندما يطلب الملصق ذلك، كما مع الكلور والأحماض."},{title:"استخدم منتجًا واحدًا في كل مرة",detail:"لا تخلط المنتجات أبدًا. خفِّف بالماء فقط كما يقول الملصق، واغسل الدلو والقطعة بين منتج وآخر.",critical:!0},{title:"رذاذ على الجلد أو في العينين",detail:"اشطف فورًا بالماء الجاري مدة 20 دقيقة على الأقل وانزع الملابس الملوثة؛ واتصل بالرقم 122 إذا وُجد حرق أو تأثرت العينان.",critical:!0},{title:"أبخرة أو شخص يشعر بتوعك",detail:"إذا ظهرت رائحة نفّاذة أو بدأ أحد بالسعال أو الدوار، يخرج الجميع إلى الهواء النقي، ويُغلق الباب، ويُتصل بالرقم 122. لا تعد إلى الداخل لتهوية الغرفة.",critical:!0},{title:"ابتلاع بالخطأ",detail:"لا تحثّه على التقيؤ ولا تعطه أي طعام أو شراب إلا إذا قال الطبيب ذلك. احتفظ بالعبوة واتصل بالرقم 122.",critical:!0}],warnings:["لا تخلط الكلور أبدًا مع الأمونيا أو الأحماض أو الخل: فالغازات الناتجة قد تقتل.","لا تضع المواد الكيميائية أبدًا في قناني الماء أو المشروبات الغازية أو في عبوات بلا ملصق: قد يشربها أحد بالخطأ.","لا تحثّ من ابتلع مادة كيميائية على التقيؤ، ولا تعطه حليبًا أو زيتًا أو ماءً مالحًا."],tips:["أبقِ مخزن مواد التنظيف مقفلًا والمفتاح مع شخص مسؤول.","ضع نسخة من صحيفة SDS لكل منتج حيث يجدها عمال التنظيف.","اختر المنتجات الجاهزة للاستعمال قدر الإمكان، كي لا يحتاج العمال إلى التخفيف أو الخلط.","علّم عمال التنظيف الجدد قاعدة عدم الخلط في يومهم الأول."],activity:{prompt:"عاملة تنظيف تنظّف دورة المياه بالكلور. البقع لا تزول، فتهمّ بسكب مزيل الترسبات الكلسية (وهو حمض) في الدلو نفسه. ماذا تفعل؟",options:[{text:"أدعها تفعل ذلك لكن أفتح النافذة أولًا",correct:!1,feedback:"النافذة المفتوحة لا تجعل الأمر آمنًا: الكلور والحمض معًا يكوّنان غاز الكلور الذي قد يقتل."},{text:"أوقفها فورًا وأشرح أن الكلور والحمض يكوّنان غازًا سامًا، لذلك يُستخدم كل منتج وحده ويُشطف قبل استخدام الآخر",correct:!0,feedback:"صحيح: لا خلط أبدًا. استخدم منتجًا واحدًا، واشطف، ثم استخدم الآخر."},{text:"أطلب منها إضافة ماء ساخن ليصبح الخليط أضعف",correct:!1,feedback:"إضافة الماء لا توقف التفاعل؛ والغاز يتكوّن رغم ذلك."},{text:"أقترح أن تستخدم الأمونيا بدل الحمض",correct:!1,feedback:"الكلور والأمونيا يكوّنان غاز الكلورامين وهو سام أيضًا. لا يُخلط الكلور إلا بالماء."}]},caseStudy:[{prompt:"في دورة مياه إحدى الدوائر خلطت عاملة تنظيف منتجين. تملأ رائحة نفّاذة الممر؛ والعاملة تسعل وعيناها تدمعان. ما أول ما تفعله؟",options:[{text:"أُخرجها مع كل من حولها إلى الهواء النقي، وأغلق باب دورة المياه، وأتصل بالرقم 122",correct:!0,feedback:"صحيح: أبعِد الناس عن الغاز أولًا واطلب المساعدة الطبية."},{text:"أدخل بقطعة قماش مبللة على وجهي لأسكب الخليط في البالوعة",correct:!1,feedback:"القماش المبلل لا يحميك من الغاز؛ وقد تصبح أنت المصاب الثاني."},{text:"أرشّ معطّر الجو في الممر لإخفاء الرائحة",correct:!1,feedback:"معطّر الجو لا يزيل الغاز السام ويضيف مادة كيميائية أخرى. أخرِج الناس."}]},{prompt:"العاملة الآن في الخارج في الهواء النقي. لا تزال تسعل، وقد تناثر بعض السائل على ساعدها. سيارة الإسعاف في الطريق. ماذا بعد؟",options:[{text:"أعطيها حليبًا لتهدئة حلقها",correct:!1,feedback:"لا شراب إلا إذا قال الطبيب ذلك؛ والحليب لا يعالج التعرض للمواد الكيميائية."},{text:"أشطف ساعدها بالماء الجاري مدة 20 دقيقة على الأقل، وأنزع الملابس الملوثة، وأحتفظ بعبوات المنتجات لفريق الإسعاف",correct:!0,feedback:"صحيح: اشطف الجلد وأعطِ فريق الإسعاف أسماء المنتجات ليعرفوا ما تعرّضت له."},{text:"أطلب منها أن تذهب إلى البيت لترتاح",correct:!1,feedback:"من يسعل بعد التعرض لمادة كيميائية يحتاج إلى فحص طبي. انتظر 122."}]}],realCase:"أرادت عاملة تنظيف في مبنى حكومي أن تكون أرضية دورة المياه نظيفة جدًا، فسكبت الكلور ثم مزيلًا قويًا للترسبات الكلسية في الدلو نفسه. وخلال لحظات انتشرت رائحة نفّاذة في الممر. طلب زميل كان قد حضر تدريب السلامة في الدائرة من الجميع المغادرة، وأغلق الباب واتصل بالرقم 122. أُخرجت العاملة، وكانت تسعل، إلى الهواء النقي وفحصها فريق الإسعاف. وبعد ذلك أقفلت الدائرة مخزن التنظيف، ووضعت قاعدة عدم الخلط على بابه، ودرّبت جميع عمال التنظيف."},{id:13,code:"GOV-113",icon:"ArrowUpDown",accent:"#4f46e5",title:"السلامة في المصاعد والسلالم",subtitle:"Elevator & Stairway Safety",summary:"الاستخدام الآمن للمصعد والوقاية من السقوط على السلالم",blocks:[{body:"تُعدّ المصاعد والسلالم من الأماكن التي تكثر فيها الحوادث في المباني الحكومية. فالسقوط على السلالم من أكثر حوادث العمل شيوعًا، كما أن الاحتجاز داخل المصعد حالة خطيرة. ومعرفة القواعد تقلل من الخطر."},{heading:"1. السلامة في المصعد",body:"قواعد استخدام المصعد:",points:["إذا تأخر المصعد، فاصبر — ولا تضغط الزر مرات كثيرة.","لا تفتح باب المصعد يدويًا — دعه يُفتح تلقائيًا.","لا تتجاوز الحمولة المسموح بها (المكتوبة عليه).","لا تستخدمه أثناء انقطاع الكهرباء.","لا تستخدمه أثناء الحريق والزلزال — استخدم السلالم فقط.","اعرف مكان زر الطوارئ."]},{heading:"2. الاحتجاز داخل المصعد",body:"إذا احتُجزت داخل المصعد:",points:["حافظ على هدوئك — لا تخف.","اضغط زر الطوارئ.","استخدم هاتف الطوارئ داخل المصعد.","إذا توفرت تغطية لشبكة الهاتف المحمول، فاتصل بالرقم 115.","لا تحاول فتح الباب أو الخروج — فذلك خطير.","انتظر حتى يصل الفني أو فريق 115 — فالهواء داخل المصعد لا ينفد."]},{heading:"3. السلامة على السلالم",body:"الوقاية من السقوط على السلالم:",points:["أمسك دائمًا بالدرابزين (Handrail).","انظر أمام قدميك — ولا تستخدم الهاتف المحمول.","درجة بعد درجة — لا تقفز.","امشِ بحذر على السلالم المبللة.","عند حمل الأغراض، أبقِ يدًا حرة للإمساك بالدرابزين.","يجب أن تكون إضاءة السلالم جيدة — استبدل المصابيح التالفة."]},{heading:"4. الفحص والصيانة",body:"الفحوصات المنتظمة:",points:["المصعد: صيانة شهرية من قِبل شركة مختصة، وفحص سنوي من قِبل جهة معتمدة.","علّق شهادة الفحص داخل المصعد.","افحص إضاءة الطوارئ على السلالم.","أصلِح الدرجات المكسورة فورًا.","ضع علامات تحذيرية في الأماكن الزلقة.","أبقِ السلالم نظيفة — ولا تترك أي أغراض عليها."]},{heading:"5. عند احتجاز أحد في المصعد: ما يفعله الموظفون في الخارج",body:"إذا سمعت إنذار المصعد:",points:["تحدث إلى من في الداخل وأخبرهم أن المساعدة قادمة.","اسأل عن عددهم وهل بينهم متوعك.","اتصل بفنّي المصعد وبالرقم 115؛ واتصل بالرقم 122 إذا كان أحدهم متوعكًا.","لا تفتح الأبواب بمفاتيح أو أدوات إلا إذا كنت مدربًا ومخوّلًا.","أبقِ المكان أمام الأبواب خاليًا للمنقذين."]},{heading:"6. من لا يستطيعون استخدام الدرج",body:"خطّط مسبقًا للزملاء والمراجعين محدودي الحركة:",points:["لكل من يحتاج إلى مساعدة مساعد محدد وخطة مكتوبة.","تحدد الخطة أين ينتظرون إذا لم يستطيعوا النزول وكيف يُوصل إليهم.","يخبر مسؤول الطابق فريق 115 بمكان انتظارهم.","لا يحمل الموظفون غير المدربين أحدًا على الدرج.","طبّق الخطة في كل تمرين إخلاء."]}],media:[{kind:"video",src:"media/videos/gov_elevator_safety.mp4",title:"السلامة في المصعد",description:"الاستخدام الصحيح والاحتجاز داخله"},{kind:"image",src:"media/images/gov_stair_safety.png",title:"السلامة على السلالم",description:"قواعد الوقاية من السقوط"}],quiz:[{question:"أثناء الحريق، ماذا نستخدم للخروج؟",options:[{text:"المصعد",correct:!1},{text:"سلالم المبنى",correct:!0},{text:"لا فرق",correct:!1},{text:"النوافذ",correct:!1}],explanation:"لا تستخدم المصعد أبدًا أثناء الحريق والزلزال — اخرج عبر السلالم فقط."},{question:"إذا احتُجزت داخل المصعد، فماذا تفعل؟",options:[{text:"أفتح الباب بالقوة وأتسلّق إلى الخارج بنفسي",correct:!1},{text:"أصرخ بخوف",correct:!1},{text:"أضغط زر الطوارئ وأحافظ على هدوئي",correct:!0},{text:"أقفز لكي يعود المصعد إلى العمل",correct:!1}],explanation:"حافظ على هدوئك واضغط زر الطوارئ، ولا تحاول فتح الباب."},{question:"للوقاية من السقوط على السلالم، ماذا نفعل؟",options:[{text:"نقفز",correct:!1},{text:"نمشي بسرعة ونقرأ رسائل الهاتف أثناء النزول",correct:!1},{text:"نمسك بالدرابزين وننظر أمام أقدامنا",correct:!0},{text:"نحمل صناديق كبيرة تحجب عنّا رؤية الدرجات",correct:!1}],explanation:"أمسك دائمًا بالدرابزين وانظر أمام قدميك."},{question:"أنت محتجز في مصعد مع زميل يوشك أن يُغمى عليه. ماذا تفعل؟",options:[{text:"افتح الأبواب بالقوة ليدخل الهواء النقي",correct:!1},{text:"اضغط زر الطوارئ واتصل بالرقمين 115 و122",correct:!0},{text:"اخرج من فتحة السقف لتجلب المساعدة",correct:!1},{text:"اقفز ليعود المصعد إلى الحركة",correct:!1}],explanation:"أطلِق التنبيه واطلب المساعدة؛ والرقم 122 مطلوب لأن أحدكم متوعك. فتح الأبواب بالقوة أو الخروج خطر."},{question:"أوقف انقطاع الكهرباء المصعد بين الطوابق. يريد موظفون في الخارج فتح الأبواب بأيديهم لإخراج من في الداخل. ما التصرف الصحيح؟",options:[{text:"فتح الأبواب معًا وإخراجهم",correct:!1},{text:"فتح الأبواب بمفتاح من مكتب الأمن",correct:!1},{text:"التحدث إليهم والاتصال بالفنّي و115 والانتظار",correct:!0},{text:"الضغط على زر الاستدعاء حتى يتحرك المصعد",correct:!1}],explanation:"قد يسقط الناس في بئر المصعد أو يُسحقون إذا تحرك. الفنّي أو فريق 115 وحدهم يُخرجونهم."},{question:"يدوي إنذار الحريق. زميلة تستخدم كرسيًا متحركًا تعمل في الطابق الثالث. ماذا تقول الخطة الجيدة؟",options:[{text:"أن تستخدم المصعد وحدها قبل الآخرين",correct:!1},{text:"أن يحملها زميلان غير مدربين على الدرج",correct:!1},{text:"أن تنتظر في المكان المحدد مع مساعد ويُبلَّغ 115",correct:!0},{text:"أن تبقى في مكتبها والباب مفتوح",correct:!1}],explanation:"من لا يستطيع استخدام الدرج يتبع خطة مكتوبة: مساعد، ومكان انتظار محدد، وإبلاغ فريق 115 بمكانه."}],steps:[{title:"استخدم الدرج في الطوارئ",detail:"أثناء الحريق أو الزلزال أو انقطاع الكهرباء لا تستخدم المصعد أبدًا؛ استخدم الدرج وأمسك الدرابزين.",critical:!0},{title:"إذا احتُجزت في المصعد فالزم الهدوء",detail:"لن ينفد الهواء. اضغط زر الطوارئ واستخدم الهاتف داخل المصعد.",critical:!0},{title:"اطلب المساعدة",detail:"إذا توفرت تغطية للهاتف، فاتصل بالرقم 115: اذكر المبنى والمصعد والطابق الذي توقف عنده، وعدد الأشخاص في الداخل، وما إذا كان أحدهم متوعكًا (واتصل حينئذ بالرقم 122 أيضًا)."},{title:"لا تفتح الأبواب بالقوة",detail:"لا تحاول فتح الأبواب أو الخروج من السقف أو من فتحة: فقد يتحرك المصعد فجأة. انتظر الفنّي أو فريق 115.",critical:!0},{title:"خارج المصعد: طمئِن وأبلِغ",detail:"إذا احتُجز أحد، فتحدث إليه من خلف الباب، وأخبره أن المساعدة قادمة، واتصل بفنّي المصعد وبالرقم 115، وأبعِد الآخرين عن الأبواب."},{title:"أبلِغ عن كل عطل",detail:"أبلِغ عن باب لا يُغلق جيدًا، أو مصعد يهتز، أو درابزين مكسور، أو درجة متضررة، ولا تستخدمه حتى يُصلَح."}],warnings:["لا تستخدم المصعد أبدًا أثناء الحريق أو الزلزال: قد يتوقف بين الطوابق أو يُفتح في طابق الحريق، وقد يمتلئ بئر المصعد بالدخان.","لا تفتح أبواب المصعد بالقوة أبدًا ولا تُخرج الناس من مصعد متوقف بين الطوابق: فقد يسقطون في بئر المصعد أو يُسحقون إذا تحرك."],tips:["اعرف مكان زر الطوارئ في المصعد وتأكد من أن هاتف المصعد يعمل.","علّق رقم الطوارئ لشركة المصاعد بجانب المصعد وعلى مكتب الأمن.","أبقِ يدًا حرة للدرابزين على الدرج، حتى وأنت مستعجل.","أبلِغ عن أي مصباح محترق في الدرج في اليوم نفسه."],activity:{prompt:"يتوقف المصعد الذي أنت فيه بين طابقين وتومض الإضاءة. معك ثلاثة أشخاص، أحدهم يذعر ويحاول فتح الأبواب بيديه. ماذا تفعل؟",options:[{text:"أطلب منه بهدوء أن يتوقف، وأضغط زر الطوارئ، وأستخدم هاتف المصعد، وأوضح أن الهواء لن ينفد وأن المساعدة قادمة",correct:!0,feedback:"صحيح: هدّئ الآخرين، وأطلِق التنبيه، وانتظر؛ ففتح الأبواب بالقوة خطر."},{text:"أساعده على فتح الأبواب لنخرج",correct:!1,feedback:"إذا تحرك المصعد وأنت تخرج فقد تسقط في البئر أو تُسحق."},{text:"نقفز جميعًا معًا ليعود المصعد إلى العمل",correct:!1,feedback:"القفز قد يشغّل نظام الأمان ويسبب إصابات؛ ولا يعيد تشغيل المصعد أبدًا."},{text:"نبقى صامتين وننتظر دون إبلاغ أحد",correct:!1,feedback:"قد لا يعرف أحد أنكم محتجزون. اضغط زر الطوارئ واطلب المساعدة."}]},caseStudy:[{prompt:"أنت مسؤول الطابق. يدوي إنذار الحريق ويتجه موظفو طابقك بحكم العادة نحو المصعد. وزميلة لك تستخدم كرسيًا متحركًا موجودة في مكتبها. ما أول ما تفعله؟",options:[{text:"أوقف الناس عند المصعد، وأوجههم إلى الدرج، وأذهب إلى زميلتي لأساعدها على اتباع خطة إخلائها",correct:!0,feedback:"صحيح: لا يُستخدم المصعد في الحريق، ومن لا يستطيع استخدام الدرج يحتاج إلى خطته وإلى مساعد."},{text:"أدعهم يستخدمون المصعد لأنه أسرع",correct:!1,feedback:"قد يتوقف المصعد أو يُفتح في طابق الحريق. لا تستخدمه أبدًا في الحريق."},{text:"أنزل أولًا لأتأكد من أن المخرج مفتوح",correct:!1,feedback:"بصفتك مسؤول الطابق تتأكد من خروج كل من في طابقك؛ لا تترك زميلتك خلفك."}]},{prompt:"وصلت زميلتك ومساعدها إلى المكان الذي تقول خطتها إنها تنتظر فيه المنقذين. الجميع ينزلون على الدرج. ماذا بعد؟",options:[{text:"أطلب من المساعد أن يحملها فورًا وينزل بها على الدرج",correct:!1,feedback:"حمل شخص على الدرج دون تدريب ومعدات قد يؤذي الاثنين. اتبع الخطة."},{text:"أنزل وأخبر فريق 115 وقائد الحادث بدقة أين تنتظر ومن معها",correct:!0,feedback:"صحيح: يجب أن يعرف المنقذون أين ينتظر من لم يستطيعوا النزول، ليصلوا إليهم بسرعة."},{text:"أعود إلى الأعلى لأنتظر معها، وأترك بقية طابقي",correct:!1,feedback:"مساعدها يبقى معها؛ ومهمتك أن تبلّغ عن مكانها وأن تتحقق من وجود طابقك في نقطة التجمع."}]}],realCase:"في عصر يوم حار، أوقف انقطاع الكهرباء مصعدًا بين طابقين في مبنى حكومي وفيه أربعة موظفين. ذكّر أحدهم، وكان قد حضر دورة السلامة، الآخرين بأن الهواء لن ينفد وضغط زر الطوارئ. سمع حارس الأمن الإنذار، فتحدث إليهم من خلف الباب واتصل بشركة المصاعد وبالرقم 115. أراد أحد الزملاء فتح الأبواب بمفتاح من مكتب الحارس، لكن الحارس منعه. وأعاد الفنّي المصعد إلى مستوى الطابق وفتح الأبواب بأمان."},{id:14,code:"GOV-114",icon:"Network",accent:"#e11d48",title:"إدارة الأزمات",subtitle:"Crisis Management & ICS",summary:"تشكيل فريق إدارة الأزمات ونظام قيادة الحوادث (ICS)",blocks:[{body:"يجب أن يكون لكل دائرة حكومية فريق لإدارة الأزمات (Crisis Management Team). وقد تكون الأزمة حريقًا أو زلزالًا أو فيضانًا أو هجومًا أمنيًا أو حتى هجومًا سيبرانيًا. ويُعدّ نظام قيادة الحوادث (ICS) أداة دولية لإدارة أي حادث."},{heading:"1. فريق إدارة الأزمات (CMT)",body:"تشكيلة الفريق:",points:["رئيس الفريق (Crisis Commander): صاحب القرار والموجِّه.","مسؤول العمليات (Operations): تنظيم الأنشطة.","مسؤول الاتصال والإعلام: التواصل مع الجهات الخارجية ووسائل الإعلام.","مسؤول الدعم اللوجستي: المستلزمات والمعدات.","مسؤول البيانات: توثيق الأحداث.","مسؤول الإسعافات الأولية: مساعدة المصابين."]},{heading:"2. نظام قيادة الحوادث (ICS)",body:"ICS (Incident Command System):",points:["طُوِّر في الولايات المتحدة الأمريكية، ويُستخدم الآن في دول كثيرة.","قائد واحد للحادث — وتسلسل القيادة واضح.","تحديد المهام: يعرف كل شخص مهمته ويتبع مشرفًا واحدًا.","اتصال موحَّد: قناة اتصال واحدة ولغة بسيطة.","تنظيم مرن (Modular): يتوسّع الهيكل أو يتقلّص بحسب حجم الحادث.","التقارير: تحديث التقارير في أوقات محددة."]},{heading:"3. خطوات الاستجابة للأزمة",body:"الإجراء العام:",points:["1. الإنذار: فعِّل نظام الإنذار.","2. التقييم: اعرف ما الذي حدث وما حجمه.","3. التفعيل: اجمع فريق CMT.","4. الإدارة: اتخذ القرارات ونفّذها.","5. الاتصال: أبلغ جميع الجهات المعنية.","6. التعافي: نفِّذ خطة العودة إلى العمل الطبيعي."]},{heading:"4. التدريب والاختبار",body:"الاستعداد المستمر:",points:["تمرين مكتبي (Tabletop Exercise) كل 3 أشهر.","تمرين شامل (Full-Scale Drill) كل 6 أشهر.","تحديث خطة الأزمات سنويًا.","اختبار نظام الاتصال.","التنسيق مع الدفاع المدني (115) والشرطة (104).","أجرِ تقييمًا بعد كل تمرين وحسِّن الأداء."]},{heading:"5. الأولويات والتسليم",body:"ترتيب الأولويات واحد في كل أزمة:",points:["أولًا: أرواح الموظفين والمراجعين والمستجيبين وسلامتهم.","ثانيًا: منع الحادث من الاتساع.","ثالثًا: حماية الممتلكات والسجلات والبيئة.","عند وصول الدفاع المدني، أطلِعهم على الوضع واتبع تعليماتهم.","أعطِهم مخططات الطوابق وأسماء المفقودين والمخاطر المعروفة."]},{heading:"6. استمرار الخدمات الأساسية",body:"الاستمرارية بعد الأزمة:",points:["دوّن الخدمات التي يجب ألّا تتوقف والموظفين الذين تحتاجهم.","احتفظ بنسخ من السجلات الأساسية خارج المبنى.","حدِّد مسبقًا مكان عمل بديلًا.","خطّط لكيفية إبلاغ الجمهور إذا أُغلقت الدائرة."]}],media:[{kind:"video",src:"media/videos/gov_crisis_management.mp4",title:"إدارة الأزمات",description:"نظام ICS وفريق CMT"},{kind:"image",src:"media/images/gov_ics_chart.png",title:"مخطط ICS",description:"هيكل القيادة"}],quiz:[{question:"في نظام ICS، كم عدد قادة الحادث؟",options:[{text:"3",correct:!1},{text:"5",correct:!1},{text:"1",correct:!0},{text:"10",correct:!1}],explanation:"في ICS يوجد قائد واحد للحادث، ليكون تسلسل القيادة واضحًا. وإذا شاركت عدة جهات، تعمل القيادة الموحَّدة (Unified Command) وفق خطة واحدة."},{question:"وفقًا لهذا البرنامج، كم مرة يلزم إجراء التمرين المكتبي (Tabletop)؟",options:[{text:"كل سنة",correct:!1},{text:"كل 6 أشهر",correct:!1},{text:"كل 3 أشهر",correct:!0},{text:"مرة واحدة فقط",correct:!1}],explanation:"يوصي هذا البرنامج بإجراء تمرين مكتبي كل 3 أشهر."},{question:"ما الخطوة الأولى في الاستجابة للأزمة؟",options:[{text:"عقد اجتماع للإدارة لمناقشة الوضع",correct:!1},{text:"الاتصال",correct:!1},{text:"الإنذار وتفعيل نظام الإنذار",correct:!0},{text:"التعافي وإصلاح الأضرار",correct:!1}],explanation:"الخطوة الأولى: الإنذار — فعِّل نظام الإنذار."},{question:"أثناء حادث يعطي مديران أوامر متعارضة للموظفين. أيّ مبدأ من مبادئ ICS يُخرق؟",options:[{text:"التنظيم المرن الذي يتسع مع الحادث",correct:!1},{text:"قائد واحد للحادث ومشرف واحد لكل شخص",correct:!0},{text:"تقارير تُحدَّث في أوقات محددة",correct:!1},{text:"لغة بسيطة على قناة اتصال واحدة",correct:!1}],explanation:"في ICS قائد واحد للحادث، وكل شخص يتبع مشرفًا واحدًا، حتى لا تتعارض الأوامر."},{question:"ألحق زلزال أضرارًا بمبناكم وهناك موظفون مفقودون. ما ترتيب الأولويات؟",options:[{text:"الممتلكات والسجلات أولًا، ثم الناس",correct:!1},{text:"الأرواح أولًا، ثم وقف الحادث، ثم الممتلكات",correct:!0},{text:"التقرير الرسمي أولًا، ثم الإنقاذ",correct:!1},{text:"وقف الحادث أولًا، ثم إنقاذ الأرواح",correct:!1}],explanation:"سلامة الأرواح تأتي أولًا دائمًا، ثم السيطرة على الحادث، ثم حماية الممتلكات والسجلات."},{question:"يصل الدفاع المدني (115) إلى حريق في مبنى دائرتك. ماذا يجب أن يفعل قائد الحادث في الدائرة؟",options:[{text:"إطلاعهم على المخاطر والمفقودين ثم دعمهم",correct:!0},{text:"الاحتفاظ بالقيادة وتوجيه رجال الإطفاء",correct:!1},{text:"مغادرة المكان لأن المختصين قد وصلوا",correct:!1},{text:"إعادة الموظفين إلى الداخل لمساعدة رجال الإطفاء",correct:!1}],explanation:"يحتاج الدفاع المدني إلى معلومات الدائرة عن المخاطر والمفقودين؛ ثم يدعمهم فريق الدائرة ويتبع تعليماتهم."}],steps:[{title:"أطلِق الإنذار واطلب المساعدة",detail:"من يرى الحادث يشغّل الإنذار ويتصل بالرقم 115 أو 122 أو 104. سلامة الأرواح قبل أي شيء آخر.",critical:!0},{title:"تولَّ القيادة",detail:"يتولى قائد واحد للحادث المسؤولية، ويختار مكانًا آمنًا لمركز القيادة ويعلنه؛ وكل شخص يتبع مشرفًا واحدًا."},{title:"قيِّم وحدِّد الأولويات",detail:"اعرف ما حدث، وكم شخصًا تأثر، وما الذي لا يزال خطرًا. الأولويات: الأرواح أولًا، ثم منع الحادث من الاتساع، ثم الممتلكات والسجلات.",critical:!0},{title:"فعِّل الفريق",detail:"استدعِ فريق إدارة الأزمات وكلّف كل عضو بمهمة: العمليات، والاتصال، والدعم اللوجستي، والسجلات، والإسعافات الأولية."},{title:"اعمل مع الدفاع المدني",detail:"عند وصول 115 يطلعهم قائد الحادث على الوضع والمفقودين والمخاطر ويتبع تعليماتهم؛ ويدعمهم فريق الدائرة.",critical:!0},{title:"تعافَ وتعلّم",detail:"أعِد تشغيل الخدمات الأساسية، واعتنِ بالموظفين، واكتب تقرير ما بعد الحادث، وحدّث الخطة."}],warnings:["لا تسمح لعدة مديرين بإعطاء أوامر مختلفة: فمن دون قائد واحد يتلقى الناس تعليمات متناقضة ويضيع الوقت.","لا تؤخر الإنذار أو الاتصال بالرقم 115 حتى يقرر اجتماع ما: الإنذار والاتصال أولًا، والاجتماع بعد ذلك."],tips:["احتفظ بقائمة مطبوعة بأرقام فريق الأزمات ونوابهم تحسبًا لتعطل الشبكة.","سمِّ نائبًا لكل دور، فقد يكون صاحب الدور غائبًا.","جهّز صندوق أزمات: الخطة، ومخططات الطوابق، وقائمة الاتصال، وسترات مميزة، ومصباحًا يدويًا، ودفترًا.","بعد كل تمرين، دوّن ما نجح وما يجب تحسينه."],activity:{prompt:"يدوي إنذار الحريق في مبنى دائرتك. المدير غائب، وثلاثة رؤساء أقسام يعطون أوامر مختلفة في الممر. والخطة تسمّيك نائبًا لقائد الأزمة. ماذا تفعل؟",options:[{text:"أعلن أنني أتولى القيادة كما تنص الخطة، وأُخرج الموظفين عبر طرق الإخلاء، وأطلب من رؤساء الأقسام تولي أدوارهم في فريق الأزمة",correct:!0,feedback:"صحيح: قائد واحد محدد مسبقًا ينهي الأوامر المتناقضة، ويتولى الآخرون أدوارًا محددة."},{text:"أنتظر أن يرد المدير على هاتفه قبل اتخاذ أي قرار",correct:!1,feedback:"انتظار شخص غائب يضيّع الوقت؛ ولهذا يُسمّى نائب."},{text:"أترك كل رئيس قسم يدير موظفيه على طريقته",correct:!1,feedback:"الأوامر المختلفة تسبب الارتباك. ونظام ICS يتطلب قائدًا واحدًا للحادث."},{text:"أدعو إلى اجتماع في قاعة الاجتماعات للاتفاق على الخطة",correct:!1,feedback:"عند الإنذار يخرج الناس أولًا؛ وتُتخذ القرارات في مركز القيادة في الخارج."}]},caseStudy:[{prompt:"يهز زلزال مبنى دائرتك صباحًا. عندما يتوقف الاهتزاز تظهر تشققات في الجدران، وأُصيب موظف على الدرج، وموظفان غير موجودين عند العدّ في نقطة التجمع. أنت قائد الأزمة. ما أول ما تفعله؟",options:[{text:"أعيد الموظفين إلى داخل المبنى للبحث عن الزميلين المفقودين",correct:!1,feedback:"إرسال موظفين غير مدربين إلى مبنى متضرر قد يزيد عدد الضحايا. أبلِغ 115."},{text:"أتأكد من الاتصال بالرقمين 115 و122، وأوفر الإسعافات الأولية للموظف المصاب، وأعطي المنقذين أسماء المفقودين وآخر مكان شوهدا فيه",correct:!0,feedback:"صحيح: سلامة الأرواح أولًا. يفتش المنقذون المبنى بالمعدات المناسبة مستعينين بمعلوماتك."},{text:"أبدأ بكتابة التقرير الرسمي إلى المديرية العامة",correct:!1,feedback:"التقرير مهم، لكنه يأتي بعد سلامة الناس."}]},{prompt:"فريق 115 يفتش المبنى. يصل صحفيون وعائلات قلقة إلى البوابة، وينشر موظفون شائعات على مواقع التواصل الاجتماعي. ماذا بعد؟",options:[{text:"أطلب من مسؤول الاتصال والإعلام إعطاء العائلات ووسائل الإعلام معلومات قصيرة مؤكدة، وأطلب من الموظفين عدم نشر معلومات غير مؤكدة",correct:!0,feedback:"صحيح: متحدث واحد بحقائق مؤكدة يوقف الشائعات ويحمي العائلات."},{text:"أدع كل موظف يجيب عن أسئلة الصحفيين",correct:!1,feedback:"الروايات المختلفة غير المؤكدة تنشر الارتباك؛ ولا يتحدث إلا مسؤول الاتصال والإعلام."},{text:"أقول للجميع إن كل الموظفين بخير كي يهدؤوا",correct:!1,feedback:"لا تعطِ أبدًا معلومات غير مؤكدة: فموظفان لا يزالان مفقودين."}]}],realCase:"ملأ حريق صغير في مطبخ إحدى الدوائر طابقًا من مبنى حكومي بالدخان. وكانت خطة الأزمات قد سمّت قائدًا ونائبًا له. ولأن القائد كان في إجازة، تولى النائب المسؤولية فورًا، وأقام مركز القيادة في نقطة التجمع، وكلّف كل عضو في الفريق بمهمة. أبلغ مسؤولو الطوابق عن أعدادهم، وسلّم النائب فريق 115 مخططات الطوابق واسمَي موظفين لم يُعرف مكانهما بعد. ووُجد الاثنان لاحقًا سالمين في مبنى آخر. وأضافت مراجعة ما بعد الحادث نقطة تجمع ثانية إلى الخطة."},{id:15,code:"GOV-115",icon:"Megaphone",accent:"#c026d3",title:"الاتصال في حالات الطوارئ",subtitle:"Emergency Communication",summary:"نظام الاتصال والإنذار أثناء الحوادث",blocks:[{body:"أثناء الحوادث، يُنقذ الاتصال الصحيح والسريع الأرواح. ففي كثير من الحوادث، أدّى غياب الاتصال الجيد إلى زيادة عدد الضحايا. ويجب أن يكون لكل دائرة حكومية نظام اتصال قوي."},{heading:"1. أنظمة الإنذار",body:"توجد عدة أنظمة:",points:["صفارة الإنذار الداخلية: جرس الحريق والطوارئ.","نظام مكبرات الصوت (PA System): لبث الرسائل إلى جميع الطوابق.","الرسائل النصية الجماعية (SMS Group): للموظفين.","البريد الإلكتروني العاجل: للتبليغات الرسمية.","مجموعات واتساب وتيليغرام: للتنسيق السريع.","أجهزة اللاسلكي ثنائية الاتجاه (Walkie-Talkie): لفريق الطوارئ."]},{heading:"2. سلسلة الاتصال",body:"من يرسل الرسالة:",points:["1. المبلِّغ: الشخص الذي شاهد الحادث — يتصل فورًا بالرقم 115 (وبالرقم 122 إذا وُجد مصابون).","2. مسؤول الطابق: الموظف المسؤول عن الطابق والغرف.","3. قائد الأزمة: اتخاذ القرار والتوجيه.","4. مسؤول الاتصال: التواصل مع 115 والجهات الخارجية.","5. مدير الدائرة: إبلاغ المستوى الأعلى.","يجب أن تكون جميع الرسائل دقيقة وأن تتضمن معلومات كاملة."]},{heading:"3. محتوى رسالة الطوارئ",body:"تتضمن الرسالة الجيدة ما يأتي:",points:["المكان: أين وقع الحادث (المبنى، الطابق، الغرفة).","ماذا: ما الذي حدث (حريق، زلزال، هجوم...)","الأشخاص: كم شخصًا أُصيب أو بقي في المكان.","الخطر: هل يوجد خطر مستمر؟","الاحتياجات: ما المساعدة المطلوبة.","الاتصال: رقم هاتفك للتواصل معك."]},{heading:"4. الاتصال بالجهات الخارجية",body:"التواصل مع الجهات الخارجية:",points:["115 — الدفاع المدني: الحرائق والإنقاذ.","122 — الإسعاف: الإصابات والحالات المرضية.","104 — الشرطة: الحالات الأمنية.","وسائل الإعلام: يتحدث مسؤول الاتصال وحده.","عائلات الموظفين: إبلاغها بأيسر الطرق.","المديرية العامة: التقرير الرسمي."]},{heading:"5. اختبار النظام",body:"الفحص المستمر:",points:["اختبر صفارة الإنذار الداخلية كل شهر.","أرسل رسالة تجريبية إلى المجموعة كل أسبوع.","افحص بطاريات أجهزة اللاسلكي ثنائية الاتجاه ومداها.","حدِّث قائمة أرقام الطوارئ.","قيِّم نظام الاتصال بعد كل تمرين.","الخطة البديلة: إذا تعطّل أحد الأنظمة، فما البديل؟"]},{heading:"6. عندما تتعطل الأنظمة",body:"خطّط لانقطاع الكهرباء أو تعطل الشبكة:",points:["أجهزة لاسلكي مشحونة لمسؤولي الطوابق والقائد.","مكبر صوت يدوي في نقطة التجمع.","سُعاة ينقلون الرسائل بين الطوابق.","قوائم اتصال مطبوعة، لأن الهواتف قد لا تعمل.","نقطة لقاء متفق عليها لفريق الأزمة."]},{heading:"7. الرسائل إلى الموظفين والمراجعين",body:"الإعلان الجيد قصير وواضح:",points:["قل ما حدث في كلمات قليلة.","قل بدقة ما يجب أن يفعله الناس وأي طريق يسلكون.","كرّر الرسالة ببطء وهدوء.","استخدم اللغات التي يفهمها الموظفون والمراجعون.","أعطِ مستجدات عندما يتغير الوضع."]}],media:[{kind:"video",src:"media/videos/gov_emergency_comm.mp4",title:"الاتصال في حالات الطوارئ",description:"نظام الاتصال وسلسلته"},{kind:"image",src:"media/images/gov_comm_chain.png",title:"سلسلة الاتصال",description:"من يتصل بمن"},{kind:"image",src:"media/images/gov_message_template.png",title:"نموذج رسالة",description:"محتوى الرسالة الصحيحة"}],quiz:[{question:"أثناء الطوارئ، ما أسرع نظام لإبلاغ جميع الطوابق؟",options:[{text:"البريد الإلكتروني",correct:!1},{text:"رسالة في مجموعة واتساب",correct:!1},{text:"نظام مكبرات الصوت (PA)",correct:!0},{text:"إعلان ورقي على لوحة كل طابق",correct:!1}],explanation:"نظام PA هو الأسرع لأنه يُسمع فورًا في جميع الطوابق."},{question:"ما المعلومات التي يجب أن تتضمنها رسالة الطوارئ؟",options:[{text:"اسم المتصل ومسمّاه الوظيفي ورقم هاتفه فقط",correct:!1},{text:"عدد المصابين وأسماؤهم فقط",correct:!1},{text:"المكان، وما الذي حدث، والأشخاص، والخطر، والاحتياجات",correct:!0},{text:"الرقم 115 فقط",correct:!1}],explanation:"الرسالة الكاملة: المكان + ما الذي حدث + الأشخاص + الخطر + الاحتياجات + رقم التواصل."},{question:"أثناء الأزمة، من المخوَّل بالتحدث إلى وسائل الإعلام؟",options:[{text:"أي موظف شاهد ما حدث",correct:!1},{text:"مسؤول الاتصال فقط",correct:!0},{text:"المراجع",correct:!1},{text:"رئيس حرّاس الأمن فقط",correct:!1}],explanation:"مسؤول الاتصال وحده هو المخوَّل بالتحدث إلى وسائل الإعلام، لكي لا تنتشر معلومات خاطئة."},{question:"تتصل بالرقم 115 بشأن حريق في دائرتك. ماذا تقول أولًا؟",options:[{text:"اسمك الكامل ومنصبك الوظيفي والقسم الذي تعمل فيه",correct:!1},{text:"المكان: المنطقة والشارع والمَعلم والمبنى والطابق",correct:!0},{text:"كيف تظن أن الحريق بدأ ومن لاحظه",correct:!1},{text:"أي المكاتب والأقسام في ذلك الطابق",correct:!1}],explanation:"المكان أولًا، كي تُرسل المساعدة حتى لو انقطع الاتصال؛ ثم ما حدث والأشخاص والمخاطر، ثم اسمك ورقمك."},{question:"بعد الاتصال بالرقم 115، أيّ تصرف خاطئ؟",options:[{text:"إبقاء هاتفك متاحًا لمعاودة الاتصال",correct:!1},{text:"إبلاغ مسؤول الطابق بأنك اتصلت",correct:!1},{text:"إنهاء المكالمة قبل أن يطلب موظف الاستقبال ذلك",correct:!0},{text:"إرسال شخص لإرشاد سيارات الإطفاء إلى المدخل",correct:!1}],explanation:"إنهاء المكالمة مبكرًا قد يضيّع المكان الدقيق أو تعليمات مهمة. ابقَ على الخط حتى يُطلب منك إنهاؤها."},{question:"أثناء انقطاع الكهرباء تتعطل الإذاعة الداخلية والهواتف ويجب إخلاء المبنى. ما أفضل وسيلة بديلة؟",options:[{text:"الانتظار حتى تعود الكهرباء لإطلاق الإعلان",correct:!1},{text:"ينبّه مسؤولو الطوابق كل الطوابق باللاسلكي والسُّعاة",correct:!0},{text:"إرسال بريد إلكتروني إلى جميع الموظفين عن الإخلاء",correct:!1},{text:"نشر أمر الإخلاء في مجموعة الموظفين على مواقع التواصل",correct:!1}],explanation:"اللاسلكي والسُّعاة لا يعتمدون على الكهرباء أو الشبكة؛ أما البريد الإلكتروني والمجموعات على الإنترنت فقد لا تصل إلى أحد."}],steps:[{title:"أطلِق الإنذار الداخلي",detail:"شغّل إنذار الحريق أو نظام الإذاعة الداخلية (PA) لينبَّه كل من في المبنى فورًا.",critical:!0},{title:"اتصل من مكان آمن",detail:"اتصل بالرقم 115 للحريق والإنقاذ، و122 للمصابين والمرضى، و104 للحالات الأمنية. وإذا اجتمع الحريق والمصابون فاتصل بالرقمين 115 و122.",critical:!0},{title:"اذكر المكان أولًا",detail:"اذكر المنطقة والشارع ومَعلمًا معروفًا والمبنى والطابق؛ ثم ما حدث، وكم شخصًا أُصيب أو احتُجز، وأي مخاطر.",critical:!0},{title:"اذكر اسمك ورقمك ولا تُنهِ المكالمة",detail:"أجب عن أسئلة موظف الاستقبال وابقَ على الخط حتى يُطلب منك إنهاء المكالمة؛ وبعد ذلك أبقِ هاتفك متاحًا لمعاودة الاتصال.",critical:!0},{title:"أبلِغ عبر السلسلة",detail:"أخبر مسؤول الطابق وقائد الأزمة بما أبلغت عنه، كي لا تتكرر الرسالة أو تضيع."},{title:"صوت واحد نحو الخارج",detail:"لا يتحدث إلى وسائل الإعلام ويعطي المستجدات للعائلات إلا مسؤول الاتصال والإعلام؛ ولا ينشر الموظفون معلومات غير مؤكدة."}],warnings:["لا تُنهِ المكالمة قبل أن يطلب منك موظف الاستقبال ذلك: فقد يحتاج بعدُ إلى المكان الدقيق أو لديه تعليمات لك.","لا تفترض أن غيرك قد اتصل بالرقم 115: اتصل بنفسك، أو تأكد من أن أحدًا اتصل.","لا تنشر صورًا أو أسماء مصابين أو شائعات على مواقع التواصل الاجتماعي أثناء الحادث: يجب أن تسمع العائلات الأخبار من الدائرة لا من الإنترنت."],tips:["ضع بطاقة بعنوان المبنى الكامل والمعالم القريبة بجانب كل هاتف في الدائرة.","أبقِ بطاريات أجهزة اللاسلكي مشحونة واختبرها في كل تمرين.","استخدم كلمات بسيطة في الإعلانات ليفهم المراجعون أيضًا ما عليهم فعله.","اتفقوا على وسيلة بديلة: إذا تعطلت الهواتف والإنترنت، ينقل سُعاة الرسائل بين الطوابق."],activity:{prompt:"ترى دخانًا يخرج من غرفة الأرشيف في طابقك. يقف عدد من الزملاء في الممر ويقولون إن أحدًا ربما اتصل بالفعل. ماذا تفعل؟",options:[{text:"أنتظر دقيقة، لأن أحدًا ربما اتصل بالفعل",correct:!1,feedback:"قد يفكر الجميع بالطريقة نفسها؛ والمكالمة التي لا يجريها أحد تضيّع وقتًا ثمينًا."},{text:"أشغّل إنذار الحريق، وأتصل بالرقم 115 من مكان آمن، وأبلغ مسؤول الطابق أنني اتصلت",correct:!0,feedback:"صحيح: إنذار واتصال وإبلاغ مسؤول الطابق، لينبَّه الجميع ولا يُنسى الاتصال ولا يتكرر."},{text:"أرسل رسالة في مجموعة الموظفين أسأل فيها هل اتصل أحد",correct:!1,feedback:"الرسائل بطيئة وقد لا تُقرأ. أطلِق الإنذار واتصل بالرقم 115 بنفسك."},{text:"أدخل الأرشيف لأرى حجم الحريق",correct:!1,feedback:"دخول غرفة مملوءة بالدخان خطر؛ والمكان والدخان يكفيان للإبلاغ."}]},caseStudy:[{prompt:"تسقط زميلة في قاعة اجتماعات الدائرة. تتصل بالرقم 122. ماذا تقول أولًا؟",options:[{text:"أصف بالتفصيل ما كانت تفعله قبل أن تسقط",correct:!1,feedback:"قد يفيد ذلك لاحقًا؛ لكن الإسعاف يحتاج أولًا إلى معرفة وجهته."},{text:"المكان: المنطقة والشارع والمَعلم واسم المبنى والطابق، ثم أن شخصًا سقط وهل يتنفس",correct:!0,feedback:"صحيح: المكان أولًا، كي تُرسل المساعدة حتى لو انقطع الاتصال."},{text:"اسمي ومنصبي الوظيفي",correct:!1,feedback:"اذكر اسمك ورقمك، لكن بعد المكان وما حدث."}]},{prompt:"يقول موظف الاستقبال إن سيارة الإسعاف في الطريق ويطلب منك البقاء على الخط. يطلب منك زميل أن تُنهي المكالمة وتتصل بالمدير. ماذا تفعل؟",options:[{text:"أبقى على الخط، وأتبع تعليمات موظف الاستقبال، وأطلب من الزميل إبلاغ المدير واستقبال الإسعاف عند المدخل",correct:!0,feedback:"صحيح: قد يرشدك موظف الاستقبال إلى الإسعافات الأولية، ويتولى الآخرون إبلاغ المدير وإرشاد الإسعاف."},{text:"أُنهي المكالمة وأتصل بالمدير لأنه يجب أن يقرر",correct:!1,feedback:"لا يحتاج الإسعاف إلى موافقة المدير، وإنهاء المكالمة قد يضيّع تعليمات مهمة."},{text:"أُنهي المكالمة وأتصل بالرقم 115 أيضًا للتأكد",correct:!1,feedback:"مكالمة طوارئ واحدة تكفي لحالة سقوط شخص؛ ولا تُنهِ المكالمة إلا عندما يطلب منك موظف الاستقبال ذلك."}]}],realCase:"عندما ظهر الدخان في قبو دائرة عامة، ظن كل واحد من ثلاثة موظفين أن غيره قد طلب المساعدة. وفي النهاية ضغطت عاملة تنظيف زر إنذار الحريق واتصلت بالرقم 115. ولأنها ذكرت الشارع ومَعلمًا قريبًا والمدخل الخلفي للمبنى، وصلت سيارات الإطفاء مباشرة إلى الباب الصحيح. وفي أثناء ذلك أخبر مسؤول الاتصال والإعلام الموظفين عبر نظام الإذاعة الداخلية بأي درج يستخدمون، ثم أعطى العائلات معلومات قصيرة بالهاتف. وأضافت مراجعة ما بعد الحادث بطاقات العنوان بجانب كل هاتف في الدائرة."},{id:16,code:"GOV-116",icon:"Heart",accent:"#db2777",title:"الإسعافات الأولية والإنعاش القلبي الرئوي (CPR)",subtitle:"First Aid & CPR — Complete Training",summary:"تدريب شامل على الإسعافات الأولية والإنعاش القلبي الرئوي (CPR) والاستجابة للطوارئ في الدوائر",blocks:[{body:"الإسعافات الأولية (First Aid) هي المساعدة الأولية التي تُقدَّم للمصاب أو المريض قبل وصول الفرق الطبية. وفي الدوائر توجد مخاطر الحريق والزلازل والحالات المرضية المفاجئة. ويجب على كل موظف أن يعرف كيف يُجري CPR، ويوقف النزيف، ويحمي المصاب حتى وصول سيارة الإسعاف (122)."},{heading:"1. الإنعاش القلبي الرئوي (CPR)",body:"الإنعاش القلبي الرئوي (CPR) إجراء لإنقاذ الحياة عند توقف قلب الإنسان أو تنفسه:",points:["1. سلامة المكان: هل المكان آمن؟ (لا كهرباء ولا نار ولا غاز؟)","2. الاستجابة: هزّ كتفيه برفق واسأله بصوت عالٍ: «هل أنت بخير؟ هل تسمعني؟»","3. اتصل بالرقم 122: إذا لم يستجب ولم يتنفس بصورة طبيعية، فاتصل فورًا بالرقم 122 وأحضِر جهاز إزالة الرجفان الخارجي الآلي (AED) أو اطلب إحضاره.","4. الضغطات الصدرية: 30 ضغطة في منتصف الصدر — بعمق 5-6 سم، وبمعدل 100-120 ضغطة في الدقيقة.","5. التنفس: أمِل الرأس إلى الخلف وارفع الذقن، وأغلق فتحتَي الأنف وأعطِ نَفَسين (2) مدة كل منهما ثانية واحدة؛ وإذا لم تتلقَّ تدريبًا، فاكتفِ بالضغطات الصدرية.","6. الاستمرار (30:2): حتى يصل فريق الإسعاف (122).","7. جهاز AED: إن وُجد، فشغّله وضع الوسادتين اللاصقتين على الصدر العاري واتبع التعليمات الصوتية."]},{heading:"2. إيقاف النزيف",body:"قد يؤدي النزيف الشديد إلى الوفاة بسرعة:",points:["الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط بقوة ومن دون توقف؛ وإذا تشبّع القماش بالدم فلا تنزعه — بل ضع قطعة أخرى فوقه.","حشو الجرح (Wound Packing): إذا كان الجرح عميقًا (كما في الفخذ أو الإبط أو الرقبة)، فاحشُ الجرح بالشاش النظيف واضغط بقوة.","العاصبة (Tourniquet): استخدمها مبكرًا في النزيف الخطير من الذراع أو الساق، على بُعد 5-7 سم فوق الجرح؛ ودوِّن وقت وضعها ولا ترخِها أبدًا.","الجسم المنغرس: إذا كانت قطعة حديد أو زجاج داخل الجرح — فلا تنزعها! ثبّتها من حولها واتصل بالرقم 122."]},{heading:"3. علاج الحروق",body:"تحدث الحروق في الدوائر بسبب الحرارة والمواد الكيميائية والكهرباء:",points:["الحروق الحرارية: صُبّ ماءً باردًا جاريًا (لا الثلج!) على الحرق مدة 20 دقيقة.","الحروق الكيميائية: اغسلها بكمية كبيرة من الماء الجاري مدة 20 دقيقة.","الحروق الكهربائية: افصل الكهرباء أولًا! ثم برِّد الحرق كما في الحروق الحرارية واتصل بالرقم 122.","لا تفقأ فقاعات الحرق؛ ولا تستخدم الزيت أو المراهم أو معجون الأسنان."]},{heading:"4. الكسور وإصابات العمود الفقري",body:"عند السقوط:",points:["التجبير (Splinting): لا تحرّك الطرف المصاب — بل ثبّته بقطعة خشب أو كرتون.","حماية العمود الفقري: إذا سقط شخص من مكان مرتفع، فلا تحرّكه — أبقِه ثابتًا واتصل بالرقم 122. لا تحرّكه إلا إذا كان المكان خطرًا (حريق، أو حركة مرور، أو انهيار، أو غاز، أو ارتفاع المياه)، مع إبقاء الرأس والرقبة والظهر على خط واحد؛ وإذا احتاج إلى الإنعاش القلبي الرئوي (CPR)، فمدّده على ظهره على سطح صلب. ولا تضعه على جنبه في وضعية الإفاقة (Recovery Position).","التبريد: لُفّ الثلج بقطعة قماش وضعه على موضع الألم (لا تضعه مباشرةً على الجلد)."]},{heading:"5. الصعق الكهربائي",body:"قد تؤدي الكهرباء إلى توقف القلب:",points:["افصل الكهرباء فورًا! ولا تلمس المصاب حتى تُفصل الكهرباء.","إذا لم تستطع فصل الكهرباء وكانت كهرباء المبنى العادية (جهد منخفض): أبعِد السلك عنه بقطعة خشب جافة أو بأداة بلاستيكية؛ أما في حالة الجهد العالي فابقَ بعيدًا واتصل بالرقم 115.","يجب نقل كل من تعرّض للصعق الكهربائي إلى المستشفى — اتصل بالرقم 122؛ وإذا لم يكن يتنفس، فابدأ CPR."]}],media:[{kind:"video",src:"media/videos/gov_cpr.mp4",title:"CPR والإسعافات الأولية",description:"تدريب الموظفين على CPR"}],quiz:[{question:"في CPR، كم ضغطة صدرية يجب إجراؤها في الدقيقة؟",options:[{text:"50-70",correct:!1},{text:"80-90",correct:!1},{text:"100-120",correct:!0},{text:"140-160",correct:!1}],explanation:"يجب أن يكون المعدل 100-120 ضغطة في الدقيقة (AHA 2025)."},{question:"إذا كان هناك جسم حاد داخل الجرح، فماذا تفعل؟",options:[{text:"أنزعه برفق ثم أضغط على الجرح",correct:!1},{text:"أتركه في مكانه وأتصل بالرقم 122",correct:!0},{text:"أُبعد يدي ولا أفعل شيئًا",correct:!1},{text:"أغسله بالماء",correct:!1}],explanation:"نزع الجسم يزيد النزيف؛ ثبّته من حوله واتصل بالرقم 122."},{question:"إذا تعرّض شخص للصعق الكهربائي، فما أول ما يجب فعله؟",options:[{text:"أمسك بيده",correct:!1},{text:"أُجري CPR",correct:!1},{text:"أفصل الكهرباء",correct:!0},{text:"أسكب عليه الماء",correct:!1}],explanation:"يجب فصل الكهرباء أولًا، لكي لا تصبح أنت نفسك ضحية."},{question:"يُغمى على موظفة عند مكتبها دون أن تسقط أو ترتطم بشيء. لا تستجيب لكنها تتنفس طبيعيًا. ماذا تفعل؟",options:[{text:"وضعية الإفاقة، والاتصال بالرقم 122، ومراقبة التنفس",correct:!0},{text:"إجلاسها على كرسي وإعطاؤها كوبًا من الشاي المحلّى",correct:!1},{text:"البدء بالضغطات الصدرية فورًا دون انتظار",correct:!1},{text:"تركها ترتاح وحدها ثم تفقّدها بعد قليل",correct:!1}],explanation:"عدم الاستجابة مع تنفس طبيعي ودون اشتباه في إصابة الرقبة أو الظهر أو الورك أو الحوض: وضعية الإفاقة، والاتصال بالرقم 122، ومواصلة مراقبة التنفس؛ ولا شيء عن طريق الفم."},{question:"لم تتدرب قط على أنفاس الإنقاذ، وتجد زميلًا لا يستجيب ولا يتنفس طبيعيًا. ما التصرف الصحيح؟",options:[{text:"عدم فعل أي شيء حتى يصل شخص مدرب",correct:!1},{text:"الاتصال بالرقم 122 وإعطاء ضغطات صدرية متواصلة",correct:!0},{text:"إعطاء أنفاس الإنقاذ وحدها دون أي ضغطات",correct:!1},{text:"هزّه بقوة ورشّ الماء عليه حتى يستجيب",correct:!1}],explanation:"Hands-Only CPR: المُسعف غير المدرب يكتفي بالضغطات، بمعدل 100-120 في الدقيقة، حتى يصل جهاز AED أو فريق الإسعاف."},{question:"بعد انكسار باب زجاجي ينزف ساعد زميل نزيفًا شديدًا. ويتسرب الدم عبر القطعة الأولى التي ضغطت بها. ماذا الآن؟",options:[{text:"انزع القطعة المشبعة واضغط بقطعة نظيفة",correct:!1},{text:"ضع قطعة أخرى فوقها وواصل الضغط بقوة",correct:!0},{text:"ارفع الذراع وتوقف عن الضغط",correct:!1},{text:"اغسل الجرح تحت الحنفية قبل الضغط",correct:!1}],explanation:"لا تُنزع الضمادة المشبعة: أضِف المزيد فوقها وواصل الضغط بقوة. وإذا كان النزيف مهددًا للحياة ولم يتوقف، فاستخدم العاصبة مبكرًا."}],steps:[{title:"تأكد من أمان المكان",detail:"قبل لمس الشخص، افحص وجود كهرباء أو نار أو غاز أو حركة مرور. وإذا تعذّر إزالة الخطر فلا تدخل: اتصل بالرقمين 115 و122.",critical:!0},{title:"افحص الاستجابة والتنفس ثم اتصل",detail:"هزّ كتفيه برفق واسأله بصوت عالٍ. إذا لم يستجب ولم يتنفس بصورة طبيعية — فاللهاث (Gasping) ليس تنفسًا طبيعيًا — فاتصل فورًا بالرقم 122 وأرسل أحدًا لإحضار جهاز إزالة الرجفان الخارجي الآلي (AED).",critical:!0},{title:"اضغط بقوة وسرعة في منتصف الصدر",detail:"أعطِ 30 ضغطة بكعب راحة اليد: بعمق 5-6 سم، وبمعدل 100-120 في الدقيقة، مع ترك الصدر يرتفع بالكامل بعد كل ضغطة.",critical:!0},{title:"أنفاس إن كنت مدربًا، وإلا فالضغطات فقط",detail:"إذا كنت مدربًا، فأعطِ نَفَسين مدة كل منهما ثانية واحدة واستمر بنسبة 30:2. وإذا لم تكن مدربًا، فاكتفِ بالضغطات (Hands-Only CPR) دون توقف.",critical:!0},{title:"استخدم جهاز AED فور وصوله",detail:"شغّله، وضع الوسادتين اللاصقتين على الصدر العاري، واتبع التعليمات الصوتية. واصل CPR حتى يتولى فريق الإسعاف (122) الأمر.",critical:!0},{title:"فاقد الوعي لكنه يتنفس طبيعيًا",detail:"ضع الشخص في وضعية الإفاقة (Recovery Position) فقط إذا لم يُشتبه في إصابة الرقبة أو الظهر أو الورك أو الحوض؛ واتصل بالرقم 122، ولا تعطه شيئًا عن طريق الفم، وواصل مراقبة تنفسه.",critical:!0}],warnings:["لا تعدّ اللهاث المتقطع تنفسًا طبيعيًا: فاقد الوعي الذي يلهث فقط يحتاج إلى CPR، لا إلى وضعية الإفاقة.","بعد السقوط من مكان مرتفع أو ضربة على الرأس أو الرقبة أو الظهر، لا تحرّك الشخص ولا تضعه على جنبه، إلا إذا كان المكان غير آمن أو احتاج إلى CPR.","لا تعطِ طعامًا أو شرابًا لشخص فاقد الوعي أو شبه نائم: فقد يسد مجرى الهواء."],tips:["اعرف مكان أقرب جهاز AED وحقيبة إسعافات أولية في طابقك.","افحص حقيبة الإسعافات الأولية بانتظام واستبدل ما استُخدم منها.","عند وجود مُسعفَين مدربَين، تبادلا الضغطات عندما يتعب الأول، بأقصر توقف ممكن.","البس قفازات الحقيبة عند التعامل مع النزيف."],activity:{prompt:"يسقط زميل عند مكتبه. لا يستجيب عندما تهز كتفيه وتسأله بصوت عالٍ، ولا يصدر عنه إلا لهاث متقطع. معك زميل آخر. ماذا تفعل؟",options:[{text:"أضعه على جنبه وأنتظر أن يفيق",correct:!1,feedback:"اللهاث المتقطع ليس تنفسًا طبيعيًا؛ إنه يحتاج إلى CPR لا إلى وضعية الإفاقة."},{text:"أطلب من زميلي الاتصال بالرقم 122 وإحضار جهاز AED، وأبدأ الضغطات الصدرية في منتصف الصدر",correct:!0,feedback:"صحيح: عدم الاستجابة وغياب التنفس الطبيعي يعنيان توقف القلب. اتصل، وأحضِر الجهاز، وابدأ الضغطات فورًا."},{text:"أعطيه ماءً ليفيق",correct:!1,feedback:"لا تعطِ شيئًا عن طريق الفم لشخص لا يستجيب أبدًا؛ فقد يسد مجرى الهواء."},{text:"أنتظر الإسعاف قبل أن ألمسه",correct:!1,feedback:"كل دقيقة دون ضغطات تقلل فرصة نجاته. ابدأ CPR الآن."}]},caseStudy:[{prompt:"تسقط مراجِعة على درج مبناكم وتبقى في أسفله. لا تستجيب لصوتك أو لمسك، لكنها تتنفس طبيعيًا. لا يوجد حريق أو حركة مرور أو خطر آخر. ماذا تفعل؟",options:[{text:"أضعها في وضعية الإفاقة (Recovery Position)",correct:!1,feedback:"بعد السقوط قد تكون الرقبة أو الظهر مصابة، لذلك لا تُستخدم وضعية الإفاقة."},{text:"أبقيها ثابتة في الوضع الذي وجدتها عليه، وأتصل بالرقم 122، وأواصل مراقبة تنفسها",correct:!0,feedback:"صحيح: لا تحرّك الشخص بعد السقوط إلا إذا كان المكان غير آمن أو احتاج إلى CPR؛ وراقب تنفسه حتى تصل المساعدة."},{text:"أُجلسها مسندة ظهرها إلى الجدار لتتنفس أفضل",correct:!1,feedback:"التحريك قد يزيد إصابة العمود الفقري سوءًا. أبقِها ثابتة."}]},{prompt:"أثناء الانتظار يتغير تنفسها: لم تعد تتنفس طبيعيًا وصارت تلهث فقط. لم تصل سيارة الإسعاف بعد. ماذا تفعل الآن؟",options:[{text:"أقلبها بحذر على ظهرها على الأرض مع إبقاء الرأس والرقبة والظهر على خط واحد، وأبدأ الضغطات الصدرية بينما يُحضر زميل جهاز AED",correct:!0,feedback:"صحيح: الآن يأتي CPR أولًا. حرّكها بالقدر اللازم فقط لتستلقي على ظهرها على سطح صلب."},{text:"أبقيها ثابتة بسبب احتمال إصابة العمود الفقري",correct:!1,feedback:"من دون تنفس طبيعي تحتاج إلى CPR؛ والحاجة إلى CPR هي الاستثناء الذي يسمح بتحريكها."},{text:"أعطيها نَفَسَي إنقاذ ثم أنتظر",correct:!1,feedback:"الأنفاس وحدها لا تكفي. ابدأ الضغطات (30:2 إن كنت مدربًا، والضغطات فقط إن لم تكن) واستمر."}]}],realCase:"أثناء اجتماع صباحي في دائرة حكومية، سقط موظف كبير فجأة وتوقف عن التنفس الطبيعي. أرسلت زميلة كانت قد حضرت دورة الإسعافات الأولية في الدائرة شخصًا للاتصال بالرقم 122 وآخر لإحضار جهاز AED من الممر، ثم بدأت الضغطات الصدرية. وعندما وصل الجهاز شغّلته، ووضعت الوسادتين على صدره العاري، واتبعت التعليمات الصوتية، بينما كان زميل مدرب آخر يتناوب معها على الضغطات. ثم تولى فريق الإسعاف الأمر. وبعد الحادث وضعت الدائرة لافتات تدل على مكان الجهاز ودرّبت مزيدًا من الموظفين."},{id:17,code:"GOV-117",icon:"FlameKindling",accent:"#dc2626",title:"تصنيف أنواع الحرائق",subtitle:"Fire Classification — NFPA 10 / BS EN 2",summary:"التصنيف الدولي لأنواع الحرائق واختيار مطفأة الحريق المناسبة",blocks:[{body:"يُعدّ تصنيف الحرائق أساس عمل الدفاع المدني. والنظامان الرئيسيان هما NFPA 10 (المعيار الأمريكي) وEN 2 (المعيار الأوروبي)، ويجب دائمًا تحديد النظام المقصود. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. فاختيار مطفأة حريق خاطئة قد يؤدي إلى تفاقم الحريق أو إلى وقوع إصابات. ويشرح هذا الدرس كل فئة وفقًا للمعايير الدولية."},{heading:"1. الفئة A — المواد الصلبة (Solid Combustibles)",body:"المواد الصلبة العضوية التي تخلّف رمادًا:",points:["المواد القابلة للاحتراق: الخشب، والورق، والقماش، والبلاستيك، والمطاط، والنفايات.","درجة الاشتعال الذاتي: للورق نحو 218-246°C.","الخصائص: تخلّف رمادًا وجمرًا، وقد تبقى النار مشتعلة في عمق المادة.","مطفآت الحريق: الماء، والمسحوق ABC، والرغوة — اقرأ الملصق (Label) ورموز الفئات (اللون ليس فئة الحريق).","في الدوائر: معظم المواد القابلة للاحتراق هي الورق والملفات وأثاث الغرف.","المعايير: NFPA 10، EN 2.","التدريب: لا تستخدم المطفأة إلا إذا تحقّق كل ما يلي: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وتمّ إطلاق الإنذار والاتصال بالرقم 115، وأنت مدرَّب، ولا يوجد دخان أو حرارة يمنعان خروجك. ثم طريقة PASS: ابدأ من المسافة المحددة على ملصق المطفأة، ووجِّه فوهة الخرطوم نحو قاعدة النار؛ وإذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب."]},{heading:"2. الفئة B — السوائل القابلة للاشتعال (Flammable Liquids)",body:"السوائل التي تُطلق أبخرة قابلة للاشتعال في درجات الحرارة العادية (وفي NFPA تشمل أيضًا الغازات القابلة للاشتعال):",points:["المواد القابلة للاحتراق: البنزين، وزيت الغاز (Diesel)، والنفط الأبيض، والكحول، والتنر، والدهانات.","نقطة الوميض (Flash Point)، بحسب نوع الوقود: للبنزين نحو −43°C، ولزيت الغاز نحو 52-96°C.","الخصائص: الذي يحترق هو بخار السائل، لا السائل نفسه.","مطفآت الحريق للسوائل: الرغوة أو CO₂ أو مسحوق ABC؛ وللكحول والمذيبات القطبية الأخرى (Polar Solvents): CO₂ أو مسحوق ABC أو الرغوة المقاومة للكحول (AR Foam)، لأن الرغوة العادية تنهار عليها. حريق الغاز (غاز LPG أو الغاز الطبيعي): الأولوية لإيقاف تدفق الغاز؛ يُغلق شخصٌ مؤهَّل صمامَ الغاز فقط إذا كان الوصول إليه آمنًا. لا تُطفئ لهب الغاز إذا لم يمكن إيقاف الغاز بأمان، فالغاز غير المحترق يتجمّع وقد ينفجر. وإذا لم يكن ذلك آمنًا، فأخلِ الجميع، وأطلق الإنذار، واتصل بالرقم 115. والرغوة ليست الخيار العام لحرائق الغاز.","لا ترشّ الماء بالخرطوم على السائل المشتعل: فهو يُطاير السائل المشتعل وينشره (Slop-over / Boil-over). أما BLEVE فأمر مختلف، وهو انفجار وعاء مضغوط بعد تعرّضه للحرارة، وقد يساعد تبريد الوعاء بالماء من مسافة بعيدة على منعه؛ وهذه مهمة فريق 115، ويُخلي جميعُ الآخرين المكان.","في الدوائر: مخازن وقود المولدات ومركبات الخدمة.","المعيار: NFPA 30 (Flammable and Combustible Liquids Code).","الأسلوب: قطع الأكسجين (الخنق / Smothering)، لا التبريد وحده."]},{heading:"3. الفئة C في NFPA — الأجهزة الكهربائية الموصولة بالتيار (Energized Electrical)",body:"الحرائق في الأجهزة الكهربائية أثناء سريان التيار فيها:",points:["المواد القابلة للاحتراق: الحواسيب، والخوادم، والمقابس، واللوحات الكهربائية.","حرارة القوس الكهربائي (Arc Flash): تصل إلى نحو 19400°C (35000°F) — أي أشد حرارة من سطح الشمس بنحو 4 أضعاف (OSHA).","مطفآت الحريق: CO₂، ومسحوق ABC، والعوامل النظيفة (Clean Agent) مثل FK-5-1-12.","لا تستخدم الماء أو الرغوة على الأجهزة الكهربائية الموصولة بالتيار إلا إذا أظهر الملصق تصنيف الفئة C أو علامة اختبار كهربائي (كبعض مطفآت رذاذ الماء Water Mist) — بسبب خطر الصعق الكهربائي القاتل.","أولًا: إن كان الوصول إلى اللوحة آمنًا دون المرور بجانب النار، فافصل الكهرباء منها؛ ثم أطفئ النار وفقًا للمادة المحترقة.","المعيار: NFPA 70E (Electrical Safety in the Workplace).","في غرف تقنية المعلومات والاتصالات (ICT): العوامل النظيفة أفضل — فهي لا تُلحق ضررًا بالأجهزة الثمينة.","ملاحظة: في EN 2 تمثل الفئة C الغازات لا الكهرباء؛ ففي أوروبا لا تُعدّ الحرائق الكهربائية فئة مستقلة، أما الفئة E (الكهرباء) فتُستخدم في أستراليا فقط."]},{heading:"4. الفئة D — المعادن القابلة للاحتراق (Combustible Metals)",body:"المعادن القابلة للاحتراق — من أخطر الأنواع:",points:["المواد القابلة للاحتراق: المغنيسيوم، والتيتانيوم، والصوديوم، والبوتاسيوم، والليثيوم المعدني.","الحرارة: يحترق المغنيسيوم بدرجة حرارة تقارب 3100°C (5610°F).","لا تستخدم الماء أبدًا! فالماء + المغنيسيوم = هيدروجين وانفجار.","لا تستخدم CO₂ أبدًا! فالمغنيسيوم يحترق حتى في CO₂ ويشتدّ الحريق.","فقط: مطفأة أو مادة يذكر ملصقها هذا المعدن (مساحيق الفئة D مثل كلوريد الصوديوم أو الغرافيت)، فالمادة تختلف من معدن لآخر (فالليثيوم مثلًا يحتاج مادة مخصّصة لليثيوم). ولا تستخدم المسحوق العادي أو الرغوة أبدًا. ولا يُستخدم الرمل الجاف إلا إذا نصّت عليه خطة الحريق في الموقع أو صحيفة بيانات السلامة (SDS) للمعدن وكان جافًا تمامًا.","في الدوائر: المختبرات الكيميائية وأماكن تشغيل المعادن. أما بطاريات الليثيوم أيون العادية فلا تحتوي على الليثيوم المعدني، ويُوصى بتبريدها بالماء.","المعيار: NFPA 484 (Combustible Metals).","اتصل فورًا بالرقم 115 — إذ يلزم فريق متخصص."]},{heading:"5. الفئة F (EN 2) / الفئة K (NFPA) — زيوت الطبخ (Cooking Oils)",body:"زيوت الطبخ ودهونه — من أكثر حرائق المطابخ شيوعًا:",points:["المواد القابلة للاحتراق: زيوت الطبخ (النباتية والحيوانية) والدهون.","درجة الاشتعال الذاتي: أعلى من 340°C عمومًا، بحسب نوع الزيت.","المطفأة: المادة الكيميائية الرطبة (Wet Chemical) — أملاح البوتاسيوم؛ وهي مصنوعة لزيوت الطبخ ودهونه، وكثير منها مصنَّف للفئة A أيضًا، لذا اقرأ الملصق واستخدمها وفقه (وفي بريطانيا تحمل شريطًا أصفر وفق BS 7863).","لا تستخدم الماء أبدًا! فالماء يتحول سريعًا إلى بخار داخل الزيت الساخن ويقذف الزيت المشتعل بقوة (كرة نارية).","مسحوق ABC غير مناسب لزيوت الطبخ — فقد يعود الحريق إلى الاشتعال.","الأسلوب: إذا كان الحريق صغيرًا، فأوقف مصدر الحرارة وضع غطاءً أو بطانية حريق (Fire Blanket) فوقه ولا ترفع الغطاء أو البطانية.","في كافتيريا الدائرة: مطفأة المادة الكيميائية الرطبة (Wet Chemical) قرب مكان إعداد الطعام (NFPA 10: على مسافة لا تزيد على 9 أمتار).","المعايير: BS EN 3-7، NFPA 10، NFPA 17A (Wet Chemical Systems)."]},{heading:"6. اختيار مطفأة الحريق المناسبة — مصفوفة القرار",body:"الأساس: 1) المادة المحترقة، 2) حجم الحريق، 3) المكان:",points:["المصفوفة: A: الماء أو ABC | B السوائل: الرغوة أو CO₂ أو ABC (المذيبات القطبية: رغوة AR أو CO₂ أو ABC) | B الغاز: أوقف الغاز أولًا إن كان ذلك آمنًا، ولا تُطفئ أبدًا لهب غاز لا تستطيع إيقافه | C: CO₂ أو العامل النظيف (Clean Agent) أو مسحوق ABC (المسحوق يُتلف الأجهزة الإلكترونية) | D: مطفأة D يذكر ملصقها هذا المعدن | F/K: المادة الكيميائية الرطبة (Wet Chemical).","الحجم: لا تستخدم مطفأة الحريق إلا لحريق صغير في بدايته؛ ولا تستخدمها إذا كانت النار أكبر من سلة مهملات، أو كانت تنتشر، أو كان الدخان يزداد: اخرج واتصل بالرقم 115.","المكان: غرف ICT: العامل النظيف (Clean Agent) أو CO₂ | مخازن الورق: الماء أو ABC | الكافتيريا: المادة الكيميائية الرطبة (Wet Chemical).","للدائرة العادية: ABC وCO₂، والمادة الكيميائية الرطبة (Wet Chemical) في المطبخ.","مدة التشغيل: تفرغ المطفآت الصغيرة بسرعة، غالبًا خلال ثوانٍ قليلة، ومدة التفريغ الدقيقة مكتوبة على الملصق — فكن ضمن المدى المحدد على الملصق، وطريق الخروج خلفك، قبل البدء.","الفحص والخدمة (NFPA 10 وOSHA؛ ولم تُؤكَّد بعدُ القواعد في دهوك): فحص بصري شهريًا؛ فحص وصيانة سنويًا على يد فني مختص؛ إعادة التعبئة بعد أي استخدام؛ مطفآت المسحوق الجاف ذات الضغط المخزَّن: تفريغ وفحص داخلي كل 6 سنوات؛ اختبار الضغط (Hydrostatic): كل 5 سنوات لمطفآت الماء والرغوة وCO₂ والمادة الكيميائية الرطبة (Wet Chemical) والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ (Stainless Steel)، وكل 12 سنة لمطفآت المسحوق الجاف ذات الضغط المخزَّن والجسم من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم."]},{heading:"7. مراحل تطور الحريق (Stages of Fire)",body:"يمر كل حريق بـ4 مراحل:",points:["1. البداية (Incipient): دخان قليل ونار صغيرة.","2. النمو (Growth): ترتفع الحرارة وتنتشر النار.","3. التطور الكامل (Fully Developed): تحترق جميع محتويات الغرفة وقد تتجاوز الحرارة 1000°C.","4. الخمود (Decay): يقل الوقود، لكن خطر الارتداد اللهبي (Backdraft) قائم.","الاشتعال الوميضي (Flashover) بين المرحلتين 2 و3: عندما تصل حرارة طبقة الغازات العليا إلى نحو 500-600°C، تشتعل جميع محتويات الغرفة بسرعة.","الارتداد اللهبي (Backdraft): فتح باب غرفة فيها نار ونقص في الأكسجين يُدخل الأكسجين إليها فيحدث انفجار ناري.","استجابة الموظف: لا يكون إطفاء الحريق آمنًا إلا في المرحلة 1 (Incipient)."]}],media:[{kind:"video",src:"media/videos/gov_fire_classes.mp4",title:"تصنيف أنواع الحرائق",description:"عرض فئات الحرائق وفقًا لـNFPA وEN 2"},{kind:"image",src:"media/images/gov_fire_decision.png",title:"مصفوفة القرار (Decision Matrix)",description:"اختيار مطفأة الحريق المناسبة"}],quiz:[{question:"بأي مطفأة يُطفأ حريق الحاسوب (الفئة C في NFPA)؟",options:[{text:"الماء",correct:!1},{text:"CO₂ أو العامل النظيف (Clean Agent)",correct:!0},{text:"الرغوة",correct:!1},{text:"مطفأة D",correct:!1}],explanation:"CO₂ أو العامل النظيف (Clean Agent) — فهما لا يتركان بقايا. ويصلح مسحوق ABC أيضًا لكنه يُتلف الأجهزة الإلكترونية. أما الماء والرغوة العاديان فيوصلان الكهرباء وقد يسببان الصعق."},{question:"ما الفئة D؟",options:[{text:"السوائل القابلة للاشتعال",correct:!1},{text:"الخشب والورق",correct:!1},{text:"المعادن القابلة للاحتراق",correct:!0},{text:"الغازات المضغوطة",correct:!1}],explanation:"الفئة D = المعادن القابلة للاحتراق (المغنيسيوم، والتيتانيوم...). ولا تُستخدم لها إلا مطفأة أو مادة يذكر ملصقها هذا المعدن؛ ولا يُستخدم الرمل الجاف إلا إذا نصّت عليه خطة الحريق في الموقع أو صحيفة بيانات السلامة (SDS) للمعدن وكان جافًا تمامًا."},{question:"لماذا لا يجوز استخدام الماء على حريق زيت الطبخ؟",options:[{text:"لأنه يبرّد المقلاة فقط فيستمر الحريق في الاشتعال ببطء",correct:!1},{text:"لأن الماء يتحول إلى بخار ويقذف الزيت المشتعل بقوة",correct:!0},{text:"لأنه ثقيل جدًا",correct:!1},{text:"لأن الماء يمتزج بالزيت فيجعل اللهب يدوم مدة أطول بكثير",correct:!1}],explanation:"الزيت شديد السخونة يحوّل الماء سريعًا إلى بخار؛ والبخار يقذف الزيت المشتعل ويُحدث كرة نارية."},{question:"ما المعيار NFPA 10؟",options:[{text:"تصنيف الموظفين",correct:!1},{text:"مطفآت الحريق اليدوية (Portable Fire Extinguishers)",correct:!0},{text:"أنظمة المرشّات المائية (Sprinkler)",correct:!1},{text:"حماية البيانات",correct:!1}],explanation:"NFPA 10 هو المعيار الأمريكي لمطفآت الحريق اليدوية: اختيارها، وتركيبها، وفحصها، وصيانتها."},{question:"ما مرحلة الحريق الوحيدة التي يستطيع فيها الموظف إطفاء الحريق بأمان؟",options:[{text:"الخمود (Decay)",correct:!1},{text:"التطور الكامل (Fully Developed)",correct:!1},{text:"البداية (Incipient)",correct:!0},{text:"الاشتعال الوميضي (Flashover)",correct:!1}],explanation:"لا يكون إطفاء الحريق من قِبل الموظف آمنًا إلا في المرحلة الأولى (Incipient)."},{question:"عند أي درجة حرارة تقريبًا لطبقة الغازات العليا يحدث الاشتعال الوميضي (Flashover) عمومًا؟",options:[{text:"نحو 200-300°C",correct:!1},{text:"نحو 300-400°C",correct:!1},{text:"نحو 500-600°C",correct:!0},{text:"نحو 800-900°C",correct:!1}],explanation:"يحدث الاشتعال الوميضي (Flashover) عندما تصل حرارة طبقة الغازات العليا إلى نحو 500-600°C — فتشتعل جميع محتويات الغرفة بسرعة."},{question:"تحترق بقعة صغيرة من ديزل المولّد على الأرض في الساحة. أُطلق الإنذار والمخرج خلفك. أيّ مطفأة تختار؟",options:[{text:"مطفأة ماء لا يبيّن ملصقها إلا الفئة A، لأن الماء يبرّد أي حريق",correct:!1},{text:"أي مطفأة حمراء، لأن الجسم الأحمر يدلّ على أنها مناسبة لكل الفئات",correct:!1},{text:"مطفأة يبيّن ملصقها الفئة B، مثل الرغوة أو مسحوق ABC، من مدى الملصق",correct:!0},{text:"مطفأة مسحوق الفئة D، لأنها أقوى مادة إطفاء لكل أنواع الوقود",correct:!1}],explanation:"الديزل سائل قابل للاشتعال من الفئة B. اختر بحسب رموز الفئات على الملصق لا بحسب اللون؛ فتيار الماء ينشر السائل المشتعل، ومواد الفئة D مخصّصة فقط للمعادن المذكورة على ملصقها."}],steps:[{title:"أطلق الإنذار أولًا",detail:"اضغط زر إنذار الحريق، ونبّه من حولك، وتأكّد من أن أحدًا اتصل بالرقم 115 قبل أن تفكّر في المطفأة.",critical:!0},{title:"حدِّد ما الذي يحترق",detail:"المواد الصلبة العادية كالورق والخشب من الفئة A؛ والسوائل القابلة للاشتعال من الفئة B؛ والغازات من الفئة B في NFPA ومن الفئة C في EN 2؛ والمعدات الكهربائية الموصولة بالتيار من الفئة C في NFPA؛ والمعادن من الفئة D؛ وزيت الطبخ من الفئة K في NFPA (= الفئة F في EN). وإذا لم تعرف ما الذي يحترق فلا تكافحه: اخرج."},{title:"اقطع المصدر فقط إذا كان ذلك آمنًا",detail:"اقطع الكهرباء من اللوحة فقط إذا استطعت الوصول إليها دون المرور بجانب النار. ولا يوقف الغازَ إلا شخص مؤهَّل وفقط إذا كان ذلك آمنًا؛ ولا تُطفئ أبدًا لهب غاز لا يمكن إيقافه.",critical:!0},{title:"طابِق الملصق مع الفئة",detail:"اقرأ رموز الفئات على ملصق المطفأة؛ فاللون ليس الفئة أبدًا. ومسحوق ABC يغطي A وB وC فقط، لا D (المعادن) ولا K/F (زيت الطبخ)؛ وحريق الفئة D يحتاج إلى مادة يذكر ملصقها ذلك المعدن بالاسم."},{title:"نعم أو لا",detail:"لا تستخدم المطفأة إلا إذا كان الحريق صغيرًا وفي بدايته، والمطفأة مناسبة له، والمخرج خلفك، وتمّ الاتصال بالرقم 115، وأنت مدرَّب، ولا يسدّ الدخان أو الحرارة طريق خروجك. ابدأ من المسافة المذكورة على الملصق. وإذا كانت أي إجابة «لا»، أو لم تنطفئ النار فورًا، فاخرج وأغلق الباب.",critical:!0}],warnings:["لا تصبّ الماء أبدًا على زيت طبخ مشتعل: يتحوّل الماء فورًا إلى بخار ويقذف الزيت المشتعل على الناس.","لا تستخدم الماء أو الرغوة أبدًا على معدات كهربائية موصولة بالتيار إلا إذا بيّن الملصق أنها معتمدة لذلك: فقد ينقل التيار صدمة كهربائية قاتلة.","لا تُطفئ أبدًا لهب غاز إذا تعذّر إيقاف الغاز بأمان: يتجمّع الغاز غير المحترق وقد ينفجر."],tips:["تجوّل في طابقك وسجّل الفئات التي قد تحدث في كل غرفة: الملفات والأثاث (A)، ووقود المولّد (B)، وغرف الخوادم والكهرباء (C في NFPA)، والمطبخ (K في NFPA = F في EN).","تأكّد من أن ملصق المطفأة في كل منطقة يبيّن رموز الفئة التي تناسب خطر تلك المنطقة.","عندما تتصل بالرقم 115، قل ما الذي يحترق: فهذا يساعد الفريق على اختيار المادة الصحيحة وحماية أفراده.","عندما يذكر مورّد أو وثيقة فئةً ما، اسأل عن النظام المستخدم: فحروف NFPA وحروف EN 2 لا تعني الشيء نفسه دائمًا."],activity:{prompt:"أنت مسؤول الحريق المدرَّب في طابقك. اشتعلت مقلاة زيت طبخ على الموقد في مطبخ الموظفين. أُطلق الإنذار، والنار ما تزال صغيرة، والباب خلفك. وفي متناولك مطفأة ماء، ومطفأة مسحوق ABC، ومطفأة مادة كيميائية رطبة (Wet Chemical) يبيّن ملصقها الفئة K (= F في EN)، وغطاء للمقلاة. ماذا تفعل؟",options:[{text:"أستخدم مطفأة الماء لأنها الأقرب إلى الموقد",correct:!1,feedback:"خطأ: الماء على الزيت المشتعل يتحوّل فورًا إلى بخار ويقذف الزيت المشتعل عليك وفي أرجاء الغرفة."},{text:"أطفئ مصدر الحرارة إن كان ذلك آمنًا، ثم أغطّي المقلاة بالغطاء أو أستخدم مطفأة المادة الكيميائية الرطبة برفق كما يبيّن ملصقها",correct:!0,feedback:"صحيح: زيت الطبخ من الفئة K في NFPA (= F في EN). الغطاء أو المادة الرطبة يخنقان الزيت ويبرّدانه دون أن يتناثر؛ وإذا لم تنطفئ النار فورًا فاخرج وأغلق الباب."},{text:"أستخدم مطفأة مسحوق ABC لأن ABC يغطي كل أنواع الحرائق",correct:!1,feedback:"خطأ: مسحوق ABC يغطي A وB وC فقط، لا K/F؛ وقد يشتعل الزيت الساخن من جديد بعد أن يستقرّ المسحوق."},{text:"أحمل المقلاة المشتعلة إلى خارج المطبخ نحو الساحة المفتوحة",correct:!1,feedback:"خطأ: نقل مقلاة مشتعلة يسكب الزيت المشتعل عليك وعلى من في الطريق."}]},caseStudy:[{prompt:"يخرج دخان وشرر من لوحة توزيع كهربائية صغيرة في ممرّ مديريتك. أحد زملائك يتصل بالرقم 115. وبالقرب منك مطفأة CO₂ ومطفأة ماء، والمفتاح الرئيسي للطابق عند الدرج بعيدًا عن الدخان. ماذا تفعل أولًا؟",options:[{text:"أرشّ مطفأة الماء داخل اللوحة لأنها تحتوي على أكبر كمية من المادة",correct:!1,feedback:"خطأ: اللوحة موصولة بالتيار (الفئة C في NFPA)؛ وقد ينقل الماء إليك صدمة كهربائية قاتلة."},{text:"أقطع كهرباء الطابق من المفتاح الرئيسي الذي أصل إليه دون المرور بجانب النار، ثم أراجع قرار «نعم أو لا» قبل استخدام مطفأة CO₂",correct:!0,feedback:"صحيح: اقطع الكهرباء فقط عندما تصل إليها بأمان، ثم قرّر؛ وCO₂ مناسب للمعدات الكهربائية ولا يترك بقايا."},{text:"أفتح غطاء اللوحة لأرى بالضبط أيّ سلك يحترق",correct:!1,feedback:"خطأ: فتح الغطاء يُدخل الهواء إلى النار ويقرّب وجهك ويديك من الأجزاء الموصولة بالتيار ومن اللهب."}]},{prompt:"استخدمت مطفأة CO₂ من المسافة المذكورة على ملصقها فانطفأ اللهب. وبعد وقت قصير عاد الدخان، ومطفأة CO₂ فارغة، والممرّ يمتلئ بالدخان. ماذا الآن؟",options:[{text:"آخذ مطفأة الماء وأعود إلى اللوحة لأن الكهرباء مقطوعة الآن",correct:!1,feedback:"خطأ: النار لم تبقَ منطفئة والدخان يزداد، فالجواب «لا»؛ لا تكافحها بعد الآن."},{text:"أبقى في الممرّ وأبعد الدخان بملفّ ورقي حتى يصل فريق 115",correct:!1,feedback:"خطأ: الدخان سامّ، وتحريكه يمدّ النار بمزيد من الهواء؛ يجب أن تخرج."},{text:"أخرج، وأغلق الأبواب خلفي، وأتأكّد من أن فريق 115 في الطريق، وأخبر الفريق بما احترق وما استخدمته",correct:!0,feedback:"صحيح: إذا لم تنطفئ النار فورًا أو عادت، فاخرج وأغلق الباب. ويحتاج فريق 115 إلى معرفة أن المصدر لوحة كهربائية وأن CO₂ قد استُخدم."}]}],realCase:"سيناريو توضيحي: في دائرة حكومية، تصاعد دخان من مشترك كهربائي تحت مكتب مكدّس بالملفات. أمسك أحد الموظفين أقرب مطفأة، وكانت مطفأة ماء، لكن مسؤول الحريق في الطابق أوقفه: فالمشترك ما زال موصولًا بالتيار. طلب المسؤول من زميل أن يُطلق الإنذار ويتصل بالرقم 115، وقطع كهرباء الطابق من المفتاح الرئيسي عند الدرج بعيدًا عن الدخان، وقرأ ملصق مطفأة CO₂ قبل أن يستخدمها على الحريق الصغير. فانطفأ اللهب. تراجع المسؤول، وراقب الأوراق خشية أن تبقى مشتعلة من الداخل، وأخبر فريق 115 بما احترق. الدرس: حدِّد ما الذي يحترق قبل أن تختار المطفأة."},{id:18,code:"GOV-118",icon:"FireExtinguisher",accent:"#ea580c",title:"مطفآت الحريق — أنواعها واختيارها",subtitle:"Fire Extinguisher Types — NFPA 10 + BS EN 3",summary:"الأنواع الستة الرئيسية لمطفآت الحريق اليدوية وفقًا للمعايير الدولية واختيارها للدوائر",blocks:[{body:"يجب اختيار مطفأة الحريق في الدوائر وفقًا لنوع الحريق المحتمل. ففي معظم الدوائر، تُشكّل مطفآت مسحوق ABC ومطفآت CO₂ معًا الأساس، مع مطفأة المادة الكيميائية الرطبة (Wet Chemical) في المطبخ. ويشرح هذا الدرس الأنواع الستة الرئيسية، وألوانها، وأحجامها، وطريقة PASS، وجدول الفحص. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. اللون ليس فئة الحريق: الألوان أدناه هي الممارسة البريطانية (جسم أحمر وفق BS EN 3 مع شريط ملوّن وفق BS 7863)، ولم تُؤكَّد بعدُ الألوان المتّبعة في دهوك، لذا اقرأ الملصق (Label) ورموز الفئات دائمًا."},{heading:"1. مطفأة الماء — Water (الفئة A)",body:"أكثر المطفآت شيوعًا للفئة A — المواد الصلبة:",points:["اللون في بريطانيا (BS EN 3): أحمر بالكامل بلا شريط.","الفئة: A فقط (الخشب، والورق، والقماش، والبلاستيك).","طريقة العمل: تبرّد النار وتخفض الحرارة.","الأحجام الشائعة: 6 و9 لترات.","المسافة: ابدأ من المسافة المحددة على ملصق المطفأة، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار.","لا تستخدمها أبدًا للكهرباء (الصعق) ولا للسوائل ولا لزيوت الطبخ (فهي تنشر النار).","في الدائرة: الممرات وغرف الأرشيف.","سعرها منخفض، لكنها مناسبة للفئة A فقط.","الفحص: فحص بصري شهري (مقياس الضغط إن وُجد، ومسمار الأمان، والختم) وفحص وصيانة كل سنة من قِبل شخص مختص."]},{heading:"2. مطفأة الرغوة — Foam (الفئتان A وB)",body:"رغوة AFFF (Aqueous Film-Forming Foam):",points:["اللون في بريطانيا (BS EN 3 / BS 7863): أحمر مع شريط كريمي.","الفئة: A وB (السوائل القابلة للاشتعال) — وليست للكحول والمذيبات القطبية الأخرى (Polar Solvents) إلا إذا كانت رغوة مقاومة للكحول (AR Foam)، وليست الخيار العام لحرائق الغاز.","طريقة العمل: تُكوّن الرغوة طبقة فوق السائل، فتقطع الأكسجين وتبرّد.","الأحجام الشائعة: 6 و9 لترات.","المسافة: ابدأ من المسافة المحددة على الملصق، ولا تقترب إلا كلما صغرت النار.","مناسبة لـ: مخازن الوقود وأماكن المولدات.","لا تستخدمها للأجهزة الكهربائية الموصولة بالتيار — فهي توصل الكهرباء كالماء.","في الدائرة: موقف السيارات ومخزن زيت الغاز.","تحتوي AFFF على مواد PFAS الضارة بالبيئة والصحة؛ والرغوة الخالية من الفلور (Fluorine-Free Foam) هي البديل الحديث."]},{heading:"3. مطفأة CO₂ — Carbon Dioxide (الفئة B والحرائق الكهربائية)",body:"الأفضل للأجهزة الكهربائية والسوائل:",points:["اللون في بريطانيا (BS EN 3 / BS 7863): أحمر مع شريط أسود.","الفئة: B والأجهزة الكهربائية الموصولة بالتيار (الفئتان B وC في NFPA؛ وفي EN 2 تعني C الغاز، وCO₂ غير مصنَّفة لحرائق الغاز).","طريقة العمل: يُزيح غاز CO₂ الأكسجين من حول النار (الخنق).","الأحجام الشائعة: 2 و5 كغ.","المسافة: مدى CO₂ قصير؛ ابدأ من المسافة المحددة على الملصق، ولا تقترب إلا كلما صغرت النار.","مناسبة لـ: غرف ICT، واللوحات الكهربائية، وغرفة الخوادم (Server Room).","لا تترك أي بقايا ولا تُلحق ضررًا بالأجهزة الثمينة؛ لكنها غير فعّالة في حرائق الفئة A العميقة.","الخطر: تُخفض الأكسجين في الغرف المغلقة — فأخلِ الغرفة وجدّد هواءها بعد الاستخدام.","يصبح البوق باردًا جدًا (نحو −78°C) — لا تلمس البوق، وأمسك المقبض فقط.","في الدائرة: قسم ICT، وغرفة الخوادم، وقرب اللوحات الكهربائية."]},{heading:"4. مطفأة المسحوق الجاف ABC — Dry Chemical Powder",body:"أكثر المطفآت شيوعًا — للفئات A وB وC، وليست للفئتين D وK/F:",points:["اللون في بريطانيا (BS EN 3 / BS 7863): أحمر مع شريط أزرق.","الفئة: A وB وC — وليست D (المعادن) ولا K/F (زيوت الطبخ).","المادة: فوسفات الأمونيوم الأحادي (Monoammonium Phosphate).","طريقة العمل: يوقف المسحوق التفاعل الكيميائي للنار.","الأحجام الشائعة: 1 و2 و6 و9 كغ.","المسافة: ابدأ من المسافة المحددة على الملصق، ولا تقترب إلا كلما صغرت النار.","مناسبة لـ: الممرات والمرائب والمخازن — وليست لزيوت الطبخ.","ينتشر المسحوق في الغرفة، ويحجب الرؤية، ويصعب تنظيفه.","يُلحق المسحوق ضررًا بالأجهزة الإلكترونية — ولذلك فإن CO₂ أفضل للحواسيب وأجهزة ICT.","في الدائرة: الممرات والمرآب وقرب المخارج.","سعرها منخفض، وتُركَّب عادةً في الدوائر."]},{heading:"5. مطفأة المادة الكيميائية الرطبة — Wet Chemical (الفئة F/K) — المطبخ",body:"مخصصة لزيوت المطبخ ودهونه الساخنة:",points:["اللون في بريطانيا (BS EN 3 / BS 7863): أحمر مع شريط أصفر.","الفئة: K (NFPA) / F (EN 2) — زيوت الطبخ.","المادة: أملاح البوتاسيوم (Potassium Acetate أو Potassium Citrate).","طريقة العمل: تحوّل الزيت إلى طبقة شبيهة بالصابون (Saponification) تبرّد الزيت وتقطع الأكسجين.","الأحجام الشائعة: 2 و6 لترات.","استخدمها كما يبيّن الملصق: رُشَّها ببطء وبالأنبوب الطويل فوق الزيت لكي لا يتطاير.","مصنوعة لزيوت المطبخ ودهونه (NFPA K / EN F)؛ وكثير منها مصنَّف للفئة A أيضًا، لذا اقرأ الملصق. وليست لزيت الغاز والنفط الأبيض (الفئة B).","لا تصبّ الماء أبدًا على الزيت الساخن — فالماء يتحول إلى بخار ويقذف الزيت المشتعل!","في الدائرة: الكافتيريا والمطبخ.","قبل الاستخدام، إن كان ذلك آمنًا، افصل الغاز أو الكهرباء عن جهاز الطهي."]},{heading:"6. العوامل النظيفة — Clean Agent (FK-5-1-12 / HFC-227ea)",body:"لأجهزة ICT والأجهزة الثمينة:",points:["اللون: جسم أحمر مكتوب عليه اسم المادة (وفي بعض الدول شريط أخضر).","الفئة: تختلف بحسب الطراز؛ اقرأ الملصق.","المادة: FK-5-1-12 (الاسم التجاري Novec 1230) أو HFC-227ea.","طريقة العمل: غاز نظيف — لا يترك أي بقايا ولا يُلحق ضررًا بالأجهزة.","تُفرَّغ الأنظمة الثابتة للعوامل النظيفة (NFPA 2001)، وهي ليست مطفآت يدوية، خلال 10 ثوانٍ أو أقل.","مناسبة لـ: غرفة الخوادم (Server Room)، ومركز البيانات (Data Center)، والأرشيف.","مطفأة العوامل النظيفة اليدوية: تصنيف الفئات والحد الأدنى لحجم الغرفة مكتوبان على الملصق؛ وغادر الغرفة بعد الاستخدام. الأنظمة الثابتة: المادة آمنة للإنسان بتراكيز التصميم، لكن يجب إخلاء الغرفة بسبب الدخان والمواد الناتجة عن الحريق.","لا تضر بطبقة الأوزون، وقد حلّت محل Halon 1301.","مرتفعة الثمن؛ وفي غرف الخوادم تُركَّب غالبًا بوصفها نظامًا ثابتًا للغمر الكلي للغرفة (Total Flooding)، وهو منفصل عن المطفآت اليدوية.","في الدائرة: في الأماكن الحساسة فقط — غرفة الخوادم ومركز عمليات الطوارئ (EOC).","المعيار: NFPA 2001 (Clean Agent Fire Extinguishing Systems)."]},{heading:"7. PASS — طريقة الاستخدام",body:`قبل استخدام المطفأة (يجب أن تكون كل الإجابات «نعم»):
• الحريق صغير وفي بدايته، مثل حريق في سلة مهملات أو مقلاة.
• المطفأة مناسبة لهذا النوع من الحريق.
• طريق الخروج خلفك، والنار ليست بينك وبين المخرج.
• تمّ إطلاق الإنذار: نُبِّه الآخرون واتُّصل بالرقم 115.
• أنت مدرَّب على استخدام المطفأة.
• لا يوجد دخان أو حرارة يمنعان خروجك.
• إذا لم تنطفئ النار فورًا، فتوقّف واخرج وأغلق الباب خلفك.

طريقة PASS هي الطريقة العامة لمعظم مطفآت الحريق اليدوية. أما مطفآت الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والعوامل النظيفة (Clean Agent) والمطفآت ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة. خطوة بخطوة:`,points:["P = Pull (اسحب): اسحب مسمار الأمان واكسر الختم.","A = Aim (وجِّه): وجِّه فوهة الخرطوم نحو قاعدة النار لا أعلاها — ابدأ من المسافة المحددة على ملصق المطفأة، ولا تقترب إلا كلما صغرت النار.","S = Squeeze (اضغط): اضغط المقبض بقوة وباستمرار.","S = Sweep (حرِّك): من جانب إلى آخر، ببطء، حتى تنطفئ النار.","تفرغ المطفآت الصغيرة بسرعة، غالبًا خلال ثوانٍ قليلة؛ ومدة التفريغ الدقيقة مكتوبة على الملصق — فكن مستعدًا.","موضع الوقوف: يجب أن يكون طريق الخروج (الباب) خلفك.","بعد الإطفاء راقب المكان؛ وإذا عاودت النار الاشتعال، فكرّر PASS أو اخرج.","إذا لم تنطفئ النار فورًا أو فرغت المطفأة: اخرج فورًا، وأغلق الباب خلفك، وتأكد من الاتصال بالرقم 115."]},{heading:"8. الاختيار المناسب للدوائر",body:"خطة مطفآت الحريق في الدائرة:",points:["مثال لدائرة: ABC في الممرات، وCO₂ قرب الأجهزة الكهربائية وأجهزة ICT، والمادة الكيميائية الرطبة (Wet Chemical) في المطبخ (إن وُجد).","وفق NFPA 10، في منطقة الخطر المنخفض (Light Hazard) تغطي كل وحدة A (A Unit) مساحة تصل إلى 3000 قدم مربع (نحو 279 م²)، لذا تغطي المطفأة بتصنيف 2-A مساحة تصل إلى نحو 557 م² (6000 قدم مربع)؛ ولا يجوز أن تغطي مطفأة واحدة أكثر من نحو 1045 م² (11250 قدمًا مربعًا)، ويجب ألّا يضطر أحد إلى السير أكثر من 23 م (75 قدمًا) للوصول إلى مطفأة. ويوصي الكود البريطاني BS 5306-8 بمطفأتين (2) على الأقل في كل طابق (باستثناء الطوابق الصغيرة جدًا). أما المتطلب الخاص بدوائر دهوك فتضعه مديرية الدفاع المدني، ولم يُؤكَّد بعدُ.","مسافة الوصول (Travel Distance): لا تزيد على 23 مترًا للفئة A، و9 أو 15 مترًا للفئة B (بحسب تصنيف المطفأة)، و9 أمتار للفئة K (NFPA 10).","على الجدار وقرب الأبواب؛ ولا يزيد ارتفاع أعلى المطفأة على 1.5 متر عن الأرض (للمطفآت حتى 18 كغ — NFPA 10).","ضع علامة مطفأة الحريق (ISO 7010 F001) في مكان مرتفع لكي تُرى من بعيد.","الفحص البصري (شهريًا، من قِبل موظف معيَّن): في مكانها، ظاهرة ويسهل الوصول إليها؛ مسمار الأمان والختم سليمان؛ الملصق مقروء ومتجه إلى الخارج؛ لا ضرر ولا صدأ ولا تسرّب؛ الخرطوم والفوهة غير مسدودين؛ ومؤشر مقياس الضغط في المنطقة الخضراء إن وُجد. مطفآت CO₂ لا مقياس لها: ارفعها لتتأكد من أنها ممتلئة.","الفحص والصيانة (سنويًا، على يد فني مختص من شركة معتمدة).","إعادة التعبئة (Recharge): بعد أي استخدام ولو كان قصيرًا، على يد فني مختص.","صيانة السنوات الست: تُفرَّغ مطفآت المسحوق الجاف (ABC) ذات الضغط المخزَّن (Stored Pressure) التي تحتاج إلى اختبار ضغط كل 12 سنة، ويُفحص داخلها كل 6 سنوات (NFPA 10) — وهذا لا يعني استبدال المطفأة.","اختبار ضغط جسم المطفأة (Hydrostatic Test) بحسب النوع: كل 5 سنوات لمطفآت الماء والرغوة (AFFF) وCO₂ والمادة الكيميائية الرطبة (Wet Chemical) والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ (Stainless Steel)؛ وكل 12 سنة لمطفآت المسحوق الجاف (ABC) ذات الضغط المخزَّن والجسم من الفولاذ الطري (Mild Steel) أو النحاس الأصفر الملحوم (Brazed Brass) أو الألمنيوم. ولم تُؤكَّد بعدُ القواعد في دهوك.","السحب من الخدمة: تُسحب المطفأة من الخدمة إذا لم تنجح في الفحص أو الاختبار، أو تضرّرت، أو أصبحت قديمة الطراز (Obsolete) أو استدعتها الشركة المصنّعة (Recall)، أو لم يعد ملصقها مقروءًا، أو كانت غير قابلة لإعادة التعبئة (Non-rechargeable) وتجاوزت مدة الخدمة المكتوبة على ملصقها."]}],media:[{kind:"video",src:"media/videos/gov_ext_pass.mp4",title:"طريقة PASS (PASS Technique)",description:"تجربة طريقة PASS"},{kind:"image",src:"media/images/gov_ext_chart.png",title:"جدول اختيار مطفآت الحريق (Extinguisher Selection Chart)",description:"الاختيار وفقًا لفئة الحريق"}],quiz:[{question:"لأي الفئات تصلح مطفأة ABC؟",options:[{text:"A فقط",correct:!1},{text:"A + B + C",correct:!0},{text:"B + C فقط",correct:!1},{text:"D + K",correct:!1}],explanation:"مطفأة ABC للفئات A وB وC (فوسفات الأمونيوم) — وليست للفئة D (المعادن) ولا للفئة K/F (زيوت الطبخ)."},{question:"أي مطفأة حريق مناسبة لغرفة الخوادم (Server Room)؟",options:[{text:"المسحوق الجاف ABC لجميع أنواع الحرائق",correct:!1},{text:"الماء",correct:!1},{text:"العامل النظيف (Clean Agent) من نوع FK-5-1-12",correct:!0},{text:"الرغوة",correct:!1}],explanation:"لا تترك العوامل النظيفة (Clean Agent) أي بقايا ولا تُلحق ضررًا بالأجهزة."},{question:"ماذا يعني الحرف P في PASS؟",options:[{text:"Push (ادفع)",correct:!1},{text:"Pull (اسحب)",correct:!0},{text:"Point (أشِر)",correct:!1},{text:"Press (اضغط)",correct:!1}],explanation:"P = Pull (اسحب مسمار الأمان)."},{question:"وفقًا لـNFPA 10، ما الحد الأقصى لمسافة الوصول (Travel Distance) إلى مطفأة الفئة A؟",options:[{text:"10 أمتار",correct:!1},{text:"23 مترًا",correct:!0},{text:"50 مترًا",correct:!1},{text:"100 متر",correct:!1}],explanation:"NFPA 10: حتى 23 مترًا (75 قدمًا) للفئة A؛ و9 أو 15 مترًا للفئة B بحسب تصنيف المطفأة."},{question:"كم تبلغ درجة حرارة CO₂ تقريبًا عند خروجه من المطفأة؟",options:[{text:"0°C",correct:!1},{text:"−78°C",correct:!0},{text:"−30°C",correct:!1},{text:"20°C",correct:!1}],explanation:"يخرج CO₂ بدرجة حرارة تقارب −78°C — فلا تلمس البوق، لكي لا تُصاب يدك بقضمة الصقيع (Frostbite)."},{question:"ما خطر رغوة AFFF؟",options:[{text:"لا يوجد خطر",correct:!1},{text:"PFAS — ضرر بيئي",correct:!0},{text:"مرتفعة الثمن جدًا لاستخدامها في التدريب",correct:!1},{text:"باردة جدًا وتجمّد الجلد",correct:!1}],explanation:"تحتوي AFFF على مواد مفلورة (PFAS) تشكّل خطرًا على البيئة؛ والرغوة الخالية من الفلور هي البديل الحديث."},{question:"يقول زميلك إن المطفأة ذات الشريط الأزرق تعمل على كل أنواع الحرائق. ما الردّ الصحيح؟",options:[{text:"نعم: في كل البلدان يعني الشريط الأزرق أن المطفأة تغطي كل الفئات",correct:!1},{text:"لا: اقرأ رموز الفئات على الملصق؛ فاللون لا يدلّ على الفئة أبدًا",correct:!0},{text:"لا: الشريط الأزرق يدلّ دائمًا على أن المطفأة للحرائق الكهربائية فقط",correct:!1},{text:"نعم، ما دام مؤشر مقياس الضغط في الأخضر والمسمار في مكانه",correct:!1}],explanation:"اللون ليس فئة الحريق أبدًا. حتى في الممارسة البريطانية لا يبيّن الشريط إلا المادة (الأزرق = مسحوق)، ومسحوق ABC لا يغطي الفئة D (المعادن) ولا K/F (زيت الطبخ). اقرأ الملصق دائمًا."}],steps:[{title:"اعرف خطر كل منطقة",detail:"دوّن ما قد يحترق في كل منطقة: الورق والأثاث، ووقود المولّد، والمعدات الكهربائية ومعدات تقنية المعلومات (ICT)، وزيت الطبخ في المطبخ."},{title:"اختر بحسب الملصق لا بحسب اللون",detail:"يجب أن تطابق رموز الفئات على الملصق خطر المنطقة: في أغلب المكاتب مسحوق ABC وCO₂ معًا، والمادة الكيميائية الرطبة (Wet Chemical) في المطبخ، وCO₂ أو عامل نظيف (Clean Agent) لغرف تقنية المعلومات. واتّبع متطلبات الدفاع المدني فيما يجب أن يتوفر في مبناك."},{title:"افحص كل مطفأة شهريًّا",detail:"في مكانها، ظاهرة وغير محجوبة؛ مسمار الأمان والختم في مكانهما؛ مؤشر مقياس الضغط في المنطقة الخضراء إن وُجد مقياس؛ ولا ضرر فيها. وأبلغ عن أي خلل. أما الفحص والصيانة السنويان فيقوم بهما شخص مؤهَّل."},{title:"قبل الاستخدام: نعم أو لا",detail:"لا تستخدم المطفأة إلا إذا كان الحريق صغيرًا وفي بدايته، والمطفأة مناسبة له، والمخرج خلفك، وتمّ الاتصال بالرقم 115، وأنت مدرَّب، ولا يسدّ الدخان أو الحرارة طريق خروجك.",critical:!0},{title:"استخدم PASS من المدى المذكور على الملصق",detail:"اسحب المسمار، وصوّب نحو قاعدة النار، واضغط المقبض، وحرّك الفوهة يمينًا ويسارًا. ابدأ من المسافة المذكورة على الملصق ولا تقترب إلا كلما صغرت النار؛ وإذا لم تنطفئ فورًا فاخرج وأغلق الباب.",critical:!0},{title:"بعد أي استخدام: أبلغ واستبدل",detail:"المطفأة التي استُخدمت ولو للحظة تُسحب من الخدمة وتُعاد تعبئتها أو تُستبدل. وبعد استخدام CO₂ في غرفة صغيرة يخرج الجميع وتُهوّى الغرفة."}],warnings:["لا تستخدم الماء أو الرغوة أبدًا على معدات كهربائية موصولة بالتيار إلا إذا بيّن الملصق أنها معتمدة لذلك: خطر صدمة كهربائية قاتلة.","لا تستخدم الماء أو مسحوق ABC أبدًا على زيت الطبخ: الماء يقذف الزيت المشتعل، ومسحوق ABC غير معتمد للفئة K (= F في EN).","لا تمسك بوق مطفأة CO₂ أبدًا: فهو يبرد كثيرًا وقد يسبّب تجمّد الجلد؛ أمسك المقبض فقط."],tips:["ثبّت كل مطفأة قرب الخطر الذي تغطيه وعلى طريق الخروج، لكي تستخدمها والمخرج خلفك.","أبقِ الملصقات متّجهة إلى الخارج ومقروءة؛ ولا تُخفِ المطافئ أبدًا خلف الأبواب أو الأثاث أو الصناديق.","درّب الموظفين على النوع المركَّب في منطقتهم: فمطفأة CO₂ ومطفأة المسحوق لا تتصرفان بالطريقة نفسها في اليد.","سجّل كل فحص شهري على بطاقة الصيانة أو في السجل، حتى يُلاحَظ أي فحص فائت أو خلل."],activity:{prompt:"طُلب منك اقتراح مطافئ لغرفة خوادم جديدة فيها خزائن أجهزة ومزوّد طاقة غير منقطعة (UPS) كبير. يعمل فيها موظفون خلال النهار. بماذا توصي؟",options:[{text:"مطافئ ماء، لأنها رخيصة وسهلة التعبئة",correct:!1,feedback:"خطأ: لا يُستخدم الماء على معدات كهربائية موصولة بالتيار؛ فقد يسبّب صدمة قاتلة ويُتلف الأجهزة."},{text:"مطافئ مسحوق ABC فقط، لأنها معتمدة للفئة C",correct:!1,feedback:"ليس الخيار الأفضل: المسحوق معتمد للحرائق الكهربائية، لكنه ينتشر في الغرفة ويُتلف الأجهزة الإلكترونية؛ وCO₂ أو العامل النظيف أفضل هنا."},{text:"مطافئ CO₂ أو عامل نظيف يبيّن ملصقها أنها مناسبة للمعدات الكهربائية، مثبّتة عند الباب، مع تدريب الموظفين على استخدامها",correct:!0,feedback:"صحيح: CO₂ والعوامل النظيفة لا تترك بقايا على الأجهزة. وتثبيتها عند الباب يتيح للموظفين استخدامها والمخرج خلفهم، والخروج فورًا بعد استخدام CO₂."},{text:"مطافئ رغوة، لأن الرغوة تخنق كل أنواع الحرائق",correct:!1,feedback:"خطأ: الرغوة توصل الكهرباء مثل الماء، وليست للمعدات الكهربائية الموصولة بالتيار."}]},caseStudy:[{prompt:"في أثناء الفحص الشهري تجد أن مؤشر مقياس الضغط في مطفأة مسحوق ABC في الممرّ في المنطقة الحمراء وأن ختمها مكسور. ماذا تفعل؟",options:[{text:"أتركها على الجدار، فقد تعمل في حالة الطوارئ",correct:!1,feedback:"خطأ: الضغط المنخفض والختم المكسور يعنيان أنها قد لا تعمل عند الحاجة؛ يجب الإبلاغ عن الخلل."},{text:"أسحبها من الخدمة، وأبلّغ عنها لتُعاد تعبئتها أو تُستبدل، وأتأكّد من أن مطفأة أخرى مناسبة تغطي المنطقة حتى ذلك الحين",correct:!0,feedback:"صحيح: المطفأة المعطّلة لا تبقى أبدًا على الجدار كأنها سليمة، ولا يجوز أن تبقى المنطقة بلا مطفأة."},{text:"أهزّها جيدًا وأعلّقها مجددًا، لأن المسحوق كثيرًا ما يترسّب",correct:!1,feedback:"خطأ: الهزّ لا يعيد الضغط المفقود ولا الختم المكسور؛ يجب أن يفحصها شخص مؤهَّل."}]},{prompt:"قبل وصول البديل، يبدأ حريق صغير في سلّة مهملات مليئة بالورق في الممرّ نفسه. أُطلق الإنذار وتمّ الاتصال بالرقم 115. يمكنك الوصول إلى مطفأة ماء عند الدرج ومطفأة CO₂ في غرفة تقنية المعلومات المجاورة. والمخرج خلفك. أيّها تستخدم؟",options:[{text:"مطفأة الماء، بعد مراجعة قرار «نعم أو لا»، من المدى المذكور على ملصقها",correct:!0,feedback:"صحيح: الورق المحترق من الفئة A، والماء يبرّده حتى الداخل. أبقِ المخرج خلفك وراقب تجدّد الاشتعال."},{text:"مطفأة المسحوق المعطّلة، لأنها الأقرب",correct:!1,feedback:"خطأ: أنت تعرف أنها قد لا تعمل؛ ومطفأة معطّلة أمام النار تعرّضك للخطر."},{text:"مطفأة CO₂، لأن CO₂ أفضل خيار لكل حرائق المكاتب",correct:!1,feedback:"ليس الخيار الأفضل: قد يُخمد CO₂ اللهب، لكنه غير مناسب لحرائق الفئة A العميقة وقد يشتعل الورق من جديد."},{text:"أحمل سلّة المهملات المشتعلة إلى الشارع",correct:!1,feedback:"خطأ: حملها ينثر الورق المشتعل ويقرّب اللهب من جسمك."}]}],realCase:"سيناريو توضيحي: في أثناء مراجعة مبنى حكومي، وجد مسؤول السلامة أن مطبخ الموظفين لا يحوي إلا مطفأة مسحوق ABC، وأن غرفة الخوادم لا تحوي إلا مطفأة ماء. ولم تكن أيّ منهما مناسبة لخطر غرفتها. قرأ المسؤول كل الملصقات، وأبلغ عن النواقص، ورتّب وفق متطلبات الدفاع المدني مطفأة مادة كيميائية رطبة للمطبخ ومطفأة CO₂ لغرفة الخوادم، كلٌّ منهما مثبّتة عند الباب. وعُرض على موظفي الغرفتين كيف يعمل النوع الخاص بهم، وأن المطفأة بعد أي استخدام يُبلَّغ عنها وتُعاد تعبئتها. الدرس: تُختار المطفأة الصحيحة بحسب الخطر والملصق، لا بحسب العادة."},{id:19,code:"GOV-119",icon:"HeartHandshake",accent:"#db2777",title:"الإسعافات الأولية للموظفين",subtitle:"Workplace First Aid — Primary Check + CPR + AED + Common Emergencies",summary:"برنامج شامل للإسعافات الأولية لموظفي الدوائر",blocks:[{body:"في حالات الطوارئ، تكون الدقائق الأولى بالغة الأهمية: فإذا توقف القلب، يبدأ تلف الدماغ بعد بضع دقائق، وكل دقيقة تأخير في الإنعاش القلبي الرئوي (CPR) وصدمة جهاز إزالة الرجفان الخارجي الآلي (AED) تُقلل فرصة النجاة. ويشرح هذا الدرس الفحص الأولي، وCPR في الدائرة، وجهاز AED، والاختناق، والنزيف، والحروق، وحالات الطوارئ الشائعة الأخرى."},{heading:"1. الفحص الأولي — الخطر، الاستجابة، التنفس",body:"الإجراء الأول عند رؤية شخص ساقط أو فاقد للقوة:",points:["الخطر (Danger): افحص المكان قبل الاقتراب: هل توجد كهرباء أو نار أو غاز أو حركة مرور؟ سلامتك أولًا.","الاستجابة (Response): هزّ كتفيه برفق واسأله بصوت عالٍ: «هل أنت بخير؟»","إذا لم يستجب: اطلب المساعدة، واتصل بالرقم 122 (ضع الهاتف على مكبر الصوت)، وأرسل شخصًا لإحضار جهاز AED.","التنفس (Breathing): راقب الصدر مدة تصل إلى 10 ثوانٍ لترى هل يرتفع وينخفض بصورة طبيعية أم لا.","إذا لم يكن يتنفس أو كان يلهث بأنفاس غير طبيعية فقط (Gasping): فهذا توقف للقلب — ابدأ الضغطات الصدرية فورًا.","لا يفحص الأشخاص العاديون (غير الأطباء) النبض (Pulse) — فلا تُضِع الوقت في الفحص.","إذا كان يتنفس بصورة طبيعية ولم يُشتبه في إصابة الرقبة أو الظهر: ضعه على جنبه في وضعية الإفاقة (Recovery Position)، ولا تعطه شيئًا عن طريق الفم، وراقب تنفسه حتى وصول سيارة الإسعاف."]},{heading:"2. CPR في الدائرة",body:"للموظفين (غير الأطباء):",points:["موضع اليدين: منتصف الصدر (النصف السفلي من عظمة القص)، يد فوق الأخرى.","يجب أن تكون الذراعان مستقيمتين وكتفاك فوق الصدر مباشرةً؛ واضغط مستعينًا بثقل وركيك وجسمك.","العمق: 5-6 سم لجميع البالغين.","المعدل: 100-120 ضغطة في الدقيقة؛ واترك الصدر يعود إلى وضعه بالكامل بعد كل ضغطة.","النسبة: 30 ضغطة + نَفَسان (2)؛ وإذا لم تتلقَّ تدريبًا، فاكتفِ بالضغطات الصدرية (Hands-Only CPR).","إذا وُجد شخصان: تبادلا الأدوار كل دقيقتين (5 دورات) لكي لا تضعف قوة الضغطات.","لا تتوقف حتى: يصل جهاز AED ويعمل، أو يصل الفريق الطبي، أو يستعيد الشخص وعيه بوضوح.","الأخطاء الشائعة: العمق غير الكافي، والمعدل البطيء، والتوقفات الطويلة، وعدم ترك الصدر يعود إلى وضعه."]},{heading:"3. جهاز إزالة الرجفان الخارجي الآلي (AED — Automated External Defibrillator)",body:"يُوصى بتوفيره في كل مبنى حكومي كبير:",points:["الموضع: في ممر عام وظاهر، ليسهل الوصول إليه بسرعة.","العلامة: صندوق يحمل علامة AED (ISO 7010 E010) مع إضاءة واضحة.","الهدف: أن يصل جهاز AED إلى أي موقع في المبنى خلال نحو 3 دقائق.","الخطوات: 1) شغّله، 2) ضع الوسادتين اللاصقتين على الصدر العاري، 3) استمع إلى التعليمات الصوتية، 4) إذا طلب الجهاز الصدمة، فاضغط الزر.","قبل الصدمة قل بصوت عالٍ: «ابتعدوا!» — ولا يلمس أحد المصاب.","الفحص الشهري: البطارية وتاريخ انتهاء صلاحية الوسادتين.","بعد الصدمة: أجرِ CPR فورًا مدة دقيقتين، ثم يُعيد جهاز AED تحليل نظم القلب.","بعد الاستخدام: ركّب وسادتين جديدتين وبطارية جديدة ليكون الجهاز جاهزًا للمرة القادمة."]},{heading:"4. الاختناق (Choking)",body:"إذا علق شيء في حلق الشخص:",points:["الفحص: هل يستطيع الكلام أو السعال أو التنفس؟","إذا كان يسعل بقوة: شجّعه على السعال وابقَ بجانبه.","إذا لم يستطع الكلام أو السعال أو التنفس: اتصل بالرقم 122 (أو اطلب من شخص آخر الاتصال) وابدأ فورًا.","5 ضربات على الظهر: أمِله إلى الأمام واضربه بقوة بكعب راحة اليد بين لوحي الكتفين.","5 ضغطات على البطن (Heimlich): قف خلفه، وضع قبضتك فوق السرة وأسفل عظمة القص بمسافة كافية، وأمسكها باليد الأخرى واضغط بسرعة إلى الداخل وإلى الأعلى.","كرّر 5 ضربات على الظهر و5 ضغطات على البطن حتى يخرج الجسم؛ وإذا فقد وعيه، فابدأ CPR.","الرضّع دون سنة واحدة: 5 ضربات على الظهر (والرأس أخفض من الصدر) + 5 ضغطات على الصدر بكعب راحة يد واحدة؛ ولا تُجرِ ضغطات البطن أبدًا.","المرأة الحامل أو الشخص الذي لا تحيط يداك ببطنه: ضغطات على الصدر (Chest thrusts) بدلًا من ضغطات البطن."]},{heading:"5. إيقاف النزيف (Stop the Bleed)",body:"الإجراءات الثلاثة الرئيسية في Stop the Bleed:",points:["1. الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط بكلتا يديك بقوة ومن دون توقف.","2. حشو الجرح (Wound Packing): في الجروح العميقة (الفخذ، والإبط، والرقبة)، احشُ الجرح بالشاش النظيف واضغط بقوة.","3. العاصبة (Tourniquet): للنزيف الخطير من الذراع أو الساق، وبصورة مبكرة؛ على بُعد 5-7 سم فوق الجرح، لا فوق المفصل.","دوِّن وقت وضع العاصبة ولا ترخِها أو تفكّها أبدًا — فالفريق الطبي وحده هو من يزيلها.","لا تنزع أبدًا الجسم المنغرس من الجرح (فسيزداد النزيف).","إذا كان هناك جسم منغرس: لُفّ القماش حوله لكي لا يتحرك، واضغط حوله لا عليه.","جرح الرأس: اضغط برفق؛ وإذا اشتُبه في كسر الجمجمة، فلا تضغط بقوة.","جرح العين: لا تضغط على العين — بل غطِّها برفق بقطعة قماش نظيفة فقط.","في النزيف الشديد اتصل فورًا بالرقم 122؛ وإذا تشبّع القماش بالدم فلا تنزعه — بل ضع قطعة أخرى فوقه."]},{heading:"6. الحروق (Burns)",body:"درجات الحروق ونسبة مساحة سطح الجسم المحترقة (TBSA):",points:["الدرجة الأولى (سطحية): احمرار وألم فقط — مثل حروق الشمس.","الدرجة الثانية (متوسطة العمق): فقاعات وألم شديد.","الدرجة الثالثة (عميقة): يصبح الجلد أبيض أو بنيًا أو أسود؛ وقد لا يوجد ألم لأن الأعصاب احترقت.","قاعدة التسعات (Rule of 9s) للبالغين: الرأس 9%، وكل ذراع 9%، وكل ساق 18%، والصدر والبطن 18%، والظهر 18%، والأعضاء التناسلية 1%.","برِّد الحرق فورًا بماء بارد جارٍ مدة 20 دقيقة (لا الثلج ولا الماء شديد البرودة).","ثم غطِّه برفق بغلاف الطعام البلاستيكي (Cling Film) أو بقطعة قماش نظيفة غير لاصقة.","الحروق الكيميائية: اغسلها بالماء الجاري مدة 20 دقيقة على الأقل، وراجع صحيفة بيانات السلامة (SDS).","الحروق الكهربائية: افصل الكهرباء أولًا؛ فهناك جرح دخول وجرح خروج، وقد يكون الضرر الداخلي أكبر.","لا تستخدم أبدًا: الثلج أو الزيت أو الكريمات أو معجون الأسنان؛ ولا تفقأ الفقاعات ولا تنزع الملابس الملتصقة.","اتصل بالرقم 122 إذا: كان الحرق كبيرًا أو عميقًا، أو في الوجه أو اليدين أو القدمين أو الأعضاء التناسلية، أو كان حرقًا كهربائيًا، أو استنشق المصاب الدخان."]},{heading:"7. حالات طوارئ شائعة أخرى",body:"حالات شائعة في الدوائر:",points:["الإغماء (Fainting): ضعه على ظهره، وإذا لم يكن مصابًا فارفع ساقيه نحو 30 سم، وأدخل هواءً نقيًا إلى الغرفة.","طوارئ السكري (Diabetic Emergency): إذا كان واعيًا ويستطيع البلع، فأعطه سكرًا أو مشروبًا محلّى. وإذا كان فاقدًا للوعي: لا تعطه شيئًا عن طريق الفم، وضعه على جنبه واتصل بالرقم 122. ولا يُعطى الغلوكاغون (Glucagon) إلا إذا وصفه الطبيب له وكنت مدرَّبًا عليه.","نوبة الهلع (Panic Attack): تحدّث معه بهدوء وساعده على التنفس ببطء؛ ولم يعد التنفس داخل كيس ورقي موصى به.","إصابة الرأس: إذا اشتُبه في إصابة العمود الفقري فلا تحرّكه إلا إذا كان المكان خطرًا أو احتاج إلى الإنعاش القلبي الرئوي (CPR) (وعندها أبقِ الرأس والرقبة والظهر على خط واحد)، ولا تضعه على جنبه في وضعية الإفاقة (Recovery Position)؛ وراقب وعيه وتنفسه، واتصل بالرقم 122.","الكسر (Fracture): ثبّت الطرف المصاب على وضعه (Splint) ولا تحاول تقويمه، وضع ثلجًا ملفوفًا بقطعة قماش لتخفيف الألم، واتصل بالرقم 122.","الصعق الكهربائي: افصل الكهرباء، وأجرِ CPR إذا لم يكن يتنفس؛ ويجب أن يخضع كل المصابين لتخطيط القلب (ECG) في المستشفى.","التسمم: 1) ما المادة؟ 2) ما الكمية؟ 3) متى؟ — اتصل بالرقم 122، وخذ عبوة المادة معك، ولا تحثّه على التقيؤ.","لدغة الأفعى (Snake Bite): أبقِ الشخص هادئًا ومن دون حركة وثبّت الطرف المصاب بجبيرة؛ ولا تربط عليه شيئًا، ولا تجرح مكان اللدغة، ولا تمصّ الدم؛ واتصل فورًا بالرقم 122."]}],media:[{kind:"video",src:"media/videos/gov_cpr_workplace.mp4",title:"CPR في الدائرة (Workplace CPR)",description:"CPR في مكان العمل"},{kind:"video",src:"media/videos/gov_aed_demo.mp4",title:"عرض جهاز AED (AED Demo)",description:"استخدام جهاز AED"}],quiz:[{question:"ما الخطوة الأولى في الفحص الأولي؟",options:[{text:"البدء بـ CPR فورًا",correct:!1},{text:"فحص الخطر (Danger)",correct:!0},{text:"الاتصال بالرقم 122",correct:!1},{text:"AED",correct:!1}],explanation:"قبل أي شيء تأكد من أن المكان آمن لك — فإذا أُصبت، فلن تستطيع تقديم المساعدة."},{question:"في CPR، ما عمق الضغطات للبالغين؟",options:[{text:"2-3 سم",correct:!1},{text:"5-6 سم",correct:!0},{text:"8-10 سم",correct:!1},{text:"لا شيء مما سبق",correct:!1,fixed:!0}],explanation:"5-6 سم لجميع البالغين (AHA 2025)."},{question:"إذا أُعطيت صدمة AED خلال الدقائق 3-5 الأولى بعد السقوط، فإلى أي حد قد تصل فرصة النجاة؟",options:[{text:"حتى 10-20%",correct:!1},{text:"حتى 50-70%",correct:!0},{text:"حتى 20-30%",correct:!1},{text:"حتى 90-100%",correct:!1}],explanation:"قد ترفع الصدمة المبكرة خلال 3-5 دقائق نسبة النجاة إلى 50-70%؛ وكل دقيقة تأخير تُقلل الفرصة بنسبة ملحوظة."},{question:"ماذا يُفعل لرضيع دون سنة واحدة يختنق (وهو واعٍ)؟",options:[{text:"ضغطات البطن (Heimlich) فورًا",correct:!1},{text:"5 ضربات على الظهر + 5 ضغطات على الصدر",correct:!0},{text:"تركه فقط",correct:!1},{text:"CPR فورًا",correct:!1}],explanation:"5 ضربات على الظهر و5 ضغطات على الصدر بكعب راحة يد واحدة — ولا تُجرَ ضغطات البطن للرضّع أبدًا (AHA 2025)."},{question:"بعد وضع العاصبة (Tourniquet)، ماذا يجب أن تفعل؟",options:[{text:"أرخِها كل 6 ساعات",correct:!1},{text:"دوِّن وقت وضعها ولا ترخِها أبدًا",correct:!0},{text:"أزِلها بعد 10 دقائق",correct:!1},{text:"أرخِها كل 20 دقيقة ليصل الدم",correct:!1}],explanation:"دوِّن وقت الوضع (Stop the Bleed). تبقى العاصبة في مكانها حتى يزيلها الفريق الطبي؛ فإرخاؤها يُعيد النزيف."},{question:"بأي ماء يجب تبريد الحرق مدة 20 دقيقة؟",options:[{text:"الماء الساخن",correct:!1},{text:"الماء البارد الجاري، لا الثلج",correct:!0},{text:"الثلج",correct:!1},{text:"المرهم أو معجون الأسنان، لا الماء",correct:!1}],explanation:"الماء البارد الجاري — لا الماء الساخن (فهو يُعمّق الحرق) ولا الثلج (فهو يضر الجلد)."},{question:"سقط زميلك على الدرج. وهو ممدّد في أسفله، واعٍ، ويقول إن رقبته تؤلمه. والمكان آمن. ماذا تفعل؟",options:[{text:"أبقيه ساكنًا كما وجدته، وأتصل بالرقم 122، وأراقب تنفسه",correct:!0},{text:"أساعده على الجلوس ببطء والمشي إلى كرسي ليرتاح عليه",correct:!1},{text:"أقلبه فورًا على جنبه في وضعية الإفاقة (Recovery Position)",correct:!1},{text:"أرفع رأسه على معطف مطويّ لكي يتنفس بسهولة أكبر",correct:!1}],explanation:"بعد سقوط مع ألم في الرقبة يُشتبه في إصابة الرقبة أو الظهر: لا تحرّكه إلا إذا كان المكان غير آمن أو احتاج إلى CPR، ولا تستخدم وضعية الإفاقة. اتصل بالرقم 122 وواصل مراقبة تنفسه."}],steps:[{title:"افحص الخطر والاستجابة",detail:"قبل أن تقترب، تحقّق من وجود كهرباء أو نار أو غاز أو حركة مرور. ثم هزّ كتفي الشخص برفق واسأله بصوت عالٍ: «هل أنت بخير؟»",critical:!0},{title:"اطلب النجدة واتصل بالرقم 122 وأرسل في طلب جهاز AED",detail:"إذا لم يستجب، فاطلب المساعدة بصوت عالٍ، واتصل بالرقم 122 والهاتف على مكبر الصوت، وأرسل شخصًا لإحضار أقرب جهاز AED.",critical:!0},{title:"افحص التنفس مدة تصل إلى 10 ثوانٍ",detail:"انظر إلى الصدر. انعدام التنفس أو اللهاث فقط (Gasping) يعني توقف القلب: ابدأ الإنعاش القلبي الرئوي (CPR) فورًا. ولا يفحص المسعفون العاديون النبض.",critical:!0},{title:"اضغط بقوة وبسرعة في منتصف الصدر",detail:"النصف السفلي من عظمة القص، والذراعان مستقيمتان، بعمق 5-6 سم، و100-120 ضغطة في الدقيقة، مع ترك الصدر يعود إلى وضعه بالكامل. المدرَّب: 30 ضغطة ونفَسان؛ وغير المدرَّب: الضغطات فقط.",critical:!0},{title:"استخدم جهاز AED فور وصوله",detail:"شغّله واتّبع التعليمات الصوتية؛ ضع اللاصقتين على الصدر العاري؛ وتأكّد من ألّا يلمس أحدٌ الشخصَ في أثناء التحليل والصدمة؛ وتابع CPR مباشرة بعدها.",critical:!0},{title:"إذا كان الشخص يتنفس بصورة طبيعية",detail:"إذا لم يُشتبه في إصابة الرقبة أو الظهر، فضعه على جنبه في وضعية الإفاقة (Recovery Position)، ولا تعطه شيئًا عن طريق الفم، وواصل مراقبة تنفسه حتى وصول سيارة الإسعاف."}],warnings:["لا تخلط بين اللهاث والتنفس، ولا تنتظر لترى هل سيتحسّن الشخص: كل دقيقة دون CPR تُنقص فرصة النجاة.","لا تحرّك شخصًا بعد سقوط أو ضربة على الرأس أو الرقبة أو الظهر إلا إذا كان المكان غير آمن أو احتاج إلى CPR.","لا تضع أبدًا ثلجًا أو زيتًا أو كريمًا أو معجون أسنان على الحرق: برّده بماء جارٍ بارد مدة 20 دقيقة."],tips:["اعرف مكان أقرب جهاز AED وحقيبة إسعافات أولية في طابقك، ومن هم المسعفون المدرَّبون.","ضع الهاتف على مكبر الصوت لكي تتّبع تعليمات موظف الرقم 122 وأنت تُسعف.","إذا وُجد مسعفان، فتبادلا كل دقيقتين لكي تبقى الضغطات عميقة وسريعة.","بعد أي حادث، أعِد تجهيز حقيبة الإسعافات الأولية وتأكّد من تركيب لاصقات جديدة لجهاز AED وجاهزيته من جديد."],activity:{prompt:"في اجتماع، يتهاوى زميلك فجأة على كرسيه ولا يستجيب عندما تهزّ كتفيه. ويتحرّك صدره بين حين وآخر بحركات لهاث. يقول زميل آخر: «إنه يتنفس، فلننتظر قليلًا.» ماذا تفعل؟",options:[{text:"أنتظر دقيقة وأعطيه قليلًا من الماء عندما يفتح عينيه",correct:!1,feedback:"خطأ: إنه لا يتنفس بصورة طبيعية، والشخص الذي لا يستجيب لا يُعطى أي شيء عن طريق الفم أبدًا."},{text:"أطلب المساعدة، وأتصل بالرقم 122 على مكبر الصوت، وأرسل من يُحضر جهاز AED، وأمدّده على الأرض وأبدأ الضغطات الصدرية",correct:!0,feedback:"صحيح: اللهاث المتقطّع ليس تنفسًا طبيعيًّا، بل علامة على توقف القلب. والإنعاش المبكر وصدمة AED المبكرة يمنحان أفضل فرصة للنجاة."},{text:"أضعه في وضعية الإفاقة وأراقب تنفسه حتى تصل سيارة الإسعاف",correct:!1,feedback:"خطأ: وضعية الإفاقة فقط لمن يتنفس بصورة طبيعية؛ واللهاث يعني CPR الآن."},{text:"أفحص نبضه في الرقبة دقيقة كاملة قبل أن أقرّر",correct:!1,feedback:"خطأ: لا يفحص المسعفون العاديون النبض؛ فذلك يُضيع الوقت وكثيرًا ما يكون خاطئًا."}]},caseStudy:[{prompt:"في أثناء الغداء في مقصف الموظفين، تمسك زميلتك فجأة بحلقها. لا تستطيع الكلام أو السعال أو التنفس. ماذا تفعل أولًا؟",options:[{text:"أربّت على ظهرها برفق وأعطيها كأس ماء ليُدفع الجسم إلى الأسفل",correct:!1,feedback:"خطأ: قد يزيد الماء الحالة سوءًا، والتربيت الخفيف لا يحرّك الانسداد؛ فهي تحتاج إلى ضربات قوية على الظهر وضغطات على البطن."},{text:"أطلب من أحدهم الاتصال بالرقم 122، ثم أعطي 5 ضربات قوية على الظهر و5 ضغطات على البطن، وأكرّر حتى يخرج الجسم",correct:!0,feedback:"صحيح: هي لا تستطيع الكلام أو السعال أو التنفس، فمجرى الهواء مسدود. ضع القبضة فوق السرة وأسفل عظمة القص بمسافة كافية عند الضغطات."},{text:"أبقى بجانبها وأشجّعها على مواصلة السعال وحدها",correct:!1,feedback:"خطأ: تشجيع السعال صحيح فقط عندما يستطيع الشخص السعال بقوة؛ وهي لا تستطيع."}]},{prompt:"رغم عدة جولات من الضربات على الظهر والضغطات على البطن، تفقد الاستجابة وتسقط على الأرض. وزميل على الهاتف مع الرقم 122. ماذا الآن؟",options:[{text:"أواصل الضغطات على البطن وهي ممدّدة على الأرض",correct:!1,feedback:"خطأ: عندما يفقد الشخص المختنق الاستجابة يتحوّل التسلسل إلى CPR."},{text:"أضعها في وضعية الإفاقة وأنتظر سيارة الإسعاف",correct:!1,feedback:"خطأ: هي لا تستجيب بعد الاختناق وقد لا تتنفس؛ ووضعية الإفاقة لا تعالج ذلك."},{text:"أنزلها بأمان إلى الأرض، وأبدأ CPR فورًا، وأرسل من يُحضر جهاز AED",correct:!0,feedback:"صحيح: إذا فقد الشخص المختنق الاستجابة فابدأ CPR. وقد تساعد الضغطات الصدرية أيضًا على تحريك الجسم العالق."}]}],realCase:"سيناريو توضيحي: في اجتماع صباحي في مديرية حكومية، سقط موظف ولم يستجب. اتصل أحد الزملاء بالرقم 122 على مكبر الصوت، وركض آخر لإحضار جهاز AED من الممرّ. ولاحظ موظف سبق أن تلقّى تدريبًا على الإسعافات الأولية أن الرجل يلهث فقط، فبدأ الضغطات الصدرية فورًا، بقوة وسرعة في منتصف الصدر. وعندما وصل جهاز AED اتّبعوا تعليماته الصوتية، وتأكّدوا من ألّا يلمسه أحد في أثناء الصدمة، وعادوا فورًا إلى الضغطات حتى تسلّم فريق الإسعاف. وبعد ذلك أعادت الدائرة تجهيز الحقيبة واستبدلت لاصقات الجهاز. الدرس: اللهاث ليس تنفسًا؛ ابدأ CPR دون تأخير."},{id:20,code:"GOV-120",icon:"Siren",accent:"#2563eb",title:"عمليات الدفاع المدني والتنسيق",subtitle:"CD Operations + ICS + Multi-Agency Response",summary:"دور الدائرة أثناء استجابة الدفاع المدني (115) والتنسيق مع الجهات الأخرى",blocks:[{body:"يجب أن تعرف الدوائر كيف تعمل مع الدفاع المدني (115) في حالات الطوارئ. ويُعدّ المعيار NFPA 1660 (الذي دُمج فيه NFPA 1600) ودورات FEMA ICS-100/200 أسسًا دولية. ووفقًا لنظام ICS، يتولى قائد واحد للحادث (Incident Commander) إصدار الأوامر، وتعمل جميع الفرق الطبية والشرطة وفرق الإطفاء والدوائر تحت هذه القيادة."},{heading:"1. نظام قيادة الحوادث (ICS)",body:"معيار موحَّد لجميع الجهات:",points:["دورتا ICS-100 وICS-200 ضروريتان للموظفين الرئيسيين.","قائد الحادث (IC): واحد فقط، ويتحمل المسؤولية العامة عن الحادث.","خمسة أقسام: القيادة (Command)، والعمليات (Operations)، والتخطيط (Planning)، والدعم اللوجستي (Logistics)، والمالية والإدارة (Finance/Admin).","نطاق الإشراف (Span of Control): 3-7 أشخاص لكل مشرف (والأمثل 5).","يحصل كل حادث على اسم خاص (التاريخ + المكان + النوع).","اللغة البسيطة (Plain Language): لا تستخدم الرموز والاختصارات الخاصة.","خطة عمل الحادث (IAP) لكل فترة عمل (Operational Period)، وتكون عادةً 12 أو 24 ساعة.","إذا كانت عدة جهات مسؤولة: القيادة الموحَّدة (Unified Command) — يضع قادة الجهات معًا خطة واحدة."]},{heading:"2. الاتصال بالرقم 115 — ماذا تقول",body:"حافظ على هدوئك، وتحدّث بوضوح، واذكر هذه الأمور بهذا الترتيب:",points:["1. المكان الدقيق أولًا: المبنى واسم الدائرة، والشارع، ومَعلم قريب، والطابق.","2. ماذا حدث: حريق، انفجار، حادث، تسمم.","3. كم شخصًا أُصيب أو حوصر.","4. أيّ خطر: انتشار النار، الغاز، الكهرباء، المواد الكيميائية.","5. اسمك ورقم هاتفك.","6. أجب عن الأسئلة، واتّبع التعليمات، ولا تُنهِ المكالمة حتى يطلبوا منك ذلك."]},{heading:"3. الاستجابة متعددة الجهات (Multi-Agency Response)",body:"عند وصول عدة جهات:",points:["الدفاع المدني (115): إطفاء الحرائق، والإنقاذ، والمواد الخطرة (HazMat).","الإسعاف (122): العلاج الطبي والنقل.","الشرطة (104): تطويق محيط الموقع وتنظيم حركة المرور.","دائرة الكهرباء: قطع التيار الكهربائي.","دائرتا الماء والغاز: قطع الماء والغاز في حال وجود تسرّب.","وزارة الصحة: تجهيز المستشفيات.","هيئة البيئة: انسكاب المواد الكيميائية.","مركز عمليات الطوارئ (EOC — Emergency Operations Center) للحوادث الكبرى."]},{heading:"4. دور الدائرة أثناء الطوارئ",body:"ما يجب عليك فعله حتى يصل الدفاع المدني (115):",points:["1. اتصل بالرقم 115 (وبالرقم 122 إذا وُجد مصابون) واذكر المكان أولًا.","2. فعِّل الإنذار الداخلي (جرس الحريق أو مكبر الصوت).","3. الموظفون في نقطة التجمع — عدّ الأشخاص (Accountability).","4. جهّز مخطط المبنى: المخاطر وصمامات ومفاتيح الكهرباء والغاز والماء.","5. ضابط الارتباط (Liaison Officer): شخص واحد فقط يتواصل مع الدفاع المدني 115.","6. جهّز صحائف بيانات السلامة (SDS) وقوائم الاتصال.","7. تنظيم حركة المرور: أبقِ الطريق مفتوحًا لمركبات الطوارئ.","8. مسؤول الإعلام العام (PIO): إعلام المواطنين ووسائل الإعلام بصورة منظمة.","9. التوثيق: الصور ومقاطع الفيديو وأقوال الشهود.","10. تسليم القيادة: عند وصول الدفاع المدني (115)، تُسلَّم القيادة إلى قائد فريق 115."]},{heading:"5. فريق الاستجابة للطوارئ في الدائرة (ERT)",body:"التشكيلة المقترحة:",points:["قائد الحادث (IC): المدير أو معاونه.","منسق الإنذار: زر إنذار الحريق والاتصالات.","مسؤولو الطوابق (Floor Wardens): اثنان في كل طابق، لمسارات الإخلاء.","فريق الإسعافات الأولية: 2-3 موظفين مدرَّبين على الإنعاش القلبي الرئوي (CPR) واستخدام جهاز إزالة الرجفان الخارجي الآلي (AED).","فريق البحث: تفتيش الغرف والتأكد من إخلاء المبنى.","فريق مطفآت الحريق: موظفون مدرَّبون على إطفاء الحرائق الصغيرة في مرحلتها الأولى.","الاتصالات: التواصل الهاتفي مع الدفاع المدني (115) والتنسيق الداخلي.","التدريب: تدريب أولي وتحديث سنوي."]},{heading:"6. التمارين والاختبار (Drills + Tabletop Exercises)",body:"أنواع التمارين (FEMA HSEEP):",points:["تمرين الإخلاء (Drill): وفقًا لهذا البرنامج، مرة واحدة كل 3 أشهر.","التمرين المكتبي (Tabletop Exercise): يناقش المديرون والمسؤولون سيناريو حول الطاولة.","التمرين الوظيفي (Functional Exercise): تُختبر الفرق والمهام الرئيسية فقط (الاتصال، والقيادة).","التمرين الشامل (Full-Scale): المبنى بأكمله والجهات الخارجية، مرة واحدة في السنة على الأقل.","اكتب تقرير ما بعد التمرين (After-Action Report) في أسرع وقت.","الهدف: تحديد ما نجح، وما كان ناقصًا، وما يجب تغييره.","التحسين المستمر: أدرِج نتائج AAR في إجراءات العمل القياسية (SOP)."]},{heading:"7. خطة الاتصال (Communication Plan)",body:"من دون اتصال، لا يسير أي عمل على نحو صحيح:",points:["الأساسية: هواتف الدائرة ونظام مكبرات الصوت (PA).","الثانوية: الهواتف المحمولة وأجهزة اللاسلكي ثنائية الاتجاه.","الثالثة: إرسال أشخاص سيرًا على الأقدام (Runners).","البديلة: الهاتف الفضائي للحوادث الكبرى.","الاختبار: أسبوعيًا للفرق الرئيسية.","قائمة الهواتف: جاهزة على مدار الساعة (24/7) ومحدَّثة.","للمواطنين: الخط الهاتفي، والموقع الإلكتروني، ووسائل التواصل الاجتماعي — عبر PIO فقط.","ملاحظة: في الحوادث الكبرى قد تزدحم شبكة الهاتف المحمول — والرسائل النصية SMS تصل عادةً بصورة أفضل."]},{heading:"8. التقييم بعد الحادث (After-Action Review)",body:"المراجعة بعد الحادث:",points:["التوصية: خلال 72 ساعة بعد كل حادث، والذاكرة لا تزال حاضرة.","مشاركة جميع الجهات: IC، والعمليات، والدعم اللوجستي، والجهات الخارجية.","4 أسئلة: ما الذي كان مخططًا له؟ ماذا حدث؟ لماذا وُجد الاختلاف؟ ما الذي سنغيّره في المرة القادمة؟","المؤشرات: زمن الاستجابة، وعدد المصابين، والخسائر المادية.","التوثيق: تقرير الدروس المستفادة (Lessons Learned).","التحديث: SOP، وخطة عمليات الطوارئ (EOP)، ومواد التدريب.","المتابعة: افحص التنفيذ بعد 30 و60 و90 يومًا.","المشاركة: شارك النتائج مع الجهات الأخرى."]}],media:[{kind:"video",src:"media/videos/gov_ics_demo.mp4",title:"ICS أثناء العمل (ICS in Action)",description:"ICS في كارثة حقيقية"},{kind:"image",src:"media/images/gov_salute_card.png",title:"بطاقة الاتصال بالرقم 115",description:"بطاقة تذكير: ماذا تقول عند الاتصال بالرقم 115"}],quiz:[{question:"في ICS، كم قائدًا للحادث (IC) يلزم؟",options:[{text:"3-5",correct:!1},{text:"واحد فقط",correct:!0},{text:"كل موظف",correct:!1},{text:"2-4",correct:!1}],explanation:"في ICS يوجد قائد واحد للحادث. وإذا كانت عدة جهات مسؤولة، تعمل القيادة الموحَّدة (Unified Command) وفق خطة مشتركة واحدة."},{question:"عند الاتصال بالرقم 115، ماذا تذكر أولًا؟",options:[{text:"اسمك الكامل ومسمّاك الوظيفي واسم القسم الذي تعمل فيه",correct:!1},{text:"المكان الدقيق: المبنى، والشارع، ومَعلم قريب، والطابق",correct:!0},{text:"متى بدأ الحادث",correct:!1},{text:"ما المعدات المتوفرة لديك: المطافئ وخراطيم الحريق وحقائب الإسعافات الأولية",correct:!1}],explanation:"اذكر المكان الدقيق أولًا، ثم ما حدث، وعدد المصابين أو المحاصَرين، وأيّ خطر، واسمك ورقم هاتفك."},{question:"عند وصول الدفاع المدني (115)، إلى من تنتقل القيادة؟",options:[{text:"يستمر فريق ERT",correct:!1},{text:"قائد فريق 115",correct:!0},{text:"ضابط الارتباط (Liaison)",correct:!1},{text:"الشرطة",correct:!1}],explanation:"تسليم القيادة: عند وصول الدفاع المدني (115)، تُسلَّم القيادة إلى قائد فريق 115 ويساعده فريق ERT."},{question:"ما التمرين المكتبي (Tabletop Exercise)؟",options:[{text:"تمرين إخلاء المبنى بأكمله بمشاركة جميع العاملين",correct:!1},{text:"مناقشة سيناريو حول الطاولة مع المسؤولين",correct:!0},{text:"اختبار صفارة الإنذار",correct:!1},{text:"التدريب على استخدام مطفآت الحريق",correct:!1}],explanation:"التمرين المكتبي مناقشة لسيناريو دون تحريك الأشخاص أو المعدات، بهدف اختبار الخطط والمهام (FEMA HSEEP)."},{question:"خلال كم ساعة يُوصى بإجراء التقييم بعد الحادث (AAR)؟",options:[{text:"24",correct:!1},{text:"48",correct:!1},{text:"72",correct:!0},{text:"168",correct:!1}],explanation:"خلال 72 ساعة — والذاكرة لا تزال حاضرة وكاملة."},{question:"ما نطاق الإشراف (Span of Control) في ICS؟",options:[{text:"شخصان (2)",correct:!1},{text:"3-7 أشخاص",correct:!0},{text:"10+ أشخاص",correct:!1},{text:"بلا حدود",correct:!1}],explanation:"وفقًا لـNIMS: 3-7 أشخاص لكل مشرف، والأمثل 5."},{question:"يصل قائد فريق 115 ويسأل عن المسؤول. فيبدأ المدير ورئيس الأمن ومسؤولا طابقين بالكلام في وقت واحد. ماذا يجب أن يحدث؟",options:[{text:"يعطي كلٌّ منهم القائد تقريره الخاص، حتى لا يُنسى أي شيء",correct:!1},{text:"يُطلع رئيس الأمن القائد، لأنه يعرف المبنى أفضل من الجميع",correct:!1},{text:"يحتفظ المدير بالقيادة ويخبر فرق 115 أين تذهب داخل المبنى",correct:!1},{text:"يُطلع ضابط الارتباط المسمّى القائد، وتنتقل القيادة إلى قائد فريق 115",correct:!0}],explanation:"صوت واحد يتحدّث باسم الدائرة: يقدّم ضابط الارتباط المسمّى إحاطة قصيرة (العدّ، والمفقودون، والمخاطر، ومفاتيح القطع)، وتُسلَّم القيادة لقائد فريق 115. أما التقارير المتعدّدة في وقت واحد فتسبّب الارتباك."}],steps:[{title:"اتصل بالرقم 115، والمكان أولًا",detail:"اذكر المكان بدقة أولًا (المبنى، والدائرة، والشارع، ومَعلم قريب، والطابق)، ثم ما حدث، وعدد المصابين أو المحاصرين، وأي مخاطر. واتصل بالرقم 122 أيضًا إذا وُجد مصابون. ولا تُنهِ المكالمة حتى يُطلب منك ذلك.",critical:!0},{title:"أطلق الإنذار وأخلِ المبنى وفق الخطة",detail:"فعِّل الإنذار الداخلي أو نظام مكبرات الصوت؛ ويقود مسؤولو الطوابق الموظفين والزوار إلى الخارج عبر المسارات المحدّدة حتى نقطة التجمع.",critical:!0},{title:"عُدّ الجميع في نقطة التجمع",detail:"يعدّ كل مسؤول طابق أفراده ويبلّغ فورًا: الجميع حاضرون، أو أسماء أي مفقودين وآخر مكان شوهدوا فيه.",critical:!0},{title:"استعدّ لفريق 115",detail:"يُجهّز ضابط الارتباط مخطط الطوابق، وأماكن صمامات ومفاتيح قطع الكهرباء والغاز والماء، ومخاطر المبنى، وصحائف بيانات السلامة (SDS)، وقائمة الاتصال."},{title:"أبقِ طريق الدخول مفتوحًا",detail:"يُبقي الموظفون طريق الوصول ومدخل المبنى خاليين لسيارات الإطفاء والإسعاف، ويُبعدون المتجمهرين."},{title:"سلِّم القيادة وقدّم الدعم",detail:"عند وصول فريق 115، يُطلع ضابط الارتباط قائد الفريق وتنتقل إليه القيادة؛ ثم تدعم الدائرة الفريق وتتّبع تعليماته، وتُجري لاحقًا مراجعة ما بعد الحدث."}],warnings:["لا تُعِد الموظفين أبدًا إلى داخل المبنى للبحث عن أحد: أعطِ الأسماء وآخر الأماكن المعروفة لفريق 115.","لا تسمح لعدة أشخاص بإعطاء الرقم 115 معلومات مختلفة: ضابط ارتباط واحد يتحدّث باسم الدائرة.","لا تنشر صور الحادث أو تفاصيله على مواقع التواصل الاجتماعي: مسؤول الإعلام العام وحده يُعلم الجمهور بصورة منظمة."],tips:["احتفظ بملف جاهز لضابط الارتباط: مخططات الطوابق، وأماكن مفاتيح القطع، وقائمة المخاطر، وصحائف SDS، وقائمة الموظفين، وأرقام الاتصال.","تدرّبوا على الاتصال بالرقم 115 وعلى تسليم القيادة لقائد فريق 115 في تمارين المحاكاة المكتبية (Tabletop).","ضع علامة واضحة لنقطة التجمع، وامنع وقوف السيارات على الطريق الذي ستستخدمه مركبات الطوارئ.","خطِّط لطريقة احتياطية لنقل الرسائل عند تعطّل الهواتف، مثل أجهزة الاتصال اللاسلكي أو المراسلين سيرًا على الأقدام."],activity:{prompt:"يرنّ إنذار الحريق في مديريتك وأنت ضابط الارتباط المسمّى. الموظفون في نقطة التجمع، وأولى مركبات الدفاع المدني تتوقّف عند البوابة. ماذا تفعل؟",options:[{text:"أبقى في نقطة التجمع وأنتظر حتى يأتي فريق 115 ويجدني",correct:!1,feedback:"خطأ: يحتاج الفريق إلى المعلومات فورًا؛ ويذهب ضابط الارتباط لاستقباله في المكان المتّفق عليه."},{text:"أطلب من قائد فريق 115 أن ينتظر حتى يصل المدير ويُطلعه",correct:!1,feedback:"خطأ: أي تأخير يُضيع الوقت؛ وضابط الارتباط المسمّى يُطلع القائد فورًا."},{text:"أستقبل قائد فريق 115 في المكان المتّفق عليه ومعي مخطط الطوابق ونتيجة العدّ والمفقودون والمخاطر وأماكن مفاتيح القطع",correct:!0,feedback:"صحيح: هذا دور ضابط الارتباط. والإحاطة القصيرة الواضحة تساعد الفريق على تخطيط البحث والبقاء آمنًا."},{text:"أقود رجال الإطفاء بنفسي إلى داخل المبنى لأدلّهم على الطريق",correct:!1,feedback:"خطأ: ليس لديك معدات حماية ولا تدريب لدخول مبنى يحترق؛ أعطهم المخطط والمعلومات بدلًا من ذلك."}]},caseStudy:[{prompt:"أنت المدير، وحتى يصل فريق 115 فأنت قائد الحادث. سُمع صوت انفجار وخرج دخان من غرفة المولّد في الطابق السفلي، وأُصيب عدد من الموظفين في الطابق الأرضي. ماذا تفعل أولًا؟",options:[{text:"أتأكّد من الاتصال بالرقمين 115 و122 مع ذكر المكان أولًا، وأُطلق الإنذار، ويُخلي مسؤولو الطوابق الجميع وفق الخطة",correct:!0,feedback:"صحيح: طلب المساعدة وتنبيه الجميع وإخراج الناس تأتي أولًا. ويُبعَد المصابون عن الخطر ويُبلَّغ الرقم 122 بعددهم."},{text:"أنزل بنفسي إلى الطابق السفلي لأرى ما الذي انفجر",correct:!1,feedback:"خطأ: قد يكون في الطابق السفلي نار أو دخان أو وقود أو انفجار آخر؛ وأنت مطلوب لتقود من مكان آمن."},{text:"أتصل بمكتب الإعلام أولًا لكي يسمع الناس الخبر مني",correct:!1,feedback:"خطأ: المعلومات للجمهور تأتي لاحقًا وفقط عبر مسؤول الإعلام العام؛ والأرواح أولًا."}]},{prompt:"في نقطة التجمع، يبلّغ أحد مسؤولي الطوابق أن موظفَين من الأرشيف مفقودان. وقد وصل قائد فريق 115 للتوّ. ماذا الآن؟",options:[{text:"أرسل متطوعَين بسرعة إلى داخل المبنى للبحث في الأرشيف",correct:!1,feedback:"خطأ: غير المدرَّبين الذين يعودون إلى الدخان قد يصبحون ضحايا إضافيين؛ والبحث مهمة فريق 115."},{text:"أعطي قائد فريق 115 الاسمين وآخر مكان شوهدا فيه ومخاطر الطابق السفلي كالوقود والمولّد، وأسلّمه القيادة",correct:!0,feedback:"صحيح: المعلومات الدقيقة عن المفقودين والمخاطر تتيح لفريق 115 البحث بسرعة وأمان. والآن تنتقل القيادة إلى قائد فريق 115."},{text:"أنتظر لأرى هل يخرج الموظفان وحدهما قبل أن أقول شيئًا",correct:!1,feedback:"خطأ: الانتظار يُضيع وقتًا قد لا يملكه المفقودون؛ أبلغ فورًا."}]}],realCase:"سيناريو توضيحي: بعد عطل كهربائي، ملأ الدخان ممرًّا في مديرية حكومية. أُطلق الإنذار، وقاد مسؤولو الطوابق الموظفين إلى نقطة التجمع، وأعطى الشخص المكلَّف بالاتصال الرقم 115 المكان أولًا. وفي أثناء العدّ تبيّن أن موظفًا مفقود. لم يعد أحد إلى الداخل: استقبل ضابط الارتباط قائد فريق 115 عند البوابة ومعه مخطط الطوابق وأماكن مفاتيح القطع واسم المفقود ومكتبه. فوجده الفريق في دورة مياه في طابق علوي لم يسمع فيها الإنذار، وأخرجه. وفي مراجعة ما بعد الحدث أضافت الدائرة إنذارات ضوئية وتفقّد دورات المياه إلى مسار مسؤولي الطوابق. الدرس: عُدّ الجميع، ولا تُعِد الموظفين إلى الداخل، وأعطِ فريق 115 معلومات دقيقة."},{id:21,code:"GOV-121",icon:"School",accent:"#0e7490",title:"كوادر المدرسة: إدارة الطوارئ وتعليم دروس السلامة",subtitle:"خطة الطوارئ المدرسية، والتمارين، والتلاميذ الذين يحتاجون إلى مساعدة، وتسليم الأطفال لأسرهم، والتعليم بحسب العمر",summary:"ما يفعله المديرون والمعلّمون وسائر العاملين في المدرسة قبل الطوارئ وأثناءها وبعدها، وكيف يستخدمون دروس هذا التطبيق مع كل فئة عمرية.",blocks:[{body:"تضمّ المدرسة أطفالًا كثيرين يعتمدون على الكبار في سلامتهم. وتحتاج كل مدرسة إلى خطة طوارئ مكتوبة يعرفها جميع العاملين، وإلى تمارين تختبر الخطة، وإلى دروس تعلّم الأطفال ما يفعلونه. هذا الدرس موجّه إلى المديرين والمعلّمين وسائر العاملين في المدرسة. اتبع متطلبات الدفاع المدني ووزارة التربية. أما القواعد المحلية، مثل عدد مرات تنفيذ التمارين، فتحددها وزارة التربية ولم تُؤكَّد بعدُ، لذلك لا يذكر هذا الدرس رقمًا لها."},{heading:"1. خطة الطوارئ المدرسية",body:"اكتب الخطة مع العاملين، واحتفظ بنسخ منها في الإدارة ولدى المسؤول عن كل طابق، وحدّثها كلما تغيّر العاملون أو الغرف أو احتياجات التلاميذ. وتجيب الخطة عن هذه الأسئلة:",points:["من يقود: يتولّى المدير، أو نائب محدَّد عند غياب المدير، القيادة حتى وصول الدفاع المدني، ثم يسلّمها إلى قائد فريق الدفاع المدني.","من يتصل: شخص محدَّد، ومعه بديل، يتصل بالرقم 115 في حالات الحريق أو الانهيار أو الغاز أو الفيضان، وبالرقم 122 للمصابين والمرضى، ويذكر موقع المدرسة أولًا.","الإنذار: إشارة واحدة يعرف كل صف أن معناها «اخرجوا من المبنى الآن»، وأسماء العاملين الذين يطلقونها.","المسارات: مسار رئيسي ومسار بديل للخروج من كل غرفة، يبقيان مفتوحين دائمًا؛ وتُفتح أبواب الخروج من الداخل دون مفتاح.","نقاط التجمع: نقطة رئيسية ونقطة بديلة في الخارج، بعيدًا عن المبنى والزجاج وأسلاك الكهرباء والطريق الذي ستسلكه سيارات الدفاع المدني والإسعاف.","الأدوار: يقود معلّم كل صف صفّه؛ ويتفقّد عاملون محدَّدون دورات المياه والمختبرات والمكتبة والساحة؛ ويساعد عاملون محدَّدون التلاميذ الذين يحتاجون إلى مساعدة.","قطع الغاز والكهرباء: أشخاص كبار محدَّدون يعرفون مواقع قواطع الغاز والكهرباء. ولا يُغلق الغاز إلا إذا كان الصمام قريبًا ويمكن الوصول إليه دون دخول المنطقة التي تجمّع فيها الغاز؛ وإلا يخرج الجميع ويُتصل بالرقم 115 من الخارج."]},{heading:"2. عدّ التلاميذ وسجلّ التمارين",body:"العدّ السريع والكامل هو الطريقة لمعرفة ما إذا كان أحد لا يزال داخل المبنى:",points:["يأخذ كل معلّم قائمة الصف معه عند الخروج، ويعدّ التلاميذ عند نقطة التجمع.","عُدّ أيضًا الزوار وعمال المطبخ والتنظيف وسائر العاملين.","أبلغ المسؤول فورًا: الجميع حاضرون، أو اسم أي غائب والمكان الذي شوهد فيه آخر مرة.","لا ترسل أبدًا تلميذًا أو معلّمًا إلى داخل المبنى للبحث عن أحد: أبلغ فريق الدفاع المدني، فهو الذي يبحث.","لا يعود أحد إلى الداخل حتى يقول الدفاع المدني أو المسؤول إن المكان آمن.","بعد كل تمرين، سجّل في سجلّ التمارين: التاريخ والوقت، ونوع التمرين، والمدة التي استغرقها الخروج وإتمام العدّ، ومن كان غائبًا أو متأخرًا، والمشكلات التي ظهرت، ومن سيعالجها ومتى.","تدرّبوا على المسار البديل أيضًا: يجب أن تبيّن الخطة كيفية الخروج إذا تعذّر استخدام المسار الرئيسي. أما عدد مرات التمارين فتحدده وزارة التربية."]},{heading:"3. التلاميذ الذين يحتاجون إلى مساعدة للخروج",body:"ضع خطة لكل واحد من هؤلاء التلاميذ قبل وقوع الطوارئ، بالتعاون مع التلميذ وأسرته:",points:["خطة إخلاء شخصية لكل تلميذ لا يستطيع الخروج وحده أو بسرعة: مثل مستخدم الكرسي المتحرك، أو التلميذ الكفيف أو الأصمّ، أو التلميذ المصاب بحالة صحية أو صعوبة في التعلّم.","مساعدون محدَّدون (الرفيق): شخص بالغ وبديل له لكل واحد من هؤلاء التلاميذ، في كل حصة وفي الاستراحة؛ ويمكن لزميل في الصف أن يمشي معه، لكن الأطفال لا يحملون أحدًا أبدًا.","لا يحمل التلميذَ على الدرج إلا عاملون مدرَّبون؛ ولا يُستخدم المصعد أثناء الحريق إلا إذا كان مصمَّمًا ومعلَّمًا للإخلاء.","ينتظر التلميذ الذي لا يستطيع استخدام الدرج مع شخص بالغ في المكان الآمن الذي تحدده الخطة، ويُبلغ البالغُ الدفاعَ المدني (115) بمكانهما.","التلاميذ الذين لا يسمعون الإنذار: ضوء وامض أو شخص محدَّد يخبرهم؛ والبطاقة المكتوبة أفضل من الصراخ.","خطِّط لكيفية خروج وسائل التلميذ الخاصة معه، مثل الكرسي المتحرك أو السماعة الطبية أو البخّاخ (inhaler) أو حاقن الأدرينالين الذاتي الخاص به.","تدرّبوا على الخطة في التمارين؛ فالتلميذ وأسرته هم في الغالب الأعرف بالمساعدة التي يحتاج إليها."]},{heading:"4. المختبرات والمدافئ والمطبخ",body:"يمكن منع معظم حرائق المدارس بقواعد بسيطة:",points:["المختبر: لا يعمل التلاميذ أبدًا دون حضور المعلّم؛ ويعرف المعلّم أماكن بطانية الحريق والمطافئ ومحطة غسل العيون (Eyewash) وحقيبة الإسعافات الأولية وطريقة استخدامها.","لا تترك موقد الغاز (burner) المشتعل دون مراقبة أبدًا؛ وأطفئ أجهزة التسخين وأغلق صمامات الغاز عند عدم استخدامها؛ ولا تُبقِ مذيبات قابلة للاشتعال بالقرب منه عند إشعال اللهب.","احتفظ بجرد للمواد الكيميائية، واحفظها في مكان مقفل، وخزّن السوائل القابلة للاشتعال في خزانة معتمدة مخصّصة لها.","مدافئ الصفوف: سليمة، على أرض ثابتة، على بُعد متر واحد (3 أقدام) على الأقل من الستائر والأوراق والحقائب، بعيدة عن الأبواب والممرات، لا تُترك مشتعلة في غرفة فارغة أبدًا، وتُطفأ في نهاية اليوم.","مدافئ الوقود: لا تستعمل إلا الوقود الذي تحدّده الشركة المصنّعة، وتُملأ في الخارج بعد أن تبرد؛ والمدفأة التي لا مدخنة لها تحتاج إلى هواء نقي في الغرفة، وإذا شعر أحد بصداع أو دوار أو نعاس فأخرج الجميع إلى الهواء الطلق واتصل بالرقم 122.","مطبخ المدرسة: لا تترك الطبخ دون مراقبة أبدًا؛ تُغطّى نار المقلاة بغطاء أو ببطانية الحريق ويُطفأ مصدر الحرارة إن كان ذلك آمنًا، ولا ماء أبدًا."]},{heading:"5. تسليم التلاميذ إلى أسرهم",body:"عندما لا يستطيع التلاميذ العودة إلى الصفوف بعد الإخلاء، سلِّمهم إلى أسرهم بطريقة منظّمة:",points:["أخبر الأسر مسبقًا بكيفية تسليم الأطفال: أين يذهبون، وماذا يحضرون معهم، وأن الأطفال لا يُسلَّمون إلا في ذلك المكان.","لا تسلّم الطفل إلا إلى أحد والديه أو إلى شخص بالغ آخر مذكور اسمه في سجلات المدرسة، بعد التحقق من هويته، وسجّل من أخذ كل طفل ومتى.","افصل مكان استقبال الأهالي عن مكان انتظار التلاميذ، وأبعد كليهما عن الطريق الذي تستخدمه مركبات الطوارئ.","تأكّد من ألّا يغادر أي تلميذ وحده، وأطلِع الأسر بانتظام عبر القناة الرسمية للمدرسة، ولا تشارك أسماء التلاميذ أو صورهم مع وسائل الإعلام أو على الإنترنت.","احتفظ بقائمة التلاميذ المصابين والمستشفى الذي نُقلوا إليه، وأبلغ أسرهم فورًا.","حافظ على هدوئك مع الأطفال القلقين، وابقَ معهم، واشرح لهم ما حدث بكلمات بسيطة وصادقة."]},{heading:"6. تعليم دروس السلامة في هذا التطبيق",body:"يضم التطبيق دروسًا لكل فئة عمرية. علّمها في الصف وتدرّب عليها في التمارين:",points:["رياض الأطفال: قصص قصيرة وصور. ابتعد عن النار والكبريت والولاعات والمدافئ؛ وعندما يرنّ الإنذار ابقَ مع المعلّمة واخرج؛ وأخبر شخصًا كبيرًا.","الابتدائية: خطة الهروب، والدخان والبقاء منخفضًا، والرقم 115، وتمرين المدرسة. يخبر الأطفال شخصًا كبيرًا أولًا، وإن لم يكن معهم أحد من الكبار اتصلوا بالرقم 115 بأنفسهم من مكان آمن.","المتوسطة والإعدادية: تخطيط الإخلاء، والإسعافات الأولية، والقيادة. يمكن للمراهقين مساعدة المعلّم في العدّ وإرشاد التلاميذ الأصغر، لكنهم لا يكافحون النار أبدًا ولا يعودون إلى الداخل أبدًا.","لا يستخدم الأطفال مطافئ الحريق أبدًا، ولا يكافحون النار، ولا يلمسون أسلاك الكهرباء أو صمامات الغاز، ولا يقتربون من الأجسام التي قد تنفجر: بل يخرجون، ويخبرون شخصًا كبيرًا، ولا يتصلون بالرقم 115 إلا كما تعلّمهم الدروس.","علّم دون تخويف: استخدم كلمات هادئة، ودع الأطفال يسألون، وكرّر التمرين حتى يصبح أمرًا معتادًا.","استخدم لعبة كل درس واختباره لمعرفة ما تعلّمه الأطفال، وشارك الرسائل الأساسية مع الأهالي."]}],media:[{kind:"image",src:"media/images/w8_school_emergency_plan.webp",title:"المعلّمة تعدّ التلاميذ عند نقطة التجمع",description:"يقف التلاميذ في صفوف فصولهم عند نقطة التجمع، بينما تراجع المعلّمة قائمة الصف ويساعد أحد العاملين تلميذًا على كرسي متحرك."}],quiz:[{question:"عند نقطة التجمع، تكتشف المعلّمة أن أحد التلاميذ غائب. ماذا يجب أن تفعل؟",options:[{text:"تبلغ المسؤول فورًا باسم التلميذ والمكان الذي شوهد فيه آخر مرة",correct:!0},{text:"تعود فورًا إلى المبنى وحدها وتفتّش كل الصفوف ودورات المياه بنفسها",correct:!1},{text:"ترسل تلميذين أكبر سنًّا إلى الداخل للبحث عن التلميذ الغائب بسرعة",correct:!1},{text:"تنتظر حتى نهاية اليوم الدراسي ثم تخبر المدير بالأمر",correct:!1}],explanation:"لا ترسل أحدًا إلى الداخل أبدًا. يبلّغ المسؤول فريق الدفاع المدني، وهو الذي يفتّش المبنى."},{question:"ماذا يجب أن يُسجَّل في سجلّ التمارين بعد كل تمرين؟",options:[{text:"التاريخ والوقت، ونوع التمرين، ومدة الخروج والعدّ، والمشكلات ومن يعالجها",correct:!0},{text:"أسماء المعلّمين المناوبين في جميع طوابق المبنى في ذلك اليوم فقط",correct:!1},{text:"لا شيء، لأن التمرين للتعلّم فقط ولا يحتاج إلى أي سجلّ مكتوب",correct:!1},{text:"فقط ما إذا كان جرس الإنذار مسموعًا بوضوح في الممر الرئيسي والساحة ذلك اليوم",correct:!1}],explanation:"يبيّن السجلّ ما نجح وما يجب إصلاحه: التاريخ والوقت، ونوع التمرين، ومدة الخروج والعدّ، ومن كان غائبًا أو متأخرًا، والمشكلات التي ظهرت، ومن سيعالجها ومتى."},{question:"أثناء تسليم الأطفال، يطلب شخص بالغ لا تعرفه أن يأخذ تلميذًا إلى البيت. ماذا تفعل؟",options:[{text:"أراجع سجلات المدرسة ولا أسلّم الطفل إلا لشخص بالغ مذكور اسمه فيها",correct:!0},{text:"أترك الطفل يذهب إذا قال الطفل إنه يعرف هذا الشخص منذ زمن وجيدًا",correct:!1},{text:"أترك الطفل يذهب إذا عرف الشخص اسم الطفل الكامل وصفّه بدقة",correct:!1},{text:"أطلب من الطفل أن يمشي إلى البيت وحده ليخفّ الازدحام في المكان",correct:!1}],explanation:"لا تسلّم الطفل إلا إلى أحد والديه أو إلى شخص بالغ آخر مذكور اسمه في سجلات المدرسة، بعد التحقق من هويته، وسجّل من أخذ الطفل ومتى."},{question:"تلميذ يستخدم كرسيًّا متحركًا ودروسه في الطابق الثاني. ماذا يجب أن تتضمن خطة المدرسة؟",options:[{text:"خطة شخصية بمساعدين مدرَّبين ومكان آمن للانتظار، يُتدرَّب عليها في التمارين",correct:!0},{text:"إنزال التلميذ بالمصعد، لأنه أسرع طريق للخروج من المبنى أثناء الحريق",correct:!1},{text:"ترك التلميذ في الصف والباب مفتوح حتى يُطفأ الحريق تمامًا ويعود الهدوء",correct:!1},{text:"الطلب من زميلين في الصف أن يحملاه على الدرج دون أي تدريب سابق",correct:!1}],explanation:"كل تلميذ لا يستطيع الخروج وحده يحتاج إلى خطة شخصية: بالغون محدَّدون وبديل لهم، ومكان آمن للانتظار إذا تعذّر استخدام الدرج، وإبلاغ الدفاع المدني (115) بمكانه، والتدرّب على ذلك في التمارين. لا يُستخدم المصعد أثناء الحريق إلا إذا كان مصمَّمًا للإخلاء، ولا يحمل الأطفال أحدًا أبدًا."},{question:"ماذا تعلّم دروس المرحلة الابتدائية الأطفال أن يفعلوا إذا رأوا حريقًا؟",options:[{text:"أن يخرجوا ويخبروا كبيرًا، ولا يتصلوا بالرقم 115 بأنفسهم إلا إن غاب الكبار",correct:!0},{text:"أن يستخدموا أقرب مطفأة، لأن إطفاء الحريق الصغير سهل على أي شخص",correct:!1},{text:"أن يصبّوا الماء على النار، ثم يخبروا المعلّم لاحقًا إذا لم تنطفئ",correct:!1},{text:"أن يختبئوا في زاوية هادئة من الصف حتى يأتي المعلّم ويجدهم",correct:!1}],explanation:"لا يكافح الأطفال النار ولا يستخدمون المطافئ أبدًا. بل يخرجون، ويخبرون شخصًا كبيرًا، ولا يتصلون بالرقم 115 من مكان آمن إلا إذا لم يكن معهم أحد من الكبار."},{question:"يبدأ حريق صغير في مقلاة على الموقد في مطبخ المدرسة. الطاهي مدرَّب وقد أُطلق الإنذار. ما التصرّف الصحيح؟",options:[{text:"يصبّ إبريق ماء على المقلاة فورًا لكي يبرد الزيت الساخن بسرعة",correct:!1},{text:"يحمل المقلاة المشتعلة إلى الساحة، بعيدًا عن التلاميذ والعاملين",correct:!1},{text:"يطفئ مصدر الحرارة إن كان ذلك آمنًا ويغطي المقلاة بغطاء أو ببطانية حريق",correct:!0},{text:"يطلب من تلميذ أكبر سنًّا أن يُحضر المطفأة من الممرّ بأسرع ما يمكن",correct:!1}],explanation:"يُغطّى حريق المقلاة الصغير بغطاء أو ببطانية حريق، وتُطفأ الحرارة إن كان ذلك آمنًا. فالماء على الزيت المشتعل يقذف الزيت، وحمل المقلاة يسكبه، والتلاميذ لا يكافحون الحرائق ولا يُحضرون المطافئ لها أبدًا."}],steps:[{title:"أخرِج صفّك",detail:"عندما يرنّ الإنذار، خذ قائمة الصف، وأخرج التلاميذ عبر المسار المحدّد في الخطة (أو المسار البديل إذا كان الرئيسي مسدودًا)، وأغلق الباب خلفك، ولا تسمح لأحد بالعودة لأخذ الحقائب.",critical:!0},{title:"تفقّد وساعد في طريق الخروج",detail:"يتفقّد العاملون المحدَّدون دورات المياه والمختبرات والمكتبة والساحة في طريق خروجهم، فقط إذا كان ذلك آمنًا؛ ويُخرج المساعدون المحدَّدون التلاميذ الذين يحتاجون إلى مساعدة كما تنصّ خططهم الشخصية.",critical:!0},{title:"عُدّ في نقطة التجمع",detail:"عُدّ تلاميذك بمطابقتهم مع قائمة الصف، وأبلغ المسؤول فورًا: الجميع حاضرون، أو اسم أي غائب والمكان الذي شوهد فيه آخر مرة.",critical:!0},{title:"لا يعود أحد إلى الداخل",detail:"لا ترسل أبدًا تلميذًا أو معلّمًا إلى الداخل للبحث عن أحد: يُبلغ المسؤولُ فريقَ الدفاع المدني، فهو الذي يبحث. ولا يدخل أحد حتى يقول الدفاع المدني أو المسؤول إن المكان آمن.",critical:!0},{title:"سلِّم التلاميذ إلى أسرهم بأمان",detail:"إذا لم يستطع التلاميذ العودة إلى الصفوف، فلا تسلّم أي طفل إلا إلى أحد والديه أو إلى شخص بالغ آخر مذكور اسمه في سجلات المدرسة، بعد التحقق من هويته، وسجّل من أخذ كل طفل ومتى."},{title:"سجِّل التمرين وعالج المشكلات",detail:"بعد كل تمرين أو حدث حقيقي، اكتب في سجلّ التمارين ما جرى، ومن غاب أو تأخّر، والمشكلات التي ظهرت، ومن سيعالجها وفي أي موعد. أما عدد مرات التمارين فتحدّده وزارة التربية."}],warnings:["لا ترسل أبدًا تلميذًا أو معلّمًا إلى داخل المبنى للبحث عن أحد: أبلغ فريق الدفاع المدني، فهو الذي يبحث.","لا يكافح التلاميذ الحرائق أبدًا، ولا يستخدمون المطافئ، ولا يلمسون صمامات الغاز أو أسلاك الكهرباء: إنهم يخرجون ويُخبرون شخصًا بالغًا.","لا تستخدم المصاعد أثناء الحريق إلا إذا كانت مصمَّمة ومعلَّمة للإخلاء، ولا يحمل الأطفال شخصًا آخر أبدًا."],tips:["أبقِ قائمة الصف والخطط الشخصية لإخلاء تلاميذك قرب باب الصف، جاهزة للأخذ بسرعة.","أجروا التمارين من غرف مختلفة، وفي وقت الاستراحة، ومع سدّ المسار الرئيسي، حتى يُتدرَّب على المسار البديل أيضًا.","أخبر الأسر مسبقًا بكيفية التسليم: أين يذهبون، وماذا يُحضرون، وأن الأطفال لا يُسلَّمون إلا هناك.","بعد التمرين، تحدّث بهدوء مع الأطفال ودعهم يسألون، حتى لا يخيفهم التمرين."],activity:{prompt:"في أثناء تمرين إخلاء، يقف أحد العاملين عند الدرج الرئيسي حاملًا لافتة: «هذا المسار مسدود.» صفّك في الطابق الثاني. ماذا تفعل؟",options:[{text:"أستخدم الدرج الرئيسي رغم ذلك، لأنه مجرد تمرين وهو أسرع",correct:!1,feedback:"خطأ: التمرين يختبر الخطة؛ وفي حريق حقيقي قد يمتلئ الدرج الرئيسي بالدخان، لذا يجب التدرّب على المسار البديل."},{text:"أقود الصف عبر المسار البديل في الخطة، وأعدّ التلاميذ في نقطة التجمع، وأبلّغ",correct:!0,feedback:"صحيح: في الخطة مسار بديل لهذه الحالة بالذات. والتدرّب عليه يبيّن هل ينجح وكم يستغرق من وقت."},{text:"أُبقي الصف في الغرفة حتى يُفتح الدرج الرئيسي من جديد",correct:!1,feedback:"خطأ: البقاء في الداخل ليس خطة الإخلاء من الحريق؛ والانتظار يُضيع الوقت الذي يحتاجه التلاميذ للخروج."},{text:"أطلب من التلاميذ أن يجدوا طريقهم إلى الأسفل بأي درج آخر",correct:!1,feedback:"خطأ: يجب أن يبقى التلاميذ مع معلّمهم لكي يُعدّ الصف ولا يضيع أحد."}]},caseStudy:[{prompt:"يرنّ إنذار الحريق في وقت الاستراحة. يخرج دخان من الممرّ القريب من مختبر العلوم. أنت المعلّم المناوب في الساحة؛ كثير من التلاميذ في الساحة وبعضهم في دورات المياه القريبة من الممرّ. ماذا تفعل أولًا؟",options:[{text:"أنقل التلاميذ في الساحة إلى نقطة التجمع بعيدًا عن المبنى، بينما يتفقّد العاملون المحدَّدون دورات المياه في طريق خروجهم إن كان ذلك آمنًا، وأتأكّد من الاتصال بالرقم 115",correct:!0,feedback:"صحيح: أبعِد التلاميذ عن المبنى أولًا. ولا يتفقّد دورات المياه إلا العاملون المحدَّدون وفقط إذا كان ذلك آمنًا؛ ويجب أن يتأكّد أحدٌ من الاتصال بالرقم 115."},{text:"أدخل بنفسي ممرّ المختبر لأرى ما الذي يحترق",correct:!1,feedback:"خطأ: التوجّه نحو الدخان يعرّضك للخطر ويترك تلاميذ الساحة بلا شخص بالغ."},{text:"أُبقي التلاميذ مجتمعين في الساحة بجانب المبنى ليتفرّجوا",correct:!1,feedback:"خطأ: قد يصل الدخان أو الزجاج المتساقط أو سيارات الإطفاء إلى الساحة المجاورة للمبنى؛ يذهب التلاميذ إلى نقطة التجمع."}]},{prompt:"في نقطة التجمع، ينقص أحدَ الصفوف تلميذٌ واحد. يقول زميل له إن التلميذ الغائب ذهب إلى دورة المياه القريبة من المختبر قبل الإنذار بقليل. ماذا الآن؟",options:[{text:"أرسل الزميل بسرعة ليُحضر التلميذ الغائب من دورة المياه",correct:!1,feedback:"خطأ: لا تُعِد تلميذًا إلى الداخل أبدًا؛ فقد يُحاصَر الزميل في الدخان أيضًا."},{text:"أبلغ المسؤول فورًا باسم التلميذ وبأنه شوهد آخر مرة عند دورة المياه القريبة من المختبر، لكي يُبلَّغ الدفاع المدني",correct:!0,feedback:"صحيح: الاسم الدقيق وآخر مكان شوهد فيه يتيحان لفريق الدفاع المدني البحث بسرعة. ولا يعود أحد من المدرسة إلى الداخل."},{text:"أعود بنفسي بسرعة إلى الداخل، لأنني أعرف المبنى جيدًا",correct:!1,feedback:"خطأ: قد تُحاصَر في الدخان؛ والبحث في مبنى يحترق هو عمل فريق الدفاع المدني."}]}],realCase:"سيناريو توضيحي: في تمرين إخلاء مخطَّط له في مدرسة، أظهر عدّ الصفوف عند نقطة التجمع غياب تلميذة من صف في الطابق العلوي. أبلغ المعلّم باسمها فورًا، فوجدها قائد التمرين، وهي صمّاء، ما تزال في الصف: لم تسمع الجرس، وكانت مساعِدتها المحدَّدة غائبة ذلك اليوم. وبعد التمرين حدّثت المدرسة خطتها الشخصية مع التلميذة وأسرتها: ضوء وامض في الصف، ومساعد بديل لكل حصة، وبطاقة مكتوب عليها «اخرجي الآن». وجرى التمرين التالي بسلاسة. الدرس: التمارين تكشف ثغرات الخطة قبل أن يكشفها حريق حقيقي."},{id:22,code:"GOV-122",icon:"Landmark",accent:"#7c3aed",title:"المؤسسات الحساسة: مراكز البيانات والأرشيفات والمتاحف والمصارف ومرافق الكهرباء والماء",subtitle:"أنظمة الإطفاء الثابتة، والسجلات والمقتنيات، واستمرارية العمل، والإخلاء المنضبط، والكهرباء والماء",summary:"تحتاج المباني التي تضمّ البيانات أو السجلات أو المقتنيات أو الأموال أو الخدمات الأساسية إلى حماية خاصة من الحريق وإلى خطة تضمن استمرار العمل. يشرح هذا الدرس ما يجب أن يعرفه العاملون: إنذارات الأنظمة الثابتة، وحماية السجلات والمقتنيات، واستمرارية العمل، والإخلاء المنضبط، والكهرباء والماء.",blocks:[{body:"في مركز بيانات أو أرشيف أو متحف أو مصرف أو منشأة للكهرباء أو الماء، قد يدمّر حريق أو فيضان ما لا يمكن تعويضه، ويوقف خدمات يعتمد عليها كثير من الناس. الحياة أولًا دائمًا: لا سجلّ ولا قطعة ولا مال ولا جهاز يساوي حياة إنسان. هذا الدرس على مستوى التوعية؛ فتصميم الأنظمة الثابتة وتركيبها واختبارها عمل المختصين المؤهَّلين، فاتبع متطلبات الدفاع المدني والجهة المانحة للترخيص. المراجع الدولية: NFPA 75 (معدات تقنية المعلومات)، وNFPA 76 (منشآت الاتصالات)، وNFPA 2001 (أنظمة العامل النظيف)، وNFPA 909 (المتاحف والمكتبات ودور العبادة)، وNFPA 914 (المباني التاريخية)، وNFPA 1660 وISO 22301 (الاستمرارية)."},{heading:"1. أنظمة الإطفاء الغازية الثابتة: ما يجب أن يعرفه كل موظف",body:"كثيرًا ما تُحمى غرف الخوادم والأرشيفات والخزائن الحصينة (vault) بنظام ثابت يملأ الغرفة كلها بغاز: العامل النظيف (Clean Agent) أو CO₂. يحمي الغاز محتويات الغرفة، لكن يجب أن يكون الناس قد خرجوا منها قبل إطلاقه:",points:["تعرّف إلى الإشارات: إنذار الحريق، وإنذار ما قبل التصريف (صوت مميّز أو ضوء وامض يعني أن الغاز على وشك أن يُطلق)، ولافتات التحذير على الباب.","عندما يدوّي إنذار ما قبل التصريف: أوقف العمل، واخرج من الغرفة فورًا من أقرب مخرج، وأغلق الباب، ونبّه الآخرين. زمن التأخير (Time Delay) موجود ليمنح الناس وقتًا للخروج، لا لإنهاء العمل.","لا تعد إلى الغرفة بعد التصريف حتى يقول المسؤول أو الدفاع المدني إنها آمنة: فقد يبقى فيها الغاز والدخان ونواتج الاحتراق.","أنظمة CO₂: تركيز الإطفاء قد يقتل الإنسان، لذلك تُستخدم عادةً في الغرف التي لا يعمل فيها أحد فقط، ويُقفَل تشغيلها (lock-out) عند وجود أشخاص في الداخل.","لا تسدّ أو تغطِّ أبدًا فوهات تصريف الغاز أو الكواشف أو رؤوس المرشّات أو محطات التشغيل اليدوي والإيقاف (abort)، ولا ترصّ الصناديق حتى السقف. (تُبقي قواعد OSHA الأمريكية مسافة خالية لا تقل عن 45.7 سم (18 بوصة) تحت المرشّات.)","لا يستخدم التشغيل اليدوي أو مفتاح الإيقاف إلا العاملون المدرَّبون والمخوَّلون، ووفق إجراءات الموقع فقط.","أبلغ فورًا عن أي عطل، أو إنذار لا يعود إلى وضعه الطبيعي، أو نظام أُوقف لأجل أعمال: فإلى أن يعود إلى العمل تلزم احتياطات إضافية، مثل شخص يراقب الحريق.","يتولّى الفحص والاختبار والصيانة مختصون مؤهَّلون؛ أما الفترات المطلوبة في دهوك فيحدّدها الدفاع المدني ولم تُؤكَّد بعدُ."]},{heading:"2. حماية السجلات والمقتنيات",body:"تبدأ معظم الخسائر بسوء الترتيب والنظافة أو بتسرّب أو بحريق صغير. الوقاية:",points:["حافظ على نظافة أماكن الحفظ وترتيبها: لا نفايات ولا أكوام كرتون ولا أثاث غير ضروري، ولا تدخين ولا لهب مكشوف حيث تُحفظ السجلات أو المقتنيات.","خزّن السوائل القابلة للاشتعال، مثل مواد التنظيف أو وقود المولّدات، في خزائن معدنية مقفلة بعيدًا عن الناس والسجلات.","لا تحفظ السجلات مباشرة تحت أنابيب الماء أو التدفئة أو الصرف أو فوقها، وارفع الرفّ الأدنى عن الأرض (تذكر إرشادات أرشيف الأمم المتحدة 15 سم).","اعرف من أين يمكن أن يدخل الماء، وافحص هذه الأماكن بانتظام، وفكّر في تركيب جهاز إنذار لتسرّب الماء في غرف الحفظ.","افحص الأسلاك والقوابس والكابلات بانتظام واستبدل الأجزاء البالية.","ضع على السجلات الحيوية علامات واضحة ليُعثر عليها وتُخرج فورًا، واحتفظ بنسخ منها في مكان آخر (قاعدة 3-2-1).","اتفق مسبقًا على قائمة أولويات للإنقاذ: أولًا الفهرس وسجلات المقتنيات، ثم أهم القطع وأندرها."]},{heading:"3. بعد الحريق أو الفيضان: الإنقاذ الآمن",body:"لا يبدأ الإنقاذ إلا بعد إعلان أن المبنى آمن:",points:["لا تحاول إنقاذ الوثائق أو القطع أثناء الطارئ نفسه: اخرج.","لا تدخل أبدًا منطقة متضرّرة حتى تقول الجهة المسؤولة إنها آمنة، واحذر كثيرًا حيث يكون الماء قريبًا من مآخذ الكهرباء أو الأجهزة.","تحرّك بسرعة: في الأجواء الدافئة الرطبة قد يظهر العفن خلال 48 ساعة.","لا تبدأ بإخراج المواد حتى تكون لدى المسؤول خطة بأولويات ويُطلَع الفريق عليها.","لا تفتح الكتب المبتلّة ولا تفصل الأوراق المبتلّة عن بعضها؛ ويمكن تجميد السجلات التي لا يمكن تجفيفها خلال أول 48 ساعة، ثم يجفّفها المختصون لاحقًا.","أبقِ المواد المبتلّة باردة مع هواء متحرك؛ وتجنّب الحرارة العالية وأشعة الشمس القوية، فهي تُتلف السجلات.","استشر مختصًا في الحفظ والصيانة قبل معالجة القطع الثمينة."]},{heading:"4. استمرارية العمل: إبقاء الخدمات الأساسية قائمة",body:"تبيّن خطة الاستمرارية كيف تواصل المؤسسة أهم أعمالها أثناء أي انقطاع وبعده:",points:["حدّد الوظائف الحرجة والموارد التي تحتاج إليها: الأشخاص والأنظمة والبيانات والسجلات والمباني والمورّدين.","تحليل تأثير الأعمال (BIA): ماذا يحدث إذا توقّفت كل وظيفة، وما السرعة التي يجب أن تُستعاد بها؛ وتُستعاد الوظائف الأكبر تأثيرًا أولًا.","انسخ احتياطيًّا (backup) كل المعلومات الحرجة بصورة متكررة، واحتفظ بنسخة في مكان آخر، وامسح ضوئيًّا السجلات الورقية المهمة.","تتبع استعادة أنظمة تقنية المعلومات الأولويات نفسها التي للوظائف التي تدعمها.","خطّط للبدائل: موقع آخر، وإجراءات يدوية، ووسيلة للتواصل مع العاملين والجمهور.","اختبر الخطة دوريًّا، وحدّثها بعد كل تمرين وكل حادث حقيقي.","المعايير الدولية: ISO 22301 (أنظمة إدارة استمرارية الأعمال)، وNFPA 1660 (التي تضمّ الآن معيار NFPA 1600 السابق)."]},{heading:"5. الإخلاء المنضبط والأمن",body:"في المصرف أو الخزينة الحصينة أو مركز البيانات أو المتحف، يجب أن يعمل الأمن وسلامة الأرواح معًا:",points:["سلامة الأرواح أولًا: يجب ألّا تمنع أقفال الأمن أحدًا من الخروج أبدًا، وتُفتح أبواب الخروج من الداخل دون مفتاح.","خطّط لمن يؤمّن ماذا: فمثلًا لا تُغلق أدراج النقد وأبواب الخزائن إلا إذا استغرق ذلك ثواني ولم يعرّض أحدًا للخطر؛ ولا يبقى أحد لحراسة الأشياء الثمينة.","رافق الزوار والمقاولين إلى الخارج، وعُدّهم مع العاملين عند نقطة التجمع.","احتفظ بقائمة بمن هم داخل المناطق المقيّدة، مثل غرفة الخوادم أو الخزينة أو المخزن، لتتمكّن من إبلاغ الدفاع المدني إن كان أحد مفقودًا.","يُبقي عناصر الأمن المداخل تحت السيطرة كي لا يعود أحد إلى الداخل، ويستقبلون الدفاع المدني بالمفاتيح وبطاقات الدخول ومخطط المبنى.","عند الاتصال بالرقم 115، اذكر ما يضمّه المبنى وأي مخاطر خاصة: أنظمة إطفاء غازية ثابتة، أو بطاريات كبيرة، أو وقود، أو مواد كيميائية."]},{heading:"6. الكهرباء والماء",body:"تحتاج منشآت الكهرباء والماء، وتزويد كل مبنى حساس بالكهرباء والماء، إلى ترتيبات واضحة:",points:["احتفظ بقائمة محدَّثة لأرقام الطوارئ: 115 الدفاع المدني، و122 الإسعاف، و104 الشرطة، وأرقام الطوارئ لدوائر الكهرباء والماء بعد التأكد منها لدى كل دائرة.","اعرف أماكن القواطع والمحابس الرئيسية للكهرباء والماء والغاز؛ ولا يشغّلها إلا العاملون المدرَّبون والمخوَّلون، وعندما يكون ذلك آمنًا فقط.","يركّب المولّدات الاحتياطية وأنظمة UPS ويصونها أشخاص مؤهَّلون؛ أما المولّد المتنقّل فلا يُستخدم إلا في الخارج، على بُعد 6 أمتار (20 قدمًا) على الأقل من النوافذ والأبواب وفتحات التهوية.","إذا تسرّب الماء وكان ذلك آمنًا فأوقفه من الصمام، وابتعد عن الماء القريب من الكهرباء، وأبلغ المسؤول؛ ولا تغطِّ السجلات والأجهزة بالنايلون إلا إذا كان ذلك آمنًا.","في منشآت الكهرباء أو الماء، اتبع إجراءات الطوارئ الخاصة بالموقع وتعليمات الدفاع المدني؛ ولم تُؤكَّد بعدُ المتطلبات المحلية لهذه المنشآت."]}],media:[{kind:"image",src:"media/images/w8_sensitive_fixed_system.webp",title:"العاملون يغادرون غرفة الخوادم عند انطلاق إنذار ما قبل التصريف",description:"ضوء تحذير وامض ولافتة فوق باب غرفة الخوادم؛ يخرج موظفان بهدوء ويغلقان الباب."}],quiz:[{question:"في غرفة الخوادم، يبدأ إنذار ما قبل التصريف في نظام الإطفاء الغازي الثابت بالرنين. ماذا تفعل؟",options:[{text:"أوقف العمل، وأخرج فورًا، وأغلق الباب، وأنبّه الآخرين",correct:!0},{text:"أبقى على مكتبي وأحفظ عملي، لأن الغاز لن يخرج قبل مدة",correct:!1},{text:"أضغط مفتاح الإيقاف بنفسي، مع أنني لم أتدرّب على استخدامه قط",correct:!1},{text:"أفتح النوافذ والباب على مصراعيها ليخرج الغاز بسرعة أكبر",correct:!1}],explanation:"يمنح إنذار ما قبل التصريف وزمن التأخير الناس وقتًا للخروج قبل إطلاق الغاز. اخرج فورًا من أقرب مخرج؛ ولا يستخدم مفتاح الإيقاف إلا العاملون المدرَّبون والمخوَّلون."},{question:"بعد أن يطلق نظام إطفاء غازي ثابت غازه، متى يمكن للعاملين العودة إلى الغرفة؟",options:[{text:"فقط عندما يقول المسؤول أو الدفاع المدني إن المكان آمن",correct:!0},{text:"حالما يتوقف الإنذار، لأن استنشاق هذا الغاز آمن دائمًا",correct:!1},{text:"بعد بضع دقائق، إن لم تظهر ألسنة لهب من نافذة الباب",correct:!1},{text:"فورًا، لمعرفة الأجهزة التي أتلفها الحريق",correct:!1}],explanation:"قد يبقى في الغرفة الغاز والدخان ونواتج الاحتراق. لا يعود أحد إلى الداخل حتى يقول المسؤول أو الدفاع المدني إن المكان آمن."},{question:"ما أفضل مكان لحفظ السجلات الورقية المهمة؟",options:[{text:"على رفوف مرفوعة عن الأرض، بعيدًا عن أنابيب الماء والصرف",correct:!0},{text:"على أرضية القبو، حيث لا تعترض الصناديق طريق أحد",correct:!1},{text:"في صناديق مرصوصة حتى السقف، تحت المرشّات مباشرة",correct:!1},{text:"على أعلى الرفوف، تحت أنابيب الماء الرئيسية مباشرة",correct:!1}],explanation:"الماء خطر كبير على السجلات: ارفعها عن الأرض وأبعدها عن الأنابيب، وأبقِ المساحة تحت المرشّات وفوهات الغاز خالية."},{question:"لماذا يجب التعامل مع السجلات المبتلّة بسرعة؟",options:[{text:"في الأجواء الدافئة الرطبة قد يظهر العفن خلال 48 ساعة",correct:!0},{text:"الورق المبتلّ يحترق بعد جفافه أسهل من الورق الجاف",correct:!1},{text:"الحبر على الورق المبتلّ يختفي دائمًا خلال الساعة الأولى",correct:!1},{text:"تصبح السجلات المبتلّة ثقيلة جدًّا على رفوفها خلال دقائق",correct:!1}],explanation:"قد يظهر العفن خلال 48 ساعة في الأجواء الدافئة الرطبة. ويمكن تجميد السجلات التي لا تُجفَّف خلال هذه المدة، ثم يجفّفها المختصون لاحقًا."},{question:"ما تحليل تأثير الأعمال (BIA)؟",options:[{text:"دراسة لما يحدث إذا توقّفت كل وظيفة، ولسرعة إعادتها المطلوبة",correct:!0},{text:"تقرير سنوي عن الأموال التي كسبتها المؤسسة وأنفقتها",correct:!1},{text:"قائمة بالعاملين الذين أتمّوا الدورة السنوية للتدريب على مطافئ الحريق",correct:!1},{text:"فحص لمخارج الحريق في المبنى يجريه عناصر الأمن",correct:!1}],explanation:"يحدّد تحليل تأثير الأعمال الوظائف الحرجة ومواردها، وأثر توقّفها، والسرعة التي يجب أن تُستعاد بها كل وظيفة؛ وتأتي الوظائف الأكبر تأثيرًا أولًا."},{question:"في مركز بيانات، يريد فنّي أن يكدّس صناديق أجهزة احتياطية حتى السقف في غرفة الخوادم المحمية. ما الردّ الصحيح؟",options:[{text:"نعم، بشرط أن تكون الصناديق معدنية لا من الكرتون",correct:!1},{text:"نعم، لأن نظام الغاز الثابت يحمي كل ما في الغرفة على أي حال",correct:!1},{text:"لا: يجب ألّا تسدّ الصناديق فوهات الغاز أو الكواشف أو المرشّات",correct:!0},{text:"لا، ولكن فقط لأن الصناديق ستجعل الغرفة تبدو غير مرتّبة",correct:!1}],explanation:"قد تسدّ الصناديق المكدّسة فوهات الغاز والكواشف ورؤوس المرشّات، فلا يكتشف النظام الحريق أو لا يطفئه. أبقِها خالية ولا تكدّس المخزون حتى السقف."}],steps:[{title:"الأرواح أولًا: اخرج عندما يدوّي الإنذار",detail:"عندما يدوّي إنذار الحريق أو إنذار ما قبل التصريف لنظام غازي ثابت، أوقف العمل واخرج من أقرب مخرج. ولا يبقى أحد لإنقاذ الوثائق أو الأجهزة أو المقتنيات أو المال.",critical:!0},{title:"أمِّن فقط ما يستغرق ثواني",detail:"كما تنصّ الخطة، أغلق درج النقد أو باب الخزينة فقط إذا استغرق ذلك ثواني ولم يعرّض أحدًا للخطر؛ وأغلق باب الغرفة خلفك."},{title:"تأكّد من وجود الجميع",detail:"رافق الزوار والمقاولين إلى الخارج، واستخدم قائمة من هم داخل المناطق المقيّدة، وعُدّ الجميع مع العاملين عند نقطة التجمع.",critical:!0},{title:"أخبر الرقم 115 بما يحويه المبنى",detail:"عندما تتصل بالرقم 115، اذكر المكان أولًا ثم المخاطر الخاصة: أنظمة الغاز الثابتة، والبطاريات الكبيرة، والوقود أو المواد الكيميائية، وهل قد يكون أحد ما يزال في الداخل.",critical:!0},{title:"تحكّم في المداخل",detail:"يُبقي موظفو الأمن المداخل تحت السيطرة لكي لا يعود أحد إلى الداخل، ويستقبلون الدفاع المدني ومعهم المفاتيح وبطاقات الدخول ومخطط المبنى."},{title:"لا تبدأ الاسترداد إلا حين يكون آمنًا",detail:"لا يدخل أحد حتى يقول المسؤول أو الدفاع المدني إن المكان آمن. ثم يجري الإنقاذ وفق قائمة الأولويات، وتعيد خطة الاستمرارية أهمّ الخدمات أولًا."}],warnings:["لا تعد أبدًا إلى غرفة بعد تصريف نظام غازي ثابت حتى يقول المسؤول أو الدفاع المدني إنها آمنة: فقد يبقى فيها الغاز والدخان ونواتج الاحتراق.","لا تسمح أبدًا لأقفال الأمن بأن تمنع الناس من الخروج: تُفتح أبواب الخروج من الداخل دون مفتاح.","لا تسدّ أو تغطِّ أبدًا فوهات الغاز أو الكواشف أو رؤوس المرشّات (Sprinkler) أو محطات التصريف اليدوي والإلغاء."],tips:["تدرّبوا على إنذار ما قبل التصريف مع كل من يدخل الغرف المحمية، بمن فيهم عمال النظافة والمقاولون.","احتفظ بقائمة أولويات الإنقاذ وبنسخ من السجلات الحيوية في مكان آخر، وراجعها كلما حُدّثت الخطة.","أبلغ فورًا عن أي عطل في نظام ثابت أو عن أي إيقاف له لأعمال صيانة، لكي تُتّخذ احتياطات إضافية.","حدِّث قائمة من هم داخل المناطق المقيّدة طوال اليوم، لا عند بداية الدوام فقط."],activity:{prompt:"أنت أمين صندوق (Cashier) في فرع مصرف. يدوّي إنذار الحريق. درج النقد لديك مفتوح، وثلاثة عملاء ينتظرون عند شبّاكك. ماذا تفعل؟",options:[{text:"أعدّ النقود وأحملها إلى الخزينة قبل الخروج",correct:!1,feedback:"خطأ: العدّ والحمل يستغرقان وقتًا لا تملكه؛ ولا يبقى أحد لحماية الأشياء الثمينة."},{text:"أبقى عند الشبّاك لحراسة النقود حتى يصل موظفو الأمن",correct:!1,feedback:"خطأ: الأرواح أولًا؛ والبقاء في مبنى يدوّي فيه الإنذار يعرّضك للخطر ويؤخّر العدّ."},{text:"أُقفل الأبواب الأمامية حتى لا يأخذ أحد النقود في أثناء الارتباك",correct:!1,feedback:"خطأ: يجب أن تُفتح أبواب الخروج دائمًا من الداخل؛ وإقفالها قد يحبس الناس في الحريق."},{text:"أغلق الدرج إن استغرق ذلك ثانية، ثم أرشد العملاء إلى أقرب مخرج حتى نقطة التجمع",correct:!0,feedback:"صحيح: أمِّن فقط ما يستغرق ثواني ولا يعرّض أحدًا للخطر، ثم أخرِج الناس؛ ويُعدّ العملاء عند نقطة التجمع مع العاملين."}]},caseStudy:[{prompt:"تعمل بين رفوف الأرشيف المحمية بنظام ثابت يعمل بعامل نظيف (Clean Agent). يبدأ إنذار ما قبل التصريف بالدويّ ويومض ضوء عند الباب. ويريد زميلك أن يُخرج أولًا صندوقين من الملفات النادرة. ماذا تفعل؟",options:[{text:"أساعد زميلي على إخراج الصندوقين بسرعة، لأن الغاز لم يُطلق بعد",correct:!1,feedback:"خطأ: زمن التأخير موجود ليخرج الناس، لا لنقل الوثائق؛ الصناديق تستطيع الانتظار، أما أرواحكما فلا."},{text:"أوقف العمل، وأخرج فورًا مع زميلي من أقرب مخرج، وأغلق الباب، وأنبّه الآخرين",correct:!0,feedback:"صحيح: عند إنذار ما قبل التصريف يخرج الجميع فورًا. والوثائق تحميها المنظومة وخطة الإنقاذ، لا بقاء الموظفين في الداخل."},{text:"أضغط زر الإلغاء (Abort) لأنني لا أرى أي دخان",correct:!1,feedback:"خطأ: لا يستخدم زر الإلغاء إلا الموظفون المدرَّبون المخوَّلون ووفق إجراءات الموقع؛ وعدم رؤية الدخان لا يعني عدم وجود حريق."}]},{prompt:"أُطلق الغاز. وبعد قليل توقّف الإنذار، ويريد المدير أن يدخل الموظفون فورًا لتفقّد الضرر الذي لحق بالسجلات. ماذا يجب أن يحدث؟",options:[{text:"لا يدخل أحد حتى يقول المسؤول أو الدفاع المدني إن المكان آمن؛ ثم يعمل فريق مُطَّلِع وفق قائمة أولويات الإنقاذ",correct:!0,feedback:"صحيح: قد يبقى في الغرفة الغاز والدخان ونواتج الاحتراق. ولا يبدأ الإنقاذ إلا عندما يكون آمنًا، بخطة وبفريق مُطَّلِع."},{text:"يدخل الموظفون الآن، لأن الإنذار توقّف واستنشاق الغاز آمن",correct:!1,feedback:"خطأ: توقّف الإنذار لا يعني أن الغرفة آمنة؛ والمسؤول أو الدفاع المدني وحدهما يقرّران ذلك."},{text:"نفتح الباب والنوافذ لتهوية الغرفة، ثم ندخل بعد بضع دقائق",correct:!1,feedback:"خطأ: ما زلت تدخل غرفة لم يُعلَن أنها آمنة؛ والتهوية والعودة يقرّرهما المسؤولون."}]}],realCase:"سيناريو توضيحي: في عطلة نهاية الأسبوع انفجر أنبوب ماء فوق مخزن سجلات تابع لمؤسسة حكومية. وفي أول يوم عمل وجد الموظفون ماءً على الأرض وعدة صناديق مبتلّة. لم يدخلوا فورًا: فقد عزل المسؤول الكهرباء عن الغرفة وأُعلن أن المكان آمن. ولأن الرفوف السفلى كانت مرفوعة عن الأرض، ولأن للسجلات الحيوية نسخًا في مكان آخر، واصلت المؤسسة عملها. ونقل فريق مُطَّلِع الصناديق المبتلّة وفق قائمة أولويات الإنقاذ، وحفظها في مكان بارد ليعالجها المختصون. وحُدّثت الخطة لإبعاد السجلات عن الأنبوب. الدرس: الوقاية والنسخ وخطة الإنقاذ تحمي ما لا يمكن تعويضه."},{id:23,code:"GOV-123",icon:"ClipboardCheck",accent:"#c2410c",title:"التقييم العملي لاستخدام مطفأة الحريق لمسؤولي الحريق",subtitle:"ما يتحقق منه المدرّب في تقييم عملي باستخدام مطفأة تدريبية أو جهاز محاكاة (simulator)",summary:"يجب أن يُثبت مسؤول الحريق عمليًّا، لا بالكلام فقط، أنه قادر على اتخاذ القرار الصحيح واستخدام المطفأة بأمان. يعرض هذا الدرس قائمة تحقق عملية نموذجية: قرار «نعم أو لا»، وفحص المطفأة، وطريقة PASS ضمن المدى المذكور على الملصق، والتراجع الآمن، والإبلاغ عن الاستخدام، وسلامة التدريب نفسه.",blocks:[{body:`لا يكفي حفظ طريقة PASS. ففي التقييم العملي يستخدم مسؤول الحريق مطفأة تدريبية (مملوءة بالماء عادةً) أو جهاز محاكاة رقميًّا أو يعمل بالغاز، تحت إشراف مدرّب. قائمة التحقق أدناه مثال نموذجي من الممارسة الدولية، وليست معيار المديرية: فمعايير النجاح والجهة التي يحق لها تقييم مسؤولي الحريق في دهوك ومنحهم الشهادات لم تُؤكَّد بعدُ.

تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F.`},{heading:"1. الخطوة الأولى: قرار «نعم أو لا»",body:"قبل أن يلمس المطفأة، يجيب مسؤول الحريق عن هذه الأسئلة بصوت مسموع. ويجب أن تكون كل الإجابات «نعم»:",points:["الإنذار: هل أُطلق الإنذار، وهل اتصل أحد بالرقم 115؟","الحجم: هل الحريق صغير وفي بدايته، في شيء واحد مثل سلّة مهملات أو مقلاة؟","النوع: هل هذه المطفأة مناسبة لما يحترق؟ يبيّن الملصق فئاتها.","المخرج: هل خلفي طريق خروج مفتوح لا يسدّه دخان أو حرارة؟","التدريب واللياقة: هل أنا مدرَّب وقادر جسديًّا على استخدام هذه المطفأة؟","الغاز والكهرباء: في حريق الغاز، هل أُوقف الغاز، إن كان ذلك آمنًا فقط؟ وفي الحريق الكهربائي، هل قُطع التيار إن كان ذلك آمنًا؟ لا تُطفئ أبدًا لهب غاز لا يمكن إيقافه.","في قائمة التحقق النموذجية، البدء قبل إطلاق الإنذار يعني الرسوب. وإذا أظهر السيناريو حريقًا ينتشر أو غرفة تمتلئ بالدخان، فالإجابة الصحيحة هي «لا»: اخرج، وأغلق الباب، وتأكّد من الاتصال بالرقم 115."]},{heading:"2. فحص المطفأة قبل الاستخدام",body:"في ثوانٍ قليلة، يتحقق مسؤول الحريق من:",points:["الملصق: الفئات المعتمدة للمطفأة، وتعليمات التشغيل، والتحذيرات، والمدى ومدة التفريغ إن ذكرها الملصق.","مقياس الضغط إن وُجد: المؤشر في المنطقة الخضراء. مطافئ CO₂ ليس لها مقياس ضغط.","مسمار الأمان والختم في مكانهما؛ والجسم والخرطوم والفوهة سليمة وغير مسدودة.","يتوقّع كثير من المدرّبين تفريغًا قصيرًا للاختبار مباشرة بعد سحب المسمار، موجَّهًا بعيدًا عن الناس، للتأكد من أنها تعمل.","إذا كان فيها خلل، يأخذ مسؤول الحريق مطفأة أخرى ويبلّغ عن المطفأة المعطّلة."]},{heading:"3. طريقة PASS ضمن المدى المذكور على الملصق",body:"يراقب المدرّب طريقة الاستخدام:",points:["Pull (اسحب): يسحب المسمار، فينكسر الختم أيضًا، والفوهة موجَّهة بعيدًا عنه.","Aim (وجِّه): يصوّب منخفضًا نحو قاعدة النار، لا نحو اللهب.","Squeeze (اضغط): يضغط المقبض ببطء وانتظام.","Sweep (حرِّك): يحرّك الفوهة يمينًا ويسارًا على قاعدة النار حتى تبدو النار منطفئة.","المسافة: يبدأ ضمن المدى المذكور على الملصق، ولا يقترب إلا كلما صغرت النار؛ فلا توجد مسافة صحيحة واحدة لكل المطافئ.","الموقع: يُبقي المخرج خلفه، ولا يسمح أبدًا للنار أو الحرارة أو الدخان بأن تحول بينه وبين طريق الخروج.","المادة: مدى CO₂ قصير وبوقها يبرد كثيرًا، فأمسك المقبض فقط؛ وتُستخدم المادة الكيميائية الرطبة (Wet Chemical) برفق كما يبيّن ملصقها؛ ولا ماء أبدًا على زيت الطبخ أو قرب الكهرباء الموصولة."]},{heading:"4. بعد الإطفاء: تراجع وراقب وأبلغ",body:"لا ينتهي التقييم بانطفاء اللهب:",points:["تراجع عن النار المطفأة ووجهك إليها، فقد تشتعل من جديد؛ ولا تُدر ظهرك لها أبدًا.","إذا اشتعلت النار مجددًا وكانت المطفأة لا تزال تعمل، فاستخدم PASS مرة أخرى؛ وإذا فرغت المطفأة ولم تنطفئ النار، فاخرج فورًا وأغلق الباب.","أخبر فريق الدفاع المدني بما احترق، وما استُخدم، وأين، حتى لو بدت النار منطفئة.","أبلغ عن كل استخدام: المطفأة التي استُخدمت ولو للحظة تُسحب من الخدمة وتُعاد تعبئتها أو تُستبدل؛ ولا تُعاد إلى الحائط أبدًا.","سجّل الاستخدام وأبلغ المسؤول، لتوضع مطفأة ممتلئة مكانها فورًا."]},{heading:"5. قائمة تحقق نموذجية للتقييم",body:"مثال لما قد يسجّله المدرّب. هذه قائمة نموذجية، وليست معيار المديرية:",points:["القرار: أعطى إجابة «نعم أو لا» الصحيحة للسيناريو، وأطلق الإنذار أولًا.","الاختيار: اختار مطفأة معتمدة لفئة الحريق.","الفحص: تحقّق من الملصق ومقياس الضغط والمسمار والختم.","الطريقة: استخدم PASS بشكل صحيح، ضمن المدى المذكور على الملصق، مصوّبًا نحو القاعدة.","السلامة: أبقى المخرج خلفه وتراجع ووجهه إلى النار.","الإبلاغ: أبلغ عن الاستخدام لكي تُعاد تعبئة المطفأة أو تُستبدل.","تحدّد مديرية الدفاع المدني من يحق له تقييم مسؤولي الحريق ومنحهم الشهادات، ودرجة النجاح، وعدد مرات إعادة التقييم، ولم يُؤكَّد ذلك بعدُ. وفي الولايات المتحدة تشترط OSHA تدريب العاملين المكلَّفين عند تكليفهم أول مرة، ثم مرة في السنة على الأقل."]},{heading:"6. سلامة جلسة التدريب نفسها",body:"يجب ألّا يؤذي التدريب نفسه أحدًا:",points:["استخدم المطافئ التدريبية (المائية عادةً) أو جهاز محاكاة رقميًّا كلما أمكن؛ أما جهاز المحاكاة بالنار الحقيقية فلا يشغّله إلا مدرّب مؤهَّل وفق تعليمات الشركة المصنّعة.","في الخارج، في مكان مفتوح بعيد عن المباني والمركبات وكل ما يمكن أن يحترق؛ ويتحقق المدرّب من اتجاه الريح كي يبتعد الدخان والمادة عن المتدرّبين.","يستطيع المدرّب قطع مصدر النار فورًا، ويُبقي مطفأة ممتلئة وحقيبة إسعافات أولية جاهزتين.","اشرح للجميع أولًا: ما سيحدث، وإشارة التوقف، وأين يقفون؛ ومتدرّب واحد في كل مرة.","اسأل عن المشكلات الصحية مثل الربو، وكيّف الجلسة بحسب قدرات كل شخص؛ ولا يشارك الأطفال في التدريب على المطافئ.","لا يُطلق المسحوق وCO₂ إلا حيث يسمح المدرّب: فسحب المسحوق تحجب الرؤية وتهيّج الرئتين، ولا يُطلق CO₂ أبدًا في غرفة صغيرة مغلقة.","يحدّد الدفاع المدني والسلطات المحلية من يحق له إجراء التدريب بالنار الحقيقية وأين يُسمح به، ولم يُؤكَّد ذلك بعدُ."],critical:!0}],media:[{kind:"image",src:"media/images/w8_extinguisher_assessment.webp",title:"تقييم مسؤول حريق باستخدام مطفأة تدريبية",description:"في الخارج، يوجّه متدرّب مطفأة تدريبية نحو قاعدة لهب جهاز المحاكاة وطريق الخروج خلفه، بينما يمسك المدرّب قائمة التحقق ويقف قرب مفتاح القطع."}],quiz:[{question:"في سيناريو تقييم، ينتشر حريق في مخزن كبير ويملؤه الدخان. ما التصرّف الصحيح؟",options:[{text:"لا تستخدم المطفأة: أطلق الإنذار، واخرج، وأغلق الباب، واتصل بالرقم 115",correct:!0},{text:"استخدم مطفأتين في الوقت نفسه لإيقاف النار قبل أن تنتشر أكثر",correct:!1},{text:"افتح النوافذ لطرد الدخان، ثم صوّب المطفأة نحو اللهب",correct:!1},{text:"انتظر داخل المخزن قرب الباب حتى يصل فريق الدفاع المدني",correct:!1}],explanation:"الحريق المنتشر والغرفة التي تمتلئ بالدخان يعنيان «لا»: القرار الصحيح هو إطلاق الإنذار والخروج وإغلاق الباب والتأكد من الاتصال بالرقم 115."},{question:"كيف يعرف مسؤول الحريق من أين يبدأ استخدام المطفأة؟",options:[{text:"من المدى المذكور على الملصق، والمخرج خلفه، ويقترب كلما صغرت النار",correct:!0},{text:"دائمًا من المسافة الثابتة نفسها، أيًّا كان نوع المطفأة أو حجمها",correct:!1},{text:"من أقرب نقطة ممكنة إلى اللهب، حتى لا يُهدر شيء من مادة المطفأة",correct:!1},{text:"من المكان الأقل دخانًا، حتى لو صار المخرج أمامه",correct:!1}],explanation:"لا توجد مسافة ثابتة. ابدأ ضمن المدى المذكور على الملصق، وأبقِ المخرج خلفك، ولا تقترب إلا كلما صغرت النار."},{question:"انطفأت النار. كيف يبتعد مسؤول الحريق؟",options:[{text:"يتراجع ووجهه إلى النار، ويراقب في حال اشتعلت من جديد",correct:!0},{text:"يستدير ويسير بسرعة إلى المخرج، لأن النار انطفأت تمامًا",correct:!1},{text:"يبقى بجوار المكان المحترق وينحني فوقه ليتحسّس الحرارة",correct:!1},{text:"يعيد المطفأة المستعملة إلى حاملها على الحائط قبل أن يغادر",correct:!1}],explanation:"تراجع عن النار المطفأة ووجهك إليها، فقد تشتعل من جديد. ويُبلَّغ عن المطفأة المستعملة وتُعاد تعبئتها أو تُستبدل، ولا تُعاد إلى الحائط أبدًا."},{question:"استُخدمت مطفأة لثانيتين فقط. ماذا يحدث بعد ذلك؟",options:[{text:"يُبلَّغ عنها، وتُسحب من الخدمة، وتُعاد تعبئتها أو تُستبدل",correct:!0},{text:"تُعاد إلى الحائط، لأنها ما زالت ممتلئة تقريبًا",correct:!1},{text:"تُحفظ للحريق القادم دون إبلاغ المسؤول",correct:!1},{text:"يهزّها مسؤول الحريق جيدًا ويختبرها مجددًا في نهاية اليوم",correct:!1}],explanation:"المطفأة مخصّصة لاستخدام واحد: بعد أي استخدام، ولو كان قصيرًا، يُبلَّغ عنها وتُعاد تعبئتها أو تُستبدل، وتوضع مطفأة ممتلئة مكانها."},{question:"أيّ ممارسة آمنة لجلسة التدريب نفسها؟",options:[{text:"مكان مفتوح في الخارج، ومدرّب يستطيع قطع النار، ومطفأة احتياطية",correct:!0},{text:"غرفة صغيرة مغلقة، ليتعلّم المتدرّبون العمل في دخان كثيف وحرارة حقيقية شديدة",correct:!1},{text:"عدة متدرّبين يكافحون النار الحقيقية نفسها معًا لتوفير الوقت",correct:!1},{text:"جهاز محاكاة بالغاز يشعله كل متدرّب ويشغّله بنفسه",correct:!1}],explanation:"يجب ألّا يؤذي التدريب أحدًا: مكان مفتوح في الخارج بعيد عمّا يحترق، ومدرّب يتحكم في مصدر النار ويستطيع قطعه، ومطفأة احتياطية ممتلئة، وحقيبة إسعافات أولية، وشرح مسبق، ومتدرّب واحد في كل مرة."},{question:"في أثناء التقييم، تراجعت عن حريق المحاكاة. فاشتعل من جديد، ومطفأتك الآن فارغة. ماذا تفعل؟",options:[{text:"أُحضر مطفأة أخرى من الطابق الآخر وأعود وحدي لمكافحة النار",correct:!1},{text:"أخرج فورًا، وأغلق الباب، وأتأكّد من الاتصال بالرقم 115",correct:!0},{text:"أرمي المطفأة الفارغة على قاعدة اللهب لكي تخنقه",correct:!1},{text:"أقترب وأنفخ على اللهب لأبعده عن طريق الخروج",correct:!1}],explanation:"إذا فرغت المطفأة ولم تنطفئ النار فالجواب «لا»: اخرج فورًا، وأغلق الباب لحبس النار، وتأكّد من الاتصال بالرقم 115. ولا تعد وحدك أبدًا لمكافحة نار تكبر."}],steps:[{title:"أطلق الإنذار أولًا",detail:"قبل أن تلمس المطفأة، أطلق الإنذار وتأكّد من الاتصال بالرقم 115. وفي قائمة التحقق النموذجية، البدء قبل الإنذار يعني الرسوب.",critical:!0},{title:"أجب عن أسئلة «نعم أو لا» بصوت مسموع",detail:"هل الحريق صغير وفي بدايته؟ هل المطفأة مناسبة لما يحترق؟ هل المخرج خلفك ولا يسدّه دخان أو حرارة؟ هل أنت مدرَّب وقادر؟ هل أُوقف الغاز أو التيار فقط إن كان ذلك آمنًا؟ إذا كانت أي إجابة «لا»، فاخرج وأغلق الباب.",critical:!0},{title:"افحص المطفأة",detail:"اقرأ الملصق (الفئات والتعليمات والمدى)؛ وتحقّق من أن مؤشر مقياس الضغط في المنطقة الخضراء إن وُجد مقياس، وأن مسمار الأمان والختم في مكانهما، وأن الخرطوم والفوهة سليمان. وإذا كان فيها خلل، فخذ مطفأة أخرى وأبلغ عن المعطّلة."},{title:"استخدم PASS من المدى المذكور على الملصق",detail:"اسحب المسمار، وصوّب منخفضًا نحو قاعدة النار، واضغط المقبض بانتظام، وحرّك الفوهة على القاعدة. ابدأ من المدى المذكور على الملصق ولا تقترب إلا كلما صغرت النار، مع إبقاء المخرج خلفك.",critical:!0},{title:"تراجع وراقب",detail:"عندما تبدو النار منطفئة، تراجع وأنت ما تزال تواجهها. وإذا اشتعلت من جديد والمطفأة ما تزال تعمل، فاستخدم PASS مرة أخرى؛ وإذا فرغت المطفأة ولم تنطفئ النار، فاخرج فورًا وأغلق الباب.",critical:!0},{title:"أبلغ عن الاستخدام",detail:"أخبر فريق الدفاع المدني بما احترق وبما استخدمته. وتُسحب المطفأة المستخدَمة من الخدمة وتُعاد تعبئتها أو تُستبدل، ولا تُعلَّق على الجدار من جديد أبدًا."}],warnings:["لا تسمح أبدًا للنار أو الحرارة أو الدخان بأن تحول بينك وبين طريق الخروج: إذا بدأ ذلك، فتوقّف واخرج.","لا تستخدم أبدًا الماء أو CO₂ على حريق زيت الطبخ، ولا الماء قرب الكهرباء الموصولة، ولا تُطفئ أبدًا لهب غاز لا يمكن إيقافه.","في التدريب، لا تُفرغ أبدًا CO₂ أو المسحوق في غرفة صغيرة مغلقة، ولا تمسك بوق CO₂ أبدًا: أمسك المقبض فقط."],tips:["قل كل إجابة من إجابات «نعم أو لا» بصوت مسموع: فالمدرّب يقيّم قرارك لا أسلوبك فقط.","تدرّب على أنواع المطافئ المركَّبة في مبناك، لكي يصبح المقبض والمدى مألوفين لك.","اطلب من المدرّب ملاحظات على تصويبك ووقفتك ومسافتك، وكرّر التمرين حتى يصبح سلسًا."],activity:{prompt:"في تقييم عملي، يُشعل المدرّب حريق محاكاة مكتوبًا عليه «زيت طبخ في مقلاة». أُطلق الإنذار والمخرج خلفك. وعلى الطاولة مطفأة ماء تدريبية، ومطفأة CO₂، ومطفأة مادة كيميائية رطبة (Wet Chemical) يبيّن ملصقها الفئة K (NFPA K = EN F). أيّها تختار؟",options:[{text:"مطفأة الماء التدريبية، لأنها المستخدمة في أغلب التمارين",correct:!1,feedback:"خطأ: الماء على الزيت المشتعل يتحوّل فورًا إلى بخار ويقذف الزيت؛ واختيارها رسوب في بند الاختيار."},{text:"مطفأة CO₂، لأنها تخنق النار دون أن تترك بقايا",correct:!1,feedback:"خطأ: CO₂ ليس الحل لحريق زيت الطبخ؛ فقد يدفع تيّارها الزيت إلى الخارج، وقد يشتعل الزيت الساخن من جديد."},{text:"مطفأة المادة الكيميائية الرطبة، تُستخدم برفق من المدى المذكور على ملصقها وكما يبيّن ملصقها",correct:!0,feedback:"صحيح: المادة الكيميائية الرطبة مصنوعة لزيت الطبخ (NFPA K = EN F). وعندما تُستخدم برفق تبرّد الزيت وتكوّن طبقة تمنع عودة اشتعاله."},{text:"لا شيء منها: أرمي منشفة مبلّلة على المقلاة من مكاني",correct:!1,feedback:"خطأ: المنشفة المرميّة قد تسبّب تناثر الزيت المشتعل؛ ضع بطانية حريق أو غطاءً بحذر، أو استخدم المطفأة الصحيحة."}]},caseStudy:[{prompt:"سيناريو تقييمك: حريق في سلّة مهملات في مكتب، وبجانبك مطفأة ماء تدريبية. المدرّب يراقب ولم يقل شيئًا عن الإنذار. ماذا تفعل قبل أن تلمس المطفأة؟",options:[{text:"أبدأ PASS فورًا لأن الحريق صغير وكل ثانية مهمة",correct:!1,feedback:"خطأ: البدء قبل إطلاق الإنذار رسوب في قائمة التحقق النموذجية؛ فالإنذار والاتصال بالرقم 115 يأتيان أولًا."},{text:"أطلق الإنذار، وأتأكّد من الاتصال بالرقم 115، ثم أجيب عن أسئلة «نعم أو لا» بصوت مسموع",correct:!0,feedback:"صحيح: الإنذار أولًا، ثم قرار «نعم أو لا». ويقيّم المدرّب القرار كما يقيّم الأسلوب."},{text:"أطلب من المدرّب أن يكبّر النار ليكون الاختبار أكثر واقعية",correct:!1,feedback:"خطأ: يختبر التقييم حريقًا صغيرًا في بدايته؛ والحريق المتنامي يعني «لا» والخروج."}]},{prompt:"ترفع مطفأة الماء فترى أن مؤشر مقياس الضغط في المنطقة الحمراء وأن الختم مكسور. ماذا تفعل؟",options:[{text:"أستخدمها رغم ذلك، لأن الحريق صغير ولا وقت لتبديلها",correct:!1,feedback:"خطأ: قد تتعطّل أمام النار وتتركك مكشوفًا؛ والمطفأة المعطّلة لا تُستخدم."},{text:"آخذ مطفأة أخرى مناسبة، وأبلغ عن المعطّلة، ولا أتابع إلا إذا بقيت إجابات «نعم أو لا» كلها «نعم»",correct:!0,feedback:"صحيح: فحص المطفأة جزء من التقييم. وتُبلَّغ المعطّلة، ويُراجَع القرار من جديد قبل التصرّف."},{text:"أهزّها بقوة وأجرّب تفريغًا اختباريًّا نحو النار",correct:!1,feedback:"خطأ: الهزّ لا يعيد الضغط المفقود؛ واستخدام مطفأة معطّلة قرب النار غير آمن."}]}],realCase:"سيناريو توضيحي: خضع مسؤول حريق في مبنى حكومي للتقييم العملي. أطلق الإنذار، وأجاب بصوت مسموع عن كل أسئلة «نعم أو لا»، وفحص الملصق ومقياس الضغط والمسمار والختم، وأطفأ حريق المحاكاة بأسلوب جيد من المدى المذكور على الملصق. ثم أدار ظهره ومشى. فسجّل المدرّب بند السلامة «غير متحقّق»: فالنار التي تبدو منطفئة قد تشتعل من جديد. تدرّب المسؤول مرة أخرى، فتراجع وهو يواجه النار ويراقبها، وأبلغ عن الاستخدام لكي تُعاد تعبئة المطفأة، واجتاز البند في المحاولة التالية. الدرس: لا ينتهي التقييم عندما ينطفئ اللهب."},{id:24,code:"GOV-124",icon:"ShieldAlert",accent:"#7f1d1d",title:"التهديدات بالقنابل والأجسام المشبوهة",subtitle:"تلقي تهديد هاتفي، والجسم المجهول، وعدم اللمس، والإبعاد، والإخلاء وفق الخطة، والإبلاغ عبر 104 و115",summary:"قد تتلقى الدوائر الحكومية تهديدًا بقنبلة عبر الهاتف أو رسالة أو الإنترنت، أو تجد جسمًا مشبوهًا داخل المبنى أو حوله. تعرض هذه الوحدة على الموظفين كيف يتلقون التهديد بهدوء ويدوّنون المعلومات، وكيف يتصرفون عند الجسم المشبوه (لا تلمسه، لا تقترب، أبعد الناس)، وكيف يُخلون وفق خطة الدائرة ويبلغون 104 و115.",blocks:[{body:"كثير من التهديدات يتبين أنها كاذبة، لكن كل تهديد يؤخذ بجدية حتى تقرر الجهات المختصة. لا يقرر الموظف صحة التهديد؛ مهمته أن يدوّن المعلومات بدقة ويبلغ فورًا ويتبع التعليمات. يتخذ المسؤول المعيَّن في الدائرة قرار الإخلاء وفق خطة الطوارئ وتعليمات الشرطة والدفاع المدني. تحدد الجهات المختصة قنوات الإبلاغ في الدائرة؛ وتقدم هذه الوحدة المبادئ العامة."},{heading:"1. تهديد عبر الهاتف",body:"من يتلقى المكالمة يسمع معلومات مهمة كثيرة:",points:["ابقَ هادئًا، ولا تقاطع ولا تُغلق الخط؛ دعه يتكلم أكثر.","دوّن كلامه بألفاظه، والوقت، والرقم الظاهر، والأصوات في الخلفية.","إن أمكن، اسأل: متى؟ أين؟ لماذا؟ ودوّن صفات الصوت (رجل أو امرأة، اللهجة، السرعة).","نبّه زميلًا بإشارة ليتصل بـ 104 من هاتف آخر ويبلغ المسؤول.","بعد انتهاء المكالمة، أبلغ المسؤول و104 فورًا وابقَ قرب الهاتف ليتحدث إليك الشرطة."]},{heading:"2. تهديد مكتوب أو إلكتروني",body:"إذا وصل التهديد برسالة أو بريد إلكتروني أو منشور على مواقع التواصل، فلا تحذفه ولا ترسله إلى أحد غير الجهات المختصة. حرّك الرسالة الورقية أقل ما يمكن وضعها في مكان نظيف؛ والتقط صورة للشاشة أو الرسالة ودوّن الوقت. أبلغ المسؤول و104 فورًا. نشر التهديد على مواقع التواصل يثير الخوف والارتباك وقد يعرقل عمل الشرطة."},{heading:"3. الجسم المشبوه",body:"أي جسم بلا صاحب لا يُعرف من وضعه، أو في مكان غير معتاد، أو مخبأ بطريقة غير عادية، قد يكون مشبوهًا. اسأل هل صاحبه قريب. فإن بقي الشك: لا تلمسه ولا تحركه ولا تفتحه ولا تغطّه بشيء. لا تستخدم الهاتف أو اللاسلكي قربه. أبعد الناس عن المكان، وأبلغ المسؤول و104 و115 من مكان آمن: الموقع الدقيق، ومتى وُجد، وما رأيت. حتى لو بدا الجسم غير ضار، فالقرار للجهات المختصة.",critical:!0},{heading:"4. الإخلاء وفق الخطة",body:"حين يقرر المسؤول المعيَّن الإخلاء، اخرج بهدوء وفق التعليمات. اختر طريقًا لا يمر قرب الجسم المشبوه، ولا تستخدم المصعد. ساعد الزوار والأشخاص ذوي الإعاقة. تجمّع في نقطة التجمع المحددة في الخطة، ويعدّ المسؤول الموظفين. لا تعد بنفسك للبحث عن أشياء أخرى. لا يدخل أحد حتى تقول الشرطة والدفاع المدني إن المكان آمن."}],steps:[{title:"1. ابقَ هادئًا ودوّن",detail:"عند التهديد الهاتفي، لا تغلق الخط ودوّن الكلام والوقت والأصوات."},{title:"2. لا تلمس",detail:"لا تحرك الجسم المشبوه ولا تفتحه ولا تغطه؛ ولا تستخدم الهاتف أو اللاسلكي قربه.",critical:!0},{title:"3. أبعد الناس",detail:"أبعد الناس عن المكان ولا تسمح لأحد بالاقتراب.",critical:!0},{title:"4. أبلغ",detail:"من مكان آمن أبلغ المسؤول و104 و115: المكان والوقت وما رأيت أو سمعت.",critical:!0},{title:"5. أخلِ وفق الخطة",detail:"حين يُتخذ القرار، اخرج من طريق بعيد عن الجسم، وابقَ في نقطة التجمع، ولا تعد حتى تسمح الجهات المختصة."}],warnings:["لا تلمس الجسم المشبوه ولا تحركه ولا تخرجه أبدًا: التحريك قد يسبب انفجاره.","لا تستخدم الهاتف أو اللاسلكي قرب جسم مشبوه؛ اتصل من مكان بعيد وآمن.","لا تنشر التهديد أو صور الجسم على مواقع التواصل: ذلك يثير الخوف ويعرقل عمل الشرطة."],tips:["ضع قائمة أسئلة التهديد الهاتفي قرب كل هاتف استقبال.","ليعرف الموظفون أماكن عملهم جيدًا ليلاحظوا الأشياء غير المعتادة بسرعة.","جرّب في تمرين الإخلاء طريق خروج بديلًا ونقطة تجمع بديلة.","ليعرف كل الموظفين طريقة الإبلاغ واسم المسؤول المعيَّن."],activity:{prompt:"تعمل في استقبال الدائرة. يرد اتصال يقول فيه شخص إن في المبنى قنبلة، ثم يسكت لكنه ما زال على الخط. ماذا تفعل؟",options:[{text:"أغلق الخط فورًا وأقول إنه كذب.",correct:!1,feedback:"بإغلاق الخط تضيع معلومات مهمة، والموظف لا يقرر صحة التهديد."},{text:"أبقى هادئًا وعلى الخط، وأسأل وأدوّن، وأنبّه زميلًا بإشارة ليتصل بـ 104.",correct:!0,feedback:"المكالمة الأطول تعطي معلومات أكثر، و104 يُبلَّغ بسرعة."},{text:"أصرخ في القاعة ليهرب الجميع بسرعة.",correct:!1,feedback:"قرار الإخلاء وفق الخطة بيد المسؤول المعيَّن؛ والهروب العشوائي قد يقود الناس نحو الخطر."},{text:"أبحث بنفسي في المبنى عن القنبلة.",correct:!1,feedback:"هذا عمل الجهات المختصة؛ والبحث قد يقربك من جسم خطر ويؤخر الإبلاغ."}]},caseStudy:[{prompt:"في قاعة الانتظار حقيبة مغلقة تحت كرسي. لا أحد يعرف صاحبها ولم يأتِ أحد لأخذها. ماذا تفعل؟",options:[{text:"أفتح الحقيبة لأجد هوية صاحبها.",correct:!1,feedback:"فتح الجسم المشبوه أو تحريكه قد يكون خطرًا؛ لا تلمسه."},{text:"أسأل الحاضرين عن صاحبها؛ فإن لم يوجد لا ألمسها، وأبعد الناس، وأبلغ من مكان آمن.",correct:!0,feedback:"السؤال كثيرًا ما يكشف صاحبها؛ وإلا فعدم اللمس والإبعاد والإبلاغ هو الصواب."},{text:"أحمل الحقيبة إلى خارج المبنى لحماية الناس.",correct:!1,feedback:"التحريك قد يزيد الخطر ويجعلك أقرب الناس إليها."}]},{prompt:"قرر المسؤول المعيَّن الإخلاء وفق تعليمات الشرطة. طريق الخروج المعتاد يمر بقاعة الانتظار. ماذا تفعل؟",options:[{text:"أخرج من الطريق المعتاد لأنه أسرع.",correct:!1,feedback:"هذا الطريق يقربك من الجسم المشبوه؛ اختر طريقًا آخر من الخطة."},{text:"أخرج من طريق آخر في الخطة، وأساعد الزوار، وأبقى في نقطة التجمع.",correct:!0,feedback:"الطريق البعيد عن الجسم والبقاء في نقطة التجمع يسهّلان عدّ الموظفين وعمل الجهات المختصة."},{text:"أعود إلى مكتبي لأخذ الحاسوب والوثائق.",correct:!1,feedback:"العودة تضيع الوقت وتبقيك داخل المبنى؛ اخرج مباشرة وفق الخطة."}]}],realCase:"سيناريو تدريبي: في دائرة خدمية تلقت موظفة الاستقبال اتصالًا يتضمن تهديدًا. لم تغلق الخط، واستخدمت قائمة الأسئلة الموضوعة قرب الهاتف، ونبّهت زميلتها بإشارة فاتصلت بـ 104 من هاتف آخر. قرر المسؤول المعيَّن الإخلاء وفق تعليمات الشرطة. أخرج الموظفون الزوار من طريق آخر في الخطة وجرى عدّهم في نقطة التجمع. بعد التفتيش أعلنت الجهات المختصة أن المكان آمن. وقد ساعدت ملاحظاتها الدقيقة الشرطة.",quiz:[{question:"أثناء تهديد هاتفي، أي فعل صحيح؟",options:[{text:"البقاء على الخط وتدوين الكلام بألفاظه",correct:!0},{text:"إغلاق الخط فورًا كي لا ينتشر الخوف",correct:!1},{text:"تهديد المتصل ليخاف",correct:!1},{text:"تحويل المكالمة إلى كل الغرف بمكبر الصوت",correct:!1}],explanation:"المكالمة الأطول والتدوين الدقيق يعطيان الشرطة معلومات مهمة."},{question:"يرى موظف حقيبة بلا صاحب في الممر ولا يظهر صاحبها. أي فعل خاطئ؟",options:[{text:"إبعاد الناس عن الممر",correct:!1},{text:"إبلاغ المسؤول و104 من مكان آمن",correct:!1},{text:"فتح الحقيبة لمعرفة ما فيها",correct:!0},{text:"تدوين وقت العثور على الحقيبة ومكانها",correct:!1}],explanation:"عدم اللمس والتحريك والفتح هو القاعدة الأساسية؛ والقرار للجهات المختصة."},{question:"لماذا لا يُستخدم الهاتف قرب جسم مشبوه؟",options:[{text:"لأنه قد يزيد الخطر؛ اتصل من مكان بعيد",correct:!0},{text:"لأن إشارة الهاتف ضعيفة داخل المباني",correct:!1},{text:"لأن الشرطة لا تحب أن يصور الموظفون",correct:!1},{text:"لأن بطارية الهاتف قد تنفد بسرعة",correct:!1}],explanation:"تقضي تعليمات السلامة بعدم استخدام الهاتف واللاسلكي قرب الجسم المشبوه والاتصال من مكان آمن."},{question:"وصل تهديد إلى الدائرة بالبريد الإلكتروني. ما التصرف الصحيح؟",options:[{text:"حذف البريد كي لا يخاف الموظفون",correct:!1},{text:"إرساله إلى كل الموظفين ليكونوا منتبهين",correct:!1},{text:"الاحتفاظ به وإبلاغ 104",correct:!0},{text:"الرد على البريد لمعرفة المرسل",correct:!1}],explanation:"حفظ التهديد كما هو مهم لتحقيق الشرطة؛ والحذف أو النشر يضر."},{question:"بعد الإخلاء يريد موظف العودة لأخذ حقيبته. ما الصحيح؟",options:[{text:"يمكنها العودة إن ذهبت وعادت بسرعة",correct:!1},{text:"تنتظر في نقطة التجمع حتى يُسمح بالعودة",correct:!0},{text:"يمكنها العودة إن رافقها زميل",correct:!1},{text:"يمكنها العودة إن كان مكتبها في الطابق الأول",correct:!1}],explanation:"لا يدخل أحد حتى تقول الشرطة والدفاع المدني إن المكان آمن، ولو لوقت قصير."},{question:"من يقرر إخلاء المبنى بعد تهديد بقنبلة؟",options:[{text:"الموظف الذي تلقى المكالمة وحده",correct:!1},{text:"المسؤول المعيَّن وفق الخطة",correct:!0},{text:"أول شخص يصرخ في القاعة",correct:!1},{text:"زوار قاعة الانتظار بالتصويت",correct:!1}],explanation:"القرار المنظم وفق الخطة وتعليمات الجهات المختصة يُخرج الناس من طريق آمن."}]}],t={lessons:e};export{t as default,e as lessons};
